function Write-ConnectionPreflightSummary {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$ConnectionResult,
        [Parameter(Mandatory = $false)]
        [switch]$PermissionPreflightSkipped
    )

    $connectedWorkloads = @($ConnectionResult.ConnectedWorkloads | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    $fallbackWorkloads = @($ConnectionResult.FallbackWorkloads | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    $skippedWorkloads = @($ConnectionResult.SkippedWorkloads | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })

    $formatTenantSummary = {
        param([object]$TenantDetails)

        if (-not $TenantDetails) {
            return 'not reported'
        }

        $parts = New-Object System.Collections.Generic.List[string]
        $tenantName = [string](Get-ArrayaObjectValue -Object $TenantDetails -Names @('TenantName', 'Name', 'DisplayName'))
        $tenantIdValue = [string](Get-ArrayaObjectValue -Object $TenantDetails -Names @('TenantId', 'TenantID', 'TenantInstanceId'))
        $initialDomain = [string](Get-ArrayaObjectValue -Object $TenantDetails -Names @('InitialDomain', 'Domain'))
        $connection = [string](Get-ArrayaObjectValue -Object $TenantDetails -Names @('Connection', 'RootSiteUrl', 'ConnectionUri'))
        $account = [string](Get-ArrayaObjectValue -Object $TenantDetails -Names @('Account', 'UserPrincipalName'))

        if (-not [string]::IsNullOrWhiteSpace($tenantName)) { $parts.Add($tenantName) | Out-Null }
        if (-not [string]::IsNullOrWhiteSpace($initialDomain)) { $parts.Add($initialDomain) | Out-Null }
        if (-not [string]::IsNullOrWhiteSpace($tenantIdValue)) { $parts.Add("TenantId=$tenantIdValue") | Out-Null }
        if (-not [string]::IsNullOrWhiteSpace($connection)) { $parts.Add($connection) | Out-Null }
        if (-not [string]::IsNullOrWhiteSpace($account)) { $parts.Add("Account=$account") | Out-Null }

        if ($parts.Count -eq 0) {
            return 'connected; tenant details not reported'
        }

        return ($parts -join ' | ')
    }

    $allConnected = $ConnectionResult.Graph -and $ConnectionResult.ExchangeOnline
    Write-Host ''
    if ($allConnected) {
        Write-Host '  ✓ All required workloads connected' -ForegroundColor Green
    } else {
        Write-Host '  ! One or more required workloads not connected' -ForegroundColor Yellow
    }
    Write-Host ''

    function Write-WorkloadStatus {
        param([string]$Label, [bool]$Connected, [string]$Detail = '', [string]$Qualifier = '')
        $icon  = if ($Connected) { '✓' } else { '!' }
        $color = if ($Connected) { 'Green' } else { 'Yellow' }
        Write-Host -NoNewline ("    {0}  {1,-18}" -f $icon, $Label) -ForegroundColor $color
        if ($Qualifier) {
            Write-Host -NoNewline ("{0,-10}" -f $Qualifier) -ForegroundColor Yellow
        } else {
            Write-Host -NoNewline (' ' * 10)
        }
        if ($Detail) {
            Write-Host $Detail -ForegroundColor DarkGray
        } else {
            Write-Host ''
        }
    }

    Write-WorkloadStatus -Label 'Graph'          -Connected ([bool]$ConnectionResult.Graph)                   -Detail (& $formatTenantSummary $ConnectionResult.GraphTenantDetails)
    Write-WorkloadStatus -Label 'Exchange Online' -Connected ([bool]$ConnectionResult.ExchangeOnline)          -Detail (& $formatTenantSummary $ConnectionResult.ExchangeTenantDetails)

    if ($ConnectionResult.SharePointOnline) {
        Write-WorkloadStatus -Label 'SharePoint'     -Connected $true  -Detail (& $formatTenantSummary $ConnectionResult.SharePointTenantDetails)
    } elseif ($fallbackWorkloads -contains 'SharePointOnline') {
        Write-WorkloadStatus -Label 'SharePoint'     -Connected $false -Qualifier 'fallback' -Detail 'Graph/SPO fallback active'
    } else {
        Write-WorkloadStatus -Label 'SharePoint'     -Connected $false
    }

    Write-WorkloadStatus -Label 'Teams'          -Connected ([bool]$ConnectionResult.Teams)                   -Detail $(if (-not $ConnectionResult.Teams) { 'Graph-only or not required' })
    $purviewStatus = if ($ConnectionResult.PurviewCmdletsAvailable) { $true } else { $false }
    $purviewDetail = if ($skippedWorkloads -contains 'PurviewCompliance') { 'not required by profile' } else { '' }
    Write-WorkloadStatus -Label 'Purview'         -Connected $purviewStatus                                    -Detail $purviewDetail

    Write-Host ''
    Write-Host -NoNewline '  Workloads  :  ' -ForegroundColor DarkGray
    Write-Host $(if ($connectedWorkloads.Count -gt 0) { $connectedWorkloads -join ', ' } else { 'None' }) -ForegroundColor Cyan
    if ($fallbackWorkloads.Count -gt 0) {
        Write-Host -NoNewline '  Fallback   :  ' -ForegroundColor DarkGray
        Write-Host ($fallbackWorkloads -join ', ') -ForegroundColor Yellow
    }
    if ($skippedWorkloads.Count -gt 0) {
        Write-Host -NoNewline '  Skipped    :  ' -ForegroundColor DarkGray
        Write-Host ($skippedWorkloads -join ', ') -ForegroundColor DarkGray
    }
    $permissionSummary = if ($PermissionPreflightSkipped) { 'Skipped by request' } else { 'Passed' }
    Write-Host -NoNewline '  Permissions:  ' -ForegroundColor DarkGray
    Write-Host $permissionSummary -ForegroundColor $(if ($PermissionPreflightSkipped) { 'Yellow' } else { 'Green' })
}

function Invoke-QuietRestMethod {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$Parameters
    )

    $savedProgressPreference = $ProgressPreference
    try {
        $ProgressPreference = 'SilentlyContinue'
        return Invoke-RestMethod @Parameters
    }
    finally {
        $ProgressPreference = $savedProgressPreference
    }
}

function Invoke-QuietWebRequest {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$Parameters
    )

    $savedProgressPreference = $ProgressPreference
    try {
        $ProgressPreference = 'SilentlyContinue'
        return Invoke-WebRequest @Parameters
    }
    finally {
        $ProgressPreference = $savedProgressPreference
    }
}

function Invoke-QuietCommand {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [scriptblock]$ScriptBlock
    )

    $savedProgressPreference = $ProgressPreference
    try {
        $ProgressPreference = 'SilentlyContinue'
        return (& $ScriptBlock)
    }
    finally {
        $ProgressPreference = $savedProgressPreference
    }
}

function Convert-DataSizeToBytes {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    if ($null -eq $Value) {
        return [int64]0
    }

    if ($Value -is [int64] -or $Value -is [int32] -or $Value -is [double] -or $Value -is [decimal]) {
        try { return [int64]$Value } catch { return [int64]0 }
    }

    foreach ($propertyName in @('Bytes', 'ByteCount', 'Value')) {
        if ($Value.PSObject -and $Value.PSObject.Properties[$propertyName]) {
            $nestedValue = $Value.PSObject.Properties[$propertyName].Value
            if ($nestedValue -is [int64] -or $nestedValue -is [int32] -or $nestedValue -is [double] -or $nestedValue -is [decimal]) {
                try { return [int64]$nestedValue } catch {}
            }
        }
    }

    $text = [string]$Value
    if ([string]::IsNullOrWhiteSpace($text)) {
        return [int64]0
    }

    if ($text -match '\((?<bytes>[0-9,]+)\s+bytes\)') {
        try { return [int64](($Matches['bytes'] -replace ',', '')) } catch {}
    }

    if ($text -match '^\s*(?<number>[0-9]+(?:\.[0-9]+)?)\s*(?<unit>KB|MB|GB|TB|PB)\b') {
        $number = [double]$Matches['number']
        $multiplier = switch ($Matches['unit'].ToUpperInvariant()) {
            'KB' { 1KB }
            'MB' { 1MB }
            'GB' { 1GB }
            'TB' { 1TB }
            'PB' { 1PB }
            default { 1 }
        }
        try { return [int64]($number * $multiplier) } catch { return [int64]0 }
    }

    return [int64]0
}

function Get-ArrayaCollectionDepthPolicy {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [ValidateSet('Minimum', 'Operator', 'Combined', 'Automation', 'All', 'Geek')]
        [string]$ReportingMode = 'Minimum',
        [Parameter(Mandatory = $false)]
        [ValidateSet('Default', 'TenantToTenantCutover')]
        [string]$CollectionScopePolicy = 'Default'
    )

    $mode = Normalize-ArrayaReportingMode -Mode $ReportingMode -Lowercase
    $isMinimum = $mode -eq 'minimum'
    $isOperator = $mode -eq 'operator'
    $isAutomation = $mode -eq 'automation'
    $isAll = $mode -eq 'all'
    $isGeek = $mode -eq 'geek'

    $policy = [PSCustomObject]@{
        ReportingMode                   = (Normalize-ArrayaReportingMode -Mode $mode)
        CollectEntraGroupDeepDetails    = (-not $isMinimum)
        CollectEntraGroupMemberCounts   = (-not $isMinimum)
        CollectEntraGroupOwnerCounts    = (-not $isMinimum)
        CollectEntraGroupLicenseChecks  = (-not $isMinimum)
        CollectSsoApplicationDetails    = (-not $isMinimum)
        CollectAuthenticationMethodRows = $true
        CollectSecureScoreMappings      = $true
        CollectFullMailboxNormalization = $true
        CollectMailboxDelegatePermissions = $false
        CollectMailboxCalendarDelegatePermissions = $false
        CollectUnifiedGroupMailboxStats = (-not $isMinimum)
        CollectFullSharePointDetail     = ($isAll -or $isGeek)
        CollectExtendedGraphEnrichment  = ($isAutomation -or $isAll -or $isGeek)
        IsMinimum                       = $isMinimum
        IsOperator                      = $isOperator
        IsCombined                      = $isOperator
        IsAutomation                    = $isAutomation
        IsAll                           = $isAll
        IsGeek                          = $isGeek
    }

    if ($CollectionScopePolicy -eq 'TenantToTenantCutover') {
        $policy | Add-Member -MemberType NoteProperty -Name CollectEntraGroupDeepDetails -Value $false -Force
        $policy | Add-Member -MemberType NoteProperty -Name CollectEntraGroupMemberCounts -Value $false -Force
        $policy | Add-Member -MemberType NoteProperty -Name CollectEntraGroupOwnerCounts -Value $false -Force
        $policy | Add-Member -MemberType NoteProperty -Name CollectEntraGroupLicenseChecks -Value $false -Force
        $policy | Add-Member -MemberType NoteProperty -Name CollectSsoApplicationDetails -Value $false -Force
        $policy | Add-Member -MemberType NoteProperty -Name CollectSecureScoreMappings -Value $false -Force
        $policy | Add-Member -MemberType NoteProperty -Name CollectFullMailboxNormalization -Value $true -Force
        $policy | Add-Member -MemberType NoteProperty -Name CollectMailboxDelegatePermissions -Value $true -Force
        $policy | Add-Member -MemberType NoteProperty -Name CollectMailboxCalendarDelegatePermissions -Value $true -Force
        $policy | Add-Member -MemberType NoteProperty -Name CollectUnifiedGroupMailboxStats -Value $false -Force
        $policy | Add-Member -MemberType NoteProperty -Name CollectFullSharePointDetail -Value $false -Force
        $policy | Add-Member -MemberType NoteProperty -Name CollectExtendedGraphEnrichment -Value $false -Force
    }

    return $policy
}

