function Get-AssessmentGuestUserRoleLabel {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [string]$GuestUserRoleId
    )

    $normalizedRoleId = [string]$GuestUserRoleId
    if ([string]::IsNullOrWhiteSpace($normalizedRoleId)) {
        return $null
    }

    if ($normalizedRoleId -in @('Not collected', 'Not surfaced in current source', 'Not available in current auth mode', 'Not available in current app-only source')) {
        return $null
    }

    if ($normalizedRoleId -notmatch '^[0-9a-fA-F-]{36}$') {
        if ($normalizedRoleId -match 'Guest users|directory objects|Custom guest role configured') {
            return $normalizedRoleId
        }

        return 'Custom guest role configured'
    }

    switch ($normalizedRoleId.ToLowerInvariant()) {
        '10dae51f-b6af-4016-8d66-8c2a99b929b3' { return 'Guest users have limited access to directory objects (default)' }
        '2af84b1e-32c8-42b7-82bc-daa82404023b' { return 'Guest users are restricted to their own directory objects (most restrictive)' }
        'a0b1b346-4d3e-4e8b-98f8-753987be4970' { return 'Guest users have the same access as members (most permissive)' }
        default { return 'Custom guest role configured' }
    }
}

function Get-AssessmentMfaMethodProfile {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [string]$MethodName
    )

    $rawValue = [string]$MethodName
    if ([string]::IsNullOrWhiteSpace($rawValue)) {
        return [pscustomobject]@{
            FriendlyName = $null
            Category     = 'Unknown'
            IsWeak       = $false
        }
    }

    $normalized = ($rawValue -replace '\s+', '').Trim().ToLowerInvariant()
    switch -Regex ($normalized) {
        '^(email|emailotp)$' {
            return [pscustomobject]@{
                FriendlyName = 'Email one-time passcode'
                Category     = 'Weak'
                IsWeak       = $true
            }
        }
        '^(sms|mobilephone|alternatemobilephone|voice.*|officephone|phoneappnotificationlesssecure|phone)$' {
            return [pscustomobject]@{
                FriendlyName = $(if ($normalized -match 'voice|officephone') { 'Phone call' } else { 'SMS / phone' })
                Category     = 'Weak'
                IsWeak       = $true
            }
        }
        '^(microsoftauthenticator.*|authenticatorapp|phoneappnotification|passwordlessphonesignin)$' {
            return [pscustomobject]@{
                FriendlyName = 'Microsoft Authenticator'
                Category     = 'Strong'
                IsWeak       = $false
            }
        }
        '^(softwareonetimepasscode|softwareotp)$' {
            return [pscustomobject]@{
                FriendlyName = 'Software one-time passcode'
                Category     = 'Strong'
                IsWeak       = $false
            }
        }
        '^(softwareoath.*|oath.*)$' {
            return [pscustomobject]@{
                FriendlyName = 'Software OATH token'
                Category     = 'Strong'
                IsWeak       = $false
            }
        }
        '^(temporaryaccesspass|tap)$' {
            return [pscustomobject]@{
                FriendlyName = 'Temporary Access Pass'
                Category     = 'Strong'
                IsWeak       = $false
            }
        }
        '^(fido2.*|passkey.*)$' {
            return [pscustomobject]@{
                FriendlyName = 'FIDO2 security key / passkey'
                Category     = 'PhishingResistant'
                IsWeak       = $false
            }
        }
        '^(windowshelloforbusiness|windowshello.*)$' {
            return [pscustomobject]@{
                FriendlyName = 'Windows Hello for Business'
                Category     = 'PhishingResistant'
                IsWeak       = $false
            }
        }
        default {
            $friendlyName = if ($rawValue -cmatch '[a-z][A-Z]') {
                [regex]::Replace($rawValue, '(?<=[a-z])(?=[A-Z])', ' ')
            } else {
                $rawValue
            }

            return [pscustomobject]@{
                FriendlyName = $friendlyName.Trim()
                Category     = 'Other'
                IsWeak       = $false
            }
        }
    }
}

function Convert-AssessmentMfaCountMapToText {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [hashtable]$CountMap
    )

    if ($null -eq $CountMap -or $CountMap.Count -eq 0) {
        return $null
    }

    return (
        @(
            $CountMap.GetEnumerator() |
                Sort-Object @{ Expression = { $_.Value }; Descending = $true }, @{ Expression = { $_.Name } } |
                ForEach-Object { '{0}={1}' -f $_.Name, $_.Value }
        ) -join '; '
    )
}

function Convert-ToAssessmentStringArray {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    if ($null -eq $Value) {
        return @()
    }

    if (($Value -is [System.Collections.IEnumerable]) -and -not ($Value -is [string])) {
        return @(
            @($Value) |
                ForEach-Object { [string]$_ } |
                ForEach-Object { $_.Trim() } |
                Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
        )
    }

    return @(
        ([string]$Value -split ',') |
            ForEach-Object { $_.Trim() } |
            Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
    )
}

function Test-AssessmentGuestUserRecord {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $UserRecord
    )

    $userType = [string](Get-ArrayaObjectValue -Object $UserRecord -Names @('UserType'))
    $userPrincipalName = [string](Get-ArrayaObjectValue -Object $UserRecord -Names @('UserPrincipalName'))

    return (
        $userType -match '(?i)guest' -or
        $userPrincipalName -like '*#EXT#*'
    )
}

function Test-AssessmentMeaningfulNestedValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    if ($null -eq $Value) {
        return $false
    }

    if ($Value -is [string]) {
        $textValue = $Value.Trim()
        if ([string]::IsNullOrWhiteSpace($textValue) -or $textValue -in @('null', '{}', '[]')) {
            return $false
        }

        if (
            ($textValue.StartsWith('{') -and $textValue.EndsWith('}')) -or
            ($textValue.StartsWith('[') -and $textValue.EndsWith(']'))
        ) {
            try {
                return (Test-AssessmentMeaningfulNestedValue -Value ($textValue | ConvertFrom-Json -Depth 10))
            }
            catch {
                return $true
            }
        }

        return $true
    }

    if ($Value -is [bool] -or $Value -is [ValueType]) {
        return $true
    }

    if ($Value -is [System.Collections.IDictionary]) {
        foreach ($entry in $Value.GetEnumerator()) {
            if (Test-AssessmentMeaningfulNestedValue -Value $entry.Value) {
                return $true
            }
        }

        return $false
    }

    if (($Value -is [System.Collections.IEnumerable]) -and -not ($Value -is [string])) {
        foreach ($item in @($Value)) {
            if (Test-AssessmentMeaningfulNestedValue -Value $item) {
                return $true
            }
        }

        return $false
    }

    $propertyBag = @($Value.PSObject.Properties | Where-Object { $_.MemberType -like '*Property' })
    if ($propertyBag.Count -gt 0) {
        foreach ($property in $propertyBag) {
            if (Test-AssessmentMeaningfulNestedValue -Value $property.Value) {
                return $true
            }
        }

        return $false
    }

    return $true
}

function Convert-AssessmentConditionalAccessNestedValueToText {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    if (-not (Test-AssessmentMeaningfulNestedValue -Value $Value)) {
        return ''
    }

    return [string](Convert-ToAssessmentDisplayText -Value $Value -Default '')
}

function Test-AssessmentConditionalAccessRequiresMfa {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Policy
    )

    if ($null -eq $Policy) {
        return $false
    }

    $precomputedRequiresMfa = Convert-ToAssessmentBoolean (Get-ArrayaObjectValue -Object $Policy -Names @('RequiresMfaEnforcement'))
    if ($precomputedRequiresMfa -eq $true) {
        return $true
    }

    $grantControls = Get-ArrayaObjectValue -Object $Policy -Names @('GrantControls')
    $builtInControls = Convert-ToAssessmentStringArray -Value (Get-ArrayaObjectValue -Object $Policy -Names @('GrantControls_BuiltInControls'))
    if ($builtInControls.Count -eq 0 -and $grantControls) {
        $builtInControls = Convert-ToAssessmentStringArray -Value (Get-ArrayaObjectValue -Object $grantControls -Names @('BuiltInControls'))
    }

    if (@($builtInControls | Where-Object { $_ -match '^(?i)mfa$' }).Count -gt 0) {
        return $true
    }

    $usesAuthenticationStrengthForMfa = Convert-ToAssessmentBoolean (Get-ArrayaObjectValue -Object $Policy -Names @('UsesAuthenticationStrengthForMfa'))
    if ($usesAuthenticationStrengthForMfa -eq $true) {
        return $true
    }

    $authenticationStrength = Get-ArrayaObjectValue -Object $Policy -Names @('GrantControls_AuthenticationStrength', 'AuthenticationStrength')
    if ($null -eq $authenticationStrength -and $grantControls) {
        $authenticationStrength = Get-ArrayaObjectValue -Object $grantControls -Names @('AuthenticationStrength')
    }

    return (Test-AssessmentMeaningfulNestedValue -Value $authenticationStrength)
}

function Convert-ToAssessmentBoolean {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    if ($null -eq $Value) {
        return $null
    }

    if ($Value -is [bool]) {
        return [bool]$Value
    }

    $text = [string]$Value
    if ([string]::IsNullOrWhiteSpace($text)) {
        return $null
    }

    switch -Regex ($text.Trim().ToLowerInvariant()) {
        '^(true|yes|enabled|1)$' { return $true }
        '^(false|no|disabled|0)$' { return $false }
        default {
            try {
                return [System.Convert]::ToBoolean($Value)
            }
            catch {
                return $null
            }
        }
    }
}

function Convert-ToAssessmentDisplayText {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value,
        [Parameter(Mandatory = $false)]
        [string]$Default = ''
    )

    if ($null -eq $Value) {
        return $Default
    }

    if ($Value -is [string]) {
        $textValue = $Value.Trim()
        return $(if ([string]::IsNullOrWhiteSpace($textValue)) { $Default } else { $textValue })
    }

    try {
        $serializedValue = ($Value | ConvertTo-Json -Compress -Depth 6)
        if ([string]::IsNullOrWhiteSpace($serializedValue)) {
            return $Default
        }

        return $serializedValue
    }
    catch {
        $fallbackText = [string]$Value
        return $(if ([string]::IsNullOrWhiteSpace($fallbackText)) { $Default } else { $fallbackText.Trim() })
    }
}

function Add-AssessmentUserIdsToSet {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$Set,
        [Parameter(Mandatory = $false)]
        [string[]]$UserIds = @()
    )

    foreach ($userId in @($UserIds)) {
        if ([string]::IsNullOrWhiteSpace([string]$userId)) {
            continue
        }

        $Set[[string]$userId] = $true
    }
}

function Add-AssessmentNotePropertyIfPossible {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Object,
        [Parameter(Mandatory = $true)]
        [string]$Name,
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    if ($null -eq $Object -or [string]::IsNullOrWhiteSpace($Name)) {
        return
    }

    try {
        $Object | Add-Member -MemberType NoteProperty -Name $Name -Value $Value -Force
    }
    catch {
        # Some deserialized Graph/admin objects do not support mutation cleanly.
        # The admin MFA review should still complete without losing the summary rows.
    }
}

function Get-AssessmentConditionalAccessGroupUserIds {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$GroupId,
        [Parameter(Mandatory = $true)]
        [hashtable]$GroupUserLookup,
        [Parameter(Mandatory = $true)]
        [hashtable]$EnabledUserIdLookup,
        [Parameter(Mandatory = $false)]
        [string]$OperationName = 'Conditional Access coverage expansion'
    )

    if ([string]::IsNullOrWhiteSpace($GroupId)) {
        return @()
    }

    $normalizedGroupId = $GroupId.Trim().ToLowerInvariant()
    if ($GroupUserLookup.ContainsKey($normalizedGroupId)) {
        return @($GroupUserLookup[$normalizedGroupId])
    }

    $resolvedUserIds = New-Object System.Collections.Generic.List[string]
    try {
        $groupMembers = @(
            Get-ArrayaGraphResource -Uri ("https://graph.microsoft.com/v1.0/groups/{0}/transitiveMembers/microsoft.graph.user?`$select=id" -f $GroupId) -Activity "${OperationName}: expanding group scope [$GroupId]"
        )
        foreach ($member in $groupMembers) {
            $memberId = [string](Get-ArrayaObjectValue -Object $member -Names @('id', 'Id'))
            if ([string]::IsNullOrWhiteSpace($memberId)) {
                continue
            }

            $normalizedMemberId = $memberId.Trim().ToLowerInvariant()
            if ($EnabledUserIdLookup.ContainsKey($normalizedMemberId)) {
                $resolvedUserIds.Add([string]$EnabledUserIdLookup[$normalizedMemberId]) | Out-Null
            }
        }
    }
    catch {
        Write-Log -Type WARNING -Message "[$OperationName] Unable to expand Conditional Access group scope for '$GroupId'. $($_.Exception.Message)" -ExportFileLocation $ExportDetails
    }

    $GroupUserLookup[$normalizedGroupId] = @($resolvedUserIds | Sort-Object -Unique)
    return @($GroupUserLookup[$normalizedGroupId])
}

function Get-AssessmentConditionalAccessRoleUserIds {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [string[]]$RoleTemplateIds = @(),
        [Parameter(Mandatory = $true)]
        [hashtable]$RoleTemplateLookup,
        [Parameter(Mandatory = $true)]
        [hashtable]$RoleUserLookup,
        [Parameter(Mandatory = $true)]
        [hashtable]$EnabledUserIdLookup,
        [Parameter(Mandatory = $false)]
        [string]$OperationName = 'Conditional Access coverage expansion'
    )

    $resolvedRoleTemplateIds = @(
        Convert-ToAssessmentStringArray -Value $RoleTemplateIds |
            Where-Object {
                -not [string]::IsNullOrWhiteSpace([string]$_) -and
                [string]$_ -notmatch '^(?i)(all|none|null|\[\]|\{\})$' -and
                [string]$_ -match '^[0-9a-fA-F-]{8,}$'
            }
    )

    if ($resolvedRoleTemplateIds.Count -eq 0) {
        return @()
    }

    if ($RoleTemplateLookup.Count -eq 0) {
        $errorCountBeforeRoleLookup = $global:Error.Count
        try {
            $directoryRoles = @(
                Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/directoryRoles?`$select=id,displayName,roleTemplateId' -PageSize 0 -Activity "${OperationName}: loading active directory roles"
            )
            foreach ($directoryRole in $directoryRoles) {
                $roleTemplateId = [string](Get-ArrayaObjectValue -Object $directoryRole -Names @('roleTemplateId', 'RoleTemplateId'))
                if ([string]::IsNullOrWhiteSpace($roleTemplateId)) {
                    continue
                }

                $normalizedTemplateId = $roleTemplateId.Trim().ToLowerInvariant()
                if (-not $RoleTemplateLookup.ContainsKey($normalizedTemplateId)) {
                    $RoleTemplateLookup[$normalizedTemplateId] = New-Object System.Collections.Generic.List[object]
                }

                $RoleTemplateLookup[$normalizedTemplateId].Add($directoryRole) | Out-Null
            }
        }
        catch {
            while ($global:Error.Count -gt $errorCountBeforeRoleLookup) {
                $global:Error.RemoveAt(0)
            }
            Write-Log -Type WARNING -Message "[$OperationName] Unable to load active directory roles for Conditional Access role expansion. $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }
    }

    $resolvedUserIds = New-Object System.Collections.Generic.List[string]
    foreach ($roleTemplateId in $resolvedRoleTemplateIds) {
        $normalizedTemplateId = $roleTemplateId.Trim().ToLowerInvariant()
        if ([string]::IsNullOrWhiteSpace($normalizedTemplateId)) {
            continue
        }

        if (-not $RoleUserLookup.ContainsKey($normalizedTemplateId)) {
            $templateUserIds = New-Object System.Collections.Generic.List[string]
            foreach ($directoryRole in @($RoleTemplateLookup[$normalizedTemplateId])) {
                if (-not $directoryRole) {
                    continue
                }

                $directoryRoleId = [string](Get-ArrayaObjectValue -Object $directoryRole -Names @('id', 'Id'))
                if ([string]::IsNullOrWhiteSpace($directoryRoleId)) {
                    continue
                }

                try {
                    $roleMembers = @(
                        Get-ArrayaGraphResource -Uri ("https://graph.microsoft.com/v1.0/directoryRoles/{0}/members/microsoft.graph.user?`$select=id" -f $directoryRoleId) -PageSize 0 -Activity "${OperationName}: expanding role scope [$directoryRoleId]"
                    )
                    foreach ($roleMember in $roleMembers) {
                        $roleMemberId = [string](Get-ArrayaObjectValue -Object $roleMember -Names @('id', 'Id'))
                        if ([string]::IsNullOrWhiteSpace($roleMemberId)) {
                            continue
                        }

                        $normalizedRoleMemberId = $roleMemberId.Trim().ToLowerInvariant()
                        if ($EnabledUserIdLookup.ContainsKey($normalizedRoleMemberId)) {
                            $templateUserIds.Add([string]$EnabledUserIdLookup[$normalizedRoleMemberId]) | Out-Null
                        }
                    }
                }
                catch {
                    Write-Log -Type WARNING -Message "[$OperationName] Unable to expand Conditional Access role scope for '$directoryRoleId'. $($_.Exception.Message)" -ExportFileLocation $ExportDetails
                }
            }

            $RoleUserLookup[$normalizedTemplateId] = @($templateUserIds | Sort-Object -Unique)
        }

        foreach ($resolvedId in @($RoleUserLookup[$normalizedTemplateId])) {
            $resolvedUserIds.Add([string]$resolvedId) | Out-Null
        }
    }

    return @($resolvedUserIds | Sort-Object -Unique)
}

function Get-AssessmentMfaEnforcementCoverageSummary {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [object[]]$EnabledMfaPolicies = @(),
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [System.Collections.IDictionary]$Users = $null,
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Groups = $null,
        [Parameter(Mandatory = $false)]
        [switch]$IncludeDetails,
        [Parameter(Mandatory = $false)]
        [string]$OperationName = 'Get-MfaRegistrationDetails'
    )

    $coverageSummary = [ordered]@{
        EnabledUsersReviewed                   = $null
        EnabledMemberUsersReviewed             = $null
        EnabledGuestUsersReviewed              = $null
        UsersCoveredByEnabledMfaPolicies       = $null
        UserCoveragePercent                    = $null
        MemberUsersCoveredByEnabledMfaPolicies = $null
        MemberUserCoveragePercent              = $null
        GuestUsersCoveredByEnabledMfaPolicies  = $null
        GuestUserCoveragePercent               = $null
        GroupTargetedPolicyCount               = 0
        RoleTargetedPolicyCount                = 0
        CoverageCalculationNote                = 'Not validated from the reviewed data'
    }

    $gapUserRows = New-Object System.Collections.Generic.List[object]
    $scopeReviewRows = New-Object System.Collections.Generic.List[object]

    if ($null -eq $Users -or $Users.Count -eq 0) {
        if ($IncludeDetails) {
            return [pscustomobject]@{
                Summary = [pscustomobject]$coverageSummary
                GapUsers = @()
                ScopeReview = @()
            }
        }
        return [pscustomobject]$coverageSummary
    }

    $allReviewedUsers = @($Users.Values | Where-Object { $null -ne $_ })
    $enabledReviewedUsers = @(
        $allReviewedUsers |
            Where-Object { (Convert-ToAssessmentBoolean (Get-ArrayaObjectValue -Object $_ -Names @('AccountEnabled'))) -ne $false }
    )
    $enabledMemberUsers = @($enabledReviewedUsers | Where-Object { -not (Test-AssessmentGuestUserRecord -UserRecord $_) })
    $enabledGuestUsers = @($enabledReviewedUsers | Where-Object { Test-AssessmentGuestUserRecord -UserRecord $_ })

    $coverageSummary.EnabledUsersReviewed = $enabledReviewedUsers.Count
    $coverageSummary.EnabledMemberUsersReviewed = $enabledMemberUsers.Count
    $coverageSummary.EnabledGuestUsersReviewed = $enabledGuestUsers.Count

    if ($enabledReviewedUsers.Count -eq 0 -or @($EnabledMfaPolicies).Count -eq 0) {
        $coverageSummary.CoverageCalculationNote = if ($enabledReviewedUsers.Count -eq 0) {
            'No enabled reviewed users were available for MFA enforcement coverage analysis.'
        }
        else {
            'No enabled Conditional Access policies requiring MFA were available for user coverage analysis.'
        }

        if ($IncludeDetails) {
            return [pscustomobject]@{
                Summary = [pscustomobject]$coverageSummary
                GapUsers = @()
                ScopeReview = @()
            }
        }
        return [pscustomobject]$coverageSummary
    }

    $enabledUserIdLookup = @{}
    $enabledUserRecordLookup = @{}
    $enabledReviewedUserIdSet = @{}
    $enabledMemberUserIdSet = @{}
    $enabledGuestUserIdSet = @{}

    foreach ($reviewedUser in $enabledReviewedUsers) {
        $reviewedUserId = [string](Get-ArrayaObjectValue -Object $reviewedUser -Names @('Id', 'ID'))
        if ([string]::IsNullOrWhiteSpace($reviewedUserId)) {
            continue
        }

        $canonicalUserId = $reviewedUserId.Trim()
        $normalizedUserId = $canonicalUserId.ToLowerInvariant()
        $enabledUserIdLookup[$normalizedUserId] = $canonicalUserId
        $enabledUserRecordLookup[$canonicalUserId] = $reviewedUser
        $enabledReviewedUserIdSet[$canonicalUserId] = $true
        if (Test-AssessmentGuestUserRecord -UserRecord $reviewedUser) {
            $enabledGuestUserIdSet[$canonicalUserId] = $true
        }
        else {
            $enabledMemberUserIdSet[$canonicalUserId] = $true
        }
    }

    if ($enabledUserIdLookup.Count -eq 0) {
        $coverageSummary.CoverageCalculationNote = 'Enabled reviewed users did not surface stable Graph user identifiers, so MFA enforcement coverage could not be expanded.'
        if ($IncludeDetails) {
            return [pscustomobject]@{
                Summary = [pscustomobject]$coverageSummary
                GapUsers = @()
                ScopeReview = @()
            }
        }
        return [pscustomobject]$coverageSummary
    }

    $groupUserLookup = @{}
    $groupMetadataLookup = @{}
    $roleTemplateLookup = @{}
    $roleUserLookup = @{}
    $coveredUserIdSet = @{}
    $userExclusionReasonLookup = @{}
    $userExclusionPolicyLookup = @{}
    $userIncludedPolicyLookup = @{}
    $userCoveredPolicyLookup = @{}
    $scopeReviewKeyLookup = @{}

    $groupRecords = @()
    if ($null -ne $Groups) {
        if ($Groups -is [System.Collections.IDictionary]) {
            $groupRecords = @($Groups.Values)
        }
        elseif (($Groups -is [System.Collections.IEnumerable]) -and -not ($Groups -is [string])) {
            $groupRecords = @($Groups)
        }
    }

    foreach ($groupRecord in $groupRecords) {
        if (-not $groupRecord) {
            continue
        }

        $groupId = [string](Get-ArrayaObjectValue -Object $groupRecord -Names @('ID', 'Id'))
        if ([string]::IsNullOrWhiteSpace($groupId)) {
            continue
        }

        $groupMetadataLookup[$groupId.Trim().ToLowerInvariant()] = [pscustomobject]@{
            DisplayName = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $groupRecord -Names @('DisplayName')) -Default $groupId
            GroupType = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $groupRecord -Names @('GroupType', 'MembershipType')) -Default 'Group'
            MemberCount = Get-ArrayaObjectValue -Object $groupRecord -Names @('MemberCount')
        }
    }

    $addUserReason = {
        param(
            [Parameter(Mandatory = $true)][string]$UserId,
            [Parameter(Mandatory = $true)][string]$PolicyName,
            [Parameter(Mandatory = $true)][string]$Reason
        )

        if (-not $userExclusionReasonLookup.ContainsKey($UserId)) {
            $userExclusionReasonLookup[$UserId] = New-Object System.Collections.Generic.List[string]
        }
        if (-not $userExclusionPolicyLookup.ContainsKey($UserId)) {
            $userExclusionPolicyLookup[$UserId] = New-Object System.Collections.Generic.List[string]
        }

        if (-not [string]::IsNullOrWhiteSpace($Reason) -and -not $userExclusionReasonLookup[$UserId].Contains($Reason)) {
            $userExclusionReasonLookup[$UserId].Add($Reason) | Out-Null
        }
        if (-not [string]::IsNullOrWhiteSpace($PolicyName) -and -not $userExclusionPolicyLookup[$UserId].Contains($PolicyName)) {
            $userExclusionPolicyLookup[$UserId].Add($PolicyName) | Out-Null
        }
    }

    $addUserPolicyState = {
        param(
            [Parameter(Mandatory = $true)][hashtable]$Lookup,
            [Parameter(Mandatory = $true)][string]$UserId,
            [Parameter(Mandatory = $true)][string]$PolicyName
        )

        if (-not $Lookup.ContainsKey($UserId)) {
            $Lookup[$UserId] = New-Object System.Collections.Generic.List[string]
        }

        if (-not [string]::IsNullOrWhiteSpace($PolicyName) -and -not $Lookup[$UserId].Contains($PolicyName)) {
            $Lookup[$UserId].Add($PolicyName) | Out-Null
        }
    }

    $addScopeReviewRow = {
        param(
            [Parameter(Mandatory = $true)][string]$PolicyName,
            [Parameter(Mandatory = $true)][string]$ScopeType,
            [Parameter(Mandatory = $true)][string]$ObjectType,
            [Parameter(Mandatory = $true)][string]$Identifier,
            [Parameter(Mandatory = $false)][string]$DisplayName,
            [Parameter(Mandatory = $false)]$AffectedEnabledUsers,
            [Parameter(Mandatory = $false)]$DirectoryMemberCount,
            [Parameter(Mandatory = $false)][string]$Notes
        )

        if ([string]::IsNullOrWhiteSpace($Identifier)) {
            return
        }

        $rowKey = ('{0}|{1}|{2}|{3}' -f $PolicyName, $ScopeType, $ObjectType, $Identifier).ToLowerInvariant()
        if ($scopeReviewKeyLookup.ContainsKey($rowKey)) {
            return
        }

        $scopeReviewKeyLookup[$rowKey] = $true
        $scopeReviewRows.Add([pscustomobject]@{
            PolicyName = $PolicyName
            ScopeType = $ScopeType
            ObjectType = $ObjectType
            DisplayName = $(if ([string]::IsNullOrWhiteSpace($DisplayName)) { $Identifier } else { $DisplayName })
            Identifier = $Identifier
            AffectedEnabledUsers = $AffectedEnabledUsers
            DirectoryMemberCount = $DirectoryMemberCount
            Notes = $Notes
        }) | Out-Null
    }

    foreach ($policy in @($EnabledMfaPolicies)) {
        if (-not $policy) {
            continue
        }

        $policyName = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $policy -Names @('DisplayName', 'Name')) -Default 'Unnamed enabled MFA policy'

        $includedUsers = Convert-ToAssessmentStringArray -Value (Get-ArrayaObjectValue -Object $policy -Names @('IncludedUsers'))
        $excludedUsers = Convert-ToAssessmentStringArray -Value (Get-ArrayaObjectValue -Object $policy -Names @('ExcludedUsers'))
        $includedGroups = Convert-ToAssessmentStringArray -Value (Get-ArrayaObjectValue -Object $policy -Names @('IncludedGroups'))
        $excludedGroups = Convert-ToAssessmentStringArray -Value (Get-ArrayaObjectValue -Object $policy -Names @('ExcludedGroups'))
        $includedRoles = Convert-ToAssessmentStringArray -Value (Get-ArrayaObjectValue -Object $policy -Names @('IncludedRoles'))
        $excludedRoles = Convert-ToAssessmentStringArray -Value (Get-ArrayaObjectValue -Object $policy -Names @('ExcludedRoles'))
        $includeGuestsOrExternalValue = Get-ArrayaObjectValue -Object $policy -Names @('IncludeGuestsOrExternalUsers')
        $excludeGuestsOrExternalValue = Get-ArrayaObjectValue -Object $policy -Names @('ExcludeGuestsOrExternalUsers')
        $includeGuestsOrExternalConfigured = Test-AssessmentMeaningfulNestedValue -Value $includeGuestsOrExternalValue
        $excludeGuestsOrExternalConfigured = Test-AssessmentMeaningfulNestedValue -Value $excludeGuestsOrExternalValue

        $policyTargetedUserIds = @{}
        $hasIncludeScope = $false

        if (@($includedUsers | Where-Object { $_ -ieq 'All' }).Count -gt 0) {
            Add-AssessmentUserIdsToSet -Set $policyTargetedUserIds -UserIds @($enabledReviewedUserIdSet.Keys)
            $hasIncludeScope = $true
        }

        foreach ($includedUserId in @($includedUsers | Where-Object { $_ -notmatch '^(?i)(All|None|GuestsOrExternalUsers)$' })) {
            $normalizedIncludedUserId = $includedUserId.Trim().ToLowerInvariant()
            if ($enabledUserIdLookup.ContainsKey($normalizedIncludedUserId)) {
                $policyTargetedUserIds[[string]$enabledUserIdLookup[$normalizedIncludedUserId]] = $true
                $hasIncludeScope = $true
            }
        }

        if ($includedGroups.Count -gt 0) {
            $coverageSummary.GroupTargetedPolicyCount++
            $hasIncludeScope = $true
            foreach ($includedGroupId in $includedGroups) {
                $resolvedIncludedGroupUserIds = @(Get-AssessmentConditionalAccessGroupUserIds -GroupId $includedGroupId -GroupUserLookup $groupUserLookup -EnabledUserIdLookup $enabledUserIdLookup -OperationName $OperationName)
                Add-AssessmentUserIdsToSet -Set $policyTargetedUserIds -UserIds $resolvedIncludedGroupUserIds
                $groupMetadata = $null
                $normalizedIncludedGroupId = $includedGroupId.Trim().ToLowerInvariant()
                if ($groupMetadataLookup.ContainsKey($normalizedIncludedGroupId)) {
                    $groupMetadata = $groupMetadataLookup[$normalizedIncludedGroupId]
                }
                & $addScopeReviewRow -PolicyName $policyName -ScopeType 'Include' -ObjectType 'Group' -Identifier $includedGroupId -DisplayName $(if ($groupMetadata) { $groupMetadata.DisplayName } else { $includedGroupId }) -AffectedEnabledUsers $resolvedIncludedGroupUserIds.Count -DirectoryMemberCount $(if ($groupMetadata) { $groupMetadata.MemberCount } else { $null }) -Notes 'Enabled MFA enforcement targets this group.'
            }
        }

        if ($includedRoles.Count -gt 0) {
            $coverageSummary.RoleTargetedPolicyCount++
            $hasIncludeScope = $true
            $resolvedIncludedRoleUserIds = @(Get-AssessmentConditionalAccessRoleUserIds -RoleTemplateIds $includedRoles -RoleTemplateLookup $roleTemplateLookup -RoleUserLookup $roleUserLookup -EnabledUserIdLookup $enabledUserIdLookup -OperationName $OperationName)
            Add-AssessmentUserIdsToSet -Set $policyTargetedUserIds -UserIds $resolvedIncludedRoleUserIds
            foreach ($includedRoleId in $includedRoles) {
                $roleDisplayName = $includedRoleId
                $normalizedIncludedRoleId = $includedRoleId.Trim().ToLowerInvariant()
                if ($roleTemplateLookup.ContainsKey($normalizedIncludedRoleId)) {
                    $roleDisplayName = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object (@($roleTemplateLookup[$normalizedIncludedRoleId] | Select-Object -First 1)) -Names @('displayName', 'DisplayName')) -Default $includedRoleId
                }
                & $addScopeReviewRow -PolicyName $policyName -ScopeType 'Include' -ObjectType 'DirectoryRole' -Identifier $includedRoleId -DisplayName $roleDisplayName -AffectedEnabledUsers $resolvedIncludedRoleUserIds.Count -Notes 'Enabled MFA enforcement targets this directory role scope.'
            }
        }

        if (
            $includeGuestsOrExternalConfigured -or
            @($includedUsers | Where-Object { $_ -match '(?i)guest|external' }).Count -gt 0
        ) {
            Add-AssessmentUserIdsToSet -Set $policyTargetedUserIds -UserIds @($enabledGuestUserIdSet.Keys)
            $hasIncludeScope = $true
            & $addScopeReviewRow -PolicyName $policyName -ScopeType 'Include' -ObjectType 'GuestOrExternal' -Identifier 'GuestsOrExternalUsers' -DisplayName 'Guests or external users' -AffectedEnabledUsers @($enabledGuestUserIdSet.Keys).Count -Notes 'Enabled MFA enforcement targets guest or external-user scope.'
        }

        if (-not $hasIncludeScope) {
            continue
        }

        foreach ($includedTargetUserId in @($policyTargetedUserIds.Keys)) {
            & $addUserPolicyState -Lookup $userIncludedPolicyLookup -UserId ([string]$includedTargetUserId) -PolicyName $policyName
        }

        if (@($excludedUsers | Where-Object { $_ -ieq 'All' }).Count -gt 0) {
            foreach ($currentlyTargetedUserId in @($policyTargetedUserIds.Keys)) {
                & $addUserReason -UserId $currentlyTargetedUserId -PolicyName $policyName -Reason ("Excluded from enabled MFA policy '{0}' by an 'All users' exclusion." -f $policyName)
            }
            $policyTargetedUserIds.Clear()
        }
        else {
            foreach ($excludedUserId in @($excludedUsers | Where-Object { $_ -notmatch '^(?i)(All|None|GuestsOrExternalUsers)$' })) {
                $normalizedExcludedUserId = $excludedUserId.Trim().ToLowerInvariant()
                if ($enabledUserIdLookup.ContainsKey($normalizedExcludedUserId)) {
                    $resolvedExcludedUserId = [string]$enabledUserIdLookup[$normalizedExcludedUserId]
                    & $addUserReason -UserId $resolvedExcludedUserId -PolicyName $policyName -Reason ("Excluded directly in enabled MFA policy '{0}'." -f $policyName)
                    $policyTargetedUserIds.Remove($resolvedExcludedUserId) | Out-Null
                }
            }
        }

        foreach ($excludedGroupId in $excludedGroups) {
            $resolvedExcludedGroupUserIds = @(Get-AssessmentConditionalAccessGroupUserIds -GroupId $excludedGroupId -GroupUserLookup $groupUserLookup -EnabledUserIdLookup $enabledUserIdLookup -OperationName $OperationName)
            foreach ($excludedResolvedUserId in $resolvedExcludedGroupUserIds) {
                $groupMetadata = $null
                $normalizedExcludedGroupId = $excludedGroupId.Trim().ToLowerInvariant()
                if ($groupMetadataLookup.ContainsKey($normalizedExcludedGroupId)) {
                    $groupMetadata = $groupMetadataLookup[$normalizedExcludedGroupId]
                }
                $excludedGroupLabel = if ($groupMetadata) { $groupMetadata.DisplayName } else { $excludedGroupId }
                & $addUserReason -UserId ([string]$excludedResolvedUserId) -PolicyName $policyName -Reason ("Excluded through group '{0}' in enabled MFA policy '{1}'." -f $excludedGroupLabel, $policyName)
                $policyTargetedUserIds.Remove([string]$excludedResolvedUserId) | Out-Null
            }
            & $addScopeReviewRow -PolicyName $policyName -ScopeType 'Exclude' -ObjectType 'Group' -Identifier $excludedGroupId -DisplayName $(if ($groupMetadata) { $groupMetadata.DisplayName } else { $excludedGroupId }) -AffectedEnabledUsers $resolvedExcludedGroupUserIds.Count -DirectoryMemberCount $(if ($groupMetadata) { $groupMetadata.MemberCount } else { $null }) -Notes 'Members of this group are excluded from the enabled MFA enforcement policy scope.'
        }

        $resolvedExcludedRoleUserIds = @(Get-AssessmentConditionalAccessRoleUserIds -RoleTemplateIds $excludedRoles -RoleTemplateLookup $roleTemplateLookup -RoleUserLookup $roleUserLookup -EnabledUserIdLookup $enabledUserIdLookup -OperationName $OperationName)
        foreach ($excludedResolvedUserId in $resolvedExcludedRoleUserIds) {
            & $addUserReason -UserId ([string]$excludedResolvedUserId) -PolicyName $policyName -Reason ("Excluded through directory role scope in enabled MFA policy '{0}'." -f $policyName)
            $policyTargetedUserIds.Remove([string]$excludedResolvedUserId) | Out-Null
        }
        foreach ($excludedRoleId in $excludedRoles) {
            $roleDisplayName = $excludedRoleId
            $normalizedExcludedRoleId = $excludedRoleId.Trim().ToLowerInvariant()
            if ($roleTemplateLookup.ContainsKey($normalizedExcludedRoleId)) {
                $roleDisplayName = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object (@($roleTemplateLookup[$normalizedExcludedRoleId] | Select-Object -First 1)) -Names @('displayName', 'DisplayName')) -Default $excludedRoleId
            }
            & $addScopeReviewRow -PolicyName $policyName -ScopeType 'Exclude' -ObjectType 'DirectoryRole' -Identifier $excludedRoleId -DisplayName $roleDisplayName -AffectedEnabledUsers $resolvedExcludedRoleUserIds.Count -Notes 'Members of this directory role scope are excluded from the enabled MFA enforcement policy scope.'
        }

        if (
            $excludeGuestsOrExternalConfigured -or
            @($excludedUsers | Where-Object { $_ -match '(?i)guest|external' }).Count -gt 0
        ) {
            foreach ($guestUserId in @($enabledGuestUserIdSet.Keys)) {
                & $addUserReason -UserId ([string]$guestUserId) -PolicyName $policyName -Reason ("Excluded through guest or external-user scope in enabled MFA policy '{0}'." -f $policyName)
                $policyTargetedUserIds.Remove([string]$guestUserId) | Out-Null
            }
            & $addScopeReviewRow -PolicyName $policyName -ScopeType 'Exclude' -ObjectType 'GuestOrExternal' -Identifier 'GuestsOrExternalUsers' -DisplayName 'Guests or external users' -AffectedEnabledUsers @($enabledGuestUserIdSet.Keys).Count -Notes 'Guest or external users are excluded from the enabled MFA enforcement policy scope.'
        }

        foreach ($coveredUserId in @($policyTargetedUserIds.Keys)) {
            & $addUserPolicyState -Lookup $userCoveredPolicyLookup -UserId ([string]$coveredUserId) -PolicyName $policyName
        }
        Add-AssessmentUserIdsToSet -Set $coveredUserIdSet -UserIds @($policyTargetedUserIds.Keys)
    }

    $coveredMemberUsers = @(@($coveredUserIdSet.Keys) | Where-Object { $enabledMemberUserIdSet.ContainsKey([string]$_) })
    $coveredGuestUsers = @(@($coveredUserIdSet.Keys) | Where-Object { $enabledGuestUserIdSet.ContainsKey([string]$_) })
    $guestCoveredPolicyNameLookup = @{}
    foreach ($coveredGuestUserId in $coveredGuestUsers) {
        if (-not $userCoveredPolicyLookup.ContainsKey([string]$coveredGuestUserId)) {
            continue
        }

        foreach ($policyName in @($userCoveredPolicyLookup[[string]$coveredGuestUserId])) {
            $policyNameText = Convert-ToAssessmentDisplayText -Value $policyName -Default ''
            if (-not [string]::IsNullOrWhiteSpace($policyNameText) -and -not $guestCoveredPolicyNameLookup.ContainsKey($policyNameText)) {
                $guestCoveredPolicyNameLookup[$policyNameText] = $true
            }
        }
    }

    $guestExplicitScopePolicyNameLookup = @{}
    foreach ($scopeReviewRow in @($scopeReviewRows | Where-Object { $null -ne $_ })) {
        $scopeType = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $scopeReviewRow -Names @('ScopeType')) -Default ''
        $objectType = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $scopeReviewRow -Names @('ObjectType')) -Default ''
        if ($scopeType -ne 'Include' -or $objectType -ne 'GuestOrExternal') {
            continue
        }

        $scopePolicyName = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $scopeReviewRow -Names @('PolicyName')) -Default ''
        if (-not [string]::IsNullOrWhiteSpace($scopePolicyName) -and -not $guestExplicitScopePolicyNameLookup.ContainsKey($scopePolicyName)) {
            $guestExplicitScopePolicyNameLookup[$scopePolicyName] = $true
        }
    }

    $coverageSummary.UsersCoveredByEnabledMfaPolicies = @($coveredUserIdSet.Keys).Count
    $coverageSummary.UserCoveragePercent = if ($enabledReviewedUsers.Count -gt 0) { [math]::Round((@($coveredUserIdSet.Keys).Count / $enabledReviewedUsers.Count) * 100, 1) } else { $null }
    $coverageSummary.MemberUsersCoveredByEnabledMfaPolicies = $coveredMemberUsers.Count
    $coverageSummary.MemberUserCoveragePercent = if ($enabledMemberUsers.Count -gt 0) { [math]::Round(($coveredMemberUsers.Count / $enabledMemberUsers.Count) * 100, 1) } else { $null }
    $coverageSummary.GuestUsersCoveredByEnabledMfaPolicies = $coveredGuestUsers.Count
    $coverageSummary.GuestUserCoveragePercent = if ($enabledGuestUsers.Count -gt 0) { [math]::Round(($coveredGuestUsers.Count / $enabledGuestUsers.Count) * 100, 1) } else { $null }
    $coverageSummary.GuestCoveredPolicyCount = @($guestCoveredPolicyNameLookup.Keys).Count
    $coverageSummary.GuestCoveredPolicyNames = @($guestCoveredPolicyNameLookup.Keys | Sort-Object)
    $coverageSummary.GuestExplicitScopePolicyCount = @($guestExplicitScopePolicyNameLookup.Keys).Count
    $coverageSummary.GuestExplicitScopePolicyNames = @($guestExplicitScopePolicyNameLookup.Keys | Sort-Object)
    $coverageSummary.CoverageCalculationNote = 'Estimate is based on enabled reviewed users and enabled Conditional Access policies that require MFA, whether through built-in MFA or authentication strength, expanded across direct users, targeted groups, targeted roles, and guest/external-user scope where supported.'

    if ($IncludeDetails) {
        $uncoveredUserIds = @(
            @($enabledReviewedUserIdSet.Keys) |
                Where-Object { -not $coveredUserIdSet.ContainsKey([string]$_) }
        )

        foreach ($uncoveredUserId in $uncoveredUserIds) {
            $userRecord = if ($enabledUserRecordLookup.ContainsKey($uncoveredUserId)) { $enabledUserRecordLookup[$uncoveredUserId] } else { $null }
            $displayName = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $userRecord -Names @('DisplayName')) -Default 'Unnamed user'
            $userPrincipalName = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $userRecord -Names @('UserPrincipalName')) -Default $uncoveredUserId
            $isGuestUser = $enabledGuestUserIdSet.ContainsKey($uncoveredUserId)
            $reportedUserType = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $userRecord -Names @('UserType')) -Default ''
            $userType = if ($isGuestUser) {
                'Guest'
            }
            elseif ([string]::IsNullOrWhiteSpace($reportedUserType)) {
                'Member'
            }
            else {
                $reportedUserType
            }
            $includedByPolicies = if ($userIncludedPolicyLookup.ContainsKey($uncoveredUserId)) { @($userIncludedPolicyLookup[$uncoveredUserId]) } else { @() }
            $excludedByPolicies = if ($userExclusionPolicyLookup.ContainsKey($uncoveredUserId)) { @($userExclusionPolicyLookup[$uncoveredUserId]) } else { @() }
            $relatedPolicies = if ($excludedByPolicies.Count -gt 0) { $excludedByPolicies -join '; ' } elseif ($includedByPolicies.Count -gt 0) { $includedByPolicies -join '; ' } else { '' }
            $gapReason = if ($includedByPolicies.Count -gt 0 -and $userExclusionReasonLookup.ContainsKey($uncoveredUserId)) {
                @($userExclusionReasonLookup[$uncoveredUserId]) -join '; '
            }
            else {
                'User is outside the include scope of all enabled Conditional Access policies that currently require MFA.'
            }

            $gapCategory = if ($includedByPolicies.Count -gt 0 -and $excludedByPolicies.Count -gt 0) {
                'Excluded from all enabled MFA CA policies that otherwise target the user'
            }
            else {
                'Outside enabled MFA CA include scope'
            }

            $gapUserRows.Add([pscustomobject]@{
                DisplayName = $displayName
                UserPrincipalName = $userPrincipalName
                UserType = $userType
                DirectoryObjectId = $uncoveredUserId
                GapCategory = $gapCategory
                GapReason = $gapReason
                RelatedPolicies = $relatedPolicies
                IncludedPolicyCount = $includedByPolicies.Count
                ExcludedPolicyCount = $excludedByPolicies.Count
                AccountEnabled = Convert-ToAssessmentBoolean (Get-ArrayaObjectValue -Object $userRecord -Names @('AccountEnabled'))
                LastSignInDateTime = Get-ArrayaObjectValue -Object $userRecord -Names @('LastSignInDateTime')
            }) | Out-Null
        }

        return [pscustomobject]@{
            Summary = [pscustomobject]$coverageSummary
            GapUsers = @($gapUserRows | Sort-Object DisplayName, UserPrincipalName)
            ScopeReview = @($scopeReviewRows | Sort-Object PolicyName, ScopeType, ObjectType, DisplayName)
        }
    }

    return [pscustomobject]$coverageSummary
}

function Get-AssessmentAdminMfaReview {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [System.Collections.IDictionary]$Admins = $null,
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [System.Collections.IDictionary]$Users = $null,
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [System.Collections.IDictionary]$MfaRegistrationDetails = $null,
        [Parameter(Mandatory = $false)]
        $MfaCoverageAnalysis = $null,
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [bool]$SecurityDefaultsEnabled = $false,
        [Parameter(Mandatory = $false)]
        [int]$EnabledMfaPolicyCount = 0,
        [Parameter(Mandatory = $false)]
        [int]$ReportOnlyMfaPolicyCount = 0
    )

    $summary = [ordered]@{
        TotalAdminUsersReviewed                 = 0
        EnabledAdminUsersReviewed               = 0
        AdminUsersMfaRegistrationValidated      = 0
        AdminUsersRegisteredForMfa              = 0
        AdminUsersNotRegisteredForMfa           = 0
        AdminUsersMfaEnforcementReviewed        = 0
        AdminUsersCoveredByMfaEnforcement       = 0
        AdminUsersNotCoveredByMfaEnforcement    = 0
        GuestAdminUsersReviewed                 = 0
        GuestAdminUsersNotCoveredByMfaEnforcement = 0
        CollectionState                         = 'Not validated from the reviewed data'
    }

    $registrationGapRows = New-Object System.Collections.Generic.List[object]
    $enforcementGapRows = New-Object System.Collections.Generic.List[object]

    if ($null -eq $Admins -or $Admins.Count -eq 0) {
        return [pscustomobject]@{
            Summary = [pscustomobject]$summary
            RegistrationGaps = @()
            EnforcementGaps = @()
        }
    }

    $reviewedUserById = @{}
    $reviewedUserByUpn = @{}
    if ($null -ne $Users) {
        $userRecords = if ($Users -is [System.Collections.IDictionary]) { @($Users.Values) } else { @($Users) }
        foreach ($userRecord in $userRecords) {
            if (-not $userRecord) { continue }
            $userId = [string](Get-ArrayaObjectValue -Object $userRecord -Names @('Id', 'ID'))
            $userUpn = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $userRecord -Names @('UserPrincipalName')) -Default ''
            if (-not [string]::IsNullOrWhiteSpace($userId)) {
                $reviewedUserById[$userId.Trim().ToLowerInvariant()] = $userRecord
            }
            if (-not [string]::IsNullOrWhiteSpace($userUpn)) {
                $reviewedUserByUpn[$userUpn.Trim().ToLowerInvariant()] = $userRecord
            }
        }
    }

    $registrationByUpn = @{}
    if ($null -ne $MfaRegistrationDetails) {
        $registrationRecords = if ($MfaRegistrationDetails -is [System.Collections.IDictionary]) { @($MfaRegistrationDetails.Values) } else { @($MfaRegistrationDetails) }
        foreach ($registrationRecord in $registrationRecords) {
            if (-not $registrationRecord) { continue }
            $registrationUpn = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $registrationRecord -Names @('UserPrincipalName')) -Default ''
            if (-not [string]::IsNullOrWhiteSpace($registrationUpn)) {
                $registrationByUpn[$registrationUpn.Trim().ToLowerInvariant()] = $registrationRecord
            }
        }
    }

    $gapUsers = if ($MfaCoverageAnalysis -and $MfaCoverageAnalysis.PSObject.Properties['GapUsers']) { @($MfaCoverageAnalysis.GapUsers) } else { @() }
    $gapById = @{}
    $gapByUpn = @{}
    foreach ($gapUser in $gapUsers) {
        if (-not $gapUser) { continue }
        $gapId = [string](Get-ArrayaObjectValue -Object $gapUser -Names @('DirectoryObjectId'))
        $gapUpn = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $gapUser -Names @('UserPrincipalName')) -Default ''
        if (-not [string]::IsNullOrWhiteSpace($gapId)) {
            $gapById[$gapId.Trim().ToLowerInvariant()] = $gapUser
        }
        if (-not [string]::IsNullOrWhiteSpace($gapUpn)) {
            $gapByUpn[$gapUpn.Trim().ToLowerInvariant()] = $gapUser
        }
    }

    $adminUserLookup = @{}
    $adminRecords = if ($Admins -is [System.Collections.IDictionary]) { @($Admins.Values) } else { @($Admins) }
    foreach ($adminRecord in $adminRecords) {
        if (-not $adminRecord) { continue }
        $adminUpn = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $adminRecord -Names @('UserPrincipalName')) -Default ''
        $adminObjectType = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $adminRecord -Names @('ObjectType')) -Default ''
        $adminObjectId = [string](Get-ArrayaObjectValue -Object $adminRecord -Names @('DirectoryObjectId', 'Id', 'ID'))
        $isUserAdmin = (-not [string]::IsNullOrWhiteSpace($adminUpn)) -or ($adminObjectType -match '(?i)user')
        if (-not $isUserAdmin) {
            continue
        }

        $adminLookupKey = if (-not [string]::IsNullOrWhiteSpace($adminObjectId)) {
            $adminObjectId.Trim().ToLowerInvariant()
        }
        elseif (-not [string]::IsNullOrWhiteSpace($adminUpn)) {
            $adminUpn.Trim().ToLowerInvariant()
        }
        else {
            continue
        }

        if (-not $adminUserLookup.ContainsKey($adminLookupKey)) {
            $adminUserLookup[$adminLookupKey] = $adminRecord
        }
    }

    $summary.TotalAdminUsersReviewed = $adminUserLookup.Count

    foreach ($adminKey in @($adminUserLookup.Keys)) {
        $adminRecord = $adminUserLookup[$adminKey]
        $adminUpn = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $adminRecord -Names @('UserPrincipalName')) -Default ''
        $adminDisplayName = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $adminRecord -Names @('DisplayName')) -Default 'Unnamed admin'
        $adminRole = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $adminRecord -Names @('Role')) -Default 'Privileged role'
        $adminObjectId = [string](Get-ArrayaObjectValue -Object $adminRecord -Names @('DirectoryObjectId', 'Id', 'ID'))
        $accountEnabled = Convert-ToAssessmentBoolean (Get-ArrayaObjectValue -Object $adminRecord -Names @('AccountEnabled'))
        $isGuestAdmin = (Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $adminRecord -Names @('UserType')) -Default '').ToLowerInvariant() -eq 'guest' -or $adminUpn -like '*#EXT#*'
        $registrationRecord = $null
        if (-not [string]::IsNullOrWhiteSpace($adminUpn) -and $registrationByUpn.ContainsKey($adminUpn.Trim().ToLowerInvariant())) {
            $registrationRecord = $registrationByUpn[$adminUpn.Trim().ToLowerInvariant()]
        }

        $reviewedUserRecord = $null
        if (-not [string]::IsNullOrWhiteSpace($adminObjectId) -and $reviewedUserById.ContainsKey($adminObjectId.Trim().ToLowerInvariant())) {
            $reviewedUserRecord = $reviewedUserById[$adminObjectId.Trim().ToLowerInvariant()]
        }
        elseif (-not [string]::IsNullOrWhiteSpace($adminUpn) -and $reviewedUserByUpn.ContainsKey($adminUpn.Trim().ToLowerInvariant())) {
            $reviewedUserRecord = $reviewedUserByUpn[$adminUpn.Trim().ToLowerInvariant()]
        }

        $coverageReviewed = $null -ne $reviewedUserRecord -and (Convert-ToAssessmentBoolean (Get-ArrayaObjectValue -Object $reviewedUserRecord -Names @('AccountEnabled'))) -ne $false
        if ($accountEnabled -ne $false) {
            $summary.EnabledAdminUsersReviewed++
        }
        if ($isGuestAdmin) {
            $summary.GuestAdminUsersReviewed++
        }

        $isMfaRegistered = $null
        $mfaRegistrationState = 'Not validated from registration report'
        $methodsRegistered = $null
        $defaultMfaMethod = $null
        if ($null -ne $registrationRecord) {
            $summary.AdminUsersMfaRegistrationValidated++
            $isMfaRegistered = Convert-ToAssessmentBoolean (Get-ArrayaObjectValue -Object $registrationRecord -Names @('IsMfaRegistered'))
            $methodsRegistered = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $registrationRecord -Names @('MethodsRegistered')) -Default $null
            $defaultMfaMethod = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $registrationRecord -Names @('DefaultMfaMethod')) -Default $null
            if ($isMfaRegistered -eq $true) {
                $summary.AdminUsersRegisteredForMfa++
                $mfaRegistrationState = 'Registered'
            }
            elseif ($isMfaRegistered -eq $false) {
                $summary.AdminUsersNotRegisteredForMfa++
                $mfaRegistrationState = 'Not registered'
            }
        }

        $gapRecord = $null
        if (-not [string]::IsNullOrWhiteSpace($adminObjectId) -and $gapById.ContainsKey($adminObjectId.Trim().ToLowerInvariant())) {
            $gapRecord = $gapById[$adminObjectId.Trim().ToLowerInvariant()]
        }
        elseif (-not [string]::IsNullOrWhiteSpace($adminUpn) -and $gapByUpn.ContainsKey($adminUpn.Trim().ToLowerInvariant())) {
            $gapRecord = $gapByUpn[$adminUpn.Trim().ToLowerInvariant()]
        }

        $mfaEnforcementState = 'Not validated from the reviewed MFA coverage set'
        $mfaEnforced = $null
        $gapCategory = $null
        $gapReason = $null
        $relatedPolicies = $null

        if ($accountEnabled -eq $false) {
            $mfaEnforcementState = 'Account is disabled'
            $mfaEnforced = $false
        }
        elseif ($SecurityDefaultsEnabled -eq $true) {
            $summary.AdminUsersMfaEnforcementReviewed++
            $summary.AdminUsersCoveredByMfaEnforcement++
            $mfaEnforcementState = 'Enforced by Security Defaults'
            $mfaEnforced = $true
        }
        elseif ($coverageReviewed) {
            $summary.AdminUsersMfaEnforcementReviewed++
            if ($null -ne $gapRecord) {
                $summary.AdminUsersNotCoveredByMfaEnforcement++
                if ($isGuestAdmin) {
                    $summary.GuestAdminUsersNotCoveredByMfaEnforcement++
                }
                $mfaEnforced = $false
                $gapCategory = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $gapRecord -Names @('GapCategory')) -Default 'Not clearly enforced'
                $gapReason = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $gapRecord -Names @('GapReason')) -Default 'Not validated from the reviewed data'
                $relatedPolicies = Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $gapRecord -Names @('RelatedPolicies')) -Default ''
                $mfaEnforcementState = 'Not covered by the current enabled MFA enforcement baseline'
            }
            elseif ($EnabledMfaPolicyCount -gt 0) {
                $summary.AdminUsersCoveredByMfaEnforcement++
                $mfaEnforced = $true
                $mfaEnforcementState = 'Covered by the current enabled MFA enforcement baseline'
            }
            else {
                $summary.AdminUsersNotCoveredByMfaEnforcement++
                if ($isGuestAdmin) {
                    $summary.GuestAdminUsersNotCoveredByMfaEnforcement++
                }
                $mfaEnforced = $false
                $gapCategory = 'Active MFA enforcement not clearly detected'
                $gapReason = if ($ReportOnlyMfaPolicyCount -gt 0) {
                    'MFA appears staged in report-only Conditional Access, but active enforcement was not clearly detected for this admin account.'
                }
                else {
                    'Active MFA enforcement was not clearly detected in the reviewed policy baseline for this admin account.'
                }
                $mfaEnforcementState = 'Active MFA enforcement not clearly detected'
            }
        }

        Add-AssessmentNotePropertyIfPossible -Object $adminRecord -Name 'MfaRegistered' -Value $isMfaRegistered
        Add-AssessmentNotePropertyIfPossible -Object $adminRecord -Name 'MfaRegistrationState' -Value $mfaRegistrationState
        Add-AssessmentNotePropertyIfPossible -Object $adminRecord -Name 'MfaMethodsRegistered' -Value $methodsRegistered
        Add-AssessmentNotePropertyIfPossible -Object $adminRecord -Name 'DefaultMfaMethod' -Value $defaultMfaMethod
        Add-AssessmentNotePropertyIfPossible -Object $adminRecord -Name 'MfaEnforced' -Value $mfaEnforced
        Add-AssessmentNotePropertyIfPossible -Object $adminRecord -Name 'MfaEnforcementState' -Value $mfaEnforcementState
        Add-AssessmentNotePropertyIfPossible -Object $adminRecord -Name 'MfaCoverageReviewed' -Value $coverageReviewed
        Add-AssessmentNotePropertyIfPossible -Object $adminRecord -Name 'MfaGapCategory' -Value $gapCategory
        Add-AssessmentNotePropertyIfPossible -Object $adminRecord -Name 'MfaGapReason' -Value $gapReason
        Add-AssessmentNotePropertyIfPossible -Object $adminRecord -Name 'MfaRelatedPolicies' -Value $relatedPolicies

        if ($accountEnabled -ne $false -and $mfaRegistrationState -eq 'Not registered') {
            $registrationGapRows.Add([pscustomobject]@{
                DisplayName = $adminDisplayName
                UserPrincipalName = $adminUpn
                Role = $adminRole
                AccountEnabled = $accountEnabled
                UserType = $(if ($isGuestAdmin) { 'Guest' } else { 'Member' })
                MfaRegistrationState = $mfaRegistrationState
                MethodsRegistered = $methodsRegistered
                DefaultMfaMethod = $defaultMfaMethod
                LastSignInDateTime = Get-ArrayaObjectValue -Object $adminRecord -Names @('LastSignInDateTime')
            }) | Out-Null
        }

        if ($accountEnabled -ne $false -and $mfaEnforced -eq $false -and -not [string]::Equals($mfaEnforcementState, 'Not validated from the reviewed MFA coverage set', [System.StringComparison]::OrdinalIgnoreCase)) {
            $enforcementGapRows.Add([pscustomobject]@{
                DisplayName = $adminDisplayName
                UserPrincipalName = $adminUpn
                Role = $adminRole
                AccountEnabled = $accountEnabled
                UserType = $(if ($isGuestAdmin) { 'Guest' } else { 'Member' })
                MfaEnforcementState = $mfaEnforcementState
                GapCategory = $gapCategory
                GapReason = $gapReason
                RelatedPolicies = $relatedPolicies
                LastSignInDateTime = Get-ArrayaObjectValue -Object $adminRecord -Names @('LastSignInDateTime')
            }) | Out-Null
        }
    }

    $summary.CollectionState = 'Collected'
    return [pscustomobject]@{
        Summary = [pscustomobject]$summary
        RegistrationGaps = @($registrationGapRows | Sort-Object DisplayName, UserPrincipalName)
        EnforcementGaps = @($enforcementGapRows | Sort-Object DisplayName, UserPrincipalName)
    }
}

function ConvertFrom-AssessmentJwtPayload {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [string]$Token
    )

    if ([string]::IsNullOrWhiteSpace($Token)) {
        return $null
    }

    $tokenParts = $Token.Split('.')
    if ($tokenParts.Count -lt 2) {
        return $null
    }

    $payloadSegment = $tokenParts[1].Replace('-', '+').Replace('_', '/')
    switch ($payloadSegment.Length % 4) {
        2 { $payloadSegment += '==' }
        3 { $payloadSegment += '=' }
    }

    try {
        $payloadBytes = [System.Convert]::FromBase64String($payloadSegment)
        $payloadJson = [System.Text.Encoding]::UTF8.GetString($payloadBytes)
        if ([string]::IsNullOrWhiteSpace($payloadJson)) {
            return $null
        }

        return ($payloadJson | ConvertFrom-Json -Depth 20)
    }
    catch {
        return $null
    }
}

function Get-AssessmentGrantedGraphPermissions {
    [CmdletBinding()]
    param()

    $permissionSet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

    $addPermission = {
        param([string]$PermissionName)

        if (-not [string]::IsNullOrWhiteSpace($PermissionName)) {
            $null = $permissionSet.Add($PermissionName.Trim())
        }
    }

    $mgContext = Get-MgContext -ErrorAction SilentlyContinue
    if ($mgContext -and $mgContext.Scopes) {
        foreach ($scope in @($mgContext.Scopes)) {
            & $addPermission ([string]$scope)
        }
    }

    $graphToken = $global:GraphToken
    if ([string]::IsNullOrWhiteSpace([string]$graphToken)) {
        try {
            $graphToken = Get-MgAccessToken -ErrorAction Stop
        }
        catch {}
    }

    $claims = ConvertFrom-AssessmentJwtPayload -Token $graphToken
    if ($claims) {
        $scpValue = $null
        if ($claims.PSObject.Properties['scp']) {
            $scpValue = [string]$claims.scp
        }

        if (-not [string]::IsNullOrWhiteSpace($scpValue)) {
            foreach ($scope in @($scpValue -split '\s+' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })) {
                & $addPermission ([string]$scope)
            }
        }

        $rolesValue = $null
        if ($claims.PSObject.Properties['roles']) {
            $rolesValue = $claims.roles
        }

        if ($rolesValue -is [System.Collections.IEnumerable] -and -not ($rolesValue -is [string])) {
            foreach ($role in @($rolesValue)) {
                & $addPermission ([string]$role)
            }
        }
        elseif (-not [string]::IsNullOrWhiteSpace([string]$rolesValue)) {
            & $addPermission ([string]$rolesValue)
        }
    }

    return [pscustomobject]@{
        PermissionSet = $permissionSet
        Permissions   = @($permissionSet | Sort-Object)
        Claims        = $claims
        Context       = $mgContext
    }
}

function Get-AssessmentGraphPreflightOperatorGuidance {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [object[]]$Failures,
        [Parameter(Mandatory = $false)]
        [object]$GrantedPermissionInfo
    )

    $guidance = New-Object System.Collections.Generic.List[string]
    $effectiveAuthenticationType = if (
        $script:AssessmentAuthWorkloadPlan -and
        $script:AssessmentAuthWorkloadPlan.PSObject.Properties['AuthenticationType'] -and
        -not [string]::IsNullOrWhiteSpace([string]$script:AssessmentAuthWorkloadPlan.AuthenticationType)
    ) {
        [string]$script:AssessmentAuthWorkloadPlan.AuthenticationType
    }
    else {
        'Unknown'
    }

    $graphFailures = @($Failures | Where-Object { [string]$_.Area -eq 'Graph' })
    if ($graphFailures.Count -eq 0) {
        return @()
    }

    if ([string]::Equals($effectiveAuthenticationType, 'Interactive', [System.StringComparison]::OrdinalIgnoreCase)) {
        $missingScopeNames = @(
            $graphFailures |
                ForEach-Object {
                    if ([string]$_.Details -match '^Missing Graph scope:\s*(?<scope>[^.]+(?:\.[^.]+)+)') {
                        $Matches['scope']
                    }
                } |
                Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } |
                Select-Object -Unique
        )
        if ($missingScopeNames.Count -gt 0) {
            $guidance.Add(("Missing delegated Graph scope(s): {0}" -f ($missingScopeNames -join ', '))) | Out-Null
            $guidance.Add('Run Disconnect-MgGraph, then rerun the assessment so Connect-MgGraph can request the missing scope(s). When prompted, sign in with an admin account that can consent to those scopes.') | Out-Null
            return @($guidance)
        }

        $guidance.Add('Interactive Graph auth note: access was denied by Microsoft Graph even though the token appeared to contain the requested scope. Confirm the signed-in account can use that permission in this tenant.') | Out-Null

        $requestedScopes = @()
        if ($script:AssessmentAuthWorkloadPlan) {
            $requestedScopes = @(Get-AssessmentGraphDelegatedScopes -WorkloadPlan $script:AssessmentAuthWorkloadPlan)
        }
        if ($requestedScopes.Count -gt 0) {
            $guidance.Add(("The assessment requested these delegated Graph scopes during Connect-MgGraph: {0}" -f ($requestedScopes -join ', '))) | Out-Null
        }
    }
    elseif ($effectiveAuthenticationType -in @('Certificate', 'ClientSecret')) {
        $guidance.Add(("App-only Graph auth note: confirm the app registration has admin consent for the listed Microsoft Graph application permissions in tenant {0}." -f $(if ([string]::IsNullOrWhiteSpace($TenantId)) { '(current)' } else { $TenantId }))) | Out-Null
    }

    if (@($graphFailures | Where-Object { [string]$_.Requirement -match 'Sites\.Read\.All' }).Count -gt 0) {
        if ([string]::Equals($effectiveAuthenticationType, 'Interactive', [System.StringComparison]::OrdinalIgnoreCase)) {
            $guidance.Add('For Sites.Read.All specifically, interactive preflight checks the delegated-safe /sites/root endpoint. A 403 here means the effective delegated token cannot read the tenant root site.') | Out-Null
        }
        else {
            $guidance.Add('For Sites.Read.All specifically, app-only preflight checks /sites/getAllSites. A 403 here means the effective app token cannot enumerate SharePoint/OneDrive site inventory.') | Out-Null
        }
    }

    return @($guidance)
}

function Test-AssessmentPermissionPreflight {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [object]$ConnectionResult,
        [Parameter(Mandatory = $false)]
        [ValidateSet('All', 'Graph', 'ExchangeOnline', 'Purview')]
        [string]$Workload = 'All'
    )

    $grantedPermissionInfo = Get-AssessmentGrantedGraphPermissions
    $grantedPermissions = $grantedPermissionInfo.PermissionSet
    $permissionFailures = New-Object System.Collections.Generic.List[psobject]
    $permissionWarnings = New-Object System.Collections.Generic.List[psobject]
    $effectiveAuthenticationType = if (
        $script:AssessmentAuthWorkloadPlan -and
        $script:AssessmentAuthWorkloadPlan.PSObject.Properties['AuthenticationType'] -and
        -not [string]::IsNullOrWhiteSpace([string]$script:AssessmentAuthWorkloadPlan.AuthenticationType)
    ) {
        [string]$script:AssessmentAuthWorkloadPlan.AuthenticationType
    }
    else {
        'Unknown'
    }
    $isInteractiveGraphAuth = [string]::Equals($effectiveAuthenticationType, 'Interactive', [System.StringComparison]::OrdinalIgnoreCase)
    $preflightNeedsReportsData = $true
    if (
        $script:AssessmentAuthWorkloadPlan -and
        $script:AssessmentAuthWorkloadPlan.PSObject.Properties['GraphScopePlan'] -and
        $script:AssessmentAuthWorkloadPlan.GraphScopePlan
    ) {
        $preflightNeedsReportsData = Get-AssessmentGraphScopePlanFlag -GraphScopePlan $script:AssessmentAuthWorkloadPlan.GraphScopePlan -Name 'NeedsReportsData' -Default $true
    }

    $resolvedTenantId = $null
    if (-not [string]::IsNullOrWhiteSpace($TenantId)) {
        $resolvedTenantId = $TenantId
    }
    elseif ($grantedPermissionInfo.Context -and $grantedPermissionInfo.Context.PSObject.Properties['TenantId'] -and -not [string]::IsNullOrWhiteSpace([string]$grantedPermissionInfo.Context.TenantId)) {
        $resolvedTenantId = [string]$grantedPermissionInfo.Context.TenantId
    }
    else {
        try {
            $organizationRecord = @(Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/organization?$select=id' -Activity 'Permission preflight: organization id resolution' -PreferRest:$false -SuppressProgress -SuppressAccessDeniedWarning) | Select-Object -First 1
            if ($organizationRecord -and $organizationRecord.PSObject.Properties['id']) {
                $resolvedTenantId = [string]$organizationRecord.id
            }
        }
        catch {}
    }

    $addFailure = {
        param(
            [string]$Area,
            [string]$Requirement,
            [string]$NeededFor,
            [string]$Details
        )

        $permissionFailures.Add([pscustomobject]@{
            Area        = $Area
            Requirement = $Requirement
            NeededFor   = $NeededFor
            Details     = $Details
        }) | Out-Null
    }

    $addWarning = {
        param(
            [string]$Area,
            [string]$Requirement,
            [string]$NeededFor,
            [string]$Details
        )

        $permissionWarnings.Add([pscustomobject]@{
            Area        = $Area
            Requirement = $Requirement
            NeededFor   = $NeededFor
            Details     = $Details
        }) | Out-Null
    }

    $testClaimPresence = {
        param([string[]]$PermissionNames)

        if ($null -eq $grantedPermissions -or $grantedPermissions.Count -eq 0) {
            return $null
        }

        $meaningfulGrantedPermissions = @(
            $grantedPermissions |
                Where-Object {
                    -not [string]::IsNullOrWhiteSpace([string]$_) -and
                    [string]$_ -notmatch '(^|/)\.default$'
                }
        )
        if ($meaningfulGrantedPermissions.Count -eq 0) {
            return $null
        }

        foreach ($permissionName in @($PermissionNames)) {
            if (-not [string]::IsNullOrWhiteSpace([string]$permissionName) -and $grantedPermissions.Contains([string]$permissionName)) {
                return $true
            }
        }

        return $false
    }

    $getClaimEquivalents = {
        param([string[]]$PermissionNames)

        $equivalentPermissions = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($permissionName in @($PermissionNames)) {
            if ([string]::IsNullOrWhiteSpace([string]$permissionName)) {
                continue
            }

            $null = $equivalentPermissions.Add([string]$permissionName)

            switch -Regex ([string]$permissionName) {
                '^Sites\.Read\.All$' {
                    $null = $equivalentPermissions.Add('Sites.ReadWrite.All')
                    continue
                }
                '^Application\.Read\.All$' {
                    $null = $equivalentPermissions.Add('Application.ReadWrite.All')
                    $null = $equivalentPermissions.Add('Directory.Read.All')
                    $null = $equivalentPermissions.Add('Directory.ReadWrite.All')
                    continue
                }
                '^RoleManagement\.Read\.Directory$' {
                    $null = $equivalentPermissions.Add('RoleManagement.Read.All')
                    $null = $equivalentPermissions.Add('RoleManagement.ReadWrite.Directory')
                    $null = $equivalentPermissions.Add('Directory.Read.All')
                    $null = $equivalentPermissions.Add('Directory.ReadWrite.All')
                    continue
                }
                '^CrossTenantInformation\.ReadBasic\.All$' {
                    $null = $equivalentPermissions.Add('Directory.Read.All')
                    $null = $equivalentPermissions.Add('Directory.ReadWrite.All')
                    continue
                }
            }
        }

        return @($equivalentPermissions)
    }

    $invokeGraphSdkGet = {
        param([Parameter(Mandatory = $true)][string]$Uri)

        if (Get-Command -Name 'Invoke-MgGraphRequest' -ErrorAction SilentlyContinue) {
            Invoke-MgGraphRequest -Method GET -Uri $Uri -ProgressAction SilentlyContinue -ErrorAction Stop | Out-Null
            return
        }

        Get-ArrayaGraphResource -Uri $Uri -Activity ("Permission preflight: {0}" -f $Uri) -SuppressProgress -SuppressAccessDeniedWarning | Out-Null
    }

    $invokeGraphProbe = {
        param(
            [string]$Area,
            [string[]]$PermissionNames,
            [string]$NeededFor,
            [scriptblock]$Probe,
            [bool]$IsBlocking = $true,
            [bool]$TrustClaimPresence = $false
        )

        $claimState = & $testClaimPresence (& $getClaimEquivalents $PermissionNames)
        $requirementNames = @($PermissionNames | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
        $requirementLabel = if ($requirementNames.Count -gt 0) {
            $requirementNames -join ' or '
        }
        elseif (-not [string]::IsNullOrWhiteSpace($NeededFor)) {
            $NeededFor
        }
        else {
            $Area
        }

        if ($claimState -eq $true) {
            return
        }

        if ($claimState -eq $false -and $TrustClaimPresence) {
            $missingScopeMessage = "Missing Graph scope: $requirementLabel"
            if ($IsBlocking) {
                & $addFailure $Area $requirementLabel $NeededFor $missingScopeMessage
            }
            else {
                & $addWarning $Area $requirementLabel $NeededFor $missingScopeMessage
            }
            return
        }

        if ($null -eq $Probe) {
            return
        }

        try {
            & $Probe
        }
        catch {
            $failureDetail = $_.Exception.Message
            if ($IsBlocking) {
                & $addFailure $Area $requirementLabel $NeededFor $failureDetail
            }
            else {
                & $addWarning $Area $requirementLabel $NeededFor $failureDetail
            }
        }
    }

    $formatPreflightSummary = {
        param(
            [string]$Label,
            [int]$SuccessfulCount,
            [int]$FailureCount,
            [int]$WarningCount
        )

        $remainingCount = $FailureCount + $WarningCount
        return [pscustomobject]@{
            SuccessfulCount = $SuccessfulCount
            FailureCount    = $FailureCount
            WarningCount    = $WarningCount
            RemainingCount  = $remainingCount
            SummaryText     = ("{0}: {1} successful, {2} remaining ({3} blocking, {4} non-blocking)." -f $Label, $SuccessfulCount, $remainingCount, $FailureCount, $WarningCount)
        }
    }

    $graphChecks = New-Object System.Collections.Generic.List[object]
    $graphChecks.Add([pscustomobject]@{
        Area            = 'Graph'
        PermissionNames = @('Organization.Read.All')
        NeededFor       = 'tenant organization metadata and tenant naming'
        Probe           = { Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/organization?$select=id,displayName,onPremisesSyncEnabled' -Activity 'Permission preflight: Organization.Read.All' -SuppressProgress -SuppressAccessDeniedWarning | Out-Null }
        TrustClaimPresence = $true
    }) | Out-Null
    $graphChecks.Add([pscustomobject]@{
        Area            = 'Graph'
        PermissionNames = @('User.Read.All')
        NeededFor       = 'user inventory, guest review, and sign-in hygiene analysis'
        Probe           = { Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/users?$top=1&$select=id,userType,accountEnabled' -Activity 'Permission preflight: User.Read.All' -SuppressProgress -SuppressAccessDeniedWarning | Out-Null }
        TrustClaimPresence = $true
    }) | Out-Null
    $graphChecks.Add([pscustomobject]@{
        Area            = 'Graph'
        PermissionNames = @('AuditLog.Read.All')
        NeededFor       = 'stale account detection and sign-in based identity review'
        Probe           = { & $invokeGraphSdkGet 'https://graph.microsoft.com/v1.0/auditLogs/signIns?$top=1&$select=id,createdDateTime' }
        TrustClaimPresence = $true
    }) | Out-Null
    $graphChecks.Add([pscustomobject]@{
        Area            = 'Graph'
        PermissionNames = @('Group.Read.All')
        NeededFor       = 'Entra groups, collaboration ownership, and Microsoft 365 group inventory'
        Probe           = { Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/groups?$top=1&$select=id,displayName' -Activity 'Permission preflight: Group.Read.All' -SuppressProgress -SuppressAccessDeniedWarning | Out-Null }
        TrustClaimPresence = $true
    }) | Out-Null
    $graphChecks.Add([pscustomobject]@{
        Area            = 'Graph'
        PermissionNames = @('GroupMember.Read.All')
        NeededFor       = 'group member and owner review used by ownership and collaboration findings'
        Probe           = {
            $firstGroup = @(Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/groups?$top=1&$select=id' -Activity 'Permission preflight: group lookup for GroupMember.Read.All' -SuppressProgress -SuppressAccessDeniedWarning) | Select-Object -First 1
            if ($firstGroup -and $firstGroup.PSObject.Properties['id'] -and -not [string]::IsNullOrWhiteSpace([string]$firstGroup.id)) {
                Get-ArrayaGraphResource -Uri ("https://graph.microsoft.com/v1.0/groups/{0}/members?$top=1&$select=id" -f $firstGroup.id) -Activity 'Permission preflight: GroupMember.Read.All' -SuppressProgress -SuppressAccessDeniedWarning | Out-Null
            }
        }
        TrustClaimPresence = $true
    }) | Out-Null
    $graphChecks.Add([pscustomobject]@{
        Area            = 'Graph'
        PermissionNames = @('RoleManagement.Read.Directory')
        NeededFor       = 'admin role assignments and privileged access review'
        Probe           = {
            if (Get-Command -Name 'Get-MgDirectoryRole' -ErrorAction SilentlyContinue) {
                @(Get-MgDirectoryRole -ProgressAction SilentlyContinue -ErrorAction Stop | Select-Object -First 1) | Out-Null
                return
            }

            & $invokeGraphSdkGet 'https://graph.microsoft.com/v1.0/directoryRoles?$select=id,displayName,roleTemplateId'
        }
    }) | Out-Null
    $graphChecks.Add([pscustomobject]@{
        Area            = 'Graph'
        PermissionNames = @('Domain.Read.All')
        NeededFor       = 'accepted domain inventory and DNS posture review'
        Probe           = { Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/domains?$top=1&$select=id,isVerified' -Activity 'Permission preflight: Domain.Read.All' -SuppressProgress -SuppressAccessDeniedWarning | Out-Null }
        TrustClaimPresence = $true
    }) | Out-Null
    $graphChecks.Add([pscustomobject]@{
        Area            = 'Graph'
        PermissionNames = @('Device.Read.All')
        NeededFor       = 'device inventory and compliance posture review'
        Probe           = { Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/devices?$top=1&$select=id,displayName' -Activity 'Permission preflight: Device.Read.All' -SuppressProgress -SuppressAccessDeniedWarning | Out-Null }
        TrustClaimPresence = $true
    }) | Out-Null
    $graphChecks.Add([pscustomobject]@{
        Area            = 'Graph'
        PermissionNames = @('Policy.Read.All')
        NeededFor       = 'Conditional Access, guest invitation, and authentication policy review'
        Probe           = { Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/policies/authorizationPolicy?$select=id,allowInvitesFrom,allowedToUseSSPR' -Activity 'Permission preflight: Policy.Read.All' -SuppressProgress -SuppressAccessDeniedWarning | Out-Null }
        TrustClaimPresence = $true
    }) | Out-Null
    $graphChecks.Add([pscustomobject]@{
        Area            = 'Graph'
        PermissionNames = @('CrossTenantInformation.ReadBasic.All')
        NeededFor       = 'cross-tenant partner visibility and external access posture review'
        Probe           = {
            if (-not [string]::IsNullOrWhiteSpace($resolvedTenantId)) {
                Get-ArrayaGraphResource -Uri ("https://graph.microsoft.com/v1.0/tenantRelationships/findTenantInformationByTenantId(tenantId='{0}')" -f $resolvedTenantId) -Activity 'Permission preflight: CrossTenantInformation.ReadBasic.All' -SuppressProgress -SuppressAccessDeniedWarning | Out-Null
            }
        }
    }) | Out-Null
    $graphChecks.Add([pscustomobject]@{
        Area            = 'Graph'
        PermissionNames = @('Application.Read.All')
        NeededFor       = 'enterprise application and permission posture review'
        Probe           = { Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/servicePrincipals?$top=1&$select=id,displayName' -Activity 'Permission preflight: Application.Read.All' -SuppressProgress -SuppressAccessDeniedWarning | Out-Null }
    }) | Out-Null
    $graphChecks.Add([pscustomobject]@{
        Area            = 'Graph'
        PermissionNames = @('Sites.Read.All')
        NeededFor       = 'SharePoint and OneDrive site access'
        Probe           = if ($isInteractiveGraphAuth) {
            { Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/sites/root?$select=id,webUrl,displayName' -Activity 'Permission preflight: Sites.Read.All root site' -SuppressProgress -SuppressAccessDeniedWarning | Out-Null }
        }
        else {
            { Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/sites/getAllSites?$top=1' -Activity 'Permission preflight: Sites.Read.All getAllSites' -SuppressProgress -SuppressAccessDeniedWarning | Out-Null }
        }
    }) | Out-Null
    $graphChecks.Add([pscustomobject]@{
        Area            = 'Graph'
        PermissionNames = @('SharePointTenantSettings.Read.All')
        NeededFor       = 'tenant-level SharePoint and OneDrive sharing baseline review'
        Probe           = { & $invokeGraphSdkGet 'https://graph.microsoft.com/v1.0/admin/sharepoint/settings' }
    }) | Out-Null
    $graphChecks.Add([pscustomobject]@{
        Area            = 'Graph'
        PermissionNames = @('OnPremDirectorySynchronization.Read.All')
        NeededFor       = 'directory synchronization and password lifecycle review'
        Probe           = { Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/directory/onPremisesSynchronization' -Activity 'Permission preflight: OnPremDirectorySynchronization.Read.All' -SuppressProgress -SuppressAccessDeniedWarning | Out-Null }
        IsBlocking      = $false
    }) | Out-Null
    $graphChecks.Add([pscustomobject]@{
        Area            = 'Graph'
        PermissionNames = @('SecurityEvents.Read.All')
        NeededFor       = 'Microsoft Secure Score collection'
        Probe           = { Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/security/secureScores?$top=1' -Activity 'Permission preflight: SecurityEvents.Read.All' -SuppressProgress -SuppressAccessDeniedWarning | Out-Null }
        TrustClaimPresence = $true
    }) | Out-Null
    if ($preflightNeedsReportsData) {
        $graphChecks.Add([pscustomobject]@{
            Area            = 'Graph'
            PermissionNames = @('Reports.Read.All')
            NeededFor       = 'usage reports, mailbox activity, and SharePoint/OneDrive usage coverage'
            Probe           = { Export-ArrayaGraphReportCsv -Uri "https://graph.microsoft.com/v1.0/reports/getOffice365ActiveUserDetail(period='D7')" -Activity 'Permission preflight: Reports.Read.All' | Out-Null }
        }) | Out-Null
        $graphChecks.Add([pscustomobject]@{
            Area            = 'Graph'
            PermissionNames = @('ReportSettings.Read.All')
            NeededFor       = 'report-settings validation for activity reporting'
            Probe           = {
                $adminReportSettings = Get-ArrayaGraphAdminReportSettings -Headers $global:GraphHeaders -SuppressProgress
                if (-not $adminReportSettings -or -not $adminReportSettings.Available) {
                    $reportSettingsError = if ($adminReportSettings -and $adminReportSettings.PSObject.Properties['ErrorMessage'] -and -not [string]::IsNullOrWhiteSpace([string]$adminReportSettings.ErrorMessage)) {
                        [string]$adminReportSettings.ErrorMessage
                    }
                    else {
                        'The admin report settings endpoint was not available.'
                    }
                    throw $reportSettingsError
                }
            }
        }) | Out-Null
    }

    if ($script:ProfileCollectionPlan.CollectTeamsDetails) {
        $graphChecks.Add([pscustomobject]@{
            Area            = 'Graph'
            PermissionNames = @('Team.ReadBasic.All')
            NeededFor       = 'Teams inventory and external collaboration review'
            Probe           = { & $invokeGraphSdkGet 'https://graph.microsoft.com/v1.0/teams?$top=1&$select=id,displayName' }
            TrustClaimPresence = $true
        }) | Out-Null
        $graphChecks.Add([pscustomobject]@{
            Area            = 'Graph'
            PermissionNames = @('Channel.ReadBasic.All')
            NeededFor       = 'Teams channel inventory used by collaboration analysis'
            Probe           = {
                $teamProbeResponse = $null
                if (Get-Command -Name 'Invoke-MgGraphRequest' -ErrorAction SilentlyContinue) {
                    $teamProbeResponse = Invoke-MgGraphRequest -Method GET -Uri 'https://graph.microsoft.com/v1.0/teams?$top=1&$select=id,displayName' -ProgressAction SilentlyContinue -ErrorAction Stop
                }
                else {
                    $teamProbeResponse = Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/teams?$top=1&$select=id,displayName' -Activity 'Permission preflight: Team.ReadBasic.All' -SuppressProgress -SuppressAccessDeniedWarning
                }

                $firstTeamId = $null
                if ($teamProbeResponse) {
                    if ($teamProbeResponse.PSObject -and $teamProbeResponse.PSObject.Properties['value']) {
                        $firstTeam = @($teamProbeResponse.value | Select-Object -First 1)
                        if ($firstTeam.Count -gt 0 -and $firstTeam[0].PSObject.Properties['id']) {
                            $firstTeamId = [string]$firstTeam[0].id
                        }
                    }
                    elseif ($teamProbeResponse -is [System.Collections.IEnumerable] -and -not ($teamProbeResponse -is [string])) {
                        $firstTeam = @($teamProbeResponse | Select-Object -First 1)
                        if ($firstTeam.Count -gt 0 -and $firstTeam[0].PSObject.Properties['id']) {
                            $firstTeamId = [string]$firstTeam[0].id
                        }
                    }
                    elseif ($teamProbeResponse.PSObject -and $teamProbeResponse.PSObject.Properties['id']) {
                        $firstTeamId = [string]$teamProbeResponse.id
                    }
                }

                if (-not [string]::IsNullOrWhiteSpace($firstTeamId)) {
                    & $invokeGraphSdkGet ("https://graph.microsoft.com/v1.0/teams/{0}/allChannels?$top=1&$select=displayName,membershipType" -f $firstTeamId)
                }
            }
        }) | Out-Null
    }

    $exchangeChecks = New-Object System.Collections.Generic.List[object]
    $exchangeChecks.Add([pscustomobject]@{
        Requirement = 'Exchange mailbox read access'
        NeededFor   = 'Exchange mailbox inventory, forwarding review, and messaging analysis'
        Probe       = { @(Get-EXOMailbox -ResultSize 1 -ErrorAction Stop | Select-Object -First 1) | Out-Null }
        Guidance    = 'Ensure Exchange Online access is available for the selected auth mode. App-only runs require Exchange application access such as Exchange.ManageAsApp.'
    }) | Out-Null

    if ($script:ProfileCollectionPlan.CollectExchangeGroups -or $script:ProfileCollectionPlan.CollectUnifiedGroups) {
        $exchangeChecks.Add([pscustomobject]@{
            Requirement = 'Exchange unified group read access'
            NeededFor   = 'group mailbox and collaboration-backed messaging review'
            Probe       = { @(Get-UnifiedGroup -ResultSize 1 -ErrorAction Stop | Select-Object -First 1) | Out-Null }
            Guidance    = 'Ensure the current Exchange connection can read unified groups for the selected auth mode.'
        }) | Out-Null
    }

    $selectedGraphChecks = New-Object System.Collections.Generic.List[object]
    $selectedExchangeChecks = New-Object System.Collections.Generic.List[object]
    $runPurviewCheck = $false
    $summaryLabel = 'Permission preflight summary'
    $failureHeading = 'Permission preflight failed.'
    $warningHeading = 'Permission preflight warnings:'
    $failureLead = 'Permission preflight failed. The assessment will not continue until the required access is available.'
    $warningLead = 'Permission preflight found non-blocking access gaps. The assessment will continue with validation notes for the affected fields.'

    switch ($Workload) {
        'Graph' {
            foreach ($graphCheck in $graphChecks) {
                $selectedGraphChecks.Add($graphCheck) | Out-Null
            }
            $summaryLabel = 'Graph preflight summary'
            $failureHeading = 'Graph preflight failed.'
            $warningHeading = 'Graph preflight warnings:'
            $failureLead = 'Graph preflight failed. The assessment will not continue until the required Microsoft Graph access is available.'
            $warningLead = 'Graph preflight found non-blocking access gaps. The assessment will continue with validation notes for the affected fields.'
        }
        'ExchangeOnline' {
            foreach ($exchangeCheck in $exchangeChecks) {
                $selectedExchangeChecks.Add($exchangeCheck) | Out-Null
            }
            $summaryLabel = 'Exchange preflight summary'
            $failureHeading = 'Exchange preflight failed.'
            $warningHeading = 'Exchange preflight warnings:'
            $failureLead = 'Exchange preflight failed. The assessment will not continue until the required Exchange Online access is available.'
            $warningLead = 'Exchange preflight found non-blocking access gaps. The assessment will continue with validation notes for the affected fields.'
        }
        'Purview' {
            $runPurviewCheck = [bool]$script:ProfileCollectionPlan.CollectGovernanceCompliancePolicies
            $summaryLabel = 'Purview preflight summary'
            $failureHeading = 'Purview preflight failed.'
            $warningHeading = 'Purview preflight warnings:'
            $failureLead = 'Purview preflight failed. The assessment will not continue until the required compliance access is available.'
            $warningLead = 'Purview preflight found non-blocking access gaps. The assessment will continue with validation notes for the affected fields.'
        }
        default {
            foreach ($graphCheck in @($graphChecks)) {
                $selectedGraphChecks.Add($graphCheck) | Out-Null
            }
            foreach ($exchangeCheck in @($exchangeChecks)) {
                $selectedExchangeChecks.Add($exchangeCheck) | Out-Null
            }
            $runPurviewCheck = [bool]$script:ProfileCollectionPlan.CollectGovernanceCompliancePolicies
        }
    }

    $preflightProgressId = 91
    $preflightProgressIndex = 0
    $preflightProgressTotal = $selectedGraphChecks.Count + $selectedExchangeChecks.Count + $(if ($runPurviewCheck) { 1 } else { 0 })

    $updatePreflightProgress = {
        param(
            [string]$Area,
            [string]$Requirement,
            [ref]$ProgressIndex
        )

        $ProgressIndex.Value++
        $progressActivity = "Permission preflight: {0}: {1}" -f $Area, $Requirement
        Write-ProgressHelper -Total ([Math]::Max($preflightProgressTotal, 1)) -Id $preflightProgressId -Index $ProgressIndex.Value -Activity $progressActivity
    }

    try {
        foreach ($graphCheck in $selectedGraphChecks) {
            $isBlocking = $true
            if ($graphCheck.PSObject.Properties['IsBlocking']) {
                $isBlocking = [bool]$graphCheck.IsBlocking
            }
            $trustClaimPresence = $false
            if ($graphCheck.PSObject.Properties['TrustClaimPresence']) {
                $trustClaimPresence = [bool]$graphCheck.TrustClaimPresence
            }

            $graphRequirementNames = @($graphCheck.PermissionNames | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
            $graphRequirementLabel = if ($graphRequirementNames.Count -gt 0) {
                $graphRequirementNames -join ' or '
            }
            else {
                [string]$graphCheck.NeededFor
            }

            & $updatePreflightProgress $graphCheck.Area $graphRequirementLabel ([ref]$preflightProgressIndex)
            & $invokeGraphProbe $graphCheck.Area $graphCheck.PermissionNames $graphCheck.NeededFor $graphCheck.Probe $isBlocking $trustClaimPresence
        }

        foreach ($exchangeCheck in $selectedExchangeChecks) {
            & $updatePreflightProgress 'Exchange Online' $exchangeCheck.Requirement ([ref]$preflightProgressIndex)
            try {
                & $exchangeCheck.Probe
            }
            catch {
                & $addFailure 'Exchange Online' $exchangeCheck.Requirement $exchangeCheck.NeededFor $exchangeCheck.Guidance
            }
        }

        if ($runPurviewCheck) {
            & $updatePreflightProgress 'Purview' 'Retention and DLP policy access' ([ref]$preflightProgressIndex)
            try {
                if (-not (Ensure-PurviewComplianceSession)) {
                    $purviewFailure = if (-not (Get-Command -Name 'Connect-IPPSSession' -ErrorAction SilentlyContinue)) {
                        'Connect-IPPSSession is unavailable in the current session.'
                    }
                    elseif (
                        -not [string]::IsNullOrWhiteSpace($ClientSecret) -or
                        $null -ne $ClientSecretCredential -or
                        $null -ne $ClientSecretSecure
                    ) {
                        'Client secret authentication is not supported for Purview compliance PowerShell in this workflow.'
                    }
                    else {
                        'Purview compliance PowerShell session could not be established.'
                    }
                    $purviewDiagnosticMessage = Get-PurviewComplianceDiagnosticMessage
                    if (-not [string]::IsNullOrWhiteSpace($purviewDiagnosticMessage)) {
                        $purviewFailure = $purviewDiagnosticMessage
                    }

                    & $addFailure 'Purview' 'Retention and DLP policy access' 'retention and DLP policy collection' $purviewFailure
                }
                else {
                    foreach ($requiredPurviewCommand in @('Get-RetentionCompliancePolicy', 'Get-DlpCompliancePolicy')) {
                        if (-not (Get-Command -Name $requiredPurviewCommand -ErrorAction SilentlyContinue)) {
                            & $addFailure 'Purview' $requiredPurviewCommand 'retention and DLP policy collection' 'The required compliance cmdlet was not available after establishing the Purview session.'
                        }
                    }
                }
            }
            catch {
                & $addFailure 'Purview' 'Retention and DLP policy access' 'retention and DLP policy collection' $_.Exception.Message
            }
        }
    }
    finally {
        Write-ProgressHelper -Total ([Math]::Max($preflightProgressTotal, 1)) -Id $preflightProgressId -Activity 'Permission preflight' -Completed
    }

    $preflightSummary = & $formatPreflightSummary $summaryLabel ($preflightProgressTotal - ($permissionFailures.Count + $permissionWarnings.Count)) $permissionFailures.Count $permissionWarnings.Count

    Write-Log -Type INFO -Message $preflightSummary.SummaryText -ExportFileLocation $ExportDetails

    if ($permissionFailures.Count -gt 0) {
        $messageLines = New-Object System.Collections.Generic.List[string]
        $messageLines.Add($failureLead) | Out-Null
        $messageLines.Add($preflightSummary.SummaryText) | Out-Null
        $messageLines.Add('Required updates:') | Out-Null

        Write-Host $failureHeading -ForegroundColor Red

        foreach ($failure in $permissionFailures) {
            $messageLines.Add((" - [{0}] {1}: needed for {2}. Current issue: {3}" -f $failure.Area, $failure.Requirement, $failure.NeededFor, $failure.Details)) | Out-Null
            Write-Host (" - [{0}] {1}" -f $failure.Area, $failure.Requirement) -ForegroundColor Yellow
            Write-Host ("   Needed for: {0}" -f $failure.NeededFor) -ForegroundColor DarkYellow
            Write-Host ("   Current issue: {0}" -f $failure.Details) -ForegroundColor DarkYellow
        }

        $operatorGuidance = @(Get-AssessmentGraphPreflightOperatorGuidance -Failures @($permissionFailures) -GrantedPermissionInfo $grantedPermissionInfo)
        if ($operatorGuidance.Count -gt 0) {
            $messageLines.Add('Operator guidance:') | Out-Null
            Write-Host 'Operator guidance:' -ForegroundColor Yellow
            foreach ($guidanceLine in $operatorGuidance) {
                $messageLines.Add((" - {0}" -f $guidanceLine)) | Out-Null
                Write-Host (" - {0}" -f $guidanceLine) -ForegroundColor DarkYellow
            }
        }

        $failureMessage = ($messageLines -join [System.Environment]::NewLine)
        Write-Log -Type ERROR -Message $failureMessage -ExportFileLocation $ExportDetails

        $missingGraphScopes = @(
            $permissionFailures |
                Where-Object { [string]$_.Area -eq 'Graph' -and [string]$_.Details -match '^Missing Graph scope:' } |
                ForEach-Object { ([string]$_.Details -replace '^Missing Graph scope:\s*', '').Trim() } |
                Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } |
                Select-Object -Unique
        )
        if ($missingGraphScopes.Count -gt 0) {
            throw ("Graph preflight failed. Missing Graph scope(s): {0}. Run Disconnect-MgGraph, then rerun the assessment." -f ($missingGraphScopes -join ', '))
        }

        $conciseFailures = @(
            $permissionFailures |
                ForEach-Object { "{0}: {1}" -f $_.Requirement, $_.Details }
        )
        throw ("{0} {1}" -f $failureHeading, ($conciseFailures -join '; '))
    }

    if ($permissionWarnings.Count -gt 0) {
        $warningLines = New-Object System.Collections.Generic.List[string]
        $warningLines.Add($warningLead) | Out-Null
        $warningLines.Add($preflightSummary.SummaryText) | Out-Null
        Write-Host $warningHeading -ForegroundColor Yellow
        foreach ($warning in $permissionWarnings) {
            $warningText = (" - [{0}] {1}: needed for {2}. Current issue: {3}" -f $warning.Area, $warning.Requirement, $warning.NeededFor, $warning.Details)
            $warningLines.Add($warningText) | Out-Null
            Write-Host (" - [{0}] {1}" -f $warning.Area, $warning.Requirement) -ForegroundColor Yellow
            Write-Host ("   Needed for: {0}" -f $warning.NeededFor) -ForegroundColor DarkYellow
            Write-Host ("   Current issue: {0}" -f $warning.Details) -ForegroundColor DarkYellow
        }
        Write-Host 'Hybrid sync and password lifecycle fields may be marked as not validated in current auth mode.' -ForegroundColor DarkYellow
        Write-Log -Type WARNING -Message (($warningLines -join [System.Environment]::NewLine) + [System.Environment]::NewLine + 'Hybrid sync and password lifecycle fields may be marked as not validated in current auth mode.') -ExportFileLocation $ExportDetails
    }

    Write-Log -Type INFO -Message ('[PermissionPreflight] Required Graph, Exchange Online, and supported governance access checks passed. ' + $preflightSummary.SummaryText) -ExportFileLocation $ExportDetails
    return $preflightSummary
}

function Get-CurrentProcessMemorySnapshot {
    [CmdletBinding()]
    param()

    try {
        $proc = Get-Process -Id $PID -ErrorAction Stop
        return [PSCustomObject]@{
            WorkingSetMB = [math]::Round(($proc.WorkingSet64 / 1MB), 2)
            PrivateMB    = [math]::Round(($proc.PrivateMemorySize64 / 1MB), 2)
            PagedMB      = [math]::Round(($proc.PagedMemorySize64 / 1MB), 2)
            HeapMB       = [math]::Round(([GC]::GetTotalMemory($false) / 1MB), 2)
        }
    }
    catch {
        return [PSCustomObject]@{
            WorkingSetMB = 0
            PrivateMB    = 0
            PagedMB      = 0
            HeapMB       = 0
        }
    }
}

function Ensure-AssessmentCollectorContext {
    [CmdletBinding()]
    param()

    if (-not ($script:tenantStatsHash -is [System.Collections.IDictionary])) {
        $script:tenantStatsHash = @{}
    }

    if ($null -eq $script:AssessmentContext) {
        $script:AssessmentContext = New-ArrayaAssessmentContext `
            -ExportFileLocation $ExportDetails `
            -ReportingMode ((Get-Culture).TextInfo.ToTitleCase($reportingMode)) `
            -TenantStats $script:tenantStatsHash `
            -Policies ([ordered]@{}) `
            -Runtime ([ordered]@{}) `
            -Metadata ([ordered]@{ StartedAt = $global:InitialStart })
    }

    $script:AssessmentContext.TenantStats = $script:tenantStatsHash
    $script:AssessmentContext.ExportFileLocation = $ExportDetails
    $script:AssessmentContext.Policies['ReportingMode'] = ((Get-Culture).TextInfo.ToTitleCase($reportingMode))
    $script:AssessmentContext.Policies['CollectionDepth'] = $script:CollectionDepthPolicy
    $script:AssessmentContext.Metadata['StartedAt'] = $global:InitialStart
    if ($script:MailboxUsageGraphLookup -is [System.Collections.IDictionary] -and $script:MailboxUsageGraphLookup.Count -gt 0) {
        $script:AssessmentContext.Runtime['MailboxUsageGraphLookup'] = $script:MailboxUsageGraphLookup
    }
    if ($script:UnifiedGroupsInventoryCache -and @($script:UnifiedGroupsInventoryCache).Count -gt 0) {
        $script:AssessmentContext.Runtime['UnifiedGroupsInventoryCache'] = $script:UnifiedGroupsInventoryCache
    }
    if (
        $script:Office365GroupsActivityMailboxLookup -and
        $script:Office365GroupsActivityMailboxLookup.PSObject.Properties['ByGroupId'] -and
        $script:Office365GroupsActivityMailboxLookup.PSObject.Properties['ByPrimarySmtpAddress']
    ) {
        $script:AssessmentContext.Runtime['Office365GroupsActivityMailboxLookup'] = $script:Office365GroupsActivityMailboxLookup
    }

    return $script:AssessmentContext
}

function Sync-CollectorModuleRuntimeContext {
    [CmdletBinding()]
    param()

    Ensure-AssessmentCollectorContext | Out-Null
}

function Sync-CollectorModuleRuntimeContextBack {
    [CmdletBinding()]
    param()

    $context = Ensure-AssessmentCollectorContext
    $script:tenantStatsHash = $context.TenantStats
    if ($context.Runtime.Contains('MailboxUsageGraphLookup')) {
        $script:MailboxUsageGraphLookup = $context.Runtime['MailboxUsageGraphLookup']
    }
    if ($context.Runtime.Contains('UnifiedGroupsInventoryCache')) {
        $script:UnifiedGroupsInventoryCache = $context.Runtime['UnifiedGroupsInventoryCache']
    }
    if ($context.Runtime.Contains('Office365GroupsActivityMailboxLookup')) {
        $script:Office365GroupsActivityMailboxLookup = $context.Runtime['Office365GroupsActivityMailboxLookup']
    }
}

function Initialize-AssessmentProgress {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [int]$TotalSteps
    )

    $script:AssessmentProgressId = 90
    $script:AssessmentProgressState = [ordered]@{
        Total   = [Math]::Max($TotalSteps, 1)
        Current = 0
    }
    $script:AssessmentStepMetrics = New-Object System.Collections.Generic.List[object]
    $script:AssessmentProgressLinePending = $false

    if (Test-ShowAssessmentProgress) {
        Write-Progress -Id $script:AssessmentProgressId -Activity 'Assessment progress' -Status "[0/$($script:AssessmentProgressState.Total)] Starting" -PercentComplete 0
    }
}

function Clear-TransientGraphProgress {
    [CmdletBinding()]
    param()

    $overallProgressId = if ($script:AssessmentProgressId) { [int]$script:AssessmentProgressId } else { 90 }
    for ($progressId = 0; $progressId -lt $overallProgressId; $progressId++) {
        try { Write-Progress -Id $progressId -Completed } catch {}
    }
}

function New-AssessmentStepResult {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [ValidateSet('Completed', 'Skipped', 'Partial', 'Failed')]
        [string]$Status,
        [Parameter(Mandatory = $false)]
        [string]$Message
    )

    return [pscustomobject]@{
        AssessmentStatus = $Status
        Message          = $Message
    }
}

function Invoke-AssessmentProgressStep {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Name,
        [Parameter(Mandatory)]
        [scriptblock]$ScriptBlock
    )

    if (-not $script:AssessmentProgressState) {
        return (& $ScriptBlock)
    }

    $script:AssessmentProgressState.Current++
    $current = $script:AssessmentProgressState.Current
    $total = $script:AssessmentProgressState.Total
    $percent = [math]::Round(($current / $total) * 100, 2)
    $memoryBefore = Get-CurrentProcessMemorySnapshot
    $stepStart = Get-Date
    $stepStatus = 'Completed'
    $stepMessage = $null

    if (Test-ShowAssessmentProgress) {
        Write-Progress -Id $script:AssessmentProgressId -Activity 'Assessment progress' -Status "[$current/$total] $Name" -PercentComplete $percent
    }
    $progressLinePrefix = "  [{0}/{1} | {2}%] {3}" -f $current, $total, $percent, $Name
    $usesDirectConsoleOutput = [bool]($Name -match '^(Exchange mailboxes|Exchange groups|Unified groups|SharePoint/OneDrive sites)')
    if ($usesDirectConsoleOutput) {
        $script:AssessmentProgressLinePending = $false
        Write-Host $progressLinePrefix -ForegroundColor Cyan
    }
    else {
        $script:AssessmentProgressLinePending = $true
        Write-Host $progressLinePrefix -ForegroundColor Cyan -NoNewline
    }
    try {
        Sync-CollectorModuleRuntimeContext
        $stepResult = & $ScriptBlock
        if ($stepResult -and $stepResult.PSObject -and $stepResult.PSObject.Properties['AssessmentStatus']) {
            $stepStatus = [string]$stepResult.AssessmentStatus
            if ($stepResult.PSObject.Properties['Message']) {
                $stepMessage = [string]$stepResult.Message
            }
        }
        Sync-CollectorModuleRuntimeContextBack
    }
    catch {
        $stepStatus = 'Failed'
        $stepMessage = $_.Exception.Message
        throw
    }
    finally {
        Sync-CollectorModuleRuntimeContextBack
        $memoryAfter = Get-CurrentProcessMemorySnapshot
        $elapsed = (Get-Date) - $stepStart
        $statusColor = switch ($stepStatus) {
            'Completed' { 'Green' }
            'Skipped' { 'Yellow' }
            'Partial' { 'DarkYellow' }
            default { 'Red' }
        }
        $statusSuffix = if ([string]::IsNullOrWhiteSpace($stepMessage)) { '' } else { " - $stepMessage" }
        if ($script:AssessmentProgressLinePending) {
            Write-Host (" - {0} in {1}{2}" -f $stepStatus, $elapsed.ToString('hh\:mm\:ss'), $statusSuffix) -ForegroundColor $statusColor
        }
        else {
            Write-Host ("  [{0}/{1} | {2}%] {3} - {4} in {5}{6}" -f $current, $total, $percent, $Name, $stepStatus, $elapsed.ToString('hh\:mm\:ss'), $statusSuffix) -ForegroundColor $statusColor
        }
        $script:AssessmentProgressLinePending = $false
        $script:AssessmentStepMetrics.Add([PSCustomObject]@{
            StepName             = $Name
            StartedAt            = $stepStart
            DurationSeconds      = [math]::Round($elapsed.TotalSeconds, 3)
            WorkingSetStartMB    = $memoryBefore.WorkingSetMB
            WorkingSetEndMB      = $memoryAfter.WorkingSetMB
            WorkingSetDeltaMB    = [math]::Round(($memoryAfter.WorkingSetMB - $memoryBefore.WorkingSetMB), 2)
            PrivateStartMB       = $memoryBefore.PrivateMB
            PrivateEndMB         = $memoryAfter.PrivateMB
            PrivateDeltaMB       = [math]::Round(($memoryAfter.PrivateMB - $memoryBefore.PrivateMB), 2)
            ManagedHeapStartMB   = $memoryBefore.HeapMB
            ManagedHeapEndMB     = $memoryAfter.HeapMB
            ManagedHeapDeltaMB   = [math]::Round(($memoryAfter.HeapMB - $memoryBefore.HeapMB), 2)
        }) | Out-Null
        Clear-TransientGraphProgress
    }
}

function Invoke-ProfileAwareAssessmentStep {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Name,
        [Parameter(Mandatory)]
        [bool]$Enabled,
        [Parameter(Mandatory)]
        [scriptblock]$ScriptBlock,
        [Parameter(Mandatory = $false)]
        [string]$SkipReason = 'Disabled by output profile'
    )

    if ($Enabled) {
        Invoke-AssessmentProgressStep -Name $Name -ScriptBlock $ScriptBlock
        return
    }

    $profileLabelForSkip = if ([string]::IsNullOrWhiteSpace($script:EffectiveOutputProfileLabel)) { $OutputProfile } else { $script:EffectiveOutputProfileLabel }
    $skipMessage = "Skipped by output profile '$profileLabelForSkip': $SkipReason"
    Invoke-AssessmentProgressStep -Name $Name -ScriptBlock {
        Write-Log -Type INFO -Message ("[{0}] {1}" -f $Name, $skipMessage) -ExportFileLocation $ExportDetails
        New-AssessmentStepResult -Status Skipped -Message $SkipReason
    }
}

function New-AssessmentCollectorSections {
    [CmdletBinding()]
    param()

    return @(
        [pscustomobject]@{ Step = '1/6'; Name = 'Tenant Overview' },
        [pscustomobject]@{ Step = '2/6'; Name = 'Identity' },
        [pscustomobject]@{ Step = '3/6'; Name = 'Exchange' },
        [pscustomobject]@{ Step = '4/6'; Name = 'Collaboration' },
