        $script:tenantStatsHash = @{}
    }
    $script:tenantStatsHash["LicenseSKUs"] = @{}
    Write-Log -Type Info -Message "[Get-AllLicenseSKUs] Gathering all License SKUs from tenant" -ExportFileLocation $ExportDetails
    # Get License SKUs using MGGraph   
    $skus = Get-MgSubscribedSku -ProgressAction SilentlyContinue -ErrorAction Continue | ? {$_.AppliesTo}
    $script:SkuLookupById = @{}
    $script:ServicePlanLookupById = @{}

    # Get subscription metadata to identify trials
    $subscriptions = @()
    try {
        $subscriptions = Get-MgDirectorySubscription -All -ProgressAction SilentlyContinue -ErrorAction SilentlyContinue
    } catch {}
    $subscriptionLookup = @{}
    foreach ($sub in $subscriptions) {
        if ($sub.SkuId) {
            $subscriptionLookup[$sub.SkuId.ToString()] = $sub
        }
    }
    
    Write-Log -Type Info -Message "[Get-AllLicenseSKUs] Found $($skus.count) License SKUs from tenant" -ExportFileLocation $ExportDetails

    #Add License SKUs to Hash Table and Service Plans under each SKU to another Hash Table
    Write-Log -Type Info -Message "[Get-AllLicenseSKUs] START: Add License SKUs and Service Plans under each SKU to Tenant Hash Table" -ExportFileLocation $ExportDetails
    foreach ($sku in $skus) {
        $skuIdText = $sku.SkuId.ToString()
        $subMatch = $null
        if ($subscriptionLookup.ContainsKey($skuIdText)) {
            $subMatch = $subscriptionLookup[$skuIdText]
        }

        $friendlySkuName = Get-FriendlyProductName -SkuPartNumber $sku.SkuPartNumber
        $script:SkuLookupById[$skuIdText] = [PSCustomObject]@{
            SkuId = $skuIdText
            SkuPartNumber = $sku.SkuPartNumber
            FriendlyName = $friendlySkuName
            ServicePlans = @($sku.ServicePlans)
        }
        foreach ($servicePlan in @($sku.ServicePlans)) {
            if ($servicePlan.ServicePlanId) {
                $script:ServicePlanLookupById[$servicePlan.ServicePlanId.ToString()] = $servicePlan.ServicePlanName
            }
        }

        $skuDetails = [PSCustomObject]@{
            AccountSkuId = $sku.AccountSkuId
            AccountName = $sku.AccountName
            AppliesTo = $sku.AppliesTo
            CapabilityStatus = $sku.CapabilityStatus
            SkuId = $sku.SkuId
            SkuPartNumber = $sku.SkuPartNumber
            SkuFriendlyName = $friendlySkuName
            ConsumedUnits = $sku.ConsumedUnits
        }

        #Add Prepaid Units
        $skuDetails | Add-Member -MemberType NoteProperty -Name PurchasedUnits -Value $sku.PrepaidUnits.Enabled -Force
        #Add Remaining/Available Units
        $skuDetails | Add-Member -MemberType NoteProperty -Name RemainingUnits -Value ($sku.PrepaidUnits.Enabled - $sku.ConsumedUnits) -Force
        $skuDetails | Add-Member -MemberType NoteProperty -Name ServicePlansCount -Value (($sku.ServicePlans.ServicePlanName).count) -Force
        $skuDetails | Add-Member -MemberType NoteProperty -Name ServicePlans -Value ($sku.ServicePlans.ServicePlanName -join ",") -Force
        if ($subMatch) {
            $skuDetails | Add-Member -MemberType NoteProperty -Name IsTrial -Value $subMatch.IsTrial -Force
            $skuDetails | Add-Member -MemberType NoteProperty -Name SubscriptionStatus -Value $subMatch.Status -Force
            $skuDetails | Add-Member -MemberType NoteProperty -Name NextLifecycleDateTime -Value $subMatch.NextLifecycleDateTime -Force
            $skuDetails | Add-Member -MemberType NoteProperty -Name TotalLicenses -Value $subMatch.TotalLicenses -Force

            $nextLifecycle = $subMatch.NextLifecycleDateTime
            $isFreeOrTrial = ($null -eq $nextLifecycle -or $nextLifecycle -eq '')
            $isIgnoredLifecycle = $false
            if ($nextLifecycle) {
                try {
                    $dt = [datetime]$nextLifecycle
                    if ($dt.Year -eq 9999) { $isIgnoredLifecycle = $true }
                } catch {}
            }
            if ($sku.SkuPartNumber -eq 'MCOPSTNC') {
                $isFreeOrTrial = $true
            }
            $skuDetails | Add-Member -MemberType NoteProperty -Name IsFreeOrTrial -Value $isFreeOrTrial -Force
            $skuDetails | Add-Member -MemberType NoteProperty -Name IgnoreLifecycle -Value $isIgnoredLifecycle -Force
        }

        $skuClassification = Get-LicenseClassification -License $skuDetails
        $skuDetails | Add-Member -MemberType NoteProperty -Name IsPaid -Value $skuClassification.IsPaid -Force
        $skuDetails | Add-Member -MemberType NoteProperty -Name LicenseClass -Value $skuClassification.LicenseClass -Force
        $skuDetails | Add-Member -MemberType NoteProperty -Name LicenseClassificationReason -Value $skuClassification.Reason -Force

        Write-Log -Type DEBUG -Message "[Get-AllLicenseSKUs] Gathering License details for $($AccountSkuId)" -ExportFileLocation $ExportDetails

        #Create Hash Table for License SKUs
        $script:tenantStatsHash["LicenseSKUs"][$sku.SkuId.tostring()] = $skuDetails

    }
    $CompletedTime = (((Get-Date) - $start).ToString('hh\:mm\:ss'))
    Write-Log -Type Info -Message "[Get-AllLicenseSKUs] COMPLETED: Gathering all License Details User Details in $($CompletedTime)" -ExportFileLocation $ExportDetails
}
function Get-AllUserDetails {
    [CmdletBinding()]
    param (
        [Parameter(Mandatory=$True,HelpMessage='Provide the level of detail')]
        [ValidateSet('minimum', 'operator', 'combined', 'automation', 'all', 'geek')]
        [string]$detailLevel
    )
    $start = Get-Date
    $graphUsersProgressId = 71
    $userDetailsProgressId = 72
    # Microsoft Graph returns only 11 default properties when no $select is supplied
    # (businessPhones, displayName, givenName, id, jobTitle, mail, mobilePhone,
    # officeLocation, preferredLanguage, surname, userPrincipalName). Everything the
    # assessment needs has to be requested explicitly, on every collection path.
    $DesiredProperties = @(
        "DisplayName", "AssignedLicenses", "AssignedPlans", "LicenseAssignmentStates", "UserPrincipalName"
        "UserType", "Id", "AccountEnabled"
        "CreatedDateTime", "Mail", "MailNickname", "JobTitle"
        "Department", "CompanyName", "OfficeLocation"
        "City", "State", "Country"
        "OnPremisesSyncEnabled", "OnPremisesDistinguishedName", "OnPremisesLastSyncDateTime"
        "OnPremisesImmutableId", "OnPremisesSamAccountName"
        "EmployeeId", "CreationType", "ExternalUserState", "LastPasswordChangeDateTime"
        "UsageLocation", "SignInActivity", "ProxyAddresses"
    )
    # Graph caps the page size at 500 whenever signInActivity is selected or filtered.
    $userPageSize = 500
    $minimumModeMessage = 'NotCollected (minimum mode)'
    $progressStatusInterval = 25
    $isGeekDetail = ($detailLevel -in @('geek', 'all'))
    $logPerUserDebug = $isGeekDetail
    $BasicMGDetails = $false
    $userCollectionState = [ordered]@{
        ProcessedUserCount = 0
        LicensedUserCount = 0
        UnlicensedUserCount = 0
        LicenseFallbackUserCount = 0
        UnresolvedSkuCount = 0
    }

    if (-not $script:tenantStatsHash) {
        $script:tenantStatsHash = @{}
    }
    $script:tenantStatsHash["Users"] = @{}

    $depthPolicy = if ($script:CollectionDepthPolicy) {
        $script:CollectionDepthPolicy
    }
    else {
        Get-ArrayaCollectionDepthPolicy -ReportingMode ((Get-Culture).TextInfo.ToTitleCase($detailLevel.ToLowerInvariant()))
    }
    $collectExtendedUserDetails = if ($null -ne $depthPolicy.CollectExtendedGraphEnrichment) { [bool]$depthPolicy.CollectExtendedGraphEnrichment } else { $true }
    if (-not $collectExtendedUserDetails) {
        Write-Log -Type INFO -Message "[Get-allUserDetails] Minimum mode optimization active. Skipping per-user service-plan expansion and request-id sign-in fields." -ExportFileLocation $ExportDetails
    }

    function Process-TenantUserRecord {
        param(
            [Parameter(Mandatory = $true)]
            [object]$UserRecord
        )

        $scriptLabel = if ($UserRecord.DisplayName) { [string]$UserRecord.DisplayName } elseif ($UserRecord.UserPrincipalName) { [string]$UserRecord.UserPrincipalName } else { 'User record' }
        try {
            if ($null -eq $script:tenantStatsHash -or -not ($script:tenantStatsHash -is [System.Collections.IDictionary])) {
                $script:tenantStatsHash = @{}
            }
            if ($null -eq $script:tenantStatsHash['Users'] -or -not ($script:tenantStatsHash['Users'] -is [System.Collections.IDictionary])) {
                $script:tenantStatsHash['Users'] = @{}
            }
            if ($null -eq $script:SkuLookupById -or -not ($script:SkuLookupById -is [System.Collections.IDictionary])) {
                $script:SkuLookupById = @{}
            }
            if ($null -eq $script:ServicePlanLookupById -or -not ($script:ServicePlanLookupById -is [System.Collections.IDictionary])) {
                $script:ServicePlanLookupById = @{}
            }

            function Resolve-UserLicenseSkuDisplay {
                param([AllowNull()]$SkuId)

                if ($null -eq $SkuId) {
                    return $null
                }

                $skuIdText = ([string]$SkuId).Trim()
                if ([string]::IsNullOrWhiteSpace($skuIdText)) {
                    return $null
                }

                if ($script:SkuLookupById.ContainsKey($skuIdText)) {
                    $skuLookup = $script:SkuLookupById[$skuIdText]
                    if ($skuLookup -and -not [string]::IsNullOrWhiteSpace([string]$skuLookup.FriendlyName)) {
                        return [string]$skuLookup.FriendlyName
                    }
                    if ($skuLookup -and -not [string]::IsNullOrWhiteSpace([string]$skuLookup.SkuPartNumber)) {
                        return [string]$skuLookup.SkuPartNumber
                    }
                }

                return $skuIdText
            }

            $userCollectionState.ProcessedUserCount++
            if ($userCollectionState.ProcessedUserCount -eq 1 -or ($userCollectionState.ProcessedUserCount % $progressStatusInterval) -eq 0) {
                Write-Progress -Id $userDetailsProgressId -Activity "Gathering Tenant User Details" -Status "Processed $($userCollectionState.ProcessedUserCount) user(s): $scriptLabel"
            }

            $userPrincipalName = [string]$UserRecord.UserPrincipalName
            if ([string]::IsNullOrWhiteSpace($userPrincipalName)) {
                $userPrincipalName = if ($UserRecord.Id) { "id:$($UserRecord.Id)" } else { "unknown:$([guid]::NewGuid().Guid)" }
            }
            if ($logPerUserDebug) {
                Write-Log -Type DEBUG -Message ("[Get-allUserDetails] Creating Hash for '{0}'" -f $userPrincipalName) -ExportFileLocation $ExportDetails
            }

            $signInActivity = if ($UserRecord.PSObject.Properties['SignInActivity']) { $UserRecord.SignInActivity } else { $null }
            $userProperties = [ordered]@{}
            if ($isGeekDetail) {
                foreach ($property in $UserRecord.PSObject.Properties) {
                    $userProperties[$property.Name] = $property.Value
                }
            }
            else {
                $userProperties['DisplayName'] = $UserRecord.DisplayName
                $userProperties['AssignedLicenses'] = $UserRecord.AssignedLicenses
                $userProperties['LicenseAssignmentStates'] = if ($UserRecord.PSObject.Properties['LicenseAssignmentStates']) { $UserRecord.LicenseAssignmentStates } else { $null }
                $userProperties['UserPrincipalName'] = $UserRecord.UserPrincipalName
                $userProperties['UserType'] = $UserRecord.UserType
                $userProperties['Id'] = $UserRecord.Id
                $userProperties['AccountEnabled'] = $UserRecord.AccountEnabled
                $userProperties['CreatedDateTime'] = $UserRecord.CreatedDateTime
                $userProperties['Mail'] = $UserRecord.Mail
                $userProperties['JobTitle'] = $UserRecord.JobTitle
                $userProperties['Department'] = $UserRecord.Department
                $userProperties['CompanyName'] = $UserRecord.CompanyName
                $userProperties['OfficeLocation'] = $UserRecord.OfficeLocation
                $userProperties['City'] = $UserRecord.City
                $userProperties['State'] = $UserRecord.State
                $userProperties['Country'] = $UserRecord.Country
                $userProperties['OnPremisesSyncEnabled'] = $UserRecord.OnPremisesSyncEnabled
                $userProperties['OnPremisesDistinguishedName'] = $UserRecord.OnPremisesDistinguishedName
                $userProperties['OnPremisesLastSyncDateTime'] = $UserRecord.OnPremisesLastSyncDateTime
                $userProperties['UsageLocation'] = $UserRecord.UsageLocation
                $userProperties['SignInActivity'] = $signInActivity
                $userProperties['ProxyAddresses'] = $UserRecord.ProxyAddresses
            }

            $combinedProxyAddresses = ($UserRecord.ProxyAddresses -replace '^[sS][mM][tT][pP]:') -join ';'
            $userProperties['ProxyAddresses'] = $combinedProxyAddresses

            if ($BasicMGDetails) {
                if ($logPerUserDebug) {
                    Write-Log -Type DEBUG -Message ("[Get-allUserDetails] Updating '{0}' UserType to HashTable if Basic Details" -f $userPrincipalName) -ExportFileLocation $ExportDetails
                }
                $userProperties['UserType'] = (if ($UserRecord.UserPrincipalName -like "*#EXT#*") { "GuestUser" } else { "User" })
            }
            else {
                if ($logPerUserDebug) {
                    Write-Log -Type DEBUG -Message ("[Get-allUserDetails] Gather '{0}' License Friendly Names" -f $userPrincipalName) -ExportFileLocation $ExportDetails
                }
                $assignedLicensesString = $null
                $assignedLicensesFriendlyString = $null
                $disabledPlans = $null
                $enabledServicePlans = $null
                $assignedLicenseEntries = @(
                    @($UserRecord.AssignedLicenses) | Where-Object { $null -ne $_ }
                )
                if ($assignedLicenseEntries.Count -gt 0) {
                    $userCollectionState.LicensedUserCount++
                    $resolvedSkuParts = New-Object 'System.Collections.Generic.HashSet[string]'
                    $resolvedFriendlyNames = New-Object 'System.Collections.Generic.HashSet[string]'
                    $resolvedDisabledPlans = if ($collectExtendedUserDetails) { New-Object 'System.Collections.Generic.HashSet[string]' } else { $null }
                    $resolvedEnabledPlans = if ($collectExtendedUserDetails) { New-Object 'System.Collections.Generic.HashSet[string]' } else { $null }

                    foreach ($assignedLicenseEntry in $assignedLicenseEntries) {
                        $skuId = $null
                        if ($assignedLicenseEntry.PSObject.Properties['SkuId']) {
                            $skuId = $assignedLicenseEntry.SkuId
                        }
                        elseif ($assignedLicenseEntry -is [guid]) {
                            $skuId = $assignedLicenseEntry
                        }

                        $skuIdText = if ($skuId) { $skuId.ToString() } else { $null }
                        $skuLookup = if ($skuIdText -and $script:SkuLookupById.ContainsKey($skuIdText)) { $script:SkuLookupById[$skuIdText] } else { $null }
                        if ($skuLookup) {
                            [void]$resolvedSkuParts.Add($skuLookup.SkuPartNumber)
                            [void]$resolvedFriendlyNames.Add($skuLookup.FriendlyName)

                            if ($collectExtendedUserDetails) {
                                $disabledPlanIds = @()
                                if ($assignedLicenseEntry.PSObject.Properties['DisabledPlans'] -and $assignedLicenseEntry.DisabledPlans) {
                                    $disabledPlanIds = @($assignedLicenseEntry.DisabledPlans | ForEach-Object { $_.ToString() })
                                }

                                $disabledPlanNamesForSku = @()
                                foreach ($disabledPlanId in $disabledPlanIds) {
                                    if ($script:ServicePlanLookupById.ContainsKey($disabledPlanId)) {
                                        $disabledPlanName = $script:ServicePlanLookupById[$disabledPlanId]
                                        $disabledPlanNamesForSku += $disabledPlanName
                                        [void]$resolvedDisabledPlans.Add($disabledPlanName)
                                    }
                                }

                                $enabledPlanNamesForSku = @(
                                    @($skuLookup.ServicePlans) |
                                        Where-Object {
                                            $_.ServicePlanName -and
                                            ($disabledPlanNamesForSku -notcontains $_.ServicePlanName)
                                        } |
                                        ForEach-Object { $_.ServicePlanName }
                                )
                                foreach ($enabledPlanName in $enabledPlanNamesForSku) {
                                    [void]$resolvedEnabledPlans.Add($enabledPlanName)
                                }
                            }
                        }
                        else {
                            $userCollectionState.UnresolvedSkuCount++
                            if ($skuIdText) {
                                [void]$resolvedSkuParts.Add($skuIdText)
                                [void]$resolvedFriendlyNames.Add($skuIdText)
                            }
                        }
                    }

                    $userCollectionState.LicenseFallbackUserCount++
                    $assignedLicensesString = ($resolvedSkuParts | ForEach-Object { $_ }) -join ","
                    $assignedLicensesFriendlyString = ($resolvedFriendlyNames | ForEach-Object { $_ }) -join ","
                    if ($collectExtendedUserDetails) {
                        $disabledPlans = @($resolvedDisabledPlans | ForEach-Object { $_ })
                        $enabledServicePlans = ($resolvedEnabledPlans | ForEach-Object { $_ }) -join ","
                    }
                    else {
                        $disabledPlans = @()
                        $enabledServicePlans = $minimumModeMessage
                    }
                }
                else {
                    $userCollectionState.UnlicensedUserCount++
                    if (-not $collectExtendedUserDetails) {
                        $disabledPlans = @()
                        $enabledServicePlans = $minimumModeMessage
                    }
                }
                $userProperties['AssignedLicenses'] = $assignedLicensesString
                $userProperties['AssignedLicensesFriendly'] = $assignedLicensesFriendlyString
                $userProperties['License-DisabledArray'] = $disabledPlans
                $userProperties['EnabledServicePlans'] = $enabledServicePlans

                $licenseAssignmentStates = @()
                if ($UserRecord.PSObject.Properties['LicenseAssignmentStates'] -and $UserRecord.LicenseAssignmentStates) {
                    $licenseAssignmentStates = @($UserRecord.LicenseAssignmentStates | Where-Object { $null -ne $_ })
                }
                $licenseAssignmentStateRows = New-Object System.Collections.Generic.List[object]
                $directAssignedLicenseNames = New-Object 'System.Collections.Generic.HashSet[string]'
                $groupAssignedLicenseNames = New-Object 'System.Collections.Generic.HashSet[string]'
                $licenseAssignmentErrorMessages = New-Object 'System.Collections.Generic.List[string]'
                foreach ($licenseAssignmentState in @($licenseAssignmentStates)) {
                    $stateSkuId = if ($licenseAssignmentState.PSObject.Properties['SkuId']) { $licenseAssignmentState.SkuId } elseif ($licenseAssignmentState.PSObject.Properties['skuId']) { $licenseAssignmentState.skuId } else { $null }
                    $assignedByGroup = if ($licenseAssignmentState.PSObject.Properties['AssignedByGroup']) { $licenseAssignmentState.AssignedByGroup } elseif ($licenseAssignmentState.PSObject.Properties['assignedByGroup']) { $licenseAssignmentState.assignedByGroup } else { $null }
                    $assignmentState = if ($licenseAssignmentState.PSObject.Properties['State']) { $licenseAssignmentState.State } elseif ($licenseAssignmentState.PSObject.Properties['state']) { $licenseAssignmentState.state } else { $null }
                    $assignmentError = if ($licenseAssignmentState.PSObject.Properties['Error']) { $licenseAssignmentState.Error } elseif ($licenseAssignmentState.PSObject.Properties['error']) { $licenseAssignmentState.error } else { $null }
                    $assignmentLastUpdated = if ($licenseAssignmentState.PSObject.Properties['LastUpdatedDateTime']) { $licenseAssignmentState.LastUpdatedDateTime } elseif ($licenseAssignmentState.PSObject.Properties['lastUpdatedDateTime']) { $licenseAssignmentState.lastUpdatedDateTime } else { $null }
                    $skuDisplayName = Resolve-UserLicenseSkuDisplay -SkuId $stateSkuId
                    $assignmentSource = if ([string]::IsNullOrWhiteSpace([string]$assignedByGroup) -or [string]$assignedByGroup -eq '00000000-0000-0000-0000-000000000000') { 'Direct' } else { 'Group' }

                    if (-not [string]::IsNullOrWhiteSpace([string]$skuDisplayName)) {
                        if ($assignmentSource -eq 'Direct') {
                            [void]$directAssignedLicenseNames.Add([string]$skuDisplayName)
                        }
                        else {
                            [void]$groupAssignedLicenseNames.Add([string]$skuDisplayName)
                        }
                    }

                    $hasLicenseAssignmentError = (
                        (-not [string]::IsNullOrWhiteSpace([string]$assignmentError) -and [string]$assignmentError -notmatch '^(?i)none|noerror|success$') -or
                        (-not [string]::IsNullOrWhiteSpace([string]$assignmentState) -and [string]$assignmentState -match '(?i)error')
                    )
                    if ($hasLicenseAssignmentError) {
                        $errorDisplay = if (-not [string]::IsNullOrWhiteSpace([string]$assignmentError) -and [string]$assignmentError -notmatch '^(?i)none|noerror|success$') { [string]$assignmentError } else { [string]$assignmentState }
                        $licenseAssignmentErrorMessages.Add(("{0}: {1}" -f $skuDisplayName, $errorDisplay)) | Out-Null
                    }

                    $licenseAssignmentStateRows.Add([pscustomobject]@{
                        SkuId           = if ($stateSkuId) { [string]$stateSkuId } else { $null }
                        SkuName         = $skuDisplayName
                        AssignedByGroup = if ([string]::IsNullOrWhiteSpace([string]$assignedByGroup)) { $null } else { [string]$assignedByGroup }
                        AssignmentSource = $assignmentSource
                        State           = if ($null -ne $assignmentState) { [string]$assignmentState } else { $null }
                        Error           = if ($null -ne $assignmentError) { [string]$assignmentError } else { $null }
                        LastUpdatedDateTime = if ($null -ne $assignmentLastUpdated) { [string]$assignmentLastUpdated } else { $null }
                    }) | Out-Null
                }
                $userProperties['LicenseAssignmentStates'] = @($licenseAssignmentStateRows.ToArray())
                $userProperties['DirectAssignedLicenses'] = ($directAssignedLicenseNames | ForEach-Object { $_ }) -join ','
                $userProperties['GroupAssignedLicenses'] = ($groupAssignedLicenseNames | ForEach-Object { $_ }) -join ','
                $userProperties['LicenseAssignmentErrors'] = ($licenseAssignmentErrorMessages.ToArray()) -join '; '
                $userProperties['LicenseAssignmentStateSummary'] = if ($licenseAssignmentStateRows.Count -gt 0) {
                    ('{0} direct; {1} group-based; {2} error(s)' -f $directAssignedLicenseNames.Count, $groupAssignedLicenseNames.Count, $licenseAssignmentErrorMessages.Count)
                }
                else {
                    'Not surfaced in current source'
                }
                $userProperties['LastNonInteractiveSignInDateTime'] = if ($signInActivity) { $signInActivity.LastNonInteractiveSignInDateTime } else { $null }
                if ($collectExtendedUserDetails) {
                    $userProperties['LastNonInteractiveSignInRequestId'] = if ($signInActivity) { $signInActivity.LastNonInteractiveSignInRequestId } else { $null }
                    $userProperties['LastSignInRequestId'] = if ($signInActivity) { $signInActivity.LastSignInRequestId } else { $null }
                }
                else {
                    $userProperties['LastNonInteractiveSignInRequestId'] = $minimumModeMessage
                    $userProperties['LastSignInRequestId'] = $minimumModeMessage
                }
                $userProperties['LastSignInDateTime'] = if ($signInActivity) { $signInActivity.LastSignInDateTime } else { $null }
            }

            $script:tenantStatsHash["Users"][$userPrincipalName] = [PSCustomObject]$userProperties
        }
        catch {
            $lineNumber = if ($_.InvocationInfo -and $_.InvocationInfo.ScriptLineNumber) { $_.InvocationInfo.ScriptLineNumber } else { 'unknown' }
            Write-Log -Type ERROR -Message ("[Get-allUserDetails] An error occurred in Creating User Hash for user '{0}'. Line={1}. $($_.Exception.Message)" -f $scriptLabel, $lineNumber) -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
        }
    }

    function Invoke-UserCollectionQuery {
        param(
            [switch]$BasicMode
        )

        if ($BasicMode) {
            # Deliberately degraded last-resort path: accept Graph's default property set.
            Write-Log -Type WARNING -Message '[Get-allUserDetails] Basic mode active. Graph returns only its 11 default user properties, so licensing, hybrid, and sign-in attributes will be blank.' -ExportFileLocation $ExportDetails
            Invoke-QuietCommand -ScriptBlock { Get-MgUser -All -ErrorAction Stop } |
                Where-Object { $null -ne $_.ID } |
                ForEach-Object { Process-TenantUserRecord -UserRecord $_ }
            return
        }

        # Every non-basic path selects explicitly. The geek/all levels previously omitted
        # -Property intending to fetch everything, which instead returned only Graph's 11
        # default properties and left licensing, hybrid, and sign-in columns empty.
        $selectedProperties = @($DesiredProperties)

        # signInActivity requires Microsoft Entra ID P1/P2 plus AuditLog.Read.All. Probe
        # once so a missing licence or scope costs the sign-in columns, not the whole
        # user inventory.
        if ($selectedProperties -contains 'SignInActivity') {
            try {
                Invoke-QuietCommand -ScriptBlock { Get-MgUser -Top 1 -Property 'Id', 'SignInActivity' -ErrorAction Stop } | Out-Null
            }
            catch {
                $selectedProperties = @($selectedProperties | Where-Object { $_ -ne 'SignInActivity' })
                Write-Log -Type WARNING -Message "[Get-allUserDetails] signInActivity is unavailable (needs Microsoft Entra ID P1/P2 and AuditLog.Read.All): $($_.Exception.Message). Continuing without sign-in activity; all other user attributes are still collected." -ExportFileLocation $ExportDetails
                Write-AssessmentConsoleSubstep -Message 'Users: sign-in activity unavailable (needs Entra ID P1/P2 and AuditLog.Read.All); continuing without it.' -ForegroundColor Yellow
            }
        }

        $queryProperties = $selectedProperties
        $queryPageSize = $userPageSize
        Write-Log -Type INFO -Message "[Get-allUserDetails] Requesting $($queryProperties.Count) Graph user properties (PageSize=$queryPageSize; SignInActivity=$($queryProperties -contains 'SignInActivity'))." -ExportFileLocation $ExportDetails

        Invoke-QuietCommand -ScriptBlock { Get-MgUser -All -Property $queryProperties -PageSize $queryPageSize -ErrorAction Stop } |
            Where-Object { $null -ne $_.ID } |
            ForEach-Object { Process-TenantUserRecord -UserRecord $_ }
    }

    try {
        Write-AssessmentConsoleSubstep -Message 'Users: Graph inventory retrieval and per-user enrichment'
        Write-Log -Type Info -Message "[Get-allUserDetails] START: Getting all Microsoft Graph $($detailLevel) User data" -ExportFileLocation $ExportDetails
        Write-Progress -Id $graphUsersProgressId -Activity "Getting all Microsoft Graph User Data" -Status (((Get-Date) - $global:initialStart).ToString('hh\:mm\:ss'))

        $maxRetries = 3
        $collectionSucceeded = $false
        for ($attempt = 1; $attempt -le $maxRetries; $attempt++) {
            try {
                $script:tenantStatsHash["Users"] = @{}
                $userCollectionState.ProcessedUserCount = 0
                $userCollectionState.LicensedUserCount = 0
                $userCollectionState.UnlicensedUserCount = 0
                $userCollectionState.LicenseFallbackUserCount = 0
                $userCollectionState.UnresolvedSkuCount = 0
                Invoke-UserCollectionQuery
                $collectionSucceeded = $true
                break
            }
            catch {
                if ($attempt -lt $maxRetries) {
                    $waitSeconds = [math]::Min([math]::Pow(2, $attempt), 30)
                    Write-Log -Type WARNING -Message "[Get-allUserDetails] Attempt $attempt failed: $($_.Exception.Message). Retrying in $waitSeconds seconds..." -ExportFileLocation $ExportDetails
                    Start-Sleep -Seconds $waitSeconds
                }
                else {
                    throw
                }
            }
        }
        if (-not $collectionSucceeded) {
            throw "Graph user collection did not complete successfully."
        }
    }
    catch {
        if ($_.Exception.Message -like "*Neither tenant is B2C or tenant doesn't have premium license*") {
            Write-Log -Type ERROR -Message "[Get-allUserDetails] An error occurred in running Get-allMGUserDetails function. $($_.Exception.Message)" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_

            Write-Host
            Write-AssessmentConsoleSubstep -Message 'Users: tenant license lookup unavailable, continuing without license and sign-in activity enrichment' -ForegroundColor 'Yellow'
            try {
                Write-Log -Type Info -Message "[Get-allUserDetails] Attempt 2. Getting all Microsoft Graph $($detailLevel) with limited User Details" -ExportFileLocation $ExportDetails
                $script:tenantStatsHash["Users"] = @{}
                $userCollectionState.ProcessedUserCount = 0
                $userCollectionState.LicensedUserCount = 0
                $userCollectionState.UnlicensedUserCount = 0
                $userCollectionState.LicenseFallbackUserCount = 0
                $userCollectionState.UnresolvedSkuCount = 0
                $BasicMGDetails = $true
                Invoke-UserCollectionQuery -BasicMode
            }
            catch {
                Write-Log -Type ERROR -Message "[Get-allUserDetails] An error occurred in running Get-allMGUserDetails function. $($_.Exception.Message)" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
            }
        }
        else {
            Write-Log -Type Error -Message "[Get-allUserDetails] An error occurred in running Get-allMGUserDetails function. $($_.Exception.Message)" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
            Write-Log -Type WARNING -Message "[Get-allUserDetails] Continuing without user details due to Graph request failure." -ExportFileLocation $ExportDetails
            return
        }
    }
    finally {
        Write-Progress -Id $graphUsersProgressId -Activity "Getting all Microsoft Graph User Data" -Completed
    }

    Write-Log -Type Info -Message "[Get-allUserDetails] Added additional properties for $($userCollectionState.ProcessedUserCount) users" -ExportFileLocation $ExportDetails
    try {
        Write-Progress -Id $userDetailsProgressId -Activity "Gathering Tenant User Details" -Status "Processed $($userCollectionState.ProcessedUserCount) user(s)"
        Write-AssessmentConsoleSubstep -Message ("Users: processed {0} total directory records" -f $userCollectionState.ProcessedUserCount)
        [GC]::Collect()
        [GC]::WaitForPendingFinalizers()
        $CompletedTime = (((Get-Date) - $start).ToString('hh\:mm\:ss'))
        Write-AssessmentCollectorCompletionBanner -Message "Completed in $($CompletedTime)"
        Write-Log -Type INFO -Message "[Get-allUserDetails] Licensing summary: LicensedUsers=$($userCollectionState.LicensedUserCount) UnlicensedUsers=$($userCollectionState.UnlicensedUserCount) LicenseLookupUsers=$($userCollectionState.LicenseFallbackUserCount) UnresolvedSkuReferences=$($userCollectionState.UnresolvedSkuCount)" -ExportFileLocation $ExportDetails

        # Zero licensed users in a tenant that has any processed users means the property
        # selection or the SKU lookup failed, which previously went unnoticed because it
        # was only visible in the log.
        if ($userCollectionState.ProcessedUserCount -gt 0 -and $userCollectionState.LicensedUserCount -eq 0) {
            Write-AssessmentConsoleSubstep -Message ("Users: no licensed users resolved across {0} user(s). Check that AssignedLicenses was returned by Graph and that LicenseSKUs collected." -f $userCollectionState.ProcessedUserCount) -ForegroundColor Yellow
            Write-Log -Type WARNING -Message "[Get-allUserDetails] No licensed users resolved across $($userCollectionState.ProcessedUserCount) processed user(s). This usually means AssignedLicenses was not selected from Graph or the SKU lookup was empty." -ExportFileLocation $ExportDetails
        }
        else {
            Write-AssessmentConsoleSubstep -Message ("Users: {0} licensed, {1} unlicensed of {2} processed." -f $userCollectionState.LicensedUserCount, $userCollectionState.UnlicensedUserCount, $userCollectionState.ProcessedUserCount)
        }
        Write-Log -Type Info -Message "[Get-allUserDetails] COMPLETED: Gathering all  User Details in $($CompletedTime)" -ExportFileLocation $ExportDetails
    }     
    catch {
        Write-Log -Type ERROR -Message "[Get-allUserDetails] An error occurred in running Get-allUserDetails function. $($_.Exception.Message)" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
    }
    finally {
        Write-Progress -Id $userDetailsProgressId -Activity "Gathering Tenant User Details" -Completed
    }
}

#Gather all Office 365 Admins
function Get-AllOffice365Admins {
    param ()
    $start = Get-Date
    # Ensure global hash table structure
    if (-not $script:tenantStatsHash) {
        $script:tenantStatsHash = @{}
    }
    $script:tenantStatsHash["Admins"] = @{}
    $adminResults = New-Object System.Collections.Generic.List[object]
    Write-AssessmentCollectorBanner -Message 'Gathering All Admins ...' -NoNewline
    Write-Log -Type INFO -Message "[Get-AllOffice365Admins] START: Gathering All Admins from Tenant" -ExportFileLocation $ExportDetails

    try {
        # Gather all Admin Roles
        $adminRoles = Get-MgDirectoryRole -ProgressAction SilentlyContinue | Select DisplayName, ID, Description | ? {$null -ne $_.DisplayName}
        $totalCount = $adminRoles.count
        Write-Log -Type INFO -Message "[Get-AllOffice365Admins] Admin Roles Found: $($adminRoles.count)" -ExportFileLocation $ExportDetails
        foreach ($role in $adminRoles) {
            $roleName = $role.DisplayName
            Write-Log -Type DEBUG -Message "[Get-AllOffice365Admins] $($roleName): Gathering Admins in Role" -ExportFileLocation $ExportDetails
            Write-ProgressHelper -Total $totalCount -Id 1 -Activity "Gathering Admins in Roles" -Operation "Checking Role: $($roleName)" 
            $roleMemberList = Invoke-ArrayaCollectionStepSafe -OperationName "Get-AllOffice365Admins role membership for $roleName" -DefaultValue @() -ExportFileLocation $ExportDetails -ScriptBlock {
                @(Get-MgDirectoryRoleMember -DirectoryRoleId $role.Id -ProgressAction SilentlyContinue -ErrorAction Stop | Where-Object { $null -ne $_.Id })
            }
            if ($roleMemberList) {
                $totalCount2 = $roleMemberList.count
                Write-Log -Type INFO -Message "[Get-AllOffice365Admins] $($roleName) Users Found: $($roleMemberList.count)" -ExportFileLocation $ExportDetails
                foreach ($roleMember in $roleMemberList) {
                    $Name = $null
                    $UPN = $null
                    $mail = $null
                    $jobTitle = $null
                    $UserType = $null
                    $AccountEnabled = $null
                    $LastSignInDateTime = $null
                    $CreatedDate = $null
                    $GroupMailEnabled = $null
                    $GroupMailNickname = $null
                    $GroupType = $null
                    $Name = $roleMember.AdditionalProperties['displayName']
                    if ($roleMember.AdditionalProperties['@odata.type'] -eq "#microsoft.graph.group") {
                        # Group Specific Values
                        $GroupMailEnabled = $roleMember.AdditionalProperties['mailEnabled']
                        $GroupMailNickname = $roleMember.AdditionalProperties['mailNickname']
                        $GroupType = ($roleMember.AdditionalProperties['groupTypes'] -join ",")
                        $CreatedDate = [datetime]::Parse($roleMember.AdditionalProperties['createdDateTime']).ToShortDateString()
                    } elseif ($roleMember.AdditionalProperties['@odata.type'] -eq "#microsoft.graph.user") {
                        # User Specific Values
                        $UPN = $roleMember.AdditionalProperties['userPrincipalName']
                        $mail = $roleMember.AdditionalProperties['mail']
                        $jobTitle = $roleMember.AdditionalProperties['jobTitle']

                        # Check if user is in tenant stats hash (guarded for profile/collector skips)
                        $usersLookup = if (
                            $script:tenantStatsHash.ContainsKey('Users') -and
                            $script:tenantStatsHash['Users'] -is [System.Collections.IDictionary]
                        ) {
                            $script:tenantStatsHash['Users']
                        }
                        else {
                            $null
                        }
                        if ($usersLookup -and $usersLookup.ContainsKey($UPN)) {
                            $userMatch = $usersLookup[$UPN]
                        } else { $userMatch = $null }
                        $UserType = $userMatch.UserType
                        $AccountEnabled = $userMatch.AccountEnabled
                        $LastSignInDateTime = $userMatch.LastSignInDateTime
                        $CreatedDate = $userMatch.CreatedDateTime

                    }
                    Write-Log -Type DEBUG "[Get-AllOffice365Admins] Gathering MGGraph Role Details for User: $($Name)" -ExportFileLocation $ExportDetails
                    $currentAdmin = New-Object PSObject -Property ([ordered]@{
                        # Default Values
                        Role = $roleName
                        DirectoryObjectId = $roleMember.Id
                        ObjectType = $roleMember.AdditionalProperties['@odata.type']
                        DisplayName = $Name
                        Mail = $mail
                        CreatedDate = if ($CreatedDate) { $CreatedDate } else { $null }
                        # User Specific Values
                        UserPrincipalName = if ($UPN) { $UPN } else { $null }
                        AccountEnabled = if ($null -ne $AccountEnabled) { $AccountEnabled } else { $null }
                        userType = if ($UserType) { $UserType } else { $null }
                        JobTitle = if ($jobTitle) { $jobTitle } else { $null }
                        LastSignInDateTime = if ($LastSignInDateTime) { $LastSignInDateTime } else { $null }
                        # Group Specific Values
                        GroupMailEnabled = if ($null -ne $GroupMailEnabled) { $GroupMailEnabled } else { $null }
                        GroupMailNickname = if ($GroupMailNickname) { $GroupMailNickname } else { $null }
                        GroupType = if ($GroupType) { $GroupType } else { $null }
                    })
                        
                    Write-ProgressHelper -Total $totalCount2 -Id 2 -ParentId 1 -Activity "Gathering Admin Details" -Operation "Gathering Admin Role Details: $($roleMember.DisplayName)"
    
                    $adminResults.Add($currentAdmin)
                }
            }
            
        }
        
        #Group by DisplayName or UserPrincipalName and combine roles into a comma-separated list
        $groupedResults = $adminResults | Group-Object -Property DisplayName,UserPrincipalName
        Write-Log -Type INFO -Message "[Get-AllOffice365Admins] Combining roles across $($groupedResults.Count) grouped admin entries" -ExportFileLocation $ExportDetails
        $finalResults = $groupedResults | ForEach-Object {
            $group = $_.Group
            $roles = ($group.Role -join ', ')
            # Use the properties of the first user in each group, but replace the Role with the combined roles
            $group[0] | Add-Member -MemberType NoteProperty -Name 'Role' -Value $roles -Force
            $group[0] | Add-Member -MemberType NoteProperty -Name 'RolesAssigned' -Value (($group.Role | Measure-Object).count) -Force
            $group[0]
        }

        foreach ($result in $finalResults) {
            $adminKeyBase = if (-not [string]::IsNullOrWhiteSpace([string]$result.UserPrincipalName)) {
                ([string]$result.UserPrincipalName).Trim().ToLowerInvariant()
            }
            elseif (-not [string]::IsNullOrWhiteSpace([string]$result.Mail)) {
                ([string]$result.Mail).Trim().ToLowerInvariant()
            }
            else {
                # Keep this deterministic for non-user principals.
                ("{0}|{1}|{2}" -f [string]$result.ObjectType, [string]$result.DisplayName, [string]$result.Role).ToLowerInvariant()
            }

            $adminKey = $adminKeyBase
            $duplicateSuffix = 2
            while ($script:tenantStatsHash["Admins"].ContainsKey($adminKey)) {
                $adminKey = "{0}#{1}" -f $adminKeyBase, $duplicateSuffix
                $duplicateSuffix++
            }

            $script:tenantStatsHash["Admins"][$adminKey] = $result
        }
    }
    catch {
        Write-Log -Type ERROR -Message "[Get-AllOffice365Admins] An error occurred in running Get-AllOffice365Admins function. $($_.Exception.Message)" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
    }
    finally {
        $CompletedTime = (((Get-Date) - $start).ToString('hh\:mm\:ss'))
        Write-AssessmentCollectorCompletionBanner -Message "Completed in $($CompletedTime)"
        Write-ProgressHelper -Total $totalCount -Id 1 -Activity "Gathering Admins in Roles" -Completed
        Write-ProgressHelper -Total 1 -Id 2 -Activity "Gathering Admin Details" -Completed
        Write-Log -Type INFO -Message "[Get-AllOffice365Admins] COMPLETED: Gathering All Admins in $($CompletedTime)" -ExportFileLocation $ExportDetails
    }
}

# Get all Office 365 Domains
function Get-AllOffice365Domains {
    param ()
    function Get-RecipientCounts {
        param (
            [Parameter(Mandatory = $true)]
            [array]$Recipients, # Array of recipient objects
    
            [Parameter(Mandatory = $true)]
            [string]$DomainName # The domain name to filter on
        )
    
        # Initialize counts
        $RecipientsWithPrimarySMTPCount = 0
        $DomainRecipientsCount = 0
        $RecipientsAliasOnlyCount = 0
    
        try {
            Write-Log -Type INFO -Message "[Get-AllOffice365Domains] Calculating recipient counts for domain: $DomainName" -ExportFileLocation $ExportDetails
            # Count recipients with Primary SMTP using the domain
            $RecipientsWithPrimarySMTPCount = ($Recipients | Where-Object {
                $_.PrimarySmtpAddress -like "*@$($DomainName)"
            }).Count
            Write-Log -Type INFO -Message "[Get-AllOffice365Domains] '$($DomainName)' Recipients with Primary SMTP Count: $RecipientsWithPrimarySMTPCount" -ExportFileLocation $ExportDetails
    
            # Count recipients with the domain in any of their aliases (EmailAddresses)
            $DomainRecipientsCount = ($Recipients | Where-Object {
                # Split EmailAddresses into an array
                $emailArray = $_.EmailAddresses -split ','
                # Check if any of the addresses contain the domain
                $emailArray -like "*@$($DomainName)*"
            }).Count
            Write-Log -Type INFO -Message "[Get-AllOffice365Domains] '$($DomainName)' Recipients with Alias Count: $DomainRecipientsCount" -ExportFileLocation $ExportDetails
    
            # Count recipients with the domain as alias only (not primary)
            $RecipientsAliasOnlyCount = ($Recipients | Where-Object {
                # Split EmailAddresses into an array
                $emailArray = $_.EmailAddresses -split ','
    
                # Check if there is at least one lowercase smtp alias with the domain
                $hasAlias = $emailArray -like "smtp:*@$($DomainName)"
                # Ensure the primary SMTP is not the domain
                $notPrimarySMTP = $_.PrimarySmtpAddress -notlike "*@$($DomainName)"
    
                # Return true only if the alias exists and it's not the primary SMTP
                $hasAlias -and $notPrimarySMTP
            }).Count
            Write-Log -Type INFO -Message "[Get-AllOffice365Domains] '$($DomainName)' Recipients with Alias Only Count: $RecipientsAliasOnlyCount" -ExportFileLocation $ExportDetails
    
        } catch {
            Write-Host "An error occurred while calculating recipient counts: $($_.Exception.Message)" -ForegroundColor Red
        }
    
        # Return results as a custom object
        return [PSCustomObject]@{
            PrimarySMTPCount = $RecipientsWithPrimarySMTPCount
            AliasOnlyCount   = $RecipientsAliasOnlyCount
            TotalDomainRecipientsCount = $DomainRecipientsCount
        }
    }

    # Resolve DNS
    function Get-DNSHostCompanyName {
        param (
            [Parameter(Mandatory=$true)]
            [object]$nsRecords
        )
        # Define a mapping of common DNS hosts to company names
        $dnsHostMapping = @{
            'ptd.net' = 'PenTeleData'
            'comcast.net' = 'Comcast'
            'charter.com' = 'Charter Communications'
            'rr.com' = 'Road Runner'
            'verizon.net' = 'Verizon'
            'cox.net' = 'Cox Communications'
            'sbcglobal.net' = 'AT&T'
            'frontiernet.net' = 'Frontier Communications'
            'earthlink.net' = 'EarthLink'
            'oraclecloud.net' = 'Oracle'
            'microsoft.com' = 'Microsoft'
            'google.com' = 'Google'
            'worldnic.com' = 'Network Solutions'
            'cloudflare.com' = 'Cloudflare'
            'domaincontrol.com' = 'GoDaddy'
            'namecheaphosting.com' = 'Namecheap'
            # Add more mappings as needed
        }
    
        # Function to get the main domain from a DNS host
        function Get-MainDomain {
            param (
                [string]$DNSHost
            )
            $parts = $DNSHost -split '\.'
            return ($parts[-2] + '.' + $parts[-1])
        }

        # Return if NS records are empty
        if (-not $nsRecords) {
            return @()
        }
    
        # Ensure nsRecords is an array
        if (-not ($nsRecords -is [array])) {
            $nsRecords = @($nsRecords)
        }
    
        # Get NS records and company names
        $mainDomains = $nsRecords | ForEach-Object { Get-MainDomain -DNSHost $_.NameHost }
        $uniqueMainDomains = $mainDomains | Select-Object -Unique
        $nsCompanies = ($uniqueMainDomains | ForEach-Object {
            if ($dnsHostMapping.ContainsKey($_)) {
                $dnsHostMapping[$_]
            } else {
                $_
            }
        })
    
        return $nsCompanies
    }

    # Initialize the hash tables for the domains and remote domains.
    $start = Get-Date
    # Ensure global hash table structure
    if (-not $script:tenantStatsHash) {
        $script:tenantStatsHash = @{}
    }
    $script:tenantStatsHash["Domains"] = @{}
    $script:tenantStatsHash["RemoteDomains"] = @{}
    Write-AssessmentCollectorBanner -Message 'Gathering All Domains ...' -NoNewline
    Write-Log -Type INFO -Message "[Get-AllOffice365Domains] START: Gathering All Domains from tenant" -ExportFileLocation $ExportDetails
    try {
        # Get all the domains
        $domains = Get-MgDomain -ProgressAction SilentlyContinue | ? {$null -ne $_.ID}
        #Gather Exchange Online Domain Details
        try {
            Write-Log -Type INFO -Message "[Get-AllOffice365Domains] Gathering Exchange Online Domain Details" -ExportFileLocation $ExportDetails
            $acceptedDomains = Get-AcceptedDomain
            $remoteDomains = Get-RemoteDomain | select Identity, DomainName, IsInternal, TargetDeliveryDomain, AllowedOOFType, AutoReplyEnabled, AutoForwardEnabled, DeliveryReportEnabled, NDREnabled, MeetingForwardNotificationEnabled, ContentType, TNEFEnabled, TrustedMailOutboundEnabled, TrustedMailInboundEnabled
            if ($script:tenantStatsHash['AllRecipients']) {
                $recipients = $script:tenantStatsHash['AllRecipients'].values
            } else {$recipients = Get-EXORecipient -ResultSize Unlimited}
                        
            $exchangeOnline = $True
        }
        catch {  
            if ($_.Exception.Message -like "*The term 'Get-AcceptedDomain' is not recognized*") {
                Write-Log -Type ERROR -Message "An error occurred in running Get-AllOffice365Domains function. Exception: Not Properly Connected to Exchange Online Tenant. Check Permissions and reconnect to Exchange Online. Skipping Exchange portion" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
                
                $exchangeOnline = $False
            }
            else {
                Write-Log -Type Error -Message "[Get-AllOffice365Domains] Exchange Online not connected for other reasons. $($_.Exception.Message)" -ExportFileLocation $ExportDetails
                Write-Error $_.Exception.Message
            }
        }
        # Get all Remote and Accepted domains
        $totalCount = $domains.count
        Write-Log  -Type INFO -Message "[Get-AllOffice365Domains] $($domains.count) domains found in tenant" -ExportFileLocation $ExportDetails

        foreach ($domain in $domains) {
            try {
                # Get the DNS records
                $domainName = $domain.ID
                $domainVerified = $domain.IsVerified       
                $AuthenticationType = if ($null -ne $domain.AuthenticationType -and -not [string]::IsNullOrWhiteSpace([string]$domain.AuthenticationType)) { [string]$domain.AuthenticationType } else { 'Unknown' }
                Write-Log -Type DEBUG -Message "[Get-AllOffice365Domains] Gathering '$($domainName)' domain details" -ExportFileLocation $ExportDetails
                Write-ProgressHelper -Total $totalCount -Id 1 -Activity "Gathering Domain Details" -Operation "'$($domainName)'"

                #Gather DNS Records from 1.1.1.1
                Write-Log -Type DEBUG -Message "[Get-AllOffice365Domains] Gathering DNS Records for '$($domainName)'" -ExportFileLocation $ExportDetails
                $aRecords = Resolve-DnsName -Name $domainName -Server 1.1.1.1 -Type A -ErrorAction Ignore -verbose:$false
                $mxRecords = Resolve-DnsName -Name $domainName -Server 1.1.1.1 -Type MX -ErrorAction Ignore -verbose:$false
                $NSRecords = Resolve-DnsName -Name $domainName -Server 1.1.1.1 -Type NS -ErrorAction Ignore -verbose:$false
                $txtRecords = Resolve-DnsName -Name $domainName -Server 1.1.1.1 -Type TXT -ErrorAction Ignore -verbose:$false
                $dmarcRecords = Resolve-DnsName -Name ("_dmarc.{0}" -f $domainName) -Server 1.1.1.1 -Type TXT -ErrorAction Ignore -verbose:$false

                $selectorRecords = @()
                foreach ($selector in @('selector1', 'selector2')) {
                    $selectorRecords += @(Resolve-DnsName -Name ("{0}._domainkey.{1}" -f $selector, $domainName) -Server 1.1.1.1 -Type CNAME -ErrorAction Ignore -verbose:$false)
                }

                $spfConfigured = $false
                $dmarcConfigured = $false
                $dkimSelectorCount = 0
                $dkimConfigured = $false

                $txtValues = @($txtRecords | ForEach-Object { @($_.Strings) -join '' } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
                $spfRecord = $null
                $spfPolicyMode = $null
                if ($txtValues.Count -gt 0) {
                    $spfRecord = @($txtValues | Where-Object { $_ -match '(?i)^v=spf1' } | Select-Object -First 1)
                    if ($spfRecord.Count -gt 0) {
                        $spfRecord = $spfRecord[0]
                    } else {
                        $spfRecord = $null
                    }
                    $spfConfigured = @($txtValues | Where-Object { $_ -match '(?i)^v=spf1' -and $_ -match '(?i)include:spf\.protection\.outlook\.com' }).Count -gt 0
                    if ($spfRecord) {
                        if ($spfRecord -match '(?i)\s-all\b') { $spfPolicyMode = 'HardFail (-all)' }
                        elseif ($spfRecord -match '(?i)\s~all\b') { $spfPolicyMode = 'SoftFail (~all)' }
                        elseif ($spfRecord -match '(?i)\s\+all\b') { $spfPolicyMode = 'AllowAll (+all)' }
                        elseif ($spfRecord -match '(?i)\s\?all\b') { $spfPolicyMode = 'Neutral (?all)' }
                        else { $spfPolicyMode = 'Unspecified' }
                    }
                }

                $dmarcValues = @($dmarcRecords | ForEach-Object { @($_.Strings) -join '' } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
                $dmarcRecord = $null
                $dmarcPolicy = $null
                $dmarcPct = $null
                if ($dmarcValues.Count -gt 0) {
                    $dmarcConfigured = @($dmarcValues | Where-Object { $_ -match '(?i)^v=dmarc1' }).Count -gt 0
                    $dmarcRecord = @($dmarcValues | Where-Object { $_ -match '(?i)^v=dmarc1' } | Select-Object -First 1)
                    if ($dmarcRecord.Count -gt 0) {
                        $dmarcRecord = $dmarcRecord[0]
                    } else {
                        $dmarcRecord = $null
                    }
                    if ($dmarcRecord) {
                        $policyMatch = [regex]::Match($dmarcRecord, '(?i)\bp=([a-z]+)')
                        if ($policyMatch.Success) {
                            $dmarcPolicy = $policyMatch.Groups[1].Value.ToLowerInvariant()
                        }
                        $pctMatch = [regex]::Match($dmarcRecord, '(?i)\bpct=(\d{1,3})')
                        if ($pctMatch.Success) {
                            $dmarcPct = [int]$pctMatch.Groups[1].Value
                        } else {
                            $dmarcPct = 100
                        }
                    }
                }

                $dkimSelectorCount = @($selectorRecords | Where-Object { $_.NameHost }).Count
                $dkimConfigured = ($dkimSelectorCount -ge 2)
                $selector1Host = @($selectorRecords | Where-Object { $_.Name -like 'selector1._domainkey*' -and $_.NameHost } | Select-Object -First 1 -ExpandProperty NameHost)
                $selector2Host = @($selectorRecords | Where-Object { $_.Name -like 'selector2._domainkey*' -and $_.NameHost } | Select-Object -First 1 -ExpandProperty NameHost)
                if ($selector1Host.Count -gt 0) { $selector1Host = $selector1Host[0] } else { $selector1Host = $null }
                if ($selector2Host.Count -gt 0) { $selector2Host = $selector2Host[0] } else { $selector2Host = $null }

                if ($NSRecords) {
                    $DNSCompanies =  Get-DNSHostCompanyName -nsRecords $NSRecords -ErrorAction SilentlyContinue
                }
                else {
                    $DNSCompanies = $null
                }
                Write-Log -Type DEBUG -Message "[Get-AllOffice365Domains] Completed Gathering DNS Records for '$($domainName)'"

                $DomainType = 'Unknown'
                $RecipientCounts = [PSCustomObject]@{
                    PrimarySMTPCount = 0
                    AliasOnlyCount = 0
                    TotalDomainRecipientsCount = 0
                }

                #Check for Exchange Online Dependencies
                if ($exchangeOnline -eq $true) {
                    Write-Log -Type DEBUG -Message "[Get-AllOffice365Domains] Gathering Exchange Online Domain Details for '$($domainName)'" -ExportFileLocation $ExportDetails
                    $domainTypeValue = @($acceptedDomains | Where-Object { $_.DomainName -eq $domainName } | Select-Object -First 1 -ExpandProperty "DomainType")
                    if ($domainTypeValue.Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$domainTypeValue[0])) {
                        $DomainType = [string]$domainTypeValue[0]
                    }
                    else {
                        $DomainType = 'Unknown'
                    }
                    #Domain Dependencies
                    $RecipientCounts = Get-RecipientCounts -Recipients $recipients -DomainName $domainName
                }
                else { Write-Log -Type Error -Message "[Get-AllOffice365Domains] Skipping Exchange Online Domain Details for '$($domainName)'" -ExportFileLocation $ExportDetails }
                # Add to the results array
                Write-Log -Type INFO -Message "[Get-AllOffice365Domains] Adding '$($domainName)' to results array" -ExportFileLocation $ExportDetails
                $currentDomain = [PSCustomObject]@{
                    # ===== Domain Identity =====
                    Domain             = $domainName
                    DomainType         = $DomainType
                    Verified           = $domainVerified
                    IsDefault          = $domain.IsDefault
                    AuthenticationType = $AuthenticationType
            
                    # ===== DNS Records =====
                    DNSCompanies           = $DNSCompanies -join ","
                    NSRecords              = ($NSRecords.NameHost -join ",") -replace "`n|`r",     ""
                    ARecords               = ($aRecords.IPAddress -join ",") -replace "`n|`r",     ""
                    MXRecords              = ($mxRecords.NameExchange -join ",") -replace "`n|`r", ""
                    Office365MailExchanger = ($mxRecords.NameExchange -join "," -like "*protection.outlook.com")
                    SpfRecord              = $spfRecord
                    SpfIncludesM365        = $spfConfigured
                    SpfPolicyMode          = $spfPolicyMode
                    DmarcRecord            = $dmarcRecord
                    DmarcConfigured        = $dmarcConfigured
                    DmarcPolicy            = $dmarcPolicy
                    DmarcPercent           = $dmarcPct
                    DkimConfigured         = $dkimConfigured
                    DkimSelectorsConfigured = $dkimSelectorCount
                    DkimSelector1          = $selector1Host
                    DkimSelector2          = $selector2Host
                    DkimSelectorRecords    = (($selectorRecords | Where-Object { $_.NameHost } | Select-Object -ExpandProperty NameHost) -join ",")
            
                    # ===== Recipient Counts =====
                    PrimarySMTPRecipients = $RecipientCounts.PrimarySMTPCount
                    AliasOnlyRecipients   = $RecipientCounts.AliasOnlyCount
                    TotalDomainRecipients = $RecipientCounts.TotalDomainRecipientsCount
                }
                $script:tenantStatsHash["Domains"][$domainName] = $currentDomain
            }
            catch {
                Write-Log -Type ERROR -Message "An error occurred in running Get-AllOffice365Domains function. $($_.Exception.Message)" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
            }
        }
        foreach ($domain in $remoteDomains) {
            # Add to the results Hash Table
            $script:tenantStatsHash["RemoteDomains"][$domain.Identity] = $domain
        }
    }
    catch {
        Write-Log -Type ERROR -Message "An error occurred in running Get-AllOffice365Domains function. $($_.Exception.Message)" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
    }
    finally {
        $CompletedTime = (((Get-Date) - $start).ToString('hh\:mm\:ss'))
        Write-AssessmentCollectorCompletionBanner -Message "Completed in $($CompletedTime)"
        Write-ProgressHelper -Total $totalCount -Id 1 -Activity "Gathering Domain Details" -Completed
        Write-Log -Type INFO -Message "[Get-AllOffice365Domains] COMPLETED: Gathering All Domain Details" -ExportFileLocation $ExportDetails
    }
}
# ----------------------------------
# Combine Mailbox Details Specific Functions
# ----------------------------------

# Function to combine all user and mailbox statistics - User Priority and Mailbox Priority
function Report-UserAndMailboxStats {
    [CmdletBinding()]
    param ()

    $logPerRecordDebug = Test-ShowCollectorDiagnostics
    if (-not $script:tenantStatsHash) {
        $script:tenantStatsHash = @{}
    }
    $tenantStatsStore = $script:tenantStatsHash

    function Get-LookupTable {
        param(
            [Parameter(Mandatory = $true)]
            [hashtable]$TenantStatsStore,
            [Parameter(Mandatory = $true)]
            [string]$Key
        )

        if (-not $TenantStatsStore.ContainsKey($Key)) {
            return $null
        }

        $candidate = $TenantStatsStore[$Key]
        if ($candidate -is [System.Collections.IDictionary]) {
            return $candidate
        }

        return $null
    }

    function Get-DictionaryValue {
        param(
            [Parameter(Mandatory = $false)]
            [object]$Dictionary,
            [Parameter(Mandatory = $false)]
            [AllowNull()]
            $Key
        )

        if ($null -eq $Dictionary -or $null -eq $Key) {
            return $null
        }

        if ($Dictionary -is [System.Collections.IDictionary]) {
            if ($Dictionary.Contains($Key)) {
                return $Dictionary[$Key]
            }
            return $null
        }

        return $null
    }

    function Resolve-StatsSizeGb {
        param(
            [Parameter(Mandatory = $false)]
            [AllowNull()]
            $Stats,
            [Parameter(Mandatory = $true)]
            [string]$CachePrefix,
            [Parameter(Mandatory = $true)]
            [hashtable]$Cache
        )

        if ($null -eq $Stats) {
            return 0
        }

        $cacheKey = $null
        if ($Stats.PSObject.Properties['MailboxGuid'] -and $Stats.MailboxGuid) {
            $cacheKey = "{0}:{1}" -f $CachePrefix, [string]$Stats.MailboxGuid
        }

        if ($cacheKey -and $Cache.ContainsKey($cacheKey)) {
            return $Cache[$cacheKey]
        }

        $sizeBytes = [int64]0
        if ($Stats.PSObject.Properties['TotalItemSizeBytes'] -and $Stats.TotalItemSizeBytes) {
            $sizeBytes = [int64]$Stats.TotalItemSizeBytes
        }
        elseif ($Stats.PSObject.Properties['TotalItemSize'] -and $Stats.TotalItemSize) {
            $sizeBytes = Convert-DataSizeToBytes -Value $Stats.TotalItemSize
        }

        $sizeGb = [math]::Round(($sizeBytes / 1GB), 3)
        if ($cacheKey) {
            $Cache[$cacheKey] = $sizeGb
        }

        return $sizeGb
    }

    function New-IndexedLookupTable {
        param(
            [AllowNull()]$Source,
            [Parameter(Mandatory = $true)]
            [string[]]$PropertyNames
        )

        $index = @{}
        if ($null -eq $Source) {
            return $index
        }

        $records = @()
        if ($Source -is [System.Collections.IDictionary]) {
            $records = @($Source.Values)
        }
        elseif ($Source -is [System.Collections.IEnumerable] -and -not ($Source -is [string])) {
            $records = @($Source)
        }
        else {
            $records = @($Source)
        }

        foreach ($record in $records) {
            if ($null -eq $record -or -not $record.PSObject) { continue }
            foreach ($propertyName in $PropertyNames) {
                if (-not $record.PSObject.Properties[$propertyName]) { continue }
                $rawValue = [string]$record.PSObject.Properties[$propertyName].Value
                if ([string]::IsNullOrWhiteSpace($rawValue)) { continue }

                $trimmedValue = $rawValue.Trim()
                if (-not $index.ContainsKey($trimmedValue)) {
                    $index[$trimmedValue] = $record
                }

                $lowerValue = $trimmedValue.ToLowerInvariant()
                if (-not $index.ContainsKey($lowerValue)) {
                    $index[$lowerValue] = $record
                }
            }
        }

        return $index
    }

    function Populate-Details {
        param (
            [Parameter(Mandatory = $true)]
            [object]$entity,
            [Parameter(Mandatory = $false)]
            [switch]$IsMailbox
        )

        $detailsMap = [ordered]@{}
        try {
            foreach ($property in $entity.PSObject.Properties) {
                $detailsMap[$property.Name] = $property.Value
            }

            $mailboxDetails = $null
            if ($IsMailbox -and $entity.RecipientTypeDetails -eq "GroupMailbox" -and $lookupContext.UnifiedGroups) {
                $mailboxDetails = Get-DictionaryValue -Dictionary $lookupContext.UnifiedGroups -Key $entity.PrimarySMTPAddress
                if ($mailboxDetails) {
                    Write-Verbose "Unified Group Details Found: $($entity.PrimarySMTPAddress)"
                }
            }
            elseif ($IsMailbox -and $lookupContext.AllMailboxesByIdentity) {
                $mailboxDetails = Get-DictionaryValue -Dictionary $lookupContext.AllMailboxesByIdentity -Key $entity.Identity
                if ($mailboxDetails) {
                    Write-Verbose "Mailbox Details Found: $($entity.Identity)"
                }
            }

            if (-not $mailboxDetails -and $lookupContext.AllMailboxesByUserPrincipalName -and $entity.UserPrincipalName) {
                $mailboxDetails = Get-DictionaryValue -Dictionary $lookupContext.AllMailboxesByUserPrincipalName -Key $entity.UserPrincipalName
                if ($mailboxDetails) {
                    Write-Verbose "Mailbox Details Found (UPN): $($entity.UserPrincipalName)"
                }
            }
            if (-not $mailboxDetails -and $lookupContext.AllMailboxesByPrimarySmtpAddress) {
                $primarySmtpLookup = if ($entity.PSObject.Properties['PrimarySmtpAddress']) { [string]$entity.PrimarySmtpAddress } elseif ($entity.PSObject.Properties['PrimarySMTPAddress']) { [string]$entity.PrimarySMTPAddress } else { $null }
                if (-not [string]::IsNullOrWhiteSpace($primarySmtpLookup)) {
                    $mailboxDetails = Get-DictionaryValue -Dictionary $lookupContext.AllMailboxesByPrimarySmtpAddress -Key $primarySmtpLookup
                }
            }
            if (-not $mailboxDetails -and $lookupContext.AllMailboxesByExternalDirectoryObjectId -and $entity.PSObject.Properties['ExternalDirectoryObjectId'] -and $entity.ExternalDirectoryObjectId) {
                $mailboxDetails = Get-DictionaryValue -Dictionary $lookupContext.AllMailboxesByExternalDirectoryObjectId -Key $entity.ExternalDirectoryObjectId
            }

            if (-not $mailboxDetails) {
                Write-Verbose "Mailbox Details Not Found"
            }

            $mailboxStats = $null
            if ($mailboxDetails -and $lookupContext.PrimaryMailboxStats) {
                $mailboxStats = Get-MailboxStatForRecord -MailboxRecord $mailboxDetails -StatsHash $lookupContext.PrimaryMailboxStats
                if ($mailboxStats) {
                    Write-Verbose "Mailbox Stats Found for '$($mailboxDetails.DisplayName)'"
                }
            }
            if (-not $mailboxStats) {
                Write-Verbose "Mailbox Stats Not Found"
            }

            $archiveStats = $null
            if ($mailboxDetails -and $lookupContext.ArchiveMailboxStats -and $mailboxDetails.ArchiveGuid) {
                $archiveStats = Get-DictionaryValue -Dictionary $lookupContext.ArchiveMailboxStats -Key (Convert-ToMailboxGuidKey -GuidValue $mailboxDetails.ArchiveGuid)
                if ($archiveStats) {
                    Write-Verbose "Archive Stats Found: $($mailboxDetails.ArchiveGuid.ToString())"
                }
            }
            if (-not $archiveStats) {
                Write-Verbose "Archive Stats Not Found"
            }

            $driveData = $null
            if ($IsMailbox -and $entity.RecipientTypeDetails -eq "GroupMailbox" -and $lookupContext.SharePoint -and $mailboxDetails -and $mailboxDetails.SharePointSiteUrl) {
                $driveData = Get-DictionaryValue -Dictionary $lookupContext.SharePoint -Key $mailboxDetails.SharePointSiteUrl
                if ($driveData) {
                    Write-Verbose "SharePoint Details Found: $($mailboxDetails.SharePointSiteUrl)"
                }
            }
            elseif ($IsMailbox -and $lookupContext.OneDrive -and $mailboxDetails -and $mailboxDetails.UserPrincipalName) {
                $driveData = Get-DictionaryValue -Dictionary $lookupContext.OneDrive -Key $mailboxDetails.UserPrincipalName
                if ($driveData) {
                    Write-Verbose "OneDrive Details Found: $($mailboxDetails.UserPrincipalName)"
                }
            }
            elseif ($lookupContext.OneDrive -and $entity.UserPrincipalName) {
                $driveData = Get-DictionaryValue -Dictionary $lookupContext.OneDrive -Key $entity.UserPrincipalName
                if ($driveData) {
                    Write-Verbose "OneDrive Details Found: $($entity.UserPrincipalName)"
                }
            }

            $MBXSizeGB = Resolve-StatsSizeGb -Stats $mailboxStats -CachePrefix 'MBX' -Cache $statsSizeCache
            $MBXItemCount = if ($mailboxStats -and $mailboxStats.ItemCount) { $mailboxStats.ItemCount } else { 0 }
            $ArchiveSizeGB = Resolve-StatsSizeGb -Stats $archiveStats -CachePrefix 'ARC' -Cache $statsSizeCache
            $ArchiveItemCount = if ($archiveStats -and $archiveStats.ItemCount) { $archiveStats.ItemCount } else { 0 }
            $DriveURL = if ($driveData -and $driveData.URL) { $driveData.URL } else { $null }
            $DriveStorageGB = if ($driveData -and $driveData.StorageUsageCurrent) { [math]::Round($driveData.StorageUsageCurrent / 1024, 3) } else { 0 }

            $detailsMap["MBXSizeGB"] = $MBXSizeGB
            $detailsMap["MBXItemCount"] = $MBXItemCount
            $detailsMap["ArchiveSizeGB"] = $ArchiveSizeGB
            $detailsMap["ArchiveItemCount"] = $ArchiveItemCount
            $detailsMap["DriveURL"] = $DriveURL
            $detailsMap["DriveStorageGB"] = $DriveStorageGB
        }
        catch {
            Write-Log -Type ERROR -Message "[Populate-Details] An error occurred in Populating Details for $($entity.PrimarySMTPAddress). $($_.Exception.Message)" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
        }

        return [PSCustomObject]$detailsMap
    }

    $lookupContext = [ordered]@{
        UnifiedGroups                  = Get-LookupTable -TenantStatsStore $tenantStatsStore -Key 'UnifiedGroups'
        AllMailboxesByIdentity         = Get-LookupTable -TenantStatsStore $tenantStatsStore -Key 'AllMailboxes-MailIdentity'
        AllMailboxesByUserPrincipalName = Get-LookupTable -TenantStatsStore $tenantStatsStore -Key 'AllMailboxes-UserPrincipalName'
        AllMailboxesByPrimarySmtpAddress = New-IndexedLookupTable -Source (Get-LookupTable -TenantStatsStore $tenantStatsStore -Key 'AllMailboxes') -PropertyNames @('PrimarySmtpAddress', 'PrimarySMTPAddress')
        AllMailboxesByExternalDirectoryObjectId = New-IndexedLookupTable -Source (Get-LookupTable -TenantStatsStore $tenantStatsStore -Key 'AllMailboxes') -PropertyNames @('ExternalDirectoryObjectId')
        PrimaryMailboxStats            = Get-LookupTable -TenantStatsStore $tenantStatsStore -Key 'PrimaryMailboxStats'
        ArchiveMailboxStats            = Get-LookupTable -TenantStatsStore $tenantStatsStore -Key 'ArchiveMailboxStats'
        SharePoint                     = New-IndexedLookupTable -Source (Get-LookupTable -TenantStatsStore $tenantStatsStore -Key 'SharePoint') -PropertyNames @('Url', 'URL', 'SiteUrl', 'WebUrl')
        OneDrive                       = New-IndexedLookupTable -Source (Get-LookupTable -TenantStatsStore $tenantStatsStore -Key 'OneDrive') -PropertyNames @('UserPrincipalName', 'Owner', 'Url', 'URL', 'WebUrl', 'SiteUrl')
    }

    $statsSizeCache = @{}
    
    # Combine User and Mailbox Stats with Progress
    function Combine-UserAndMailboxStats {
        param (
            [hashtable]$TenantStatsStore
        )

        # Initialize variables. Include the start time for the script and logging
        $start = Get-Date
        if (-not $TenantStatsStore) {
            throw "[Combine-UserAndMailboxStats] TenantStatsStore was not provided."
        }
        # Create hash tables for user and mailbox details
        $TenantStatsStore["UserFullDetails"] = @{}
        $TenantStatsStore["MailboxFullDetails"] = @{}
        $combinedUserProgressId = 81
        $combinedMailboxProgressId = 82
        
        # Process Users
        $usersTable = Get-LookupTable -TenantStatsStore $TenantStatsStore -Key 'Users'
        $userEntries = @()
        if ($usersTable -is [System.Collections.IDictionary]) {
            $userEntries = @($usersTable.GetEnumerator())
        }
        $userCount = $userEntries.Count

        foreach ($userEntry in $userEntries) {
            $userKey = $userEntry.Key
            $user = $userEntry.Value
            if ($logPerRecordDebug) {
                Write-Log -Type DEBUG -Message ("[Combine-UserAndMailboxStats] Combining User '{0}' Details" -f $user.DisplayName) -ExportFileLocation $ExportDetails
            }

            Write-ProgressHelper -Total ([Math]::Max($userCount, 1)) -Id $combinedUserProgressId -Activity "Processing User Data" -Operation "Processing user: $($user.DisplayName)"

            $userDetails = Populate-Details -entity $user
            $userDetailsKey = @(
                [string]$user.UserPrincipalName
                [string]$user.PrimarySmtpAddress
                [string]$user.ExternalDirectoryObjectId
                [string]$user.Id
                [string]$userKey
            ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1
            if ([string]::IsNullOrWhiteSpace($userDetailsKey)) {
                $userDetailsKey = "user:$([guid]::NewGuid().Guid)"
            }
            $TenantStatsStore["UserFullDetails"][$userDetailsKey] = $userDetails
        }
        Write-ProgressHelper -Total ([Math]::Max($userCount, 1)) -Id $combinedUserProgressId -Activity "Processing User Data" -Completed

        # Process Mailboxes
        $allRecipientRows = @()
        $allRecipientsTable = Get-LookupTable -TenantStatsStore $TenantStatsStore -Key 'AllRecipients'
        if ($allRecipientsTable -is [System.Collections.IDictionary]) {
            $allRecipientRows = @($allRecipientsTable.Values)
        }
        elseif ($null -ne $TenantStatsStore['AllRecipients'] -and $TenantStatsStore['AllRecipients'] -is [System.Collections.IEnumerable] -and -not ($TenantStatsStore['AllRecipients'] -is [string])) {
            $allRecipientRows = @($TenantStatsStore['AllRecipients'])
        }

        if ($allRecipientRows.Count -eq 0) {
            $allMailboxesTable = Get-LookupTable -TenantStatsStore $TenantStatsStore -Key 'AllMailboxes'
            if ($allMailboxesTable -is [System.Collections.IDictionary]) {
                $allRecipientRows = @($allMailboxesTable.Values)
            }
        }

        $allMailboxes = @($allRecipientRows | Where-Object {
            $_ -and $_.PSObject -and $_.PSObject.Properties['RecipientTypeDetails'] -and [string]$_.RecipientTypeDetails -like "*Mailbox"
        })
        if ($allMailboxes.Count -eq 0 -and $allRecipientRows.Count -gt 0) {
            $allMailboxes = @($allRecipientRows)
        }
        $mailboxCount = $allMailboxes.Count
        Write-Log -Type INFO -Message "[Combine-UserAndMailboxStats] Combining User and Mailbox Details - Processing Mailboxes" -ExportFileLocation $ExportDetails
        foreach ($mailbox in $allMailboxes) {
            #$mailbox = $TenantStatsStore["AllMailboxes"][$mailbox.PrimarySMTPAddress]
            if ($logPerRecordDebug) {
                Write-Log -Type DEBUG -Message ("[Combine-UserAndMailboxStats] Combining Mailbox '{0}' Details" -f $mailbox.PrimarySMTPAddress) -ExportFileLocation $ExportDetails
            }
            Write-ProgressHelper -Total ([Math]::Max($mailboxCount, 1)) -Id $combinedMailboxProgressId -Activity "Processing Mailbox Data" -Operation "Processing mailbox: $($mailbox.PrimarySMTPAddress)"

            $mailboxDetails = Populate-Details -entity $mailbox -IsMailbox
            $mailboxDetailsKey = @(
                [string]$mailbox.PrimarySMTPAddress
                [string]$mailbox.PrimarySmtpAddress
                [string]$mailbox.UserPrincipalName
                [string]$mailbox.ExternalDirectoryObjectId
                [string]$mailbox.Guid
                [string]$mailbox.Identity
            ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1
            if ([string]::IsNullOrWhiteSpace($mailboxDetailsKey)) {
                $mailboxDetailsKey = "mailbox:$([guid]::NewGuid().Guid)"
            }
            $TenantStatsStore["MailboxFullDetails"][$mailboxDetailsKey] = $mailboxDetails
        }

        Write-ProgressHelper -Total ([Math]::Max($mailboxCount, 1)) -Id $combinedMailboxProgressId -Activity "Processing Mailbox Data" -Completed
    }
    # New function to generate Inactive Mailboxes report
    function Report-InactiveMailboxes {
        [CmdletBinding()]
        param (
            [hashtable]$TenantStatsStore
        )

        # Initialize variables. Include the start time for the script and logging
        $start = Get-Date
        if (-not $TenantStatsStore) {
            throw "[Report-InactiveMailboxes] TenantStatsStore was not provided."
        }

        # Create hash table for inactive mailbox details
        $TenantStatsStore["InactiveMailboxDetails"] = @{}
        $inactiveMailboxProgressId = 83

        # Process Inactive Mailboxes
        $inactiveMailboxes = @()
        $inactiveMailboxTable = Get-LookupTable -TenantStatsStore $TenantStatsStore -Key 'InactiveMailboxes'
        if ($inactiveMailboxTable -is [System.Collections.IDictionary]) {
            $inactiveMailboxes = @($inactiveMailboxTable.Values)
        }
        elseif ($TenantStatsStore.ContainsKey('AllMailboxes') -and $TenantStatsStore['AllMailboxes'] -is [System.Collections.IDictionary]) {
            $inactiveMailboxes = @(
                $TenantStatsStore['AllMailboxes'].Values | Where-Object {
                    $_ -and $_.PSObject -and $_.PSObject.Properties['IsInactiveMailbox'] -and $_.IsInactiveMailbox -eq $true
                }
            )
        }
        $inactiveMailboxCount = $inactiveMailboxes.Count
        Write-Log -Type INFO -Message "[Report-InactiveMailboxes] Processing Inactive Mailboxes" -ExportFileLocation $ExportDetails
        foreach ($mailbox in $inactiveMailboxes) {
            if ($logPerRecordDebug) {
                Write-Log -Type DEBUG -Message ("[Report-InactiveMailboxes] Processing Inactive Mailbox '{0}'" -f $mailbox.PrimarySMTPAddress) -ExportFileLocation $ExportDetails
            }
            Write-ProgressHelper -Total ([Math]::Max($inactiveMailboxCount, 1)) -Id $inactiveMailboxProgressId -Activity "Processing Inactive Mailbox Data" -Operation "Processing inactive mailbox: $($mailbox.PrimarySMTPAddress)"

            $existingMailboxDetails = $null
            if ($TenantStatsStore.ContainsKey("MailboxFullDetails") -and $TenantStatsStore["MailboxFullDetails"]) {
                $existingMailboxDetails = Get-DictionaryValue -Dictionary $TenantStatsStore["MailboxFullDetails"] -Key $mailbox.PrimarySMTPAddress
            }

            $mailboxDetails = if ($existingMailboxDetails) {
                $existingMailboxDetails
            } else {
                Populate-Details -entity $mailbox -IsMailbox
            }
            $TenantStatsStore["InactiveMailboxDetails"][$mailbox.PrimarySMTPAddress] = $mailboxDetails
        }

        Write-ProgressHelper -Total ([Math]::Max($inactiveMailboxCount, 1)) -Id $inactiveMailboxProgressId -Activity "Processing Inactive Mailbox Data" -Completed

        $completedTime = (((Get-Date) - $start).ToString('hh\:mm\:ss'))
        Write-AssessmentCollectorCompletionBanner -Message "Completed Inactive Mailbox Report in $completedTime"
        Write-Log -Type INFO -Message "[Report-InactiveMailboxes] COMPLETED: Processed Inactive Mailboxes in $completedTime" -ExportFileLocation $ExportDetails
    }

    # Combine user and mailbox stats
    Write-Log -Type INFO -Message "[Combine-UserAndMailboxStats] Combining User and Mailbox Details" -ExportFileLocation $ExportDetails
    try {
        $start = Get-Date
        Write-AssessmentConsoleSubstep -Message 'Export preparation: user and mailbox detail projection'
        Combine-UserAndMailboxStats -TenantStatsStore $tenantStatsStore
        Write-AssessmentConsoleSubstep -Message 'Export preparation: inactive mailbox detail projection'
        Report-InactiveMailboxes -TenantStatsStore $tenantStatsStore
    } catch {
        Write-Log -Type ERROR -Message "[Combine-UserAndMailboxStats] An error occurred while combining User and Mailbox Details. $($_.Exception.Message)" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
    } finally {
        $completedTime = (((Get-Date) - $start).ToString('hh\:mm\:ss'))
        Write-AssessmentCollectorCompletionBanner -Message "Completed in $completedTime"
        Write-Log -Type INFO -Message "[Combine-UserAndMailboxStats] COMPLETED: Combined User and Mailbox Details in $completedTime" -ExportFileLocation $ExportDetails
    }
}

function Prepare-AssessmentExportData {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [bool]$BuildCombinedUserMailboxProjection,
        [Parameter(Mandatory = $true)]
        [bool]$RequiresFilteredExportSnapshot
    )

    $isTenantToTenantCutover = (
        $script:ProfileCollectionPlan -and
        [string]$script:ProfileCollectionPlan.CollectionScopePolicy -eq 'TenantToTenantCutover' -and
        [string]$script:ProfileCollectionPlan.OutputProfile -eq 'TenantToTenantMigration'
    )

    if (
        (-not $BuildCombinedUserMailboxProjection -or -not $RequiresFilteredExportSnapshot) -and
        -not $isTenantToTenantCutover
    ) {
        return
    }

    if ($BuildCombinedUserMailboxProjection -and $RequiresFilteredExportSnapshot) {
        Write-AssessmentConsoleSubstep -Message 'Export preparation: combined user/mailbox reporting'
        Report-UserAndMailboxStats
    }

    if ($isTenantToTenantCutover) {
        Write-AssessmentConsoleSubstep -Message 'Export preparation: tenant-to-tenant workbook and cutover shaping'
        Update-TenantToTenantMigrationExportData -TenantStatsStore $script:tenantStatsHash
    }
}

function Get-AssessmentExportTableArray {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$TenantStatsStore,
        [Parameter(Mandatory = $true)]
        [string]$Key
    )

    if (-not $TenantStatsStore.ContainsKey($Key) -or $null -eq $TenantStatsStore[$Key]) {
        return @()
    }

    $value = $TenantStatsStore[$Key]
    if ($value -is [System.Collections.IDictionary]) {
        return @($value.Values)
    }
    if (($value -is [System.Collections.IEnumerable]) -and -not ($value -is [string])) {
        return @($value)
    }

    return @($value)
}

function Get-AssessmentExportPropertyValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [AllowNull()]
        $Record,
        [Parameter(Mandatory = $true)]
        [string[]]$Names
    )

    return Get-ArrayaObjectValue -Object $Record -Names $Names
}

function Set-AssessmentExportProperty {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [AllowNull()]
        $Record,
        [Parameter(Mandatory = $true)]
        [string]$Name,
        [AllowNull()]
        $Value
    )

    if ($null -eq $Record -or [string]::IsNullOrWhiteSpace($Name)) {
        return
    }

    if ($Record -is [System.Collections.IDictionary]) {
        $Record[$Name] = $Value
        return
    }

    $Record | Add-Member -MemberType NoteProperty -Name $Name -Value $Value -Force
}

function Convert-AssessmentExportListToArray {
    [CmdletBinding()]
    param(
        [AllowNull()]
        $Value
    )

    if ($null -eq $Value) {
        return @()
    }

    if ($Value -is [string]) {
        return @(
            $Value -split '[,;]' |
                ForEach-Object { ([string]$_).Trim() } |
                Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
        )
    }

    if (($Value -is [System.Collections.IEnumerable]) -and -not ($Value -is [string])) {
        return @(
            $Value |
                ForEach-Object {
                    if ($null -eq $_) {
                        return
                    }

                    if ($_ -is [string]) {
                        return ([string]$_).Trim()
                    }

                    if (
                        $_ -is [ValueType] -or
                        $_ -is [datetime] -or
                        $_ -is [datetimeoffset] -or
                        $_ -is [guid] -or
                        $_ -is [uri] -or
                        $_ -is [version]
                    ) {
                        return ([string]$_).Trim()
                    }

                    $resolvedItemText = $null
                    foreach ($identityPropertyName in @(
                            'DisplayName', 'Name', 'Title', 'Domain', 'UserPrincipalName', 'Mail', 'Email',
                            'PrimarySmtpAddress', 'Address', 'Value', 'SkuFriendlyName', 'SkuPartNumber',
                            'ServicePlanName', 'Id', 'SkuId'
                        )) {
                        $identityProperty = $_.PSObject.Properties[$identityPropertyName]
                        if ($identityProperty -and -not [string]::IsNullOrWhiteSpace([string]$identityProperty.Value)) {
                            $resolvedItemText = ([string]$identityProperty.Value).Trim()
                            break
                        }
                    }

                    if ([string]::IsNullOrWhiteSpace($resolvedItemText) -and $_.PSObject.Properties['AdditionalProperties']) {
                        $additionalProperties = $_.AdditionalProperties
                        if ($additionalProperties -is [System.Collections.IDictionary]) {
                            foreach ($identityKey in @('displayName', 'name', 'title', 'domain', 'userPrincipalName', 'mail', 'email', 'value', 'id')) {
                                if (
                                    $additionalProperties.Contains($identityKey) -and
                                    -not [string]::IsNullOrWhiteSpace([string]$additionalProperties[$identityKey])
                                ) {
                                    $resolvedItemText = ([string]$additionalProperties[$identityKey]).Trim()
                                    break
                                }
                            }
                        }
                    }

                    if ([string]::IsNullOrWhiteSpace($resolvedItemText)) {
                        $propertyPairs = @(
                            $_.PSObject.Properties |
                                Where-Object { $_.MemberType -in @('NoteProperty', 'AliasProperty', 'Property') } |
                                ForEach-Object {
                                    $propertyValue = $_.Value
                                    if ($null -eq $propertyValue) {
                                        return
                                    }

                                    if (
                                        $propertyValue -is [System.Collections.IEnumerable] -and
                                        -not ($propertyValue -is [string])
                                    ) {
                                        $propertyValue = Convert-AssessmentExportListToText -Value $propertyValue
                                    }

                                    $propertyValueText = ([string]$propertyValue).Trim()
                                    if ([string]::IsNullOrWhiteSpace($propertyValueText) -or $propertyValueText -match '^Microsoft\.Graph\.PowerShell\.Models\.') {
                                        return
                                    }

                                    '{0}={1}' -f $_.Name, $propertyValueText
                                } |
                                Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
                                Select-Object -First 3
                        )

                        if ($propertyPairs.Count -gt 0) {
                            $resolvedItemText = ($propertyPairs -join ', ')
                        }
                    }

                    if ([string]::IsNullOrWhiteSpace($resolvedItemText)) {
                        $resolvedItemText = ([string]$_).Trim()
                    }

                    $resolvedItemText
                } |
                Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
        )
    }

    $text = ([string]$Value).Trim()
    if ([string]::IsNullOrWhiteSpace($text)) {
        return @()
    }

    return @($text)
}

function Convert-AssessmentExportListToText {
    [CmdletBinding()]
    param(
        [AllowNull()]
        $Value,
        [string]$Delimiter = '; '
    )

    $items = Convert-AssessmentExportListToArray -Value $Value
    if ($items.Count -eq 0) {
        return $null
    }

    return [string]::Join($Delimiter, @($items | Select-Object -Unique))
}

function Convert-AssessmentExportByteCountToGb {
    [CmdletBinding()]
    param(
        [AllowNull()]
        $Value
    )

    if ($null -eq $Value) {
        return $null
    }

    $byteCount = $null
    if ($Value -is [byte] -or $Value -is [int16] -or $Value -is [uint16] -or $Value -is [int32] -or $Value -is [uint32] -or $Value -is [int64] -or $Value -is [uint64] -or $Value -is [single] -or $Value -is [double] -or $Value -is [decimal]) {
        $byteCount = [double]$Value
    }
    else {
        $valueText = ([string]$Value).Trim()
        if ([string]::IsNullOrWhiteSpace($valueText)) {
            return $null
        }

        if ($valueText -match '^-?\d+(?:\.\d+)?$') {
            $byteCount = [double]$valueText
        }
        else {
            $bytesFromText = Convert-DataSizeToBytes -Value $valueText
            if ($bytesFromText -lt 0) {
                return $null
            }

            $byteCount = [double]$bytesFromText
        }
    }

    return [math]::Round(($byteCount / 1GB), 3)
}

function Convert-AssessmentExportDisplayText {
    [CmdletBinding()]
    param(
        [AllowNull()]
        $Value,
        [string]$Default = $null
    )

    if ($null -eq $Value) {
        return $Default
    }

    if ($Value -is [bool]) {
        return $(if ($Value) { 'Yes' } else { 'No' })
    }

    if ($Value -is [datetime] -or $Value -is [datetimeoffset]) {
        return ([datetime]$Value).ToString('yyyy-MM-dd HH:mm:ss')
    }

    if (($Value -is [System.Collections.IEnumerable]) -and -not ($Value -is [string])) {
        $listText = Convert-AssessmentExportListToText -Value $Value
        if (-not [string]::IsNullOrWhiteSpace($listText)) {
            return $listText
        }
    }

    $text = ([string]$Value).Trim()
    if ([string]::IsNullOrWhiteSpace($text)) {
        return $Default
    }

    return $text
}

function New-TenantToTenantConfigurationRow {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Section,
        [Parameter(Mandatory = $true)]
        [string]$Item,
        [AllowNull()]
        $Value,
        [string]$Notes
    )

    return [pscustomobject]@{
        Section = $Section
        Item    = $Item
        Value   = Convert-AssessmentExportDisplayText -Value $Value
        Notes   = $Notes
    }
}

function Convert-AssessmentExportSizeToGb {
    [CmdletBinding()]
    param(
        [AllowNull()]
        $Value
    )

    if ($null -eq $Value) {
        return $null
    }

    if ($Value -is [double] -or $Value -is [float] -or $Value -is [decimal]) {
        return [math]::Round(([double]$Value), 3)
    }

    if ($Value -is [int] -or $Value -is [long] -or $Value -is [int64]) {
        return [math]::Round(([double]$Value), 3)
    }

    $text = ([string]$Value).Trim()
    if ([string]::IsNullOrWhiteSpace($text) -or $text -in @('N/A', 'Unknown', 'Unavailable')) {
        return $null
    }

    if ($text -match '^-?\d+(?:\.\d+)?$') {
        return [math]::Round(([double]$text), 3)
    }

    $bytes = Convert-DataSizeToBytes -Value $text
    if ($bytes -lt 0) {
        return $null
    }

    return [math]::Round(($bytes / 1GB), 3)
}

function Get-AssessmentExportDomainFromAddress {
    [CmdletBinding()]
    param(
        [AllowNull()]
        [string]$Address
    )

    if ([string]::IsNullOrWhiteSpace($Address)) {
        return $null
    }

    $trimmedAddress = ([string]$Address).Trim()
    if ($trimmedAddress -match '@(?<domain>[^@]+)$') {
        return $Matches['domain'].ToLowerInvariant()
    }

    return $null
}

function New-AssessmentExportLookup {
    [CmdletBinding()]
    param(
        [AllowNull()]
        [object[]]$Records,
        [Parameter(Mandatory = $true)]
        [string[]]$PropertyNames
    )

    $lookup = @{}
    foreach ($record in @($Records)) {
        foreach ($propertyName in $PropertyNames) {
            $value = Get-AssessmentExportPropertyValue -Record $record -Names @($propertyName)
            if ([string]::IsNullOrWhiteSpace([string]$value)) {
                continue
            }

            $key = ([string]$value).Trim().ToLowerInvariant()
            if (-not $lookup.ContainsKey($key)) {
                $lookup[$key] = $record
            }
        }
    }

    return $lookup
}

function Resolve-AssessmentExportRoutingSummary {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [AllowNull()]
        $Record
    )

    $emailAddressValues = Convert-AssessmentExportListToArray -Value (Get-AssessmentExportPropertyValue -Record $Record -Names @('EmailAddresses'))
    $onMicrosoftAliases = New-Object System.Collections.Generic.List[string]
    $x500Addresses = New-Object System.Collections.Generic.List[string]
    $x400Addresses = New-Object System.Collections.Generic.List[string]

    foreach ($value in @($emailAddressValues)) {
        $addressText = ([string]$value).Trim()
        if ([string]::IsNullOrWhiteSpace($addressText)) {
            continue
        }

        $prefix = $null
        $resolvedValue = $addressText
        if ($addressText -match '^(?<prefix>[^:]+):(?<value>.+)$') {
            $prefix = [string]$Matches['prefix']
            $resolvedValue = ([string]$Matches['value']).Trim()
        }

        if ($resolvedValue -match '@[^@]+\.onmicrosoft\.com$') {
            if (-not $onMicrosoftAliases.Contains($resolvedValue)) {
                $onMicrosoftAliases.Add($resolvedValue) | Out-Null
            }
        }

        if ($prefix -and $prefix -match '^(?i)x500$') {
            $normalizedValue = if ($addressText -match '^(?i)x500:') { $addressText } else { 'x500:{0}' -f $resolvedValue }
            if (-not $x500Addresses.Contains($normalizedValue)) {
                $x500Addresses.Add($normalizedValue) | Out-Null
            }
        }
        elseif ($prefix -and $prefix -match '^(?i)x400$') {
            $normalizedValue = if ($addressText -match '^(?i)x400:') { $addressText } else { 'x400:{0}' -f $resolvedValue }
            if (-not $x400Addresses.Contains($normalizedValue)) {
                $x400Addresses.Add($normalizedValue) | Out-Null
            }
        }
    }

    $existingOnMicrosoftAlias = Get-AssessmentExportPropertyValue -Record $Record -Names @('OnMicrosoftAlias')
    $existingOnMicrosoftAliases = Convert-AssessmentExportListToArray -Value (Get-AssessmentExportPropertyValue -Record $Record -Names @('OnMicrosoftAliases'))
    foreach ($value in @($existingOnMicrosoftAliases)) {
        if ($value -and -not $onMicrosoftAliases.Contains([string]$value)) {
            $onMicrosoftAliases.Add([string]$value) | Out-Null
        }
    }
    if (-not [string]::IsNullOrWhiteSpace([string]$existingOnMicrosoftAlias) -and -not $onMicrosoftAliases.Contains([string]$existingOnMicrosoftAlias)) {
        $onMicrosoftAliases.Add([string]$existingOnMicrosoftAlias) | Out-Null
    }

    $existingX500Addresses = Convert-AssessmentExportListToArray -Value (Get-AssessmentExportPropertyValue -Record $Record -Names @('X500Addresses'))
    foreach ($value in @($existingX500Addresses)) {
        if ($value -and -not $x500Addresses.Contains([string]$value)) {
            $x500Addresses.Add([string]$value) | Out-Null
        }
    }

    $existingX400Addresses = Convert-AssessmentExportListToArray -Value (Get-AssessmentExportPropertyValue -Record $Record -Names @('X400Addresses'))
    foreach ($value in @($existingX400Addresses)) {
        if ($value -and -not $x400Addresses.Contains([string]$value)) {
            $x400Addresses.Add([string]$value) | Out-Null
        }
    }

    $legacyExchangeDn = Get-AssessmentExportPropertyValue -Record $Record -Names @('LegacyExchangeDn', 'LegacyExchangeDN')
    $legacyExchangeDnX500 = Get-AssessmentExportPropertyValue -Record $Record -Names @('LegacyExchangeDnX500')
    if ([string]::IsNullOrWhiteSpace([string]$legacyExchangeDnX500) -and -not [string]::IsNullOrWhiteSpace([string]$legacyExchangeDn)) {
        $legacyExchangeDnX500 = 'x500:{0}' -f ([string]$legacyExchangeDn).Trim()
    }
    $additionalX500Addresses = New-Object System.Collections.Generic.List[string]
    foreach ($x500Address in @($x500Addresses | Select-Object -Unique)) {
        if ([string]::IsNullOrWhiteSpace([string]$x500Address)) {
            continue
        }

        if (
            -not [string]::IsNullOrWhiteSpace([string]$legacyExchangeDnX500) -and
            [string]::Equals(([string]$x500Address).Trim(), ([string]$legacyExchangeDnX500).Trim(), [System.StringComparison]::OrdinalIgnoreCase)
        ) {
            continue
        }

        if (-not $additionalX500Addresses.Contains([string]$x500Address)) {
            $additionalX500Addresses.Add([string]$x500Address) | Out-Null
        }
    }

    return [pscustomobject]@{
        OnMicrosoftAlias     = if (-not [string]::IsNullOrWhiteSpace([string]$existingOnMicrosoftAlias)) { [string]$existingOnMicrosoftAlias } elseif ($onMicrosoftAliases.Count -gt 0) { [string]$onMicrosoftAliases[0] } else { $null }
        OnMicrosoftAliases   = if ($onMicrosoftAliases.Count -gt 0) { [string]::Join('; ', @($onMicrosoftAliases | Select-Object -Unique)) } else { $null }
        LegacyExchangeDn     = $legacyExchangeDn
        LegacyExchangeDnX500 = $legacyExchangeDnX500
        X500Addresses        = if ($additionalX500Addresses.Count -gt 0) { [string]::Join('; ', @($additionalX500Addresses | Select-Object -Unique)) } else { $null }
        X400Addresses        = if ($x400Addresses.Count -gt 0) { [string]::Join('; ', @($x400Addresses | Select-Object -Unique)) } else { $null }
    }
}

function Get-AssessmentMailboxStatsLookup {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [object[]]$StatsRows
    )

    $lookup = @{}
    foreach ($statsRow in @($StatsRows)) {
        $mailboxGuid = Get-AssessmentExportPropertyValue -Record $statsRow -Names @('MailboxGuid')
        if ([string]::IsNullOrWhiteSpace([string]$mailboxGuid)) {
            continue
        }

        $key = ([string]$mailboxGuid).Trim().ToLowerInvariant()
        if (-not $lookup.ContainsKey($key)) {
            $lookup[$key] = $statsRow
        }
    }

    return $lookup
}

function Get-AssessmentMailboxLicenseType {
    [CmdletBinding()]
    param(
        [AllowNull()]
        [double]$MailboxSizeGB,
        [AllowNull()]
        [string]$ArchiveStatus
    )

    $hasArchive = (-not [string]::IsNullOrWhiteSpace([string]$ArchiveStatus) -and [string]$ArchiveStatus -match '^(?i)active$')
    if ($hasArchive) {
        return 'User Migration Bundle'
    }

    if ($null -eq $MailboxSizeGB) {
        return $null
    }

    if ($MailboxSizeGB -le 50) {
        return 'MigrationWiz-Mailbox'
    }

    return 'MigrationWiz-Mailbox x2'
}

function Add-TenantToTenantMailboxDerivedFields {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [AllowNull()]
        $MailboxRecord,
        [Parameter(Mandatory = $true)]
        [hashtable]$PrimaryMailboxStatsLookup,
        [Parameter(Mandatory = $true)]
        [hashtable]$ArchiveMailboxStatsLookup
    )

    $exchangeGuid = Get-AssessmentExportPropertyValue -Record $MailboxRecord -Names @('ExchangeGuid')
    $archiveGuid = Get-AssessmentExportPropertyValue -Record $MailboxRecord -Names @('ArchiveGuid')

    $primaryStats = $null
    if (-not [string]::IsNullOrWhiteSpace([string]$exchangeGuid)) {
        $primaryStats = $PrimaryMailboxStatsLookup[([string]$exchangeGuid).Trim().ToLowerInvariant()]
    }

    $archiveStats = $null
    if (-not [string]::IsNullOrWhiteSpace([string]$archiveGuid)) {
        $archiveStats = $ArchiveMailboxStatsLookup[([string]$archiveGuid).Trim().ToLowerInvariant()]
    }

    $mailboxSizeGB = Convert-AssessmentExportSizeToGb -Value (Get-AssessmentExportPropertyValue -Record $MailboxRecord -Names @('MailboxSizeGB', 'MBXSizeGB'))
    if ($null -eq $mailboxSizeGB) {
        $mailboxSizeGB = Convert-AssessmentExportByteCountToGb -Value (Get-AssessmentExportPropertyValue -Record $primaryStats -Names @('TotalItemSizeBytes'))
    }
    if ($null -eq $mailboxSizeGB) {
        $mailboxSizeGB = Convert-AssessmentExportSizeToGb -Value (Get-AssessmentExportPropertyValue -Record $primaryStats -Names @('TotalItemSize'))
    }

    $deletedItemsGB = Convert-AssessmentExportSizeToGb -Value (Get-AssessmentExportPropertyValue -Record $MailboxRecord -Names @('DeletedItemsGB'))
    if ($null -eq $deletedItemsGB) {
        $deletedItemsGB = Convert-AssessmentExportByteCountToGb -Value (Get-AssessmentExportPropertyValue -Record $primaryStats -Names @('TotalDeletedItemSizeBytes'))
    }
    if ($null -eq $deletedItemsGB) {
        $deletedItemsGB = Convert-AssessmentExportSizeToGb -Value (Get-AssessmentExportPropertyValue -Record $primaryStats -Names @('TotalDeletedItemSize'))
    }

    $archiveSizeGB = Convert-AssessmentExportSizeToGb -Value (Get-AssessmentExportPropertyValue -Record $MailboxRecord -Names @('ArchiveSizeGB'))
    if ($null -eq $archiveSizeGB) {
        $archiveSizeGB = Convert-AssessmentExportByteCountToGb -Value (Get-AssessmentExportPropertyValue -Record $archiveStats -Names @('TotalItemSizeBytes'))
    }
    if ($null -eq $archiveSizeGB) {
        $archiveSizeGB = Convert-AssessmentExportSizeToGb -Value (Get-AssessmentExportPropertyValue -Record $archiveStats -Names @('TotalItemSize'))
    }

    $archiveDeletedItemsGB = Convert-AssessmentExportSizeToGb -Value (Get-AssessmentExportPropertyValue -Record $MailboxRecord -Names @('ArchiveDeletedItemsGB'))
    if ($null -eq $archiveDeletedItemsGB) {
        $archiveDeletedItemsGB = Convert-AssessmentExportByteCountToGb -Value (Get-AssessmentExportPropertyValue -Record $archiveStats -Names @('TotalDeletedItemSizeBytes'))
    }
    if ($null -eq $archiveDeletedItemsGB) {
        $archiveDeletedItemsGB = Convert-AssessmentExportSizeToGb -Value (Get-AssessmentExportPropertyValue -Record $archiveStats -Names @('TotalDeletedItemSize'))
    }

    $totalDataParts = @($mailboxSizeGB, $deletedItemsGB, $archiveSizeGB, $archiveDeletedItemsGB) | Where-Object { $null -ne $_ }
    $totalDataToMigrateGB = if ($totalDataParts.Count -gt 0) { [math]::Round((($totalDataParts | Measure-Object -Sum).Sum), 3) } else { $null }
    $licenseType = Get-AssessmentMailboxLicenseType -MailboxSizeGB $mailboxSizeGB -ArchiveStatus (Get-AssessmentExportPropertyValue -Record $MailboxRecord -Names @('ArchiveStatus'))
    $licenseCount = switch ($licenseType) {
        'User Migration Bundle' { 1 }
        'MigrationWiz-Mailbox' { 1 }
        'MigrationWiz-Mailbox x2' { 2 }
        default { $null }
    }

    $routingSummary = Resolve-AssessmentExportRoutingSummary -Record $MailboxRecord
    Set-AssessmentExportProperty -Record $MailboxRecord -Name 'OnMicrosoftAlias' -Value $routingSummary.OnMicrosoftAlias
    Set-AssessmentExportProperty -Record $MailboxRecord -Name 'OnMicrosoftAliases' -Value $routingSummary.OnMicrosoftAliases
    Set-AssessmentExportProperty -Record $MailboxRecord -Name 'LegacyExchangeDn' -Value $routingSummary.LegacyExchangeDn
    Set-AssessmentExportProperty -Record $MailboxRecord -Name 'LegacyExchangeDnX500' -Value $routingSummary.LegacyExchangeDnX500
    Set-AssessmentExportProperty -Record $MailboxRecord -Name 'X500Addresses' -Value $routingSummary.X500Addresses
    Set-AssessmentExportProperty -Record $MailboxRecord -Name 'X400Addresses' -Value $routingSummary.X400Addresses
    Set-AssessmentExportProperty -Record $MailboxRecord -Name 'MailboxSizeGB' -Value $mailboxSizeGB
    Set-AssessmentExportProperty -Record $MailboxRecord -Name 'DeletedItemsGB' -Value $deletedItemsGB
    Set-AssessmentExportProperty -Record $MailboxRecord -Name 'ArchiveSizeGB' -Value $archiveSizeGB
    Set-AssessmentExportProperty -Record $MailboxRecord -Name 'ArchiveDeletedItemsGB' -Value $archiveDeletedItemsGB
    Set-AssessmentExportProperty -Record $MailboxRecord -Name 'TotalDataToMigrateGB' -Value $totalDataToMigrateGB
    Set-AssessmentExportProperty -Record $MailboxRecord -Name 'BitTitanLicenseType' -Value $licenseType
    Set-AssessmentExportProperty -Record $MailboxRecord -Name 'BitTitanLicenseCount' -Value $licenseCount
    Set-AssessmentExportProperty -Record $MailboxRecord -Name 'OnPremisesSyncEnabled' -Value (Get-AssessmentExportPropertyValue -Record $MailboxRecord -Names @('OnPremisesSyncEnabled', 'IsDirSynced'))

    foreach ($propertyName in @('Wave', 'MigrationState', 'CutoverDate', 'Notes')) {
        if ($null -eq (Get-AssessmentExportPropertyValue -Record $MailboxRecord -Names @($propertyName))) {
            Set-AssessmentExportProperty -Record $MailboxRecord -Name $propertyName -Value $null
        }
    }
}

function Update-TenantToTenantMigrationExportData {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$TenantStatsStore
    )

    $users = @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'Users')
    $recipients = @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'AllRecipients')
    $allMailboxRows = @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'AllMailboxes')
    $mailboxDetailsRows = @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'MailboxFullDetails')
    $inactiveMailboxRows = @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'InactiveMailboxDetails')
    $domainRows = @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'Domains')
    $teamRows = @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'AllTeams')
    $sharePointRows = @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'SharePoint')
    $oneDriveRows = @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'OneDrive')
    $mailFlowConnectors = @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'MailFlowConnectors')
    $remoteDomainRows = @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'RemoteDomains')
    $publicFolderRows = @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'PublicFolderDetails')
    $relayAccountRows = @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'SMTPRelayServiceAccounts')
    $calendarDelegateRows = @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'MailboxCalendarDelegatePermissions')

    $primaryMailboxStatsLookup = Get-AssessmentMailboxStatsLookup -StatsRows @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'PrimaryMailboxStats')
    $archiveMailboxStatsLookup = Get-AssessmentMailboxStatsLookup -StatsRows @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'ArchiveMailboxStats')

    foreach ($mailboxRecord in @($mailboxDetailsRows + $inactiveMailboxRows)) {
        Add-TenantToTenantMailboxDerivedFields -MailboxRecord $mailboxRecord -PrimaryMailboxStatsLookup $primaryMailboxStatsLookup -ArchiveMailboxStatsLookup $archiveMailboxStatsLookup
    }

    $mailboxPlanningRows = @()
    if ($mailboxDetailsRows.Count -gt 0) {
        $mailboxPlanningRows = @($mailboxDetailsRows)
    }
    else {
        $mailboxPlanningRows = @($allMailboxRows)
    }
    $mailboxPlanningSeen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($planningRow in @($mailboxPlanningRows)) {
        $planningKey = [string](Get-AssessmentExportPropertyValue -Record $planningRow -Names @('PrimarySmtpAddress', 'UserPrincipalName', 'ExchangeGuid'))
        if (-not [string]::IsNullOrWhiteSpace($planningKey)) {
            [void]$mailboxPlanningSeen.Add($planningKey)
        }
    }
    foreach ($inactiveMailboxRecord in @($inactiveMailboxRows)) {
        $inactiveKey = [string](Get-AssessmentExportPropertyValue -Record $inactiveMailboxRecord -Names @('PrimarySmtpAddress', 'UserPrincipalName', 'ExchangeGuid'))
        if ([string]::IsNullOrWhiteSpace($inactiveKey) -or -not $mailboxPlanningSeen.Contains($inactiveKey)) {
            $mailboxPlanningRows += $inactiveMailboxRecord
            if (-not [string]::IsNullOrWhiteSpace($inactiveKey)) {
                [void]$mailboxPlanningSeen.Add($inactiveKey)
            }
        }
    }
    foreach ($mailboxRecord in @($mailboxPlanningRows)) {
        Add-TenantToTenantMailboxDerivedFields -MailboxRecord $mailboxRecord -PrimaryMailboxStatsLookup $primaryMailboxStatsLookup -ArchiveMailboxStatsLookup $archiveMailboxStatsLookup
    }

    $mailboxLookup = New-AssessmentExportLookup -Records $mailboxPlanningRows -PropertyNames @('UserPrincipalName', 'PrimarySmtpAddress', 'WindowsEmailAddress', 'ExternalDirectoryObjectId')
    foreach ($userRecord in @($users)) {
        $userPrincipalName = Get-AssessmentExportPropertyValue -Record $userRecord -Names @('UserPrincipalName')
        $userMail = Get-AssessmentExportPropertyValue -Record $userRecord -Names @('Mail')
        $directoryObjectId = Get-AssessmentExportPropertyValue -Record $userRecord -Names @('Id', 'ExternalDirectoryObjectId')

        $mailboxRecord = $null
        foreach ($candidateKey in @($userPrincipalName, $userMail, $directoryObjectId)) {
            if ([string]::IsNullOrWhiteSpace([string]$candidateKey)) {
                continue
            }

            $lookupKey = ([string]$candidateKey).Trim().ToLowerInvariant()
            if ($mailboxLookup.ContainsKey($lookupKey)) {
                $mailboxRecord = $mailboxLookup[$lookupKey]
                break
            }
        }

        $assignedLicensesFriendlyText = Convert-AssessmentExportListToText -Value (Get-AssessmentExportPropertyValue -Record $userRecord -Names @('AssignedLicensesFriendly'))
        if ([string]::IsNullOrWhiteSpace($assignedLicensesFriendlyText)) {
            $assignedLicensesFriendlyText = Convert-AssessmentExportListToText -Value (Get-AssessmentExportPropertyValue -Record $userRecord -Names @('AssignedLicenses'))
        }
        if ([string]::IsNullOrWhiteSpace($assignedLicensesFriendlyText)) {
            $assignedLicensesFriendlyText = Convert-AssessmentExportListToText -Value (Get-AssessmentExportPropertyValue -Record $userRecord -Names @('AssignedPlans'))
        }
        if ([string]::IsNullOrWhiteSpace($assignedLicensesFriendlyText)) {
            $assignedLicensesFriendlyText = Convert-AssessmentExportDisplayText -Value (Get-AssessmentExportPropertyValue -Record $userRecord -Names @('AssignedLicensesFriendly', 'AssignedLicenses'))
        }
        Set-AssessmentExportProperty -Record $userRecord -Name 'AssignedLicensesFriendly' -Value $assignedLicensesFriendlyText
        Set-AssessmentExportProperty -Record $userRecord -Name 'Mail' -Value (Get-AssessmentExportPropertyValue -Record $userRecord -Names @('Mail', 'UserPrincipalName'))

        Set-AssessmentExportProperty -Record $userRecord -Name 'HasMailbox' -Value ($null -ne $mailboxRecord)
        Set-AssessmentExportProperty -Record $userRecord -Name 'MailboxPrimarySmtpAddress' -Value (Get-AssessmentExportPropertyValue -Record $mailboxRecord -Names @('PrimarySmtpAddress'))
        Set-AssessmentExportProperty -Record $userRecord -Name 'RecipientTypeDetails' -Value (Get-AssessmentExportPropertyValue -Record $mailboxRecord -Names @('RecipientTypeDetails'))
        Set-AssessmentExportProperty -Record $userRecord -Name 'TargetUPN' -Value $null
        Set-AssessmentExportProperty -Record $userRecord -Name 'TargetPrimarySmtpAddress' -Value $null
        Set-AssessmentExportProperty -Record $userRecord -Name 'Wave' -Value $null
        Set-AssessmentExportProperty -Record $userRecord -Name 'MigrationState' -Value $null
        Set-AssessmentExportProperty -Record $userRecord -Name 'CutoverDate' -Value $null
        Set-AssessmentExportProperty -Record $userRecord -Name 'Notes' -Value $null
    }

    foreach ($recipientRecord in @($recipients)) {
        $primarySmtpAddress = Get-AssessmentExportPropertyValue -Record $recipientRecord -Names @('PrimarySmtpAddress')
        $routingSummary = Resolve-AssessmentExportRoutingSummary -Record $recipientRecord
        Set-AssessmentExportProperty -Record $recipientRecord -Name 'PrimaryDomain' -Value (Get-AssessmentExportDomainFromAddress -Address $primarySmtpAddress)
        Set-AssessmentExportProperty -Record $recipientRecord -Name 'OnMicrosoftAlias' -Value $routingSummary.OnMicrosoftAlias
        Set-AssessmentExportProperty -Record $recipientRecord -Name 'OnMicrosoftAliases' -Value $routingSummary.OnMicrosoftAliases
        Set-AssessmentExportProperty -Record $recipientRecord -Name 'Notes' -Value $null
    }

    $spamFilteringSummary = $null
    if ($TenantStatsStore.ContainsKey('SpamFilteringSummary') -and $TenantStatsStore['SpamFilteringSummary']) {
        $spamFilteringSummary = Get-AssessmentExportPropertyValue -Record $TenantStatsStore['SpamFilteringSummary'] -Names @('Summary')
    }
    if (-not $spamFilteringSummary -and $TenantStatsStore.ContainsKey('SpamFilteringConfig') -and $TenantStatsStore['SpamFilteringConfig']) {
        $spamFilteringSummary = Get-AssessmentExportPropertyValue -Record $TenantStatsStore['SpamFilteringConfig'] -Names @('Configuration', 'Summary')
    }

    $hybridSummary = $null
    if ($TenantStatsStore.ContainsKey('HybridConfiguration') -and $TenantStatsStore['HybridConfiguration']) {
        $hybridSummary = Get-AssessmentExportPropertyValue -Record $TenantStatsStore['HybridConfiguration'] -Names @('Summary')
        if (-not $hybridSummary) {
            $hybridSummary = $TenantStatsStore['HybridConfiguration']
        }
    }
    $hybridSignalsPresent = $false
    foreach ($hybridValue in @(
            (Get-AssessmentExportPropertyValue -Record $hybridSummary -Names @('HybridConfigured', 'IsHybridConfigured')),
            (Get-AssessmentExportPropertyValue -Record $hybridSummary -Names @('RemoteRoutingAddressConfigured')),
            (Get-AssessmentExportPropertyValue -Record $hybridSummary -Names @('CentralizedMailTransportEnabled'))
        )) {
        if ($hybridValue -eq $true -or ([string]$hybridValue -match '^(?i:true|yes|enabled|configured)$')) {
            $hybridSignalsPresent = $true
        }
    }

    foreach ($domainRecord in @($domainRows)) {
        $domainName = Get-AssessmentExportPropertyValue -Record $domainRecord -Names @('Name', 'Domain')
        $office365MailExchanger = Get-AssessmentExportPropertyValue -Record $domainRecord -Names @('Office365MailExchanger')
        $domainType = Get-AssessmentExportPropertyValue -Record $domainRecord -Names @('DomainType')
        $authenticationType = Get-AssessmentExportPropertyValue -Record $domainRecord -Names @('AuthenticationType')
        $recipientCount = Get-AssessmentExportPropertyValue -Record $domainRecord -Names @('RecipientCount', 'TotalDomainRecipients', 'PrimarySMTPRecipients')
        $supportedServices = Get-AssessmentExportPropertyValue -Record $domainRecord -Names @('SupportedServices', 'Capabilities')
        $mxRecords = Convert-AssessmentExportListToText -Value (Get-AssessmentExportPropertyValue -Record $domainRecord -Names @('MXRecords'))

        $thirdPartySpamFilteringDetected = $false
        if ($office365MailExchanger -eq $false -or ([string]$office365MailExchanger -match '^(?i:false|no|0)$')) {
            $thirdPartySpamFilteringDetected = $true
        }
        $spamFilteringSignal = Get-AssessmentExportPropertyValue -Record $spamFilteringSummary -Names @('Uses3rdPartyFiltering')
        if ($spamFilteringSignal -eq $true -or ([string]$spamFilteringSignal -match '^(?i:true|yes|enabled|review)$')) {
            $thirdPartySpamFilteringDetected = $true
        }

        $hybridRoutingReview = $false
        if ($hybridSignalsPresent) {
            $hybridRoutingReview = $true
        }
        if ([string]$domainType -match '^(?i)InternalRelay$' -or [string]$authenticationType -match '^(?i)Federated$') {
            $hybridRoutingReview = $true
        }

        Set-AssessmentExportProperty -Record $domainRecord -Name 'Name' -Value $domainName
        Set-AssessmentExportProperty -Record $domainRecord -Name 'SupportedServices' -Value (Convert-AssessmentExportDisplayText -Value $supportedServices)
        Set-AssessmentExportProperty -Record $domainRecord -Name 'RecipientCount' -Value $recipientCount
        Set-AssessmentExportProperty -Record $domainRecord -Name 'MXRecords' -Value $mxRecords
        Set-AssessmentExportProperty -Record $domainRecord -Name 'ThirdPartySpamFilterReview' -Value $(if ($thirdPartySpamFilteringDetected) { 'Review' } else { 'No immediate signal' })
        Set-AssessmentExportProperty -Record $domainRecord -Name 'HybridRoutingReview' -Value $(if ($hybridRoutingReview) { 'Review' } else { 'No immediate signal' })
        Set-AssessmentExportProperty -Record $domainRecord -Name 'Notes' -Value $null
    }

    foreach ($record in @($teamRows + $sharePointRows + $oneDriveRows)) {
        Set-AssessmentExportProperty -Record $record -Name 'Notes' -Value $null
    }
    foreach ($teamRecord in @($teamRows)) {
        Set-AssessmentExportProperty -Record $teamRecord -Name 'SharedChannels' -Value (Convert-AssessmentExportListToText -Value (Get-AssessmentExportPropertyValue -Record $teamRecord -Names @('SharedChannels')))
    }

    $delegateAssignmentRows = New-Object System.Collections.Generic.List[object]
    foreach ($mailboxRecord in @($mailboxPlanningRows)) {
        $baseAssignment = @{
            MailboxDisplayName        = Get-AssessmentExportPropertyValue -Record $mailboxRecord -Names @('DisplayName')
            MailboxPrimarySmtpAddress = Get-AssessmentExportPropertyValue -Record $mailboxRecord -Names @('PrimarySmtpAddress')
            MailboxUserPrincipalName  = Get-AssessmentExportPropertyValue -Record $mailboxRecord -Names @('UserPrincipalName')
            RecipientTypeDetails      = Get-AssessmentExportPropertyValue -Record $mailboxRecord -Names @('RecipientTypeDetails')
            Wave                      = Get-AssessmentExportPropertyValue -Record $mailboxRecord -Names @('Wave')
            Notes                     = $null
        }

        foreach ($assignmentDefinition in @(
                @{ PermissionType = 'FullAccess'; DelegateField = 'FullAccessDelegates'; CountField = 'FullAccessDelegateCount'; StateField = 'FullAccessDelegateState' },
                @{ PermissionType = 'SendAs'; DelegateField = 'SendAsDelegates'; CountField = 'SendAsDelegateCount'; StateField = 'SendAsDelegateState' },
                @{ PermissionType = 'SendOnBehalf'; DelegateField = 'GrantSendOnBehalfTo'; CountField = 'GrantSendOnBehalfToCount'; StateField = $null }
            )) {
            $delegates = Convert-AssessmentExportListToArray -Value (Get-AssessmentExportPropertyValue -Record $mailboxRecord -Names @($assignmentDefinition.DelegateField))
            $delegateCount = Get-AssessmentExportPropertyValue -Record $mailboxRecord -Names @($assignmentDefinition.CountField)
            $collectionState = if ($assignmentDefinition.StateField) {
                Get-AssessmentExportPropertyValue -Record $mailboxRecord -Names @($assignmentDefinition.StateField)
            } else {
                if ($delegates.Count -gt 0 -or [int](Convert-ArrayaToNumber -Value $delegateCount -AsInt64) -gt 0) { 'Collected' } else { 'NotApplicable' }
            }

            if ($delegates.Count -eq 0 -and [int](Convert-ArrayaToNumber -Value $delegateCount -AsInt64) -gt 0) {
                $delegates = @('Not surfaced in current source')
            }

            foreach ($delegate in @($delegates)) {
                $delegateAssignmentRows.Add([pscustomobject]@{
                    MailboxDisplayName        = $baseAssignment.MailboxDisplayName
                    MailboxPrimarySmtpAddress = $baseAssignment.MailboxPrimarySmtpAddress
                    MailboxUserPrincipalName  = $baseAssignment.MailboxUserPrincipalName
                    RecipientTypeDetails      = $baseAssignment.RecipientTypeDetails
                    PermissionType            = $assignmentDefinition.PermissionType
                    Delegate                  = $delegate
                    DelegateCountSource       = $delegateCount
                    CollectionState           = $collectionState
                    Wave                      = $baseAssignment.Wave
                    Notes                     = $null
                }) | Out-Null
            }
        }
    }
    $TenantStatsStore['MailboxDelegateAssignments'] = @($delegateAssignmentRows.ToArray())

    $recipientDomainSummaryRows = New-Object System.Collections.Generic.List[object]
    foreach ($domainGroup in @(
            $recipients |
                Group-Object { Get-AssessmentExportDomainFromAddress -Address (Get-AssessmentExportPropertyValue -Record $_ -Names @('PrimarySmtpAddress', 'WindowsEmailAddress')) } |
                Sort-Object Name
        )) {
        $domainName = if ([string]::IsNullOrWhiteSpace([string]$domainGroup.Name)) { 'Unknown' } else { [string]$domainGroup.Name }
        $groupRows = @($domainGroup.Group)
        $recipientDomainSummaryRows.Add([pscustomobject]@{
            Domain                     = $domainName
            RecipientCount             = $groupRows.Count
            UserMailboxCount           = @($groupRows | Where-Object { ([string]$_.RecipientTypeDetails) -eq 'UserMailbox' }).Count
            SharedMailboxCount         = @($groupRows | Where-Object { ([string]$_.RecipientTypeDetails) -eq 'SharedMailbox' }).Count
            GroupRecipientCount        = @($groupRows | Where-Object { ([string]$_.RecipientTypeDetails) -match 'Group' }).Count
            HiddenFromAddressListsCount = @($groupRows | Where-Object { $_.HiddenFromAddressListsEnabled -eq $true }).Count
            Notes                      = $null
        }) | Out-Null
    }
    $TenantStatsStore['RecipientDomainSummary'] = @($recipientDomainSummaryRows.ToArray())

    $mailboxMigrationSummaryRows = New-Object System.Collections.Generic.List[object]
    foreach ($mailboxGroup in @(
            $mailboxPlanningRows |
                Group-Object { [string](Get-AssessmentExportPropertyValue -Record $_ -Names @('RecipientTypeDetails')) } |
                Sort-Object Name
        )) {
        $groupRows = @($mailboxGroup.Group)
        $mailboxMigrationSummaryRows.Add([pscustomobject]@{
            RecipientTypeDetails             = if ([string]::IsNullOrWhiteSpace([string]$mailboxGroup.Name)) { 'Unknown' } else { [string]$mailboxGroup.Name }
            MailboxCount                     = $groupRows.Count
            ActiveMailboxCount               = @($groupRows | Where-Object { $_.IsInactiveMailbox -ne $true }).Count
            InactiveMailboxCount             = @($groupRows | Where-Object { $_.IsInactiveMailbox -eq $true }).Count
            ArchiveEnabledCount              = @($groupRows | Where-Object { ([string]$_.ArchiveStatus) -match '^(?i)active$' }).Count
            ForwardingCount                  = @($groupRows | Where-Object {
                    -not [string]::IsNullOrWhiteSpace([string]$_.ForwardingSmtpAddress) -or
                    -not [string]::IsNullOrWhiteSpace([string]$_.ForwardingAddress)
                }).Count
            MailboxesWithDelegateDependencies = @($groupRows | Where-Object {
                    ([int](Convert-ArrayaToNumber -Value $_.FullAccessDelegateCount -AsInt64) -gt 0) -or
                    ([int](Convert-ArrayaToNumber -Value $_.SendAsDelegateCount -AsInt64) -gt 0) -or
                    ([int](Convert-ArrayaToNumber -Value $_.GrantSendOnBehalfToCount -AsInt64) -gt 0) -or
                    ([int](Convert-ArrayaToNumber -Value $_.CalendarDelegateCount -AsInt64) -gt 0)
                }).Count
            TotalDataToMigrateGB            = [math]::Round((($groupRows | ForEach-Object { [double](Convert-ArrayaToNumber -Value $_.TotalDataToMigrateGB) } | Measure-Object -Sum).Sum), 3)
        }) | Out-Null
    }
    $TenantStatsStore['MailboxMigrationSummary'] = @($mailboxMigrationSummaryRows.ToArray())

    $bitTitanLicenseSummaryRows = New-Object System.Collections.Generic.List[object]
    $activeMailboxes = @($mailboxPlanningRows | Where-Object { $_.IsInactiveMailbox -ne $true })
    $inactiveMailboxes = @($mailboxPlanningRows | Where-Object { $_.IsInactiveMailbox -eq $true })
    $allMailboxesForSizing = @($mailboxPlanningRows)
    $mailboxesWithArchive = @($allMailboxesForSizing | Where-Object { ([string]$_.ArchiveStatus) -match '^(?i)active$' })
    $mailboxesOver50 = @($allMailboxesForSizing | Where-Object { $null -ne $_.MailboxSizeGB -and [double]$_.MailboxSizeGB -gt 50 })
    $mailboxesOver100 = @($allMailboxesForSizing | Where-Object { $null -ne $_.MailboxSizeGB -and [double]$_.MailboxSizeGB -gt 100 })
    $mailboxesOver50WithDeleted = @($allMailboxesForSizing | Where-Object {
            $mailboxSize = Convert-AssessmentExportSizeToGb -Value $_.MailboxSizeGB
            $deletedSize = Convert-AssessmentExportSizeToGb -Value $_.DeletedItemsGB
            $null -ne $mailboxSize -and $null -ne $deletedSize -and (($mailboxSize + $deletedSize) -gt 50) -and ($mailboxSize -le 50)
        })
    $archivesOver100 = @($allMailboxesForSizing | Where-Object { $null -ne $_.ArchiveSizeGB -and [double]$_.ArchiveSizeGB -gt 100 })
    $migrationWizMailboxLicenses = @($allMailboxesForSizing | Where-Object { $_.BitTitanLicenseType -eq 'MigrationWiz-Mailbox' }).Count
    $migrationWizMailboxX2Licenses = @($allMailboxesForSizing | Where-Object { $_.BitTitanLicenseType -eq 'MigrationWiz-Mailbox x2' }).Count
    $userMigrationBundleLicenses = @($allMailboxesForSizing | Where-Object { $_.BitTitanLicenseType -eq 'User Migration Bundle' }).Count
    $totalMailboxDataGB = [math]::Round((($allMailboxesForSizing | ForEach-Object { [double](Convert-ArrayaToNumber -Value $_.MailboxSizeGB) } | Measure-Object -Sum).Sum), 3)
    $totalDeletedItemsGB = [math]::Round((($allMailboxesForSizing | ForEach-Object { [double](Convert-ArrayaToNumber -Value $_.DeletedItemsGB) } | Measure-Object -Sum).Sum), 3)
    $totalArchiveDataGB = [math]::Round((($allMailboxesForSizing | ForEach-Object { [double](Convert-ArrayaToNumber -Value $_.ArchiveSizeGB) } | Measure-Object -Sum).Sum), 3)
    $totalArchiveDeletedItemsGB = [math]::Round((($allMailboxesForSizing | ForEach-Object { [double](Convert-ArrayaToNumber -Value $_.ArchiveDeletedItemsGB) } | Measure-Object -Sum).Sum), 3)
    $grandTotalDataGB = [math]::Round(($totalMailboxDataGB + $totalDeletedItemsGB + $totalArchiveDataGB + $totalArchiveDeletedItemsGB), 3)
    foreach ($metricRow in @(
            @{ Section = 'Counts'; Metric = 'Active mailboxes'; Value = $activeMailboxes.Count; Notes = 'Mailbox rows included in wave and cutover planning.' },
            @{ Section = 'Counts'; Metric = 'Inactive mailboxes'; Value = $inactiveMailboxes.Count; Notes = 'Inactive mailbox rows that may require inactive-mailbox handling.' },
            @{ Section = 'Counts'; Metric = 'Archive-enabled mailboxes'; Value = $mailboxesWithArchive.Count; Notes = 'Archive-enabled mailboxes usually map to User Migration Bundle planning.' },
            @{ Section = 'Thresholds'; Metric = 'Mailboxes over 50 GB'; Value = $mailboxesOver50.Count; Notes = 'Mailbox primary content only.' },
            @{ Section = 'Thresholds'; Metric = 'Mailboxes over 100 GB'; Value = $mailboxesOver100.Count; Notes = 'Mailbox primary content only.' },
            @{ Section = 'Thresholds'; Metric = 'Mailboxes over 50 GB including deleted items'; Value = $mailboxesOver50WithDeleted.Count; Notes = 'BitTitan-style review threshold from the legacy sizing model.' },
            @{ Section = 'Thresholds'; Metric = 'Archives over 100 GB'; Value = $archivesOver100.Count; Notes = 'Archive review threshold.' },
            @{ Section = 'Data'; Metric = 'Total mailbox data (GB)'; Value = $totalMailboxDataGB; Notes = 'Primary mailbox content only.' },
            @{ Section = 'Data'; Metric = 'Total deleted items (GB)'; Value = $totalDeletedItemsGB; Notes = 'Primary mailbox deleted items only.' },
            @{ Section = 'Data'; Metric = 'Total archive data (GB)'; Value = $totalArchiveDataGB; Notes = 'Archive content only.' },
            @{ Section = 'Data'; Metric = 'Total archive deleted items (GB)'; Value = $totalArchiveDeletedItemsGB; Notes = 'Archive deleted items only.' },
            @{ Section = 'Data'; Metric = 'Grand total data to migrate (GB)'; Value = $grandTotalDataGB; Notes = 'Mailbox + deleted items + archive + archive deleted items.' },
            @{ Section = 'Licensing'; Metric = 'MigrationWiz-Mailbox'; Value = $migrationWizMailboxLicenses; Notes = 'Estimated mailbox count at 50 GB or below without archive.' },
            @{ Section = 'Licensing'; Metric = 'MigrationWiz-Mailbox x2'; Value = $migrationWizMailboxX2Licenses; Notes = 'Estimated mailbox count above 50 GB without archive.' },
            @{ Section = 'Licensing'; Metric = 'User Migration Bundle'; Value = $userMigrationBundleLicenses; Notes = 'Estimated mailbox count with active archive.' }
        )) {
        $bitTitanLicenseSummaryRows.Add([pscustomobject]$metricRow) | Out-Null
    }
    $TenantStatsStore['BitTitanLicenseSummary'] = @($bitTitanLicenseSummaryRows.ToArray())

    $delegateSummaryRows = New-Object System.Collections.Generic.List[object]
    foreach ($permissionGroup in @(
            @($delegateAssignmentRows.ToArray()) |
                Group-Object PermissionType |
                Sort-Object Name
        )) {
        $permissionRows = @($permissionGroup.Group)
        $delegateSummaryRows.Add([pscustomobject]@{
            PermissionType      = $permissionGroup.Name
            AffectedMailboxCount = @($permissionRows | Select-Object -ExpandProperty MailboxPrimarySmtpAddress -Unique).Count
            AssignmentCount     = $permissionRows.Count
            CollectionStates    = Convert-AssessmentExportListToText -Value (@($permissionRows | Select-Object -ExpandProperty CollectionState -Unique))
            Notes               = $null
        }) | Out-Null
    }
    $TenantStatsStore['DelegateSummary'] = @($delegateSummaryRows.ToArray())

    $collaborationSummaryRows = New-Object System.Collections.Generic.List[object]
    foreach ($workloadDefinition in @(
            @{ Workload = 'Teams'; Rows = $teamRows; SizeField = 'SiteSize-GB'; NameField = 'DisplayName' },
            @{ Workload = 'SharePoint'; Rows = $sharePointRows; SizeField = 'StorageUsedGB'; NameField = 'Title' },
            @{ Workload = 'OneDrive'; Rows = $oneDriveRows; SizeField = 'StorageUsedGB'; NameField = 'Title' }
        )) {
        $knownSizeRows = @($workloadDefinition.Rows | Where-Object { $null -ne (Convert-AssessmentExportSizeToGb -Value (Get-AssessmentExportPropertyValue -Record $_ -Names @($workloadDefinition.SizeField))) })
        $totalStorageGB = if ($knownSizeRows.Count -gt 0) {
            [math]::Round((($knownSizeRows | ForEach-Object { [double](Convert-AssessmentExportSizeToGb -Value (Get-AssessmentExportPropertyValue -Record $_ -Names @($workloadDefinition.SizeField))) } | Measure-Object -Sum).Sum), 3)
        } else {
            $null
        }
        $largestRow = @(
            $knownSizeRows |
                Sort-Object @{ Expression = { Convert-AssessmentExportSizeToGb -Value (Get-AssessmentExportPropertyValue -Record $_ -Names @($workloadDefinition.SizeField)) }; Descending = $true } |
                Select-Object -First 1
        ) | Select-Object -First 1
        $largestObjectSizeGB = if ($largestRow) { Convert-AssessmentExportSizeToGb -Value (Get-AssessmentExportPropertyValue -Record $largestRow -Names @($workloadDefinition.SizeField)) } else { $null }
        $largestObjectName = if ($largestRow) { Get-AssessmentExportPropertyValue -Record $largestRow -Names @($workloadDefinition.NameField, 'Url') } else { $null }
        $unknownStorageCount = [Math]::Max(($workloadDefinition.Rows.Count - $knownSizeRows.Count), 0)

        $notesText = if ($unknownStorageCount -gt 0) { 'Some size fields were not surfaced in current source.' } else { $null }
        if ($workloadDefinition.Workload -eq 'Teams') {
            $teamsWithSharedChannels = @($workloadDefinition.Rows | Where-Object { [int](Convert-ArrayaToNumber -Value $_.SharedChannelCount -AsInt64) -gt 0 })
            $sharedChannelTotal = @($workloadDefinition.Rows | ForEach-Object { [int](Convert-ArrayaToNumber -Value $_.SharedChannelCount -AsInt64) } | Measure-Object -Sum).Sum
            if ($teamsWithSharedChannels.Count -gt 0) {
                $sharedChannelNote = '{0} team(s) use {1} shared channel(s).' -f $teamsWithSharedChannels.Count, $sharedChannelTotal
                $notesText = if ([string]::IsNullOrWhiteSpace([string]$notesText)) { $sharedChannelNote } else { '{0} {1}' -f $notesText, $sharedChannelNote }
            }
        }

        $collaborationSummaryRows.Add([pscustomobject]@{
            Workload          = $workloadDefinition.Workload
            TotalCount        = $workloadDefinition.Rows.Count
            TotalStorageGB    = $totalStorageGB
            UnknownStorageCount = $unknownStorageCount
            LargestObjectName = $largestObjectName
            LargestObjectSizeGB = $largestObjectSizeGB
            Notes             = $notesText
        }) | Out-Null
    }
    $TenantStatsStore['CollaborationSummary'] = @($collaborationSummaryRows.ToArray())

    $domainsNeedingSpamReview = @($domainRows | Where-Object { ([string]$_.ThirdPartySpamFilterReview) -eq 'Review' }).Count
    $domainsNeedingHybridReview = @($domainRows | Where-Object { ([string]$_.HybridRoutingReview) -eq 'Review' }).Count
    $mailboxesMissingOnMicrosoftAlias = @($mailboxPlanningRows | Where-Object { [string]::IsNullOrWhiteSpace([string]$_.OnMicrosoftAlias) }).Count
    $mailboxesMissingLegacyX500 = @($mailboxPlanningRows | Where-Object { [string]::IsNullOrWhiteSpace([string]$_.LegacyExchangeDnX500) }).Count
    $mailboxesWithForwarding = @($mailboxPlanningRows | Where-Object {
            -not [string]::IsNullOrWhiteSpace([string]$_.ForwardingSmtpAddress) -or
            -not [string]::IsNullOrWhiteSpace([string]$_.ForwardingAddress)
        }).Count
    $mailboxesOnHold = @($mailboxPlanningRows | Where-Object { $_.LitigationHoldEnabled -eq $true }).Count
    $cutoverPrepSummaryRows = @(
        [pscustomobject]@{ Category = 'Routing'; Item = 'Mailboxes missing .onmicrosoft alias'; Status = if ($mailboxesMissingOnMicrosoftAlias -gt 0) { 'Review' } else { 'Ready' }; Value = $mailboxesMissingOnMicrosoftAlias; Notes = 'Each mailbox should expose a source .onmicrosoft routing address before target-side mail user prep.' },
        [pscustomobject]@{ Category = 'Routing'; Item = 'Mailboxes missing LegacyExchangeDN x500'; Status = if ($mailboxesMissingLegacyX500 -gt 0) { 'Review' } else { 'Ready' }; Value = $mailboxesMissingLegacyX500; Notes = 'Cross-tenant mailbox moves commonly need x500:<LegacyExchangeDN> preserved.' },
        [pscustomobject]@{ Category = 'Dependencies'; Item = 'Mailboxes with forwarding'; Status = if ($mailboxesWithForwarding -gt 0) { 'Review' } else { 'Ready' }; Value = $mailboxesWithForwarding; Notes = 'Forwarding requires cutover-day validation and restamping decisions.' },
        [pscustomobject]@{ Category = 'Dependencies'; Item = 'Mailboxes on hold'; Status = if ($mailboxesOnHold -gt 0) { 'Review' } else { 'Ready' }; Value = $mailboxesOnHold; Notes = 'Hold and retention signals can affect migration sequencing and validation.' },
        [pscustomobject]@{ Category = 'Dependencies'; Item = 'Mailbox delegate assignments'; Status = if ($delegateAssignmentRows.Count -gt 0 -or $calendarDelegateRows.Count -gt 0) { 'Review' } else { 'Ready' }; Value = ($delegateAssignmentRows.Count + $calendarDelegateRows.Count); Notes = 'Full Access, Send As, Send On Behalf, and calendar delegates need cutover tracking and possible reapplication.' },
        [pscustomobject]@{ Category = 'Mail flow'; Item = 'Mail flow connectors'; Status = if ($mailFlowConnectors.Count -gt 0) { 'Review' } else { 'Ready' }; Value = $mailFlowConnectors.Count; Notes = 'Inbound and outbound connectors should be reviewed for routing changes during coexistence and cutover.' },
        [pscustomobject]@{ Category = 'Mail flow'; Item = 'Remote domains'; Status = if ($remoteDomainRows.Count -gt 0) { 'Review' } else { 'Ready' }; Value = $remoteDomainRows.Count; Notes = 'Remote domain settings can affect auto-forwarding, TNEF, and cutover routing behavior.' },
        [pscustomobject]@{ Category = 'Mail flow'; Item = 'SMTP relay service accounts'; Status = if ($relayAccountRows.Count -gt 0) { 'Review' } else { 'Ready' }; Value = $relayAccountRows.Count; Notes = 'Relay accounts often need separate SMTP auth or connector migration planning.' },
        [pscustomobject]@{ Category = 'Domains'; Item = 'Domains with third-party spam-filter review'; Status = if ($domainsNeedingSpamReview -gt 0) { 'Review' } else { 'Ready' }; Value = $domainsNeedingSpamReview; Notes = 'Heuristic review based on MX, connector, and spam-filter signals.' },
        [pscustomobject]@{ Category = 'Domains'; Item = 'Domains with hybrid/coexistence review'; Status = if ($domainsNeedingHybridReview -gt 0) { 'Review' } else { 'Ready' }; Value = $domainsNeedingHybridReview; Notes = 'Heuristic review based on hybrid configuration, internal relay, or federated domain signals.' },
        [pscustomobject]@{ Category = 'Exchange'; Item = 'Public folders'; Status = if ($publicFolderRows.Count -gt 0) { 'Review' } else { 'Ready' }; Value = $publicFolderRows.Count; Notes = 'Public folders require separate migration planning from mailbox cutover.' }
    )
    $TenantStatsStore['CutoverPrepSummary'] = @($cutoverPrepSummaryRows)

    $migrationReadinessLookup = @{}
    foreach ($migrationReadinessRow in @(Get-AssessmentExportTableArray -TenantStatsStore $TenantStatsStore -Key 'MigrationReadiness')) {
        if ($null -eq $migrationReadinessRow) {
            continue
        }

        $migrationItem = [string](Get-AssessmentExportPropertyValue -Record $migrationReadinessRow -Names @('Item'))
        if ([string]::IsNullOrWhiteSpace($migrationItem)) {
            continue
        }

        $migrationReadinessLookup[$migrationItem] = $migrationReadinessRow
    }

    $migrationReadinessChecklistRows = New-Object System.Collections.Generic.List[object]
        function Add-TenantToTenantChecklistRow {
        param(
            [Parameter(Mandatory = $true)]
            [string]$Category,
            [Parameter(Mandatory = $true)]
            [string]$Item,
            [Parameter(Mandatory = $true)]
            [string]$Status,
            [AllowNull()]$Value,
            [AllowNull()]
            [string]$Notes,
            [AllowNull()]
            [string]$MigrationAction,
            [AllowNull()]
            [string]$SourceWorksheet
        )

        if ([string]$Status -in @('Ready', 'Info')) {
            return
        }

        $migrationReadinessChecklistRows.Add([pscustomobject]@{
            Category        = $Category
            Item            = $Item
            Status          = $Status
            Value           = $Value
            Notes           = $Notes
            MigrationAction = $MigrationAction
            SourceWorksheet = $SourceWorksheet
        }) | Out-Null
    }

    foreach ($inheritedItem in @(
            'Verified custom domains',
            'Mail routing',
            'Hybrid or coexistence indicators',
            'Directory synchronization'
        )) {
        $inheritedRow = $migrationReadinessLookup[$inheritedItem]
        if (-not $inheritedRow) {
            continue
        }

        Add-TenantToTenantChecklistRow `
            -Category ([string](Get-AssessmentExportPropertyValue -Record $inheritedRow -Names @('Category'))) `
            -Item ([string](Get-AssessmentExportPropertyValue -Record $inheritedRow -Names @('Item'))) `
            -Status ([string](Get-AssessmentExportPropertyValue -Record $inheritedRow -Names @('Status'))) `
            -Value (Get-AssessmentExportPropertyValue -Record $inheritedRow -Names @('Value')) `
            -Notes ([string](Get-AssessmentExportPropertyValue -Record $inheritedRow -Names @('Notes'))) `
            -MigrationAction ([string](Get-AssessmentExportPropertyValue -Record $inheritedRow -Names @('MigrationAction'))) `
            -SourceWorksheet ([string](Get-AssessmentExportPropertyValue -Record $inheritedRow -Names @('SourceWorksheet')))
    }

    $remoteDomainsWithAutoForwardEnabled = @(
        $remoteDomainRows |
            Where-Object {
                $_ -and
                $_.PSObject.Properties['AutoForwardEnabled'] -and
                $_.AutoForwardEnabled -eq $true
            }
    )
    $remoteDomainsWithForwardingStateMissing = @(
        $remoteDomainRows |
            Where-Object {
                $_ -and
                (
                    -not $_.PSObject.Properties['AutoForwardEnabled'] -or
                    $null -eq $_.AutoForwardEnabled
                )
            }
    )
    $mailFlowConnectorCount = @($mailFlowConnectors).Count
    $relayAccountCount = @($relayAccountRows).Count

    Add-TenantToTenantChecklistRow `
        -Category 'Messaging' `
        -Item 'Mail flow connectors' `
        -Status $(if ($mailFlowConnectorCount -gt 0) { 'Review' } else { 'Ready' }) `
        -Value ("{0} connector(s)" -f $mailFlowConnectorCount) `
        -Notes 'Inbound and outbound connectors should be reviewed for coexistence routing, relay dependencies, and cutover-day mail flow changes.' `
        -MigrationAction 'Confirm whether each connector remains required during coexistence, identify who owns it, and document the cutover-day routing change plan.' `
        -SourceWorksheet 'MailFlowConnectors'

    $remoteDomainChecklistStatus = if ($remoteDomainsWithAutoForwardEnabled.Count -gt 0) {
        'Review'
    }
    elseif ($remoteDomainRows.Count -gt 0 -and $remoteDomainsWithForwardingStateMissing.Count -gt 0) {
        'Needs Data'
    }
    else {
        'Ready'
    }
    $remoteDomainChecklistValue = if ($remoteDomainsWithAutoForwardEnabled.Count -gt 0) {
        "{0} remote domain(s) allow auto-forwarding" -f $remoteDomainsWithAutoForwardEnabled.Count
    }
    elseif ($remoteDomainChecklistStatus -eq 'Needs Data') {
        "{0} remote domain(s) collected; auto-forwarding state not surfaced for {1}" -f $remoteDomainRows.Count, $remoteDomainsWithForwardingStateMissing.Count
    }
    else {
        "{0} remote domain(s) allow auto-forwarding" -f 0
    }
    Add-TenantToTenantChecklistRow `
        -Category 'Messaging' `
        -Item 'Remote domains allowing auto-forwarding' `
        -Status $remoteDomainChecklistStatus `
        -Value $remoteDomainChecklistValue `
        -Notes 'Remote domain forwarding rules can preserve legacy forwarding paths, OOF behavior, or transport decisions that need explicit review before cutover.' `
        -MigrationAction 'Review remote-domain forwarding settings, identify any accepted exceptions, and decide whether forwarding should be preserved, removed, or restamped in the target tenant.' `
        -SourceWorksheet 'RemoteDomains'

    Add-TenantToTenantChecklistRow `
        -Category 'Messaging' `
        -Item 'SMTP relay service accounts' `
        -Status $(if ($relayAccountCount -gt 0) { 'Review' } else { 'Ready' }) `
        -Value ("{0} relay account(s)" -f $relayAccountCount) `
        -Notes 'Relay accounts and their SMTP authentication paths often require separate connector, credential, or application updates outside mailbox cutover.' `
        -MigrationAction 'Inventory relay account usage, relay endpoints, and required SMTP auth or connector changes before domain cutover.' `
        -SourceWorksheet 'SMTPRelayServiceAccounts'

    $mailboxesWithOnMicrosoftAlias = @(
        $mailboxPlanningRows |
            Where-Object { -not [string]::IsNullOrWhiteSpace([string](Get-AssessmentExportPropertyValue -Record $_ -Names @('OnMicrosoftAlias'))) }
    ).Count
    $mailboxesWithLegacyExchangeDnX500 = @(
        $mailboxPlanningRows |
            Where-Object { -not [string]::IsNullOrWhiteSpace([string](Get-AssessmentExportPropertyValue -Record $_ -Names @('LegacyExchangeDnX500'))) }
    ).Count
    $mailboxesWithAdditionalX500 = @(
        $mailboxPlanningRows |
            Where-Object {
                [int](Convert-ArrayaToNumber -Value (Get-AssessmentExportPropertyValue -Record $_ -Names @('X500AddressCount')) -AsInt64) -gt 0
            }
    ).Count
    $mailboxesWithX400 = @(
        $mailboxPlanningRows |
            Where-Object {
                [int](Convert-ArrayaToNumber -Value (Get-AssessmentExportPropertyValue -Record $_ -Names @('X400AddressCount')) -AsInt64) -gt 0
            }
    ).Count
    Add-TenantToTenantChecklistRow `
        -Category 'Messaging' `
        -Item 'Mailbox routing and proxy attributes' `
        -Status $(if ($mailboxPlanningRows.Count -gt 0 -and ($mailboxesWithOnMicrosoftAlias -lt $mailboxPlanningRows.Count -or $mailboxesWithLegacyExchangeDnX500 -lt $mailboxPlanningRows.Count)) { 'Review' } elseif ($mailboxPlanningRows.Count -eq 0) { 'Needs Data' } else { 'Ready' }) `
        -Value $(if ($mailboxPlanningRows.Count -gt 0) {
                "{0}/{1} with .onmicrosoft alias; {2}/{1} with canonical LegacyExchangeDN x500; additional X500 proxies on {3} mailbox(es); X400 proxies on {4} mailbox(es)" -f $mailboxesWithOnMicrosoftAlias, $mailboxPlanningRows.Count, $mailboxesWithLegacyExchangeDnX500, $mailboxesWithAdditionalX500, $mailboxesWithX400
            } else {
                'No mailbox objects collected for cross-tenant cutover review'
            }) `
        -Notes 'Target MailUser prep depends on source routing aliases, ExchangeGuid/ArchiveGuid continuity, canonical x500:<LegacyExchangeDN>, and preserving any additional X500 or X400 proxy addresses when present.' `
        -MigrationAction 'Validate target MailUser stamping for ExchangeGuid, ArchiveGuid, source .onmicrosoft routing addresses, canonical x500:<LegacyExchangeDN>, and any additional X500 or X400 proxies before migration batches are finalized.' `
        -SourceWorksheet 'AllMailboxes'

    $calendarDelegateSignalMailboxCount = @(
        $mailboxPlanningRows |
            Where-Object { ([string](Get-AssessmentExportPropertyValue -Record $_ -Names @('CalendarDelegateState'))) -eq 'Collected' }
    ).Count
    $calendarDelegateProblemCount = @(
        $mailboxPlanningRows |
            Where-Object { ([string](Get-AssessmentExportPropertyValue -Record $_ -Names @('CalendarDelegateState'))) -in @('Partial', 'LookupFailed', 'NotCollected') }
    ).Count
    $mailboxesWithCalendarDelegates = @(
        $mailboxPlanningRows |
            Where-Object { [int](Convert-ArrayaToNumber -Value (Get-AssessmentExportPropertyValue -Record $_ -Names @('CalendarDelegateCount')) -AsInt64) -gt 0 }
    ).Count
    $fullAccessSignalMailboxCount = @(
        $mailboxPlanningRows |
            Where-Object { ([string](Get-AssessmentExportPropertyValue -Record $_ -Names @('FullAccessDelegateState'))) -eq 'Collected' }
    ).Count
    $fullAccessProblemCount = @(
        $mailboxPlanningRows |
            Where-Object { ([string](Get-AssessmentExportPropertyValue -Record $_ -Names @('FullAccessDelegateState'))) -in @('LookupFailed', 'NotCollected') }
    ).Count
    $mailboxesWithFullAccessDelegates = @(
        $mailboxPlanningRows |
            Where-Object { [int](Convert-ArrayaToNumber -Value (Get-AssessmentExportPropertyValue -Record $_ -Names @('FullAccessDelegateCount')) -AsInt64) -gt 0 }
    ).Count
    $sendAsSignalMailboxCount = @(
        $mailboxPlanningRows |
            Where-Object { ([string](Get-AssessmentExportPropertyValue -Record $_ -Names @('SendAsDelegateState'))) -eq 'Collected' }
    ).Count
    $sendAsProblemCount = @(
        $mailboxPlanningRows |
            Where-Object { ([string](Get-AssessmentExportPropertyValue -Record $_ -Names @('SendAsDelegateState'))) -in @('LookupFailed', 'NotCollected') }
    ).Count
    $mailboxesWithSendAsDelegates = @(
        $mailboxPlanningRows |
            Where-Object { [int](Convert-ArrayaToNumber -Value (Get-AssessmentExportPropertyValue -Record $_ -Names @('SendAsDelegateCount')) -AsInt64) -gt 0 }
    ).Count
    $sendOnBehalfSignalMailboxCount = @(
        $mailboxPlanningRows |
            Where-Object { $null -ne (Get-AssessmentExportPropertyValue -Record $_ -Names @('GrantSendOnBehalfToCount')) }
    ).Count
    $mailboxesWithSendOnBehalfDelegates = @(
        $mailboxPlanningRows |
            Where-Object { [int](Convert-ArrayaToNumber -Value (Get-AssessmentExportPropertyValue -Record $_ -Names @('GrantSendOnBehalfToCount')) -AsInt64) -gt 0 }
    ).Count
    $delegateChecklistStatus = if (
        $mailboxPlanningRows.Count -eq 0 -or
        $calendarDelegateSignalMailboxCount -lt $mailboxPlanningRows.Count -or
        $fullAccessSignalMailboxCount -lt $mailboxPlanningRows.Count -or
        $sendAsSignalMailboxCount -lt $mailboxPlanningRows.Count -or
        $sendOnBehalfSignalMailboxCount -lt $mailboxPlanningRows.Count
    ) {
        'Needs Data'
    }
    elseif ($mailboxesWithCalendarDelegates -gt 0 -or $mailboxesWithFullAccessDelegates -gt 0 -or $mailboxesWithSendAsDelegates -gt 0 -or $mailboxesWithSendOnBehalfDelegates -gt 0) {
        'Review'
    }
    else {
        'Ready'
    }
    $delegateChecklistStateParts = New-Object System.Collections.Generic.List[string]
    if ($mailboxPlanningRows.Count -gt 0) {
        if ($calendarDelegateSignalMailboxCount -lt $mailboxPlanningRows.Count) {
            $delegateChecklistStateParts.Add("Calendar delegates not fully collected ($calendarDelegateSignalMailboxCount/$($mailboxPlanningRows.Count) mailboxes)") | Out-Null
        }
        else {
            $delegateChecklistStateParts.Add("Calendar delegates on $mailboxesWithCalendarDelegates mailbox(es)") | Out-Null
        }
        if ($fullAccessSignalMailboxCount -lt $mailboxPlanningRows.Count) {
            $delegateChecklistStateParts.Add("Full Access not fully collected ($fullAccessSignalMailboxCount/$($mailboxPlanningRows.Count) mailboxes)") | Out-Null
        }
        else {
            $delegateChecklistStateParts.Add("Full Access on $mailboxesWithFullAccessDelegates mailbox(es)") | Out-Null
        }
        if ($sendAsSignalMailboxCount -lt $mailboxPlanningRows.Count) {
            $delegateChecklistStateParts.Add("Send As not fully collected ($sendAsSignalMailboxCount/$($mailboxPlanningRows.Count) mailboxes)") | Out-Null
        }
        else {
            $delegateChecklistStateParts.Add("Send As on $mailboxesWithSendAsDelegates mailbox(es)") | Out-Null
        }
        if ($sendOnBehalfSignalMailboxCount -lt $mailboxPlanningRows.Count) {
            $delegateChecklistStateParts.Add("Send On Behalf not fully collected ($sendOnBehalfSignalMailboxCount/$($mailboxPlanningRows.Count) mailboxes)") | Out-Null
        }
        else {
            $delegateChecklistStateParts.Add("Send On Behalf on $mailboxesWithSendOnBehalfDelegates mailbox(es)") | Out-Null
        }
    }
    else {
        $delegateChecklistStateParts.Add('No mailbox objects collected for delegate review') | Out-Null
    }
    $delegateChecklistNotes = 'Full Access, Send As, Send On Behalf, and calendar folder permissions do not move automatically in cross-tenant mailbox migrations and usually need post-cutover reapplication.'
    if ($calendarDelegateProblemCount -gt 0 -or $fullAccessProblemCount -gt 0 -or $sendAsProblemCount -gt 0 -or $sendOnBehalfSignalMailboxCount -lt $mailboxPlanningRows.Count) {
        $delegateChecklistNotes += ' Some delegate collection states were partial or unavailable in this run, so mailbox-level delegate review should be confirmed in the workbook or recollected before execution.'
    }
    Add-TenantToTenantChecklistRow `
        -Category 'Messaging' `
        -Item 'Mailbox delegate reapplication' `
        -Status $delegateChecklistStatus `
        -Value (($delegateChecklistStateParts.ToArray()) -join '; ') `
        -Notes $delegateChecklistNotes `
        -MigrationAction 'Use the mailbox delegate worksheets and cutover pack to plan post-cutover reapplication for calendar delegates, Full Access, Send As, and Send On Behalf permissions.' `
        -SourceWorksheet 'MailboxDelegateAssignments'

    Add-TenantToTenantChecklistRow `
        -Category 'Dependencies' `
        -Item 'Mailboxes with forwarding' `
        -Status $(if ($mailboxesWithForwarding -gt 0) { 'Review' } else { 'Ready' }) `
        -Value ("{0} mailbox(es) with forwarding" -f $mailboxesWithForwarding) `
        -Notes 'Mailbox forwarding needs cutover-day validation because target-side routing, relay, or forwarding rules may change.' `
        -MigrationAction 'Inventory each mailbox forwarding path and decide whether it should be preserved, replaced, or retired after the mailbox move.' `
        -SourceWorksheet 'AllMailboxes'

    Add-TenantToTenantChecklistRow `
        -Category 'Dependencies' `
        -Item 'Mailboxes on hold' `
        -Status $(if ($mailboxesOnHold -gt 0) { 'Review' } else { 'Ready' }) `
        -Value ("{0} mailbox(es) on hold" -f $mailboxesOnHold) `
        -Notes 'Hold and retention states can affect move sequencing, validation, and post-cutover compliance review.' `
        -MigrationAction 'Validate whether held mailboxes stay in migration scope, and coordinate any retention, inactive-mailbox, or legal-hold requirements before scheduling cutover.' `
        -SourceWorksheet 'AllMailboxes'

    Add-TenantToTenantChecklistRow `
        -Category 'Messaging' `
        -Item 'Public folders' `
        -Status $(if ($publicFolderRows.Count -gt 0) { 'Review' } else { 'Ready' }) `
        -Value ("{0} public folder object(s)" -f $publicFolderRows.Count) `
        -Notes 'Public folders usually require separate migration tooling, sequencing, or exclusion decisions outside normal mailbox cutover.' `
        -MigrationAction 'Confirm whether public folders remain in migration scope and document the target-state and tooling plan before cutover.' `
        -SourceWorksheet 'PublicFolderDetails'

    $mailboxesOver50WithDeletedMetricRow = @($bitTitanLicenseSummaryRows | Where-Object { [string]$_.Metric -eq 'Mailboxes over 50 GB including deleted items' } | Select-Object -First 1) | Select-Object -First 1
    $mailboxesOver100MetricRow = @($bitTitanLicenseSummaryRows | Where-Object { [string]$_.Metric -eq 'Mailboxes over 100 GB' } | Select-Object -First 1) | Select-Object -First 1
    $mailboxesOver50WithDeleted = [int](Convert-ArrayaToNumber -Value (Get-AssessmentExportPropertyValue -Record $mailboxesOver50WithDeletedMetricRow -Names @('Value')) -AsInt64)
    $mailboxesOver100 = [int](Convert-ArrayaToNumber -Value (Get-AssessmentExportPropertyValue -Record $mailboxesOver100MetricRow -Names @('Value')) -AsInt64)
    Add-TenantToTenantChecklistRow `
        -Category 'Sizing' `
        -Item 'Oversized mailbox batches' `
        -Status $(if ($mailboxesOver50WithDeleted -gt 0 -or $mailboxesOver100 -gt 0) { 'Review' } else { 'Ready' }) `
        -Value ("{0} over 50 GB including deleted items; {1} over 100 GB" -f $mailboxesOver50WithDeleted, $mailboxesOver100) `
        -Notes 'Large mailboxes often need earlier staging, separate waves, or different MigrationWiz licensing assumptions to avoid cutover-day surprises.' `
        -MigrationAction 'Review oversized mailboxes, validate batch sizing, and align migration-wave planning and licensing before execution.' `
        -SourceWorksheet 'AllMailboxes'

    $archivesOver100MetricRow = @($bitTitanLicenseSummaryRows | Where-Object { [string]$_.Metric -eq 'Archives over 100 GB' } | Select-Object -First 1) | Select-Object -First 1
    $archivesOver100 = [int](Convert-ArrayaToNumber -Value (Get-AssessmentExportPropertyValue -Record $archivesOver100MetricRow -Names @('Value')) -AsInt64)
    Add-TenantToTenantChecklistRow `
        -Category 'Sizing' `
        -Item 'Oversized archives' `
        -Status $(if ($archivesOver100 -gt 0) { 'Review' } else { 'Ready' }) `
        -Value ("{0} archive(s) over 100 GB" -f $archivesOver100) `
        -Notes 'Large archives can change licensing expectations, increase migration duration, or require separate move-wave planning.' `
        -MigrationAction 'Validate whether oversized archives stay in the same wave as the primary mailbox and confirm the licensing and timing plan for those users.' `
        -SourceWorksheet 'AllMailboxes'

    $teamsWithSharedChannels = @(
        $teamRows |
            Where-Object { [int](Convert-ArrayaToNumber -Value (Get-AssessmentExportPropertyValue -Record $_ -Names @('SharedChannelCount')) -AsInt64) -gt 0 }
    )
    $totalSharedChannels = @(
        $teamRows |
            ForEach-Object { [int](Convert-ArrayaToNumber -Value (Get-AssessmentExportPropertyValue -Record $_ -Names @('SharedChannelCount')) -AsInt64) } |
            Measure-Object -Sum
    ).Sum
    Add-TenantToTenantChecklistRow `
        -Category 'Collaboration' `
        -Item 'Teams with shared channels' `
        -Status $(if ($teamsWithSharedChannels.Count -gt 0) { 'Review' } else { 'Ready' }) `
        -Value ("{0} team(s) with {1} shared channel(s)" -f $teamsWithSharedChannels.Count, $totalSharedChannels) `
        -Notes 'Shared channels are a manual coexistence and migration review item and should be validated before collaboration cutover planning is finalized.' `
        -MigrationAction 'Identify which teams use shared channels, confirm the target-state approach, and plan any manual remediation needed around those channels.' `
        -SourceWorksheet 'AllTeams'

    $collaborationUnknownStates = New-Object System.Collections.Generic.List[string]
    $teamsUnknownStorageCount = 0
    $sharePointUnknownStorageCount = 0
    $oneDriveUnknownStorageCount = 0
    foreach ($collaborationRow in @($TenantStatsStore['CollaborationSummary'])) {
        $workloadName = [string](Get-AssessmentExportPropertyValue -Record $collaborationRow -Names @('Workload'))
        $unknownCount = [int](Convert-ArrayaToNumber -Value (Get-AssessmentExportPropertyValue -Record $collaborationRow -Names @('UnknownStorageCount')) -AsInt64)
        switch ($workloadName) {
            'Teams' { $teamsUnknownStorageCount = $unknownCount }
            'SharePoint' { $sharePointUnknownStorageCount = $unknownCount }
            'OneDrive' { $oneDriveUnknownStorageCount = $unknownCount }
        }
    }
    $collaborationUnknownTotal = $teamsUnknownStorageCount + $sharePointUnknownStorageCount + $oneDriveUnknownStorageCount
    Add-TenantToTenantChecklistRow `
        -Category 'Collaboration' `
        -Item 'Collaboration sizing gaps' `
        -Status $(if ($collaborationUnknownTotal -gt 0) { 'Needs Data' } else { 'Ready' }) `
        -Value ("Teams {0}; SharePoint {1}; OneDrive {2} with storage not surfaced" -f $teamsUnknownStorageCount, $sharePointUnknownStorageCount, $oneDriveUnknownStorageCount) `
        -Notes 'Missing storage visibility can hide large collaboration objects that affect wave design, tooling throughput, or follow-on migration planning.' `
        -MigrationAction 'Backfill missing Teams, SharePoint, or OneDrive sizing where needed before finalizing migration waves and post-mailbox workload sequencing.' `
        -SourceWorksheet 'CollaborationSummary'

    $TenantStatsStore['MigrationReadinessChecklist'] = @($migrationReadinessChecklistRows.ToArray())

    $enabledMemberUsers = @($users | Where-Object {
            $_.UserType -ne 'Guest' -and
            ([string]$_.UserPrincipalName -notlike '*#EXT#*') -and
            ($null -eq $_.AccountEnabled -or $_.AccountEnabled -eq $true)
        }).Count
    $migrationExecutiveSummaryRows = @(
        [pscustomobject]@{ Section = 'Tenant'; Metric = 'Enabled member users'; Value = $enabledMemberUsers; Notes = 'Primary wave-planning user population.' },
        [pscustomobject]@{ Section = 'Messaging'; Metric = 'Recipients'; Value = $recipients.Count; Notes = 'All recipient rows retained in the reduced T2T scope.' },
        [pscustomobject]@{ Section = 'Messaging'; Metric = 'Mailboxes'; Value = $mailboxPlanningRows.Count; Notes = 'Mailbox rows retained for migration planning and cutover prep.' },
        [pscustomobject]@{ Section = 'Messaging'; Metric = 'Grand total data to migrate (GB)'; Value = $grandTotalDataGB; Notes = 'Mailbox + archive + deleted-item content from the BitTitan-style sizing model.' },
        [pscustomobject]@{ Section = 'Messaging'; Metric = 'Mailboxes with delegate dependencies'; Value = @($mailboxPlanningRows | Where-Object {
                ([int](Convert-ArrayaToNumber -Value $_.FullAccessDelegateCount -AsInt64) -gt 0) -or
                ([int](Convert-ArrayaToNumber -Value $_.SendAsDelegateCount -AsInt64) -gt 0) -or
                ([int](Convert-ArrayaToNumber -Value $_.GrantSendOnBehalfToCount -AsInt64) -gt 0) -or
                ([int](Convert-ArrayaToNumber -Value $_.CalendarDelegateCount -AsInt64) -gt 0)
            }).Count; Notes = 'Mailboxes with delegate relationships that need cutover attention.' },
        [pscustomobject]@{ Section = 'Collaboration'; Metric = 'Teams'; Value = $teamRows.Count; Notes = 'Team objects that may need B2B access or ownership planning.' },
        [pscustomobject]@{ Section = 'Collaboration'; Metric = 'SharePoint sites'; Value = $sharePointRows.Count; Notes = 'SharePoint sites retained for cutover planning.' },
        [pscustomobject]@{ Section = 'Collaboration'; Metric = 'OneDrive sites'; Value = $oneDriveRows.Count; Notes = 'OneDrive sites retained for ownership and migration-wave planning.' }
    )
    $TenantStatsStore['MigrationExecutiveSummary'] = @($migrationExecutiveSummaryRows)

    $adConnectWorksheetRows = New-Object System.Collections.Generic.List[object]
    $adConnectConfiguration = if ($TenantStatsStore.ContainsKey('AdConnectConfiguration')) { $TenantStatsStore['AdConnectConfiguration'] } else { $null }
    $adConnectSummary = Get-AssessmentExportPropertyValue -Record $adConnectConfiguration -Names @('Summary')
    foreach ($rowDefinition in @(
            @{ Section = 'Directory Sync'; Item = 'On-premises sync enabled'; Names = @('OnPremisesSyncEnabled') ; Notes = 'Indicates whether Microsoft Entra Connect directory synchronization is in use.' },
            @{ Section = 'Directory Sync'; Item = 'Last sync time'; Names = @('OnPremisesLastSyncDateTime') ; Notes = 'Most recent sync timestamp surfaced in the current source.' },
            @{ Section = 'Directory Sync'; Item = 'Password sync enabled'; Names = @('PasswordSyncEnabled') ; Notes = 'Password hash synchronization signal.' },
            @{ Section = 'Directory Sync'; Item = 'Pass-through authentication enabled'; Names = @('PassThroughAuthenticationEnabled', 'PassThroughAuthentication') ; Notes = 'Pass-through authentication signal.' },
            @{ Section = 'Directory Sync'; Item = 'Password writeback enabled'; Names = @('PasswordWritebackEnabled') ; Notes = 'Password writeback signal.' },
            @{ Section = 'Directory Sync'; Item = 'Device writeback enabled'; Names = @('DeviceWritebackEnabled') ; Notes = 'Device writeback signal.' },
            @{ Section = 'Directory Sync'; Item = 'Unified group writeback enabled'; Names = @('UnifiedGroupWritebackEnabled') ; Notes = 'Unified group writeback signal.' },
            @{ Section = 'Directory Sync'; Item = 'User writeback enabled'; Names = @('UserWritebackEnabled') ; Notes = 'User writeback signal.' },
            @{ Section = 'Directory Sync'; Item = 'Feature collection note'; Names = @('FeatureCollectionNote') ; Notes = 'Explains when some sync features were not surfaced in the current auth mode.' }
        )) {
        $rowValue = Get-AssessmentExportPropertyValue -Record $adConnectSummary -Names $rowDefinition.Names
        if ($null -eq $rowValue -or [string]::IsNullOrWhiteSpace([string](Convert-AssessmentExportDisplayText -Value $rowValue))) {
            continue
        }

        $adConnectWorksheetRows.Add((New-TenantToTenantConfigurationRow -Section $rowDefinition.Section -Item $rowDefinition.Item -Value $rowValue -Notes $rowDefinition.Notes)) | Out-Null
    }
    $syncServices = @((Get-AssessmentExportPropertyValue -Record $adConnectConfiguration -Names @('SyncServices')))
    foreach ($syncService in $syncServices) {
        if ($null -eq $syncService) {
            continue
        }

        $serviceName = Convert-AssessmentExportDisplayText -Value (Get-AssessmentExportPropertyValue -Record $syncService -Names @('ServiceName', 'Name')) -Default 'Directory sync service'
        $serverName = Convert-AssessmentExportDisplayText -Value (Get-AssessmentExportPropertyValue -Record $syncService -Names @('ServerName', 'Server'))
        $lastSyncTime = Convert-AssessmentExportDisplayText -Value (Get-AssessmentExportPropertyValue -Record $syncService -Names @('LastSyncTime', 'LastSyncDateTime'))
        $serviceNotes = @()
        if (-not [string]::IsNullOrWhiteSpace($serverName)) { $serviceNotes += "Server: $serverName" }
        if (-not [string]::IsNullOrWhiteSpace($lastSyncTime)) { $serviceNotes += "Last sync: $lastSyncTime" }
        $adConnectWorksheetRows.Add((New-TenantToTenantConfigurationRow -Section 'Sync Services' -Item $serviceName -Value $(if ([string]::IsNullOrWhiteSpace($serverName)) { 'Detected' } else { $serverName }) -Notes $(if ($serviceNotes.Count -gt 0) { $serviceNotes -join '; ' } else { 'Sync service detected in the current source.' }))) | Out-Null
    }
    $recentSyncErrors = @((Get-AssessmentExportPropertyValue -Record $adConnectConfiguration -Names @('RecentErrors')))
    foreach ($syncError in $recentSyncErrors) {
        if ($null -eq $syncError) {
            continue
        }

        $errorItem = Convert-AssessmentExportDisplayText -Value (Get-AssessmentExportPropertyValue -Record $syncError -Names @('ErrorType', 'Name', 'DisplayName', 'Category')) -Default 'Directory sync issue'
        $errorValue = Convert-AssessmentExportDisplayText -Value (Get-AssessmentExportPropertyValue -Record $syncError -Names @('ErrorCode', 'Id', 'Severity', 'Status')) -Default 'Detected'
        $errorNotes = Convert-AssessmentExportDisplayText -Value (Get-AssessmentExportPropertyValue -Record $syncError -Names @('Message', 'Description', 'Details'))
        $adConnectWorksheetRows.Add((New-TenantToTenantConfigurationRow -Section 'Recent Errors' -Item $errorItem -Value $errorValue -Notes $errorNotes)) | Out-Null
    }
    $adConnectErrorCount = Get-AssessmentExportPropertyValue -Record $adConnectConfiguration -Names @('ErrorCount')
    if ($null -ne $adConnectErrorCount) {
        $adConnectWorksheetRows.Add((New-TenantToTenantConfigurationRow -Section 'Recent Errors' -Item 'Recent error count' -Value $adConnectErrorCount -Notes 'Count of recent directory sync issues surfaced in the current source.' )) | Out-Null
    }
    $TenantStatsStore['TenantToTenantAdConnectConfiguration'] = @($adConnectWorksheetRows.ToArray())

    $hybridWorksheetRows = New-Object System.Collections.Generic.List[object]
    $hybridConfiguration = if ($TenantStatsStore.ContainsKey('HybridConfiguration')) { $TenantStatsStore['HybridConfiguration'] } else { $null }
    $hybridExchangeSummary = Get-AssessmentExportPropertyValue -Record $hybridConfiguration -Names @('ExchangeHybrid', 'Summary')
    foreach ($rowDefinition in @(
            @{ Section = 'Hybrid State'; Item = 'Hybrid configured'; Names = @('IsHybridConfigured', 'HybridConfigured'); Notes = 'Overall Exchange hybrid or coexistence signal.' },
            @{ Section = 'Hybrid State'; Item = 'Hybrid status'; Names = @('HybridStatus'); Notes = 'High-level classification of the current hybrid signal.' },
            @{ Section = 'Hybrid State'; Item = 'Hybrid type'; Names = @('HybridType'); Notes = 'Primary coexistence pattern currently detected.' },
            @{ Section = 'Evidence'; Item = 'Hybrid evidence count'; Names = @('EvidenceCount'); Notes = 'How many hybrid/coexistence indicators were surfaced.' },
            @{ Section = 'Evidence'; Item = 'Hybrid evidence'; Names = @('Evidence'); Notes = 'Observed hybrid/coexistence evidence summary.' },
            @{ Section = 'Mail Flow'; Item = 'Inbound on-premises connectors'; Names = @('InboundOnPremConnectorCount'); Notes = 'Inbound connectors scoped to on-premises routing.' },
            @{ Section = 'Mail Flow'; Item = 'Outbound on-premises connectors'; Names = @('OutboundOnPremConnectorCount'); Notes = 'Outbound connectors scoped to on-premises routing.' },
            @{ Section = 'Mail Flow'; Item = 'Mail flow on-premises connectors'; Names = @('MailFlowOnPremConnectorCount', 'MailFlowOnPremConnectors'); Notes = 'Named mail flow connectors that imply coexistence routing.' },
            @{ Section = 'Relationships'; Item = 'Intra-organization connectors'; Names = @('IntraOrgConnectorCount'); Notes = 'Free/busy and coexistence connector count.' },
            @{ Section = 'Relationships'; Item = 'Organization relationships'; Names = @('OrgRelationshipCount', 'OrganizationRelationships'); Notes = 'Organization relationship signal count or detail.' },
            @{ Section = 'Migration'; Item = 'Migration endpoints'; Names = @('MigrationEndpointCount', 'MigrationEndpoints'); Notes = 'Migration endpoint signal count or detail.' },
            @{ Section = 'Domains'; Item = 'Hybrid domains'; Names = @('HybridDomains'); Notes = 'Hybrid domains surfaced in organization configuration.' }
        )) {
        $rowValue = Get-AssessmentExportPropertyValue -Record $hybridExchangeSummary -Names $rowDefinition.Names
        if ($null -eq $rowValue -or [string]::IsNullOrWhiteSpace([string](Convert-AssessmentExportDisplayText -Value $rowValue))) {
            continue
        }

        $hybridWorksheetRows.Add((New-TenantToTenantConfigurationRow -Section $rowDefinition.Section -Item $rowDefinition.Item -Value $rowValue -Notes $rowDefinition.Notes)) | Out-Null
    }
    $TenantStatsStore['TenantToTenantHybridConfiguration'] = @($hybridWorksheetRows.ToArray())
}



# ----------------------------------
# Entra Report Details Specific Functions
# ----------------------------------

# Device Report Details
function Get-AllDevicesReport {
    param (
        [Parameter(Mandatory=$True,HelpMessage='Provide the level of detail')]
        [ValidateSet('minimum', 'operator', 'combined', 'automation', 'all', 'geek')]
        [string]$detailLevel
    )

    # Initialize the tenant statistics hash table. Include the start time for the script and logging
    $start = Get-Date
    $deviceProgressId = 73
    $deviceProgressTotal = 1
        # Ensure global hash table structure
        if (-not $script:tenantStatsHash) {
            $script:tenantStatsHash = @{}
        }
    $script:tenantStatsHash["DeviceDetails"] = @{}

    Write-AssessmentCollectorBanner -Message 'Getting Device Details ...' -NoNewline
    Write-Log -Type INFO -Message "[Get-AllDevicesReport] START: Gathering all Device with $($detailLevel) details" -ExportFileLocation $ExportDetails
    
    try {
        $savedProgressPreference = $ProgressPreference
        try {
            $ProgressPreference = 'SilentlyContinue'
            $devices = Get-MgDevice -All -ProgressAction SilentlyContinue -ErrorAction Stop | ? {$null -ne $_.ID}
        }
        finally {
            $ProgressPreference = $savedProgressPreference
        }
        $DesiredProperties = @(
            "DisplayName", "AccountEnabled", "OperatingSystem", "OperatingSystemVersion", "DeviceId", "ID"
            "ApproximateLastSignInDateTime", "TrustType", "DirSyncEnabled", "LastDirSyncTime"
            "IsCompliant", "IsManaged", "ProfileType"
            )

        # Filter for Desired Attributes
        switch ($detailLevel) {
            {$_ -in "minimum", "operator", "combined", "automation", "all"} { 
                $devices = $devices | Select $DesiredProperties
            }
            geek {$devices = $devices}
        }

        # Add Additional Properties - MDM Solution, Join Type, Stale Device
        $totalCount = $devices.count
        $deviceProgressTotal = [Math]::Max($totalCount, 1)
        foreach ($device in $devices) {
            Write-ProgressHelper -Total $deviceProgressTotal -Id $deviceProgressId -Activity "Processing all Found Devices" -Operation "Updating Device Details for $($device.DisplayName)"
            try {
                #Add MDM Solution
                if ($device.ID) {
                    $device | Add-Member -MemberType NoteProperty -Name "ObjectID" -Value $device.ID -Force
                }
                #Add MDM Solution
                    if ($device.IsManaged -eq $true) {
                        $device | Add-Member -MemberType NoteProperty -Name "MDMSolution" -Value "Intune or SCCM" -Force
                    } else {
                        $device | Add-Member -MemberType NoteProperty -Name "MDMSolution" -Value "Not Managed" -Force
                    }
                Write-Log -Type DEBUG -Message ("[Get-AllDevicesReport] Adding Device Details for '{0}': Added {1} MDM Solution value" -f $device.DisplayName, $device.MDMSolution) -ExportFileLocation $ExportDetails
        
                #Add Join Type
                switch ($device.DeviceTrustType) {
                    AzureAD {
                        $device | Add-Member -MemberType NoteProperty -Name "DeviceJoinType" -Value "Entra AD joined" -Force
                    }
                    WorkPlace {
                        $device | Add-Member -MemberType NoteProperty -Name "DeviceJoinType" -Value "Entra AD registered" -Force
                    }
                    ServerAd {
                        $device | Add-Member -MemberType NoteProperty -Name "DeviceJoinType" -Value "Hybrid Entra AD joined" -Force
                    }
                    Default {
                        $device | Add-Member -MemberType NoteProperty -Name "DeviceJoinType" -Value "Unknown" -Force
                    }
                }
                Write-Log -Type DEBUG -Message ("[Get-AllDevicesReport] ({0}/{1}) Adding Device Details for '{2}': Added {3} Join Type value" -f $progressCounter, $devices.count, $device.DisplayName, $device.MDMSolution) -ExportFileLocation $ExportDetails
        
                #Add if Stale Device (Approximate login time older than 6 months)
                $lastLogin = $device.ApproximateLastSignInDateTime
                if ($lastLogin) {
                    $sixMonthsAgo = (Get-Date).AddMonths(-6)
                    $timeSinceLastLogon = $sixMonthsAgo - $lastLogin
                    $device | Add-Member -MemberType NoteProperty -Name "DaysDeviceInactiveFrom6MonthsAgo" -Value $timeSinceLastLogon.Days -Force
                    if ($lastLogin -le $sixMonthsAgo) {
                        $device | Add-Member -MemberType NoteProperty -Name "DeviceStale" -Value $true -Force
                    } else {
                        $device | Add-Member -MemberType NoteProperty -Name "DeviceStale" -Value $false -Force
                    }
                }
                elseif ($lastLogin) {
                    $device | Add-Member -MemberType NoteProperty -Name "DaysDeviceInactiveFrom6MonthsAgo" -Value "N/A" -Force
                    $device | Add-Member -MemberType NoteProperty -Name "DeviceStale" -Value "N/A" -Force
                }
                Write-Log -Type DEBUG -Message ("[Get-AllDevicesReport] ({0}/{1}) Adding Device Details for '{2}': Added {3} Device Stale value" -f $progressCounter, $devices.count, $device.DisplayName, $device.MDMSolution) -ExportFileLocation $ExportDetails
                
                #Add Compliant State
                if ($null -eq $device.IsCompliant) {
                    $device | Add-Member -MemberType NoteProperty -Name "IsCompliant" -Value "NotApplied" -Force
                }
                Write-Log -Type DEBUG -Message ("[Get-AllDevicesReport] ({0}/{1}) Adding Device Details for '{2}': Added {3} Device Compliant value" -f $progressCounter, $devices.count, $device.DisplayName, $device.MDMSolution) -ExportFileLocation $ExportDetails

            }
            catch {
                Write-Log -Type Error -Message ("[Get-AllDevicesReport] ({0}/{1}) Failed to add Device Details for '{2}'. $($_.Exception.Message)" -f $progressCounter, $devices.count, $device.DisplayName) -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
            }
            finally {
                #Add to Hash Table
                $script:tenantStatsHash["DeviceDetails"][$device.ObjectID] = $device
            }
        }
    }
    catch {
        Write-Log -Type ERROR -Message "[Get-AllDevicesReport] An error occurred in running Get-AllDeviceReport function. $($_.Exception.Message)" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
    }
    finally {
        $CompletedTime = (((Get-Date) - $start).ToString('hh\:mm\:ss'))
        Write-ProgressHelper -Total $deviceProgressTotal -Id $deviceProgressId -Activity "Processing all Found Devices" -Completed
        Write-AssessmentCollectorCompletionBanner -Message "Completed in $($CompletedTime)"
        Write-Log -Type INFO -Message "[Get-AllDevicesReport] COMPLETED: Gathering all Entra Devices with $($detailLevel) details" -ExportFileLocation $ExportDetails
    }   
}

# Function to Retrieve Conditional Access Policies from Microsoft Graph
function Get-ConditionalAccessPoliciesReport {
    param (
        [Parameter(Mandatory = $True, HelpMessage = 'Provide the level of detail')]
        [ValidateSet('minimum', 'operator', 'combined', 'automation', 'all', 'geek')]
        [string]$detailLevel
    )

    $start = Get-Date
    $conditionalAccessProgressId = 74
    $conditionalAccessProgressTotal = 1

    # Ensure global hash table structure
    if (-not $script:tenantStatsHash) {
        $script:tenantStatsHash = @{}
    }
    $script:tenantStatsHash["ConditionalAccessPolicies"] = @{}
    $script:tenantStatsHash["ConditionalAccessPolicySummary"] = @{}

    Write-AssessmentCollectorBanner -Message 'Getting Entra Conditional Access Policies Details ...' -NoNewline
    Write-Log -Type INFO -Message "[Get-ConditionalAccessPoliciesReport] START: Gathering all Entra Conditional Access Policies  with $($detailLevel) details" -ExportFileLocation $ExportDetails

    function Get-PolicyItemCounts {
        param (
            [object]$policyCondition
        )
        if ($null -eq $policyCondition) {
            return 0
        } elseif ($policyCondition -eq "All") {
            return "All"
        } else {
            return ($policyCondition | Measure-Object).Count
        }
    }

    try {
        # Use Get-MgIdentityConditionalAccessPolicy as primary cmdlet
        $savedProgressPreference = $ProgressPreference
        try {
            $ProgressPreference = 'SilentlyContinue'
            $conditionalAccessPolicies = Get-MgIdentityConditionalAccessPolicy -All -ProgressAction SilentlyContinue -ErrorAction Stop
        }
        finally {
            $ProgressPreference = $savedProgressPreference
        }

        switch ($detailLevel) {
            { $_ -in "minimum", "operator", "combined", "automation", "all" } {
                $DesiredProperties = @(
                    "Id", "DisplayName", "CreatedDateTime", "ModifiedDateTime", "Description", "State",
                    "Conditions", "GrantControls", "SessionControls"
                )
                $conditionalAccessPolicies = $conditionalAccessPolicies | Select-Object $DesiredProperties
            }
        }

        $totalCount = $conditionalAccessPolicies.Count
        $conditionalAccessProgressTotal = [Math]::Max($totalCount, 1)

        $summaryRows = New-Object System.Collections.Generic.List[object]
        foreach ($policy in $conditionalAccessPolicies) {
            Write-ProgressHelper -Total $conditionalAccessProgressTotal -Id $conditionalAccessProgressId -Activity "Processing all Conditional Access Policies" -Operation "Expanding Policy Details for $($policy.DisplayName)"
            Write-Log -Type INFO -Message "[Get-ConditionalAccessPoliciesReport] Expanding Conditional Access Policies for $($policy.DisplayName)" -ExportFileLocation $ExportDetails

            $includeGuestsOrExternalUsers = $null
            $excludeGuestsOrExternalUsers = $null
            $authenticationStrength = $null
            if ($policy.Conditions.Users) {
                if ($policy.Conditions.Users.PSObject.Properties['IncludeGuestsOrExternalUsers']) {
                    $includeGuestsOrExternalUsers = $policy.Conditions.Users.IncludeGuestsOrExternalUsers
                }
                if ($policy.Conditions.Users.PSObject.Properties['ExcludeGuestsOrExternalUsers']) {
                    $excludeGuestsOrExternalUsers = $policy.Conditions.Users.ExcludeGuestsOrExternalUsers
                }
            }
            if ($policy.GrantControls -and $policy.GrantControls.PSObject.Properties['AuthenticationStrength']) {
                $authenticationStrength = $policy.GrantControls.AuthenticationStrength
            }

            $clientAppTypes = @($policy.Conditions.ClientAppTypes)
            $grantControlsBuiltIn = @($policy.GrantControls.BuiltInControls)
            $includeUsers = @($policy.Conditions.Users.IncludeUsers)
            $excludeUsers = @($policy.Conditions.Users.ExcludeUsers)
            $includeGroups = @($policy.Conditions.Users.IncludeGroups)
            $excludeGroups = @($policy.Conditions.Users.ExcludeGroups)
            $includeRoles = @($policy.Conditions.Users.IncludeRoles)
            $excludeRoles = @($policy.Conditions.Users.ExcludeRoles)
            $includeLocations = @($policy.Conditions.Locations.IncludeLocations)
            $excludeLocations = @($policy.Conditions.Locations.ExcludeLocations)
            $includeApps = @($policy.Conditions.Applications.IncludeApplications)
            $excludeApps = @($policy.Conditions.Applications.ExcludeApplications)
            $signInRiskInclude = @($policy.Conditions.SignInRiskLevels.IncludeLevels)
            $servicePrincipalRiskInclude = @($policy.Conditions.ServicePrincipalRiskLevels.IncludeLevels)
            $hasMeaningfulGuestInclude = Test-AssessmentMeaningfulNestedValue -Value $includeGuestsOrExternalUsers
            $hasMeaningfulGuestExclude = Test-AssessmentMeaningfulNestedValue -Value $excludeGuestsOrExternalUsers
            $hasMeaningfulAuthenticationStrength = Test-AssessmentMeaningfulNestedValue -Value $authenticationStrength
            $requiresMfaEnforcement = (
                @($grantControlsBuiltIn | Where-Object { $_ -match '^(?i)mfa$' }).Count -gt 0 -or
                $hasMeaningfulAuthenticationStrength
            )

            $hasExclusions = (
                $excludeUsers.Count -gt 0 -or
                $excludeGroups.Count -gt 0 -or
                $excludeRoles.Count -gt 0 -or
                $excludeLocations.Count -gt 0 -or
                $excludeApps.Count -gt 0 -or
                $hasMeaningfulGuestExclude
            )
            $targetsGuestsOrExternal = (
                $hasMeaningfulGuestInclude -or
                (($includeUsers -join ',') -match 'guest|external')
            )
            $targetsPrivilegedRoles = ($includeRoles.Count -gt 0 -or $excludeRoles.Count -gt 0)
            $blocksLegacyAuth = (($clientAppTypes -join ',') -match 'exchangeactivesync|other' -and (($grantControlsBuiltIn -join ',') -match 'block'))
            $requiresCompliantDevice = (($grantControlsBuiltIn -join ',') -match 'compliantdevice|domainjoineddevice')
            $usesRiskSignals = ($signInRiskInclude.Count -gt 0 -or $servicePrincipalRiskInclude.Count -gt 0)

            $policyDetailsHash = [ordered]@{
                PolicyID         = $policy.Id
                DisplayName      = $policy.DisplayName
                State            = $policy.State
                CreatedDateTime  = $policy.CreatedDateTime
                ModifiedDateTime = $policy.ModifiedDateTime
                Description      = $policy.Description

                # Grant Controls
                GrantControls_BuiltInControls  = $policy.GrantControls.BuiltInControls -join ','
                GrantControls_CustomControls   = $policy.GrantControls.CustomControls -join ','
                GrantControls_Operator         = $policy.GrantControls.Operator

                # Session Controls
                SessionControls_ApplicationEnforcedRestrictions = $(if ($policy.SessionControls) { $policy.SessionControls.ApplicationEnforcedRestrictions.IsEnabled } else { $null })
                SessionControls_PersistentBrowser               = $(if ($policy.SessionControls) { $policy.SessionControls.PersistentBrowser.IsEnabled } else { $null })
                SessionControls_PersistentBrowserMode           = $(if ($policy.SessionControls) { $policy.SessionControls.PersistentBrowser.Mode } else { $null })
                SessionControls_SignInFrequency                 = $(if ($policy.SessionControls) { $policy.SessionControls.SignInFrequency.IsEnabled } else { $null })
                FrequencyInterval                               = $(if ($policy.SessionControls) { $policy.SessionControls.SignInFrequency.FrequencyInterval } else { $null })

                # Conditions - Users, Groups, Roles
                IncludedUsers      = $policy.Conditions.Users.IncludeUsers -join ','
                ExcludedUsers      = $policy.Conditions.Users.ExcludeUsers -join ','
                IncludedUsersCount = Get-PolicyItemCounts $policy.Conditions.Users.IncludeUsers
                ExcludedUsersCount = Get-PolicyItemCounts $policy.Conditions.Users.ExcludeUsers

                IncludedGroups      = $policy.Conditions.Users.IncludeGroups -join ','
                ExcludedGroups      = $policy.Conditions.Users.ExcludeGroups -join ','
                IncludedGroupsCount = Get-PolicyItemCounts $policy.Conditions.Users.IncludeGroups
                ExcludedGroupsCount = Get-PolicyItemCounts $policy.Conditions.Users.ExcludeGroups

                IncludedRoles      = $policy.Conditions.Users.IncludeRoles -join ','
                ExcludedRoles      = $policy.Conditions.Users.ExcludeRoles -join ','
                IncludedRolesCount = Get-PolicyItemCounts $policy.Conditions.Users.IncludeRoles
                ExcludedRolesCount = Get-PolicyItemCounts $policy.Conditions.Users.ExcludeRoles

                # Platforms
                IncludePlatforms = $policy.Conditions.Platforms.IncludePlatforms -join ','
                ExcludePlatforms = $policy.Conditions.Platforms.ExcludePlatforms -join ','

                # Locations
                IncludeLocations = $policy.Conditions.Locations.IncludeLocations -join ','
                ExcludeLocations = $policy.Conditions.Locations.ExcludeLocations -join ','

                # Devices/Device States/Filter
                IncludeDeviceStates = $policy.Conditions.Devices.IncludeDeviceStates -join ','
                ExcludeDeviceStates = $policy.Conditions.Devices.ExcludeDeviceStates -join ','
                DeviceFilterMode    = $(if ($policy.Conditions.Devices.DeviceFilter) { $policy.Conditions.Devices.DeviceFilter.Mode } else { '' })
                DeviceFilterRule    = $(if ($policy.Conditions.Devices.DeviceFilter) { $policy.Conditions.Devices.DeviceFilter.Rule } else { '' })

                # Applications/User Actions
                IncludeApplications      = $policy.Conditions.Applications.IncludeApplications -join ','
                ExcludeApplications      = $policy.Conditions.Applications.ExcludeApplications -join ','
                IncludedApplicationsCount = Get-PolicyItemCounts $policy.Conditions.Applications.IncludeApplications
                ExcludedApplicationsCount = Get-PolicyItemCounts $policy.Conditions.Applications.ExcludeApplications

                IncludeUserActions = $policy.Conditions.Applications.IncludeUserActions -join ','

                # Client Apps
                ClientAppTypes = $policy.Conditions.ClientAppTypes -join ','

                # Risk Levels & Others
                SignInRiskLevels_IncludeLevels = $policy.Conditions.SignInRiskLevels.IncludeLevels -join ','
                SignInRiskLevels_ExcludeLevels = $policy.Conditions.SignInRiskLevels.ExcludeLevels -join ','
                ServicePrincipalRiskLevels_IncludeLevels = $policy.Conditions.ServicePrincipalRiskLevels.IncludeLevels -join ','
                ServicePrincipalRiskLevels_ExcludeLevels = $policy.Conditions.ServicePrincipalRiskLevels.ExcludeLevels -join ','
                InsiderRiskLevels = $policy.Conditions.InsiderRiskLevels -join ','

                # Top-level DeviceStates
                DeviceStates_IncludeDeviceStates = $(if ($policy.Conditions.DeviceStates) { $policy.Conditions.DeviceStates.IncludeDeviceStates -join ',' } else { '' })
                DeviceStates_ExcludeDeviceStates = $(if ($policy.Conditions.DeviceStates) { $policy.Conditions.DeviceStates.ExcludeDeviceStates -join ',' } else { '' })
                IncludeGuestsOrExternalUsers = (Convert-AssessmentConditionalAccessNestedValueToText -Value $includeGuestsOrExternalUsers)
                ExcludeGuestsOrExternalUsers = (Convert-AssessmentConditionalAccessNestedValueToText -Value $excludeGuestsOrExternalUsers)
                GrantControls_AuthenticationStrength = (Convert-AssessmentConditionalAccessNestedValueToText -Value $authenticationStrength)
                UsesAuthenticationStrengthForMfa = [bool]$hasMeaningfulAuthenticationStrength
                RequiresMfaEnforcement = [bool]$requiresMfaEnforcement
                IsReportOnly                = (($policy.State -as [string]) -match 'report')
                HasExclusions               = [bool]$hasExclusions
                TargetsGuestsOrExternalUsers = [bool]$targetsGuestsOrExternal
                TargetsPrivilegedRoles      = [bool]$targetsPrivilegedRoles
                BlocksLegacyAuth            = [bool]$blocksLegacyAuth
                RequiresCompliantDevice     = [bool]$requiresCompliantDevice
                UsesRiskSignals             = [bool]$usesRiskSignals
            }

            $policyStorageKey = if (-not [string]::IsNullOrWhiteSpace([string]$policy.Id)) {
                [string]$policy.Id
            }
            elseif (-not [string]::IsNullOrWhiteSpace([string]$policy.DisplayName)) {
                '{0:D3}-{1}' -f ($summaryRows.Count + 1), $policy.DisplayName
            }
            else {
                '{0:D3}-ConditionalAccessPolicy' -f ($summaryRows.Count + 1)
            }

            $script:tenantStatsHash["ConditionalAccessPolicies"][$policyStorageKey] = $policyDetailsHash
            $summaryRows.Add([pscustomobject]@{
                DisplayName                 = $policy.DisplayName
                State                       = $policy.State
                IsEnabled                   = ([string]$policy.State).ToLowerInvariant() -eq 'enabled'
                IsReportOnly                = (($policy.State -as [string]) -match 'report')
                RequiresMfaEnforcement      = [bool]$requiresMfaEnforcement
                UsesAuthenticationStrengthForMfa = [bool]$hasMeaningfulAuthenticationStrength
                HasExclusions               = [bool]$hasExclusions
                TargetsGuestsOrExternalUsers = [bool]$targetsGuestsOrExternal
                TargetsPrivilegedRoles      = [bool]$targetsPrivilegedRoles
                BlocksLegacyAuth            = [bool]$blocksLegacyAuth
                RequiresCompliantDevice     = [bool]$requiresCompliantDevice
                UsesRiskSignals             = [bool]$usesRiskSignals
            }) | Out-Null
        }

        $enabledPolicies = @($summaryRows | Where-Object { $_.IsEnabled })
        $reportOnlyPolicies = @($summaryRows | Where-Object { $_.IsReportOnly })
        $policiesWithExclusions = @($summaryRows | Where-Object { $_.HasExclusions })
        $guestPolicies = @($summaryRows | Where-Object { $_.TargetsGuestsOrExternalUsers })
        $privilegedPolicies = @($summaryRows | Where-Object { $_.TargetsPrivilegedRoles })
        $legacyAuthPolicies = @($summaryRows | Where-Object { $_.BlocksLegacyAuth })
        $compliantDevicePolicies = @($summaryRows | Where-Object { $_.RequiresCompliantDevice })
        $riskPolicies = @($summaryRows | Where-Object { $_.UsesRiskSignals })

        $script:tenantStatsHash["ConditionalAccessPolicySummary"]["Summary"] = [pscustomobject]@{
            TotalPolicies                     = $summaryRows.Count
            EnabledPolicies                   = $enabledPolicies.Count
            ReportOnlyPolicies                = $reportOnlyPolicies.Count
            PoliciesWithExclusions            = $policiesWithExclusions.Count
            PoliciesTargetingGuestsOrExternal = $guestPolicies.Count
            PoliciesTargetingPrivilegedRoles  = $privilegedPolicies.Count
            PoliciesBlockingLegacyAuth        = $legacyAuthPolicies.Count
            PoliciesRequiringCompliantDevice  = $compliantDevicePolicies.Count
            PoliciesUsingRiskSignals          = $riskPolicies.Count
            HasGuestCoverage                  = ($guestPolicies.Count -gt 0)
            HasPrivilegedRoleCoverage         = ($privilegedPolicies.Count -gt 0)
            HasLegacyAuthProtection           = ($legacyAuthPolicies.Count -gt 0)
            HasCompliantDeviceRequirement     = ($compliantDevicePolicies.Count -gt 0)
            HasRiskBasedCoverage              = ($riskPolicies.Count -gt 0)
        }
    }
    catch {
        Write-Log -Type ERROR -Message "[Get-ConditionalAccessPoliciesReport] An error occurred in running Get-ConditionalAccessPoliciesReport function. $($_.Exception.Message)" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
    }
    finally {
        Write-ProgressHelper -Total $conditionalAccessProgressTotal -Id $conditionalAccessProgressId -Activity "Processing all Conditional Access Policies" -Completed
        $CompletedTime = (((Get-Date) - $start).ToString('hh\:mm\:ss'))
        Write-AssessmentCollectorCompletionBanner -Message "Completed in $($CompletedTime)"
        Write-Log -Type INFO -Message "[Get-ConditionalAccessPoliciesReport] COMPLETED: Gathering all Entra Conditional Access Policies with $($detailLevel) details" -ExportFileLocation $ExportDetails
    }
}

# Secure Score Report Details
function Get-SecuritySecureScoreReport {
    param (
        [Parameter(Mandatory=$True,HelpMessage='Provide the level of detail')]
        [ValidateSet('minimum', 'operator', 'combined', 'automation', 'all', 'geek')]
        [string]$detailLevel,
        [Parameter(Mandatory=$false,HelpMessage='Should It Only Pull the Most Recent?')]
        [Switch]$MostRecent 
    )
    $start = Get-Date
    $secureScoreProgressId = 75
    $secureScoreProgressTotal = 1
    # Ensure global hash table structure
    if (-not $script:tenantStatsHash) {
        $script:tenantStatsHash = @{}
    }
    $script:tenantStatsHash["SecuritySecureScore"] = @{}
    $script:tenantStatsHash["SecureScoreActions"] = @{}
    $depthPolicy = if ($script:CollectionDepthPolicy) {
        $script:CollectionDepthPolicy
    } else {
        Get-ArrayaCollectionDepthPolicy -ReportingMode ((Get-Culture).TextInfo.ToTitleCase($detailLevel.ToLowerInvariant()))
    }
    $collectSecureScoreMappings = ($depthPolicy.CollectSecureScoreMappings -eq $true)

    Write-AssessmentCollectorBanner -Message 'Getting Security Score Details ...' -NoNewline
    Write-Log -Type INFO -Message "[Get-SecuritySecureScoreReport] START: Gathering all Security Score details" -ExportFileLocation $ExportDetails
    try {
        $controlProfileLookup = @{}
        if ($collectSecureScoreMappings) {
            try {
                $controlProfileUri = "https://graph.microsoft.com/v1.0/security/secureScoreControlProfiles?`$select=id,title,maxScore,rank,controlCategory,service,actionUrl,remediation,description,threats,userImpact,implementationCost,tier"
                $controlProfiles = @(Get-ArrayaGraphResource -Uri $controlProfileUri -PageSize 250 -Activity 'Secure Score control profile mappings' -Headers $global:GraphHeaders)
                foreach ($profile in $controlProfiles) {
                    if ($profile.Id) {
                        $controlProfileLookup[$profile.Id] = [PSCustomObject]@{
                            Id                 = $profile.Id
                            Title              = $profile.Title
                            MaxScore           = $profile.MaxScore
                            Rank               = $profile.Rank
                            ControlCategory    = $profile.ControlCategory
                            Service            = $profile.Service
                            ActionUrl          = $profile.ActionUrl
                            Remediation        = $profile.Remediation
                            Description        = $profile.Description
                            Threats            = @($profile.Threats)
                            UserImpact         = $profile.UserImpact
                            ImplementationCost = $profile.ImplementationCost
                            Tier               = $profile.Tier
                        }
                    }
                }
                Write-Log -Type INFO -Message "[Get-SecuritySecureScoreReport] Loaded $($controlProfileLookup.Count) Secure Score control profile mappings" -ExportFileLocation $ExportDetails
                $controlProfiles = $null
            } catch {
                Write-Log -Type WARNING -Message "[Get-SecuritySecureScoreReport] Unable to load Secure Score control profiles for source mapping: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
            }
        } else {
            Write-Log -Type INFO -Message "[Get-SecuritySecureScoreReport] Skipping Secure Score control profile mappings for this output profile." -ExportFileLocation $ExportDetails
        }

        if ($MostRecent) {
            $secureScoreUri = "https://graph.microsoft.com/v1.0/security/secureScores?`$orderby=createdDateTime desc&`$top=1"
            $secureScoreResponse = $null
            $secureScoreResponse = Invoke-ArrayaGraphCollectionRequest -Uri $secureScoreUri -Activity 'Secure Score most recent' -GraphMode $script:CurrentGraphMode -Headers $global:GraphHeaders -Context $script:AssessmentContext -ScriptBlock {
                if ((Get-Command Invoke-MgGraphRequest -ErrorAction SilentlyContinue) -and (Get-MgContext -ErrorAction SilentlyContinue)) {
                    $savedProgressPreference = $ProgressPreference
                    try {
                        $ProgressPreference = 'SilentlyContinue'
                        Invoke-MgGraphRequest -Uri $secureScoreUri -Method GET -OutputType PSObject -ProgressAction SilentlyContinue -ErrorAction Stop
                    }
                    finally {
                        $ProgressPreference = $savedProgressPreference
                    }
                }
                else {
                    Invoke-QuietRestMethod -Parameters @{
                        Uri         = $secureScoreUri
                        Headers     = $global:GraphHeaders
                        Method      = 'Get'
                        ContentType = 'application/json'
                        ErrorAction = 'Stop'
                    }
                }
            }
            $secureScore = @($secureScoreResponse.value | Where-Object { $null -ne $_.ID } | Select-Object -First 1)
        } else {
            $secureScore = @(Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/security/secureScores' -PageSize 250 -Activity 'Secure Score history' -Headers $global:GraphHeaders | Where-Object { $null -ne $_.ID })
        }

        # Add Additional Properties
        $totalCount = $secureScore.count
        $secureScoreProgressTotal = [Math]::Max($totalCount, 1)
        foreach ($score in $secureScore) {
            Write-ProgressHelper -Total $secureScoreProgressTotal -Id $secureScoreProgressId -Activity "Processing all Security Score Details" -Operation "Gathering Score Details for $($score.ID)"
            Write-Log -Type INFO -Message "[Get-SecuritySecureScoreReport] Gathering Score Details for $($score.ID)" -ExportFileLocation $ExportDetails
            #Create Current Security Score Hash Table
            $currentSecurityScores = [PSCustomObject]@{
                ID = $score.ID
                CreatedDateTime = $score.CreatedDateTime
                # Add Current Security Score Percentage
                SecurityScorePercentage = ("{0:F2}" -f (($score.currentScore / $score.maxScore) * 100))
                CurrentScore = $score.CurrentScore
                MaxScore = $score.MaxScore
                LicensedUserCount = $score.LicensedUserCount
                # Add Enabled Services
                EnabledServicesCount = ($score.EnabledServices | Measure-Object).Count
                EnabledServices = ($score.EnabledServices -join ",")
                VendorProvider = $score.VendorInformation.Provider
                VendorName = $score.VendorInformation.Vendor
            }
            
            # Add Comparitive Scores - TotalSeats, AllTenants
            Write-Log -Type INFO -Message "[Get-SecuritySecureScoreReport] Gathering Score Details for $($score.ID): Add Comparitive Scores" -ExportFileLocation $ExportDetails
            $comparativeScores = $score.AverageComparativeScores
            $TotalSeatsScoreFullDetails = $comparativeScores | Where-Object { $_.Basis -eq "TotalSeats" }
            $currentSecurityScores | Add-Member -MemberType NoteProperty -Name "SimilarSeatSizeRangeLowerValue" -Value $(if ($TotalSeatsScoreFullDetails) { $TotalSeatsScoreFullDetails["SeatSizeRangeLowerValue"] } else { $null })
            $currentSecurityScores | Add-Member -MemberType NoteProperty -Name "SimilarSeatSizeRangeUpperValue" -Value $(if ($TotalSeatsScoreFullDetails) { $TotalSeatsScoreFullDetails["SeatSizeRangeUpperValue"] } else { $null })
            foreach ($ComparisonScore in ($comparativeScores | Where-Object { $_ })) {
                if ($ComparisonScore.Basis -eq "TotalSeats") {
                    $ComparisonBasisName = "SimilarSizeOrg"
                } elseif ($ComparisonScore.Basis -eq "AllTenants") {
                    $ComparisonBasisName = "AllTenants"
                }
                Write-Log -Type DEBUG -Message "[Get-SecuritySecureScoreReport] Gathering $($ComparisonBasisName) ComparisonScore Details Details for $($score.ID)" -ExportFileLocation $ExportDetails
                $currentSecurityScores | Add-Member -MemberType NoteProperty -Name "$($ComparisonBasisName)_ComparitiveScore" -Value $ComparisonScore.ComparativeScore
                if ($detailLevel -in "all", "geek") {
                    $comparisonAdditional = @{}
                    if ($ComparisonScore.PSObject.Properties['AdditionalProperties'] -and $ComparisonScore.AdditionalProperties) {
                        $comparisonAdditional = $ComparisonScore.AdditionalProperties
                    }
                    elseif ($ComparisonScore.PSObject.Properties['AdditionalData'] -and $ComparisonScore.AdditionalData) {
                        $comparisonAdditional = $ComparisonScore.AdditionalData
                    }

                    foreach ($individualScore in @($comparisonAdditional.Keys)) {
                        Write-Log -Type DEBUG -Message "[Get-SecuritySecureScoreReport] Gathering $($ComparisonScore.Basis):$($individualScore) Score Details for $($score.ID): Add Comparitive Scores" -ExportFileLocation $ExportDetails
                        $currentSecurityScores | Add-Member -MemberType NoteProperty -Name "$($ComparisonBasisName)_$($individualScore)" -Value $comparisonAdditional[$individualScore]
                    }
                }
            }

            
            #Add to Hash Table
            Write-Log -Type INFO -Message "[Get-SecuritySecureScoreReport] Gathering Score Details for $($score.ID): Add Score to Tenant Stats Hash Table" -ExportFileLocation $ExportDetails
            $script:tenantStatsHash["SecuritySecureScore"][$score.ID] = $currentSecurityScores
        }

        $latestScore = @($secureScore | Sort-Object CreatedDateTime -Descending | Select-Object -First 1)
        if ($latestScore.Count -gt 0 -and $collectSecureScoreMappings) {
            $actionIndex = 0
            foreach ($controlScore in @($latestScore[0].ControlScores)) {
                $actionIndex++
                $controlName = $controlScore.ControlName
                if ([string]::IsNullOrWhiteSpace($controlName)) {
                    continue
                }

                $profile = $null
                if ($controlProfileLookup.ContainsKey($controlName)) {
                    $profile = $controlProfileLookup[$controlName]
                }

                $currentControlScore = 0
                try { $currentControlScore = [double]$controlScore.Score } catch { $currentControlScore = 0 }

                $maxControlScore = 0
                if ($null -ne $controlScore.MaxScore -and $controlScore.MaxScore -ne '') {
                    try { $maxControlScore = [double]$controlScore.MaxScore } catch { $maxControlScore = 0 }
                } elseif ($profile -and $null -ne $profile.MaxScore -and $profile.MaxScore -ne '') {
                    try { $maxControlScore = [double]$profile.MaxScore } catch { $maxControlScore = 0 }
                }

                $scoreGap = [math]::Round(($maxControlScore - $currentControlScore), 2)
                $implementationStatus = if ($maxControlScore -gt 0 -and $scoreGap -le 0) {
                    'Implemented'
                } elseif ($currentControlScore -gt 0) {
                    'Partially Implemented'
                } else {
                    'Not Implemented'
                }

                $threats = @()
                if ($profile -and $profile.Threats) {
                    $threats = @($profile.Threats)
                }

                $actionRow = [PSCustomObject]@{
                    SecureScoreSnapshotId = $latestScore[0].Id
                    ControlId             = $controlName
                    RecommendationTitle   = if ($profile -and $profile.Title) { $profile.Title } else { $controlName }
                    Status                = $implementationStatus
                    CurrentScore          = $currentControlScore
                    MaxScore              = $maxControlScore
                    ScoreGap              = $scoreGap
                    Rank                  = if ($profile -and $profile.Rank) { $profile.Rank } else { $controlScore.Rank }
                    Category              = if ($profile -and $profile.ControlCategory) { $profile.ControlCategory } else { $controlScore.ControlCategory }
                    Service               = if ($profile -and $profile.Service) { $profile.Service } else { $controlScore.Service }
                    ActionUrl             = if ($profile) { $profile.ActionUrl } else { $null }
                    Remediation           = if ($profile) { $profile.Remediation } else { $null }
                    Description           = if ($profile -and $profile.Description) { $profile.Description } else { $controlScore.Description }
                    Threats               = if ($threats.Count -gt 0) { $threats -join ', ' } else { $null }
                    UserImpact            = if ($profile) { $profile.UserImpact } else { $null }
                    ImplementationCost    = if ($profile) { $profile.ImplementationCost } else { $null }
                    Tier                  = if ($profile) { $profile.Tier } else { $null }
                    SourceMapping         = if ($profile) { 'Microsoft Secure Score Control Profile' } else { 'Secure Score Snapshot Only' }
                }

                $script:tenantStatsHash["SecureScoreActions"][("{0:D3}-{1}" -f $actionIndex, $controlName)] = $actionRow
            }
            Write-Log -Type INFO -Message "[Get-SecuritySecureScoreReport] Added $($script:tenantStatsHash['SecureScoreActions'].Count) Secure Score recommendation mappings" -ExportFileLocation $ExportDetails
        } elseif (-not $collectSecureScoreMappings) {
            Write-Log -Type INFO -Message "[Get-SecuritySecureScoreReport] Secure Score recommendation mappings were skipped for this output profile." -ExportFileLocation $ExportDetails
        }

        $latestScore = $null
        $secureScore = $null
        $controlProfileLookup = $null

    }
    catch {
        Write-Log -Type ERROR -Message "[Get-SecuritySecureScoreReport] An error occurred in running Get-SecuritySecureScoreReport function. $($_.Exception.Message)" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
    }
    finally {
        [GC]::Collect()
        [GC]::WaitForPendingFinalizers()
        Write-ProgressHelper -Total $secureScoreProgressTotal -Id $secureScoreProgressId -Activity "Processing all Security Score Details" -Completed
        $CompletedTime = (((Get-Date) - $start).ToString('hh\:mm\:ss'))
        Write-AssessmentCollectorCompletionBanner -Message "Completed in $($CompletedTime)"
        Write-Log -Type INFO -Message "[Get-SecuritySecureScoreReport] COMPLETED: Gathering Security Score details" -ExportFileLocation $ExportDetails
    }   
}


# Function to check Authentication Methods and SSO Configuration
function Get-AuthenticationConfiguration {
    param (
        [Parameter(Mandatory=$True,HelpMessage='Provide the level of detail')]
        [ValidateSet('minimum', 'operator', 'combined', 'automation', 'all', 'geek')]
        [string]$detailLevel
    )
    
    $start = Get-Date
    # Ensure global hash table structure
    if (-not $script:tenantStatsHash) {
        $script:tenantStatsHash = @{}
    }
    $script:tenantStatsHash["AuthenticationConfig"] = @{}
    $script:tenantStatsHash["AuthenticationConfigSummary"] = @{}
    $script:tenantStatsHash["AuthenticationMethods"] = @{}
    $script:tenantStatsHash["AuthenticationSSOApplications"] = @{}
    $script:tenantStatsHash["EnterpriseApplications"] = @{}
    $script:tenantStatsHash["EnterpriseApplicationSummary"] = @{}
    $script:tenantStatsHash["SecurityDefaultsPolicy"] = @{}
    $script:tenantStatsHash["GuestSignInSummary"] = @{}
    $script:tenantStatsHash["PrivilegedAccessSummary"] = @{}
    
    Write-AssessmentCollectorBanner -Message 'Checking Authentication and SSO Configuration ...' -NoNewline
    Write-Log -Type INFO -Message "[Get-AuthenticationConfiguration] START: Checking Authentication Configuration" -ExportFileLocation $ExportDetails
    
    try {
        $depthPolicy = if ($script:CollectionDepthPolicy) {
            $script:CollectionDepthPolicy
        } else {
            Get-ArrayaCollectionDepthPolicy -ReportingMode ((Get-Culture).TextInfo.ToTitleCase($detailLevel.ToLowerInvariant()))
        }
        $collectSsoAppDetails = ($depthPolicy.CollectSsoApplicationDetails -eq $true)
        $collectExtendedIdentityTierB = ($depthPolicy.CollectExtendedGraphEnrichment -eq $true)

        function Set-AuthenticationConfigurationProperty {
            param(
                [Parameter(Mandatory = $true)]
                [pscustomobject]$TargetObject,
                [Parameter(Mandatory = $true)]
                [string]$Name,
                [Parameter(Mandatory = $false)]
                $Value
            )

            $existingProperty = $TargetObject.PSObject.Properties[$Name]
            if ($null -ne $existingProperty) {
                $existingProperty.Value = $Value
                return
            }

            $TargetObject | Add-Member -NotePropertyName $Name -NotePropertyValue $Value -Force
        }

        function Test-AssessmentAppUsesSso {
            param(
                [Parameter(Mandatory = $false)]
                $ServicePrincipal
            )

            $preferredSingleSignOnMode = $null
            if ($null -ne $ServicePrincipal) {
                if ($ServicePrincipal.PSObject.Properties['preferredSingleSignOnMode']) {
                    $preferredSingleSignOnMode = [string]$ServicePrincipal.preferredSingleSignOnMode
                } elseif ($ServicePrincipal.PSObject.Properties['PreferredSingleSignOnMode']) {
                    $preferredSingleSignOnMode = [string]$ServicePrincipal.PreferredSingleSignOnMode
                }
            }

            return (-not [string]::IsNullOrWhiteSpace($preferredSingleSignOnMode) -and $preferredSingleSignOnMode -ne 'notSupported')
        }

        function Get-AssessmentEnterpriseApplicationIdentityProfile {
            param(
                [Parameter(Mandatory = $false)]
                $ServicePrincipal
            )

            if ($null -eq $ServicePrincipal) {
                return [pscustomobject]@{
                    ServicePrincipalId       = $null
                    DisplayName              = $null
                    AppId                    = $null
                    ServicePrincipalType     = $null
                    PreferredSingleSignOnMode = $null
                    PublisherName            = $null
                }
            }

            return [pscustomobject]@{
                ServicePrincipalId        = $(if ($ServicePrincipal.PSObject.Properties['id']) { [string]$ServicePrincipal.id } elseif ($ServicePrincipal.PSObject.Properties['Id']) { [string]$ServicePrincipal.Id } else { $null })
                DisplayName               = $(if ($ServicePrincipal.PSObject.Properties['displayName']) { [string]$ServicePrincipal.displayName } elseif ($ServicePrincipal.PSObject.Properties['DisplayName']) { [string]$ServicePrincipal.DisplayName } else { $null })
                AppId                     = $(if ($ServicePrincipal.PSObject.Properties['appId']) { [string]$ServicePrincipal.appId } elseif ($ServicePrincipal.PSObject.Properties['AppId']) { [string]$ServicePrincipal.AppId } else { $null })
                ServicePrincipalType      = $(if ($ServicePrincipal.PSObject.Properties['servicePrincipalType']) { [string]$ServicePrincipal.servicePrincipalType } elseif ($ServicePrincipal.PSObject.Properties['ServicePrincipalType']) { [string]$ServicePrincipal.ServicePrincipalType } else { $null })
                PreferredSingleSignOnMode = $(if ($ServicePrincipal.PSObject.Properties['preferredSingleSignOnMode']) { [string]$ServicePrincipal.preferredSingleSignOnMode } elseif ($ServicePrincipal.PSObject.Properties['PreferredSingleSignOnMode']) { [string]$ServicePrincipal.PreferredSingleSignOnMode } else { $null })
                PublisherName             = $(if ($ServicePrincipal.PSObject.Properties['publisherName']) { [string]$ServicePrincipal.publisherName } elseif ($ServicePrincipal.PSObject.Properties['PublisherName']) { [string]$ServicePrincipal.PublisherName } else { $null })
            }
        }

        function Test-AssessmentEnterpriseApplicationValidRow {
            param(
                [Parameter(Mandatory = $false)]
                $ServicePrincipal
            )

            $identityProfile = Get-AssessmentEnterpriseApplicationIdentityProfile -ServicePrincipal $ServicePrincipal
            if ([string]::IsNullOrWhiteSpace([string]$identityProfile.ServicePrincipalId)) {
                return $false
            }

            if (-not [string]::IsNullOrWhiteSpace([string]$identityProfile.AppId)) {
                return $true
            }

            if (-not [string]::IsNullOrWhiteSpace([string]$identityProfile.DisplayName)) {
                return $true
            }

            return (-not [string]::IsNullOrWhiteSpace([string]$identityProfile.PreferredSingleSignOnMode) -and $identityProfile.PreferredSingleSignOnMode -ne 'notSupported')
        }

        function Test-AssessmentEnterpriseApplicationCustomerRelevant {
            param(
                [Parameter(Mandatory = $false)]
                $ServicePrincipal,
                [Parameter(Mandatory = $false)]
                [hashtable]$AdditionalProperties = @{}
            )

            if (-not (Test-AssessmentEnterpriseApplicationValidRow -ServicePrincipal $ServicePrincipal)) {
                return $false
            }

            $identityProfile = Get-AssessmentEnterpriseApplicationIdentityProfile -ServicePrincipal $ServicePrincipal
            if ([string]$identityProfile.ServicePrincipalType -eq 'ManagedIdentity') {
                return $false
            }

            $publisherName = [string]$identityProfile.PublisherName
            $isFirstPartyPublisher = (-not [string]::IsNullOrWhiteSpace($publisherName)) -and ($publisherName -match '(?i)microsoft')

            $usesSso = Test-AssessmentAppUsesSso -ServicePrincipal $ServicePrincipal
            $appRoleAssignmentRequired = $null
            if ($ServicePrincipal.PSObject.Properties['appRoleAssignmentRequired']) {
                $appRoleAssignmentRequired = $ServicePrincipal.appRoleAssignmentRequired
            } elseif ($ServicePrincipal.PSObject.Properties['AppRoleAssignmentRequired']) {
                $appRoleAssignmentRequired = $ServicePrincipal.AppRoleAssignmentRequired
            }

            $appRoleAssignmentRequired = (Convert-ToAssessmentBoolean $appRoleAssignmentRequired)
            $hasDelegatedPermissions = (Convert-ArrayaToNumber $AdditionalProperties['DelegatedPermissionGrantCount']) -gt 0
            $hasApplicationPermissions = (Convert-ArrayaToNumber $AdditionalProperties['ApplicationPermissionCount']) -gt 0
            $hasHighPrivilegePermissions = (Convert-ArrayaToNumber $AdditionalProperties['HighPrivilegePermissionCount']) -gt 0

            $looksLikeCustomerFacingEnterpriseApp =
                (-not [string]::IsNullOrWhiteSpace([string]$identityProfile.AppId)) -and
                (
                    -not [string]::IsNullOrWhiteSpace([string]$identityProfile.DisplayName) -or
                    $usesSso -or
                    $appRoleAssignmentRequired -eq $true
                )

            if ($usesSso -or $appRoleAssignmentRequired -eq $true -or $hasDelegatedPermissions -or $hasApplicationPermissions -or $hasHighPrivilegePermissions) {
                return $true
            }

            if ($isFirstPartyPublisher) {
                return $false
            }

            return $looksLikeCustomerFacingEnterpriseApp
        }

        function Get-AssessmentEnterpriseApplicationStorageKey {
            param(
                [Parameter(Mandatory = $true)]
                [int]$Index,
                [Parameter(Mandatory = $false)]
                [string]$DisplayName,
                [Parameter(Mandatory = $false)]
                [string]$AppId,
                [Parameter(Mandatory = $false)]
                [string]$ServicePrincipalId
            )

            $safeName = if ([string]::IsNullOrWhiteSpace($DisplayName)) {
                'UnnamedApplication'
            } else {
                ($DisplayName -replace '[^a-zA-Z0-9._-]', '_')
            }

            $identifierSource = @($ServicePrincipalId, $AppId, [string]$Index) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | Select-Object -First 1
            $safeIdentifier = ($identifierSource -replace '[^a-zA-Z0-9._-]', '_')
            "{0:D3}-{1}-{2}" -f $Index, $safeName, $safeIdentifier
        }

        $enterpriseApplicationKeyById = @{}
        $enterpriseApplicationSequence = 0

        function Add-AssessmentEnterpriseApplicationRecord {
            param(
                [Parameter(Mandatory = $true)]
                $ServicePrincipal,
                [Parameter(Mandatory = $false)]
                [hashtable]$AdditionalProperties = @{}
            )

            if (-not (Test-AssessmentEnterpriseApplicationCustomerRelevant -ServicePrincipal $ServicePrincipal -AdditionalProperties $AdditionalProperties)) {
                return
            }

            $identityProfile = Get-AssessmentEnterpriseApplicationIdentityProfile -ServicePrincipal $ServicePrincipal
            $servicePrincipalId = $identityProfile.ServicePrincipalId

            if ([string]::IsNullOrWhiteSpace($servicePrincipalId)) {
                return
            }

            $displayName = $identityProfile.DisplayName
            $appId = $identityProfile.AppId
            $preferredSingleSignOnMode = $identityProfile.PreferredSingleSignOnMode

            $storageKey = $null
            if ($enterpriseApplicationKeyById.ContainsKey($servicePrincipalId)) {
                $storageKey = $enterpriseApplicationKeyById[$servicePrincipalId]
            } else {
                $enterpriseApplicationSequence++
                $storageKey = Get-AssessmentEnterpriseApplicationStorageKey -Index $enterpriseApplicationSequence -DisplayName $displayName -AppId $appId -ServicePrincipalId $servicePrincipalId
                $enterpriseApplicationKeyById[$servicePrincipalId] = $storageKey
            }

            $ssoEnabled = Test-AssessmentAppUsesSso -ServicePrincipal $ServicePrincipal
            $existingRecord = if ($script:tenantStatsHash["EnterpriseApplications"].ContainsKey($storageKey)) {
                $script:tenantStatsHash["EnterpriseApplications"][$storageKey]
            } else {
                $null
            }

            $mergedProperties = [ordered]@{
                DisplayName                   = $displayName
                AppId                         = $appId
                ServicePrincipalId            = $servicePrincipalId
                AppRegistrationId             = $null
                ServicePrincipalType          = $(if ($ServicePrincipal.PSObject.Properties['servicePrincipalType']) { $ServicePrincipal.servicePrincipalType } elseif ($ServicePrincipal.PSObject.Properties['ServicePrincipalType']) { $ServicePrincipal.ServicePrincipalType } else { $null })
                AccountEnabled                = $(if ($ServicePrincipal.PSObject.Properties['accountEnabled']) { $ServicePrincipal.accountEnabled } elseif ($ServicePrincipal.PSObject.Properties['AccountEnabled']) { $ServicePrincipal.AccountEnabled } else { $null })
                AppOwnerOrganizationId        = $(if ($ServicePrincipal.PSObject.Properties['appOwnerOrganizationId']) { $ServicePrincipal.appOwnerOrganizationId } elseif ($ServicePrincipal.PSObject.Properties['AppOwnerOrganizationId']) { $ServicePrincipal.AppOwnerOrganizationId } else { $null })
                ApplicationSource             = 'Unknown'
                ApplicationSourceState        = 'Unavailable'
                PreferredSingleSignOnMode     = $preferredSingleSignOnMode
                SsoEnabled                    = $ssoEnabled
                SSOMode                       = $(if ($ssoEnabled) { $preferredSingleSignOnMode } else { $null })
                AppRoleAssignmentRequired     = $(if ($ServicePrincipal.PSObject.Properties['appRoleAssignmentRequired']) { $ServicePrincipal.appRoleAssignmentRequired } elseif ($ServicePrincipal.PSObject.Properties['AppRoleAssignmentRequired']) { $ServicePrincipal.AppRoleAssignmentRequired } else { $null })
                PublisherName                 = $identityProfile.PublisherName
                Tags                          = $(if ($ServicePrincipal.PSObject.Properties['tags']) { @($ServicePrincipal.tags) -join ',' } elseif ($ServicePrincipal.PSObject.Properties['Tags']) { @($ServicePrincipal.Tags) -join ',' } else { $null })
                Owners                        = @()
                OwnersText                    = ''
                OwnerSignalState              = 'Unavailable'
                OwnerCount                    = $null
                RedirectUris                  = @()
                RedirectUrisText              = ''
                RedirectUriSignalState        = 'Unavailable'
                RedirectUriCount              = 0
                InsecureRedirectUriCount      = $null
                HasInsecureRedirectUris       = $null
                AppCredentials                = ''
                KeyCredentialCount            = 0
                PasswordCredentialCount       = 0
                CredentialReviewState         = 'Unavailable'
                CredentialCount               = 0
                HasExpiredCredentials         = $null
                ExpiredCredentialCount        = $null
                ExpiredKeyCredentialCount     = $null
                ExpiredPasswordCredentialCount = $null
                HasCredentialsExpiringSoon    = $null
                ExpiringCredentialCount       = $null
                ExpiringKeyCredentialCount    = $null
                ExpiringPasswordCredentialCount = $null
                NextCredentialExpiryDateTime  = $null
                LatestCredentialExpiryDateTime = $null
                CredentialIssueSummary        = ''
                SignInAudience                = $null
                ApplicationCreatedDateTime    = $null
                DelegatedPermissionScopes     = ''
                DelegatedPermissionGrantCount = 0
                ApplicationPermissions        = ''
                ApplicationPermissionCount    = 0
                HighPrivilegePermissionCount  = 0
                HighPrivilegePermissions      = ''
                ActivitySignalState           = 'Unavailable'
                DelegatedLastSignIn           = $null
                ApplicationLastSignIn         = $null
                LastSignInType                = $null
                LastServicePrincipalSignInDateTime = $null
                HasRecentActivity             = $null
            }

            if ($null -ne $existingRecord) {
                foreach ($property in @($existingRecord.PSObject.Properties)) {
                    if (-not $mergedProperties.Contains($property.Name)) {
                        $mergedProperties[$property.Name] = $property.Value
                    } elseif ($null -eq $mergedProperties[$property.Name] -or [string]::IsNullOrWhiteSpace([string]$mergedProperties[$property.Name])) {
                        $mergedProperties[$property.Name] = $property.Value
                    }
                }
            }

            foreach ($key in @($AdditionalProperties.Keys)) {
                $mergedProperties[$key] = $AdditionalProperties[$key]
            }

            $script:tenantStatsHash["EnterpriseApplications"][$storageKey] = [pscustomobject]$mergedProperties
        }

        function Test-AssessmentEnterpriseApplicationResolvedSignInValue {
            param(
                [Parameter(Mandatory = $false)]
                [AllowNull()]
                $Value
            )

            $text = [string]$Value
            return (
                -not [string]::IsNullOrWhiteSpace($text) -and
                $text -ne 'No sign-ins found' -and
                $text -notlike 'Latest sign-in not resolved*'
            )
        }

        function Test-AssessmentEnterpriseApplicationUnresolvedSignInValue {
            param(
                [Parameter(Mandatory = $false)]
                [AllowNull()]
                $Value
            )

            $text = [string]$Value
            return (-not [string]::IsNullOrWhiteSpace($text) -and $text -like 'Latest sign-in not resolved*')
        }

        function Get-AssessmentEnterpriseApplicationLatestSignInMap {
            param(
                [Parameter(Mandatory = $true)]
                [object[]]$ServicePrincipals,
                [Parameter(Mandatory = $false)]
                [int]$ChunkSize = 12,
                [Parameter(Mandatory = $false)]
                [int]$PageSize = 25,
                [Parameter(Mandatory = $false)]
                [int]$MaxPagesPerChunk = 8
            )

            $signInMap = @{}
            $appProfileLookup = @{}
            foreach ($servicePrincipal in @($ServicePrincipals)) {
                $identityProfile = Get-AssessmentEnterpriseApplicationIdentityProfile -ServicePrincipal $servicePrincipal
                $appId = [string]$identityProfile.AppId
                if ([string]::IsNullOrWhiteSpace($appId) -or $appProfileLookup.ContainsKey($appId)) {
                    continue
                }

                $appProfileLookup[$appId] = [pscustomobject]@{
                    DisplayName = [string]$identityProfile.DisplayName
                }
            }

            $allAppIds = @($appProfileLookup.Keys | Sort-Object)
            if ($allAppIds.Count -eq 0) {
                return $signInMap
            }

            $truncatedAppIds = New-Object System.Collections.Generic.HashSet[string]
            for ($index = 0; $index -lt $allAppIds.Count; $index += $ChunkSize) {
                $chunkEndIndex = [Math]::Min(($index + $ChunkSize - 1), ($allAppIds.Count - 1))
                $chunkAppIds = @($allAppIds[$index..$chunkEndIndex])
                $pendingAppIds = New-Object 'System.Collections.Generic.HashSet[string]'
                foreach ($chunkAppId in $chunkAppIds) {
                    [void]$pendingAppIds.Add([string]$chunkAppId)
                }

                $filterExpression = @(
                    $chunkAppIds |
                        ForEach-Object { "appId eq '{0}'" -f (([string]$_).Replace("'", "''")) }
                ) -join ' or '
                $pageUri = "https://graph.microsoft.com/v1.0/auditLogs/signIns?`$filter=$([System.Uri]::EscapeDataString($filterExpression))&`$orderby=createdDateTime desc&`$top=$PageSize&`$select=createdDateTime,userDisplayName,userPrincipalName,conditionalAccessStatus,clientAppUsed,appDisplayName,appId"
                $pageCount = 0

                while ($pageUri -and $pendingAppIds.Count -gt 0 -and $pageCount -lt $MaxPagesPerChunk) {
                    $response = Invoke-QuietRestMethod -Parameters @{
                        Uri         = $pageUri
                        Headers     = $global:GraphHeaders
                        Method      = 'Get'
                        ContentType = 'application/json'
                        ErrorAction = 'Stop'
                    }

                    $signInRows = @()
                    if ($response) {
                        if ($response.PSObject.Properties['value']) {
                            $signInRows = @($response.value)
                        }
                        else {
                            $signInRows = @($response)
                        }
                    }

                    foreach ($signInRow in @($signInRows)) {
                        $signInAppId = [string](Get-ArrayaObjectValue -Object $signInRow -Names @('appId', 'AppId'))
                        if ([string]::IsNullOrWhiteSpace($signInAppId) -or -not $pendingAppIds.Contains($signInAppId)) {
                            continue
                        }

                        $signInMap[$signInAppId] = [pscustomobject]@{
                            LastSignInDateTime          = $(if ($signInRow.PSObject.Properties['createdDateTime']) { $signInRow.createdDateTime } elseif ($signInRow.PSObject.Properties['CreatedDateTime']) { $signInRow.CreatedDateTime } else { $null })
                            LastSignInUserDisplayName   = $(if ($signInRow.PSObject.Properties['userDisplayName']) { [string]$signInRow.userDisplayName } elseif ($signInRow.PSObject.Properties['UserDisplayName']) { [string]$signInRow.UserDisplayName } else { $null })
                            LastSignInUserPrincipalName = $(if ($signInRow.PSObject.Properties['userPrincipalName']) { [string]$signInRow.userPrincipalName } elseif ($signInRow.PSObject.Properties['UserPrincipalName']) { [string]$signInRow.UserPrincipalName } else { $null })
                            LastConditionalAccessStatus = $(if ($signInRow.PSObject.Properties['conditionalAccessStatus']) { [string]$signInRow.conditionalAccessStatus } elseif ($signInRow.PSObject.Properties['ConditionalAccessStatus']) { [string]$signInRow.ConditionalAccessStatus } else { $null })
                            LastClientAppUsed           = $(if ($signInRow.PSObject.Properties['clientAppUsed']) { [string]$signInRow.clientAppUsed } elseif ($signInRow.PSObject.Properties['ClientAppUsed']) { [string]$signInRow.ClientAppUsed } else { $null })
                        }
                        [void]$pendingAppIds.Remove($signInAppId)
                    }

                    $pageCount++
                    $pageUri = if ($response -and $response.PSObject.Properties['@odata.nextLink'] -and -not [string]::IsNullOrWhiteSpace([string]$response.'@odata.nextLink')) {
                        [string]$response.'@odata.nextLink'
                    }
                    else {
                        $null
                    }
                }

                if ($pendingAppIds.Count -gt 0 -and $pageCount -ge $MaxPagesPerChunk) {
                    foreach ($pendingAppId in $pendingAppIds) {
                        [void]$truncatedAppIds.Add([string]$pendingAppId)
                    }
                }
            }

            foreach ($appId in $allAppIds) {
                if ($signInMap.ContainsKey($appId)) {
                    continue
                }

                $signInMap[$appId] = [pscustomobject]@{
                    LastSignInDateTime          = $(if ($truncatedAppIds.Contains($appId)) { 'Latest sign-in not resolved from reviewed sign-in history' } else { 'No sign-ins found' })
                    LastSignInUserDisplayName   = $null
                    LastSignInUserPrincipalName = $null
                    LastConditionalAccessStatus = $null
                    LastClientAppUsed           = $null
                }
            }

            if ($truncatedAppIds.Count -gt 0) {
                $sampleApplications = @(
                    $truncatedAppIds |
                        ForEach-Object { if ($appProfileLookup.ContainsKey($_)) { [string]$appProfileLookup[$_].DisplayName } } |
                        Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
                        Sort-Object -Unique |
                        Select-Object -First 5
                )
                Write-Log -Type WARNING -Message "[Get-AuthenticationConfiguration] Some enterprise application sign-in lookups exceeded the reviewed sign-in history window. Those applications will note that the latest sign-in was not fully resolved. Examples: $($sampleApplications -join ', ')" -ExportFileLocation $ExportDetails
            }

            return $signInMap
        }

        function Test-AssessmentEnterpriseApplicationInsecureRedirectUri {
            param(
                [Parameter(Mandatory = $false)]
                [AllowNull()]
                [string]$Uri
            )

            if ([string]::IsNullOrWhiteSpace($Uri)) {
                return $false
            }

            return (
                $Uri -match '^https?://localhost([:/]|$)' -or
                $Uri -match '^https?://127\.0\.0\.1([:/]|$)' -or
                $Uri -match '^https?://\[::1\]([:/]|$)' -or
                $Uri -match '^https?://\*\.' -or
                $Uri -match '://\*/' -or
                $Uri -match '^https?://.*\.azurewebsites\.net([/?#:]|$)' -or
                $Uri -match '^https?://(bit\.ly|tinyurl\.com|t\.co|goo\.gl|ow\.ly|short\.link|tiny\.cc)([/?#]|$)' -or
                $Uri -match '^http://(?!localhost([:/]|$)|127\.0\.0\.1([:/]|$)|\[::1\]([:/]|$))'
            )
        }

        function Get-AssessmentEnterpriseApplicationCredentialMetadata {
            param(
                [Parameter(Mandatory = $false)]
                $ApplicationRow,
                [Parameter(Mandatory = $false)]
                [int]$ExpiringWithinDays = 30
            )

            $now = Get-Date
            $expiringThreshold = $now.AddDays($ExpiringWithinDays)
            $credentialRows = New-Object System.Collections.Generic.List[object]

            foreach ($keyCredential in @((Get-ArrayaObjectValue -Object $ApplicationRow -Names @('keyCredentials', 'KeyCredentials')))) {
                $endDateTime = Convert-ArrayaToDate (Get-ArrayaObjectValue -Object $keyCredential -Names @('endDateTime', 'EndDateTime'))
                $credentialRows.Add([pscustomobject]@{
                    CredentialType = 'Client Certificate'
                    EndDateTime    = $endDateTime
                    IsExpired      = ($null -ne $endDateTime -and $endDateTime -lt $now)
                    IsExpiringSoon = ($null -ne $endDateTime -and $endDateTime -ge $now -and $endDateTime -le $expiringThreshold)
                }) | Out-Null
            }

            foreach ($passwordCredential in @((Get-ArrayaObjectValue -Object $ApplicationRow -Names @('passwordCredentials', 'PasswordCredentials')))) {
                $endDateTime = Convert-ArrayaToDate (Get-ArrayaObjectValue -Object $passwordCredential -Names @('endDateTime', 'EndDateTime'))
                $credentialRows.Add([pscustomobject]@{
                    CredentialType = 'Client Secret'
                    EndDateTime    = $endDateTime
                    IsExpired      = ($null -ne $endDateTime -and $endDateTime -lt $now)
                    IsExpiringSoon = ($null -ne $endDateTime -and $endDateTime -ge $now -and $endDateTime -le $expiringThreshold)
                }) | Out-Null
            }

            $expiredRows = @($credentialRows | Where-Object { $_.IsExpired -eq $true })
            $expiringRows = @($credentialRows | Where-Object { $_.IsExpiringSoon -eq $true })
            $datedRows = @($credentialRows | Where-Object { $null -ne $_.EndDateTime })
            $futureDatedRows = @($datedRows | Where-Object { $_.EndDateTime -ge $now })

            $expiredSecretCount = @($expiredRows | Where-Object { $_.CredentialType -eq 'Client Secret' }).Count
            $expiredCertificateCount = @($expiredRows | Where-Object { $_.CredentialType -eq 'Client Certificate' }).Count
            $expiringSecretCount = @($expiringRows | Where-Object { $_.CredentialType -eq 'Client Secret' }).Count
            $expiringCertificateCount = @($expiringRows | Where-Object { $_.CredentialType -eq 'Client Certificate' }).Count
            $summarySegments = New-Object System.Collections.Generic.List[string]

            if ($expiredSecretCount -gt 0) {
                $summarySegments.Add(("{0} expired client secret{1}" -f $expiredSecretCount, $(if ($expiredSecretCount -eq 1) { '' } else { 's' }))) | Out-Null
            }
            if ($expiredCertificateCount -gt 0) {
                $summarySegments.Add(("{0} expired client certificate{1}" -f $expiredCertificateCount, $(if ($expiredCertificateCount -eq 1) { '' } else { 's' }))) | Out-Null
            }
            if ($expiringSecretCount -gt 0) {
                $summarySegments.Add(("{0} client secret{1} expiring within {2} days" -f $expiringSecretCount, $(if ($expiringSecretCount -eq 1) { '' } else { 's' }), $ExpiringWithinDays)) | Out-Null
            }
            if ($expiringCertificateCount -gt 0) {
                $summarySegments.Add(("{0} client certificate{1} expiring within {2} days" -f $expiringCertificateCount, $(if ($expiringCertificateCount -eq 1) { '' } else { 's' }), $ExpiringWithinDays)) | Out-Null
            }

            return [pscustomobject]@{
                CredentialReviewState             = 'Collected'
                CredentialCount                   = $credentialRows.Count
                HasExpiredCredentials             = ($expiredRows.Count -gt 0)
                ExpiredCredentialCount            = $expiredRows.Count
                ExpiredKeyCredentialCount         = $expiredCertificateCount
                ExpiredPasswordCredentialCount    = $expiredSecretCount
                HasCredentialsExpiringSoon        = ($expiringRows.Count -gt 0)
                ExpiringCredentialCount           = $expiringRows.Count
                ExpiringKeyCredentialCount        = $expiringCertificateCount
                ExpiringPasswordCredentialCount   = $expiringSecretCount
                NextCredentialExpiryDateTime      = $(if ($futureDatedRows.Count -gt 0) { @($futureDatedRows | Sort-Object EndDateTime | Select-Object -First 1)[0].EndDateTime } else { $null })
                LatestCredentialExpiryDateTime    = $(if ($datedRows.Count -gt 0) { @($datedRows | Sort-Object EndDateTime -Descending | Select-Object -First 1)[0].EndDateTime } else { $null })
                CredentialIssueSummary            = (@($summarySegments.ToArray()) -join '; ')
            }
        }

        function Get-AssessmentEnterpriseApplicationAppRegistrationMap {
            param(
                [Parameter(Mandatory = $true)]
                [object[]]$ServicePrincipals
            )

            $appRegistrationMap = @{}
            $requestedAppIds = New-Object 'System.Collections.Generic.HashSet[string]'
            foreach ($servicePrincipal in @($ServicePrincipals)) {
                $identityProfile = Get-AssessmentEnterpriseApplicationIdentityProfile -ServicePrincipal $servicePrincipal
                $appId = [string]$identityProfile.AppId
                if (-not [string]::IsNullOrWhiteSpace($appId)) {
                    [void]$requestedAppIds.Add($appId)
                }
            }

            if ($requestedAppIds.Count -eq 0) {
                return $appRegistrationMap
            }

            $applicationRows = @(
                Get-ArrayaGraphResource `
                    -Uri "https://graph.microsoft.com/v1.0/applications?`$select=id,appId,createdDateTime,signInAudience,keyCredentials,passwordCredentials,publicClient,web,spa,isFallbackPublicClient&`$top=250" `
                    -Activity 'Enterprise application registrations' `
                    -Headers $global:GraphHeaders `
                    -SuppressProgress
            )

            foreach ($applicationRow in @($applicationRows)) {
                $appId = [string](Get-ArrayaObjectValue -Object $applicationRow -Names @('appId', 'AppId'))
                if ([string]::IsNullOrWhiteSpace($appId) -or -not $requestedAppIds.Contains($appId)) {
                    continue
                }

                $ownerRows = @()
                $ownerSignalState = 'Unavailable'
                $applicationObjectId = [string](Get-ArrayaObjectValue -Object $applicationRow -Names @('id', 'Id'))
                if (-not [string]::IsNullOrWhiteSpace($applicationObjectId)) {
                    try {
                        $ownerRows = @(
                            Get-ArrayaGraphResource `
                                -Uri ("https://graph.microsoft.com/v1.0/applications/{0}/owners?`$select=id,displayName,userPrincipalName,mail&`$top=100" -f $applicationObjectId) `
                                -Activity "Enterprise application owners [$appId]" `
                                -Headers $global:GraphHeaders `
                                -SuppressProgress `
                                -SuppressAccessDeniedWarning
                        )
                        $ownerSignalState = 'Collected'
                    }
                    catch {
                        Write-Log -Type DEBUG -Message "[Get-AuthenticationConfiguration] Owner lookup failed for application '$appId': $($_.Exception.Message)" -ExportFileLocation $ExportDetails
                    }
                }

                $ownerValues = New-Object System.Collections.Generic.List[string]
                foreach ($ownerRow in @($ownerRows)) {
                    $ownerValue = @(
                        [string](Get-ArrayaObjectValue -Object $ownerRow -Names @('userPrincipalName', 'UserPrincipalName')),
                        [string](Get-ArrayaObjectValue -Object $ownerRow -Names @('mail', 'Mail')),
                        [string](Get-ArrayaObjectValue -Object $ownerRow -Names @('displayName', 'DisplayName')),
                        [string](Get-ArrayaObjectValue -Object $ownerRow -Names @('id', 'Id'))
                    ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1

                    if (-not [string]::IsNullOrWhiteSpace($ownerValue) -and -not $ownerValues.Contains($ownerValue)) {
                        $ownerValues.Add($ownerValue) | Out-Null
                    }
                }

                $redirectUris = New-Object System.Collections.Generic.List[string]
                foreach ($redirectContainerName in @('publicClient', 'web', 'spa')) {
                    $redirectContainer = $null
                    if ($applicationRow.PSObject.Properties[$redirectContainerName]) {
                        $redirectContainer = $applicationRow.$redirectContainerName
                    }
                    elseif ($applicationRow.PSObject.Properties[([string]([char]::ToUpper($redirectContainerName[0])) + $redirectContainerName.Substring(1))]) {
                        $redirectContainer = $applicationRow.([string]([char]::ToUpper($redirectContainerName[0])) + $redirectContainerName.Substring(1))
                    }

                    if ($null -eq $redirectContainer) {
                        continue
                    }

                    $candidateUris = @()
                    if ($redirectContainer.PSObject.Properties['redirectUris']) {
                        $candidateUris = @($redirectContainer.redirectUris)
                    }
                    elseif ($redirectContainer.PSObject.Properties['RedirectUris']) {
                        $candidateUris = @($redirectContainer.RedirectUris)
                    }

                    foreach ($candidateUri in @($candidateUris)) {
                        $candidateUriText = [string]$candidateUri
                        if (-not [string]::IsNullOrWhiteSpace($candidateUriText) -and -not $redirectUris.Contains($candidateUriText)) {
                            $redirectUris.Add($candidateUriText) | Out-Null
                        }
                    }
                }

                $credentialTypes = New-Object System.Collections.Generic.List[string]
                $keyCredentialCount = @((Get-ArrayaObjectValue -Object $applicationRow -Names @('keyCredentials', 'KeyCredentials'))).Count
                $passwordCredentialCount = @((Get-ArrayaObjectValue -Object $applicationRow -Names @('passwordCredentials', 'PasswordCredentials'))).Count
                if ($keyCredentialCount -gt 0) {
                    $credentialTypes.Add('Client Certificate') | Out-Null
                }
                if ($passwordCredentialCount -gt 0) {
                    $credentialTypes.Add('Client Secret') | Out-Null
                }

                $credentialMetadata = Get-AssessmentEnterpriseApplicationCredentialMetadata -ApplicationRow $applicationRow

                $appRegistrationMap[$appId] = [pscustomobject]@{
                    AppRegistrationId          = $applicationObjectId
                    Owners                     = @($ownerValues.ToArray())
                    OwnersText                 = (@($ownerValues.ToArray()) -join ', ')
                    OwnerSignalState           = $ownerSignalState
                    OwnerCount                 = $(if ($ownerSignalState -eq 'Collected') { $ownerValues.Count } else { $null })
                    RedirectUris               = @($redirectUris.ToArray())
                    RedirectUrisText           = (@($redirectUris.ToArray()) -join ', ')
                    AppCredentials             = (@($credentialTypes.ToArray()) -join ', ')
                    KeyCredentialCount         = $keyCredentialCount
                    PasswordCredentialCount    = $passwordCredentialCount
                    CredentialReviewState      = $credentialMetadata.CredentialReviewState
                    CredentialCount            = $credentialMetadata.CredentialCount
                    HasExpiredCredentials      = $credentialMetadata.HasExpiredCredentials
                    ExpiredCredentialCount     = $credentialMetadata.ExpiredCredentialCount
                    ExpiredKeyCredentialCount  = $credentialMetadata.ExpiredKeyCredentialCount
                    ExpiredPasswordCredentialCount = $credentialMetadata.ExpiredPasswordCredentialCount
                    HasCredentialsExpiringSoon = $credentialMetadata.HasCredentialsExpiringSoon
                    ExpiringCredentialCount    = $credentialMetadata.ExpiringCredentialCount
                    ExpiringKeyCredentialCount = $credentialMetadata.ExpiringKeyCredentialCount
                    ExpiringPasswordCredentialCount = $credentialMetadata.ExpiringPasswordCredentialCount
                    NextCredentialExpiryDateTime = $credentialMetadata.NextCredentialExpiryDateTime
                    LatestCredentialExpiryDateTime = $credentialMetadata.LatestCredentialExpiryDateTime
                    CredentialIssueSummary     = $credentialMetadata.CredentialIssueSummary
                    SignInAudience             = Get-ArrayaObjectValue -Object $applicationRow -Names @('signInAudience', 'SignInAudience')
                    ApplicationCreatedDateTime = Get-ArrayaObjectValue -Object $applicationRow -Names @('createdDateTime', 'CreatedDateTime')
                }
            }

            return $appRegistrationMap
        }

        function Get-AssessmentEnterpriseApplicationServicePrincipalActivityMap {
            param(
                [Parameter(Mandatory = $true)]
                [object[]]$ServicePrincipals
            )

            $activityMap = @{}
            $requestedAppIds = New-Object 'System.Collections.Generic.HashSet[string]'
            foreach ($servicePrincipal in @($ServicePrincipals)) {
                $identityProfile = Get-AssessmentEnterpriseApplicationIdentityProfile -ServicePrincipal $servicePrincipal
                $appId = [string]$identityProfile.AppId
                if (-not [string]::IsNullOrWhiteSpace($appId)) {
                    [void]$requestedAppIds.Add($appId)
                }
            }

            if ($requestedAppIds.Count -eq 0) {
                return $activityMap
            }

            $activityRows = @(
                Get-ArrayaGraphResource `
                    -Uri "https://graph.microsoft.com/beta/reports/servicePrincipalSignInActivities?`$top=250" `
                    -Activity 'Enterprise application service principal sign-in activities (beta best-effort)' `
                    -Headers $global:GraphHeaders `
                    -SuppressProgress `
                    -SuppressAccessDeniedWarning
            )

            foreach ($activityRow in @($activityRows)) {
                $appId = [string](Get-ArrayaObjectValue -Object $activityRow -Names @('appId', 'AppId'))
                if ([string]::IsNullOrWhiteSpace($appId) -or -not $requestedAppIds.Contains($appId)) {
                    continue
                }

                $delegatedActivity = Get-ArrayaObjectValue -Object $activityRow -Names @('delegatedClientSignInActivity', 'DelegatedClientSignInActivity')
                $applicationActivity = Get-ArrayaObjectValue -Object $activityRow -Names @('applicationAuthenticationClientSignInActivity', 'ApplicationAuthenticationClientSignInActivity')
                $activityMap[$appId] = [pscustomobject]@{
                    DelegatedLastSignIn   = $(if ($delegatedActivity) { Get-ArrayaObjectValue -Object $delegatedActivity -Names @('lastSignInDateTime', 'LastSignInDateTime') } else { $null })
                    ApplicationLastSignIn = $(if ($applicationActivity) { Get-ArrayaObjectValue -Object $applicationActivity -Names @('lastSignInDateTime', 'LastSignInDateTime') } else { $null })
                }
            }

            return $activityMap
        }

        function Get-AssessmentEnterpriseApplicationLatestServicePrincipalSignInMap {
            param(
                [Parameter(Mandatory = $true)]
                [object[]]$ServicePrincipals,
                [Parameter(Mandatory = $false)]
                [int]$ChunkSize = 10,
                [Parameter(Mandatory = $false)]
                [int]$PageSize = 25,
                [Parameter(Mandatory = $false)]
                [int]$MaxPagesPerChunk = 6
            )

            $signInMap = @{}
            $appProfileLookup = @{}
            foreach ($servicePrincipal in @($ServicePrincipals)) {
                $identityProfile = Get-AssessmentEnterpriseApplicationIdentityProfile -ServicePrincipal $servicePrincipal
                $appId = [string]$identityProfile.AppId
                if ([string]::IsNullOrWhiteSpace($appId) -or $appProfileLookup.ContainsKey($appId)) {
                    continue
                }

                $appProfileLookup[$appId] = [pscustomobject]@{
                    DisplayName = [string]$identityProfile.DisplayName
                }
            }

            $allAppIds = @($appProfileLookup.Keys | Sort-Object)

            if ($allAppIds.Count -eq 0) {
                return $signInMap
            }

            $truncatedAppIds = New-Object System.Collections.Generic.HashSet[string]
            for ($index = 0; $index -lt $allAppIds.Count; $index += $ChunkSize) {
                $chunkEndIndex = [Math]::Min(($index + $ChunkSize - 1), ($allAppIds.Count - 1))
                $chunkAppIds = @($allAppIds[$index..$chunkEndIndex])
                $pendingAppIds = New-Object 'System.Collections.Generic.HashSet[string]'
                foreach ($chunkAppId in $chunkAppIds) {
                    [void]$pendingAppIds.Add([string]$chunkAppId)
                }

                $filterExpression = @(
                    $chunkAppIds |
                        ForEach-Object { "appId eq '{0}'" -f (([string]$_).Replace("'", "''")) }
                ) -join ' or '
                $pageUri = "https://graph.microsoft.com/beta/auditLogs/signIns?source=sp&`$filter=$([System.Uri]::EscapeDataString($filterExpression))&`$orderby=createdDateTime desc&`$top=$PageSize&`$select=createdDateTime,appId,clientCredentialType"
                $pageCount = 0

                while ($pageUri -and $pendingAppIds.Count -gt 0 -and $pageCount -lt $MaxPagesPerChunk) {
                    $response = Invoke-QuietRestMethod -Parameters @{
                        Uri         = $pageUri
                        Headers     = $global:GraphHeaders
                        Method      = 'Get'
                        ContentType = 'application/json'
                        ErrorAction = 'Stop'
                    }

                    $signInRows = @()
                    if ($response) {
                        if ($response.PSObject.Properties['value']) {
                            $signInRows = @($response.value)
                        }
                        else {
                            $signInRows = @($response)
                        }
                    }

                    foreach ($signInRow in @($signInRows)) {
                        $signInAppId = [string](Get-ArrayaObjectValue -Object $signInRow -Names @('appId', 'AppId'))
                        if ([string]::IsNullOrWhiteSpace($signInAppId) -or -not $pendingAppIds.Contains($signInAppId)) {
                            continue
                        }

                        $signInMap[$signInAppId] = [pscustomobject]@{
                            LastServicePrincipalSignInDateTime = Get-ArrayaObjectValue -Object $signInRow -Names @('createdDateTime', 'CreatedDateTime')
                            LastSignInType                     = [string](Get-ArrayaObjectValue -Object $signInRow -Names @('clientCredentialType', 'ClientCredentialType'))
                        }
                        [void]$pendingAppIds.Remove($signInAppId)
                    }

                    $pageCount++
                    $pageUri = if ($response -and $response.PSObject.Properties['@odata.nextLink'] -and -not [string]::IsNullOrWhiteSpace([string]$response.'@odata.nextLink')) {
                        [string]$response.'@odata.nextLink'
                    }
                    else {
                        $null
                    }
                }

                if ($pendingAppIds.Count -gt 0 -and $pageCount -ge $MaxPagesPerChunk) {
                    foreach ($pendingAppId in $pendingAppIds) {
                        [void]$truncatedAppIds.Add([string]$pendingAppId)
                    }
                }
            }

            foreach ($appId in $allAppIds) {
                if ($signInMap.ContainsKey($appId)) {
                    continue
                }

                $signInMap[$appId] = [pscustomobject]@{
                    LastServicePrincipalSignInDateTime = $(if ($truncatedAppIds.Contains($appId)) { 'Latest sign-in not resolved from reviewed sign-in history' } else { 'No sign-ins found' })
                    LastSignInType                     = $null
                }
            }

            if ($truncatedAppIds.Count -gt 0) {
                $sampleApplications = @(
                    $truncatedAppIds |
                        ForEach-Object { if ($appProfileLookup.ContainsKey($_)) { [string]$appProfileLookup[$_].DisplayName } } |
                        Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
                        Sort-Object -Unique |
                        Select-Object -First 5
                )
                Write-Log -Type WARNING -Message "[Get-AuthenticationConfiguration] Some enterprise application service principal sign-in lookups exceeded the reviewed sign-in history window. Those applications will note that the latest sign-in was not fully resolved. Examples: $($sampleApplications -join ', ')" -ExportFileLocation $ExportDetails
            }

            return $signInMap
        }

        $servicePrincipals = @()
        if ($collectSsoAppDetails -or $collectExtendedIdentityTierB) {
            try {
                $servicePrincipals = @(
                    Get-ArrayaGraphResource `
                        -Uri "https://graph.microsoft.com/v1.0/servicePrincipals?`$select=id,displayName,appId,servicePrincipalType,accountEnabled,preferredSingleSignOnMode,tags,appRoleAssignmentRequired,publisherName,appOwnerOrganizationId,replyUrls&`$top=250" `
                        -Activity 'Enterprise applications inventory' `
                        -Headers $global:GraphHeaders
                )
            } catch {
                Write-Log -Type WARNING -Message "[Get-AuthenticationConfiguration] Unable to retrieve base enterprise application inventory: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
            }
        }

        foreach ($servicePrincipal in @($servicePrincipals)) {
            Add-AssessmentEnterpriseApplicationRecord -ServicePrincipal $servicePrincipal
        }
        
        # Get authentication methods policy
        $authMethodsPolicy = [PSCustomObject]@{
            MFAEnabled = $false
            MFAMethods = @()
            SSOEnabled = $false
            SSOApplications = @()
            FederatedDomains = @()
            PasswordlessMethods = @()
            DefaultUserCanCreateApps = $null
            SelfServicePasswordResetEnabled = $null
            PermissionGrantPoliciesAssigned = @()
            AdminConsentWorkflowEnabled = $null
            AdminConsentWorkflowReviewerCount = 0
        }
        
        # Check for federated domains (indicates SSO)
        $domains = $script:tenantStatsHash["Domains"].Values
        $federatedDomains = $domains | Where-Object {$_.AuthenticationType -eq "Federated"}
        
        if ($federatedDomains) {
            $authMethodsPolicy.SSOEnabled = $true
            $authMethodsPolicy.FederatedDomains = $federatedDomains.Domain
            Write-Log -Type INFO -Message "[Get-AuthenticationConfiguration] Found $($federatedDomains.Count) federated domains" -ExportFileLocation $ExportDetails
        }
        
        # Get Enterprise Applications configured for SSO
        if ($collectSsoAppDetails) {
            try {
                Write-Log -Type INFO -Message "[Get-AuthenticationConfiguration] Checking Enterprise Applications for SSO" -ExportFileLocation $ExportDetails

                $ssoAppDetails = New-Object System.Collections.Generic.List[object]
                foreach ($app in @($servicePrincipals | Where-Object { (Test-AssessmentEnterpriseApplicationCustomerRelevant -ServicePrincipal $_) -and (Test-AssessmentAppUsesSso -ServicePrincipal $_) })) {
                    $preferredSingleSignOnMode = if ($app.PSObject.Properties['preferredSingleSignOnMode']) {
                        [string]$app.preferredSingleSignOnMode
                    } elseif ($app.PSObject.Properties['PreferredSingleSignOnMode']) {
                        [string]$app.PreferredSingleSignOnMode
                    } else {
                        $null
                    }

                    if ([string]::IsNullOrWhiteSpace($preferredSingleSignOnMode)) {
                        continue
                    }

                    $ssoAppDetails.Add([PSCustomObject]@{
                        DisplayName = $(if ($app.PSObject.Properties['displayName']) { $app.displayName } else { $app.DisplayName })
                        AppId = $(if ($app.PSObject.Properties['appId']) { $app.appId } else { $app.AppId })
                        ServicePrincipalId = $(if ($app.PSObject.Properties['id']) { $app.id } else { $app.Id })
                        SSOMode = $preferredSingleSignOnMode
                        PreferredSingleSignOnMode = $preferredSingleSignOnMode
                        SsoEnabled = $true
                        ServicePrincipalType = $(if ($app.PSObject.Properties['servicePrincipalType']) { $app.servicePrincipalType } else { $app.ServicePrincipalType })
                        AccountEnabled = $(if ($app.PSObject.Properties['accountEnabled']) { $app.accountEnabled } else { $app.AccountEnabled })
                        AppRoleAssignmentRequired = $(if ($app.PSObject.Properties['appRoleAssignmentRequired']) { $app.appRoleAssignmentRequired } else { $app.AppRoleAssignmentRequired })
                        PublisherName = $(if ($app.PSObject.Properties['publisherName']) { $app.publisherName } else { $app.PublisherName })
                    })
                }

                if ($ssoAppDetails.Count -gt 0) {
                    $authMethodsPolicy.SSOEnabled = $true
                    $authMethodsPolicy.SSOApplications = $ssoAppDetails.ToArray()
                    Write-Log -Type INFO -Message "[Get-AuthenticationConfiguration] Found $($ssoAppDetails.Count) SSO-enabled applications" -ExportFileLocation $ExportDetails
                }
                
            } catch {
                Write-Log -Type WARNING -Message "[Get-AuthenticationConfiguration] Unable to retrieve SSO applications: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
            }
        } else {
            Write-Log -Type INFO -Message "[Get-AuthenticationConfiguration] Skipping detailed SSO application inventory in minimum reporting mode." -ExportFileLocation $ExportDetails
        }
        
        # Check MFA/Authentication methods policies
        try {
            $authMethodsPolicyUri = "https://graph.microsoft.com/v1.0/policies/authenticationMethodsPolicy"
            $authPolicyData = Get-ArrayaGraphResource -Uri $authMethodsPolicyUri -Activity "Fetching Authentication Methods Policy"
            
            if ($authPolicyData) {
                # Extract enabled authentication methods
                foreach ($method in $authPolicyData.authenticationMethodConfigurations) {
                    if ($method.state -eq "enabled") {
                        $authMethodsPolicy.MFAMethods += $method.'@odata.type'.Replace('#microsoft.graph.', '')
                        
                        # Check for passwordless methods
                        if ($method.'@odata.type' -match "(fido2|windowsHello|microsoftAuthenticator)") {
                            $authMethodsPolicy.PasswordlessMethods += $method.'@odata.type'.Replace('#microsoft.graph.', '')
                        }
                    }
                }
                
                if ($authMethodsPolicy.MFAMethods.Count -gt 0) {
                    $authMethodsPolicy.MFAEnabled = $true
                    Write-Log -Type INFO -Message "[Get-AuthenticationConfiguration] MFA is enabled with $($authMethodsPolicy.MFAMethods.Count) methods" -ExportFileLocation $ExportDetails
                }
            }
            
        } catch {
            Write-Log -Type WARNING -Message "[Get-AuthenticationConfiguration] Unable to retrieve authentication methods policy: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }
        
        # Check Conditional Access policies for MFA requirements
        if ($script:tenantStatsHash["ConditionalAccessPolicies"]) {
            $mfaPolicies = $script:tenantStatsHash["ConditionalAccessPolicies"].Values | 
                Where-Object { Test-AssessmentConditionalAccessRequiresMfa -Policy $_ }
            
            if ($mfaPolicies) {
                $authMethodsPolicy.MFAEnabled = $true
                $authMethodsPolicy | Add-Member -MemberType NoteProperty -Name "MFAConditionalAccessPolicies" -Value $mfaPolicies.Count
                Write-Log -Type INFO -Message "[Get-AuthenticationConfiguration] Found $($mfaPolicies.Count) CA policies requiring MFA" -ExportFileLocation $ExportDetails
            }
        }

        # Check authorization policy (app consent posture)
        try {
            $authorizationPolicyResponse = Get-ArrayaGraphResource -Uri "https://graph.microsoft.com/v1.0/policies/authorizationPolicy" -Activity "Fetching authorization policy"
            $authorizationPolicy = @($authorizationPolicyResponse | Select-Object -First 1)
            if ($authorizationPolicy.Count -gt 0 -and $authorizationPolicy[0]) {
                if ($authorizationPolicy[0].PSObject.Properties['allowInvitesFrom']) {
                    Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'AllowInvitesFrom' -Value ([string]$authorizationPolicy[0].allowInvitesFrom)
                } elseif ($authorizationPolicy[0].PSObject.Properties['AllowInvitesFrom']) {
                    Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'AllowInvitesFrom' -Value ([string]$authorizationPolicy[0].AllowInvitesFrom)
                }

                if ($authorizationPolicy[0].PSObject.Properties['allowEmailVerifiedUsersToJoinOrganization']) {
                    Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'AllowEmailVerifiedUsersToJoinOrganization' -Value ([bool]$authorizationPolicy[0].allowEmailVerifiedUsersToJoinOrganization)
                } elseif ($authorizationPolicy[0].PSObject.Properties['AllowEmailVerifiedUsersToJoinOrganization']) {
                    Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'AllowEmailVerifiedUsersToJoinOrganization' -Value ([bool]$authorizationPolicy[0].AllowEmailVerifiedUsersToJoinOrganization)
                }

                if ($authorizationPolicy[0].PSObject.Properties['guestUserRoleId']) {
                    Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'GuestUserRoleId' -Value ([string]$authorizationPolicy[0].guestUserRoleId)
                } elseif ($authorizationPolicy[0].PSObject.Properties['GuestUserRoleId']) {
                    Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'GuestUserRoleId' -Value ([string]$authorizationPolicy[0].GuestUserRoleId)
                }
                if ($authMethodsPolicy.PSObject.Properties['GuestUserRoleId'] -and -not [string]::IsNullOrWhiteSpace([string]$authMethodsPolicy.GuestUserRoleId)) {
                    Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'GuestUserRoleLabel' -Value (Get-AssessmentGuestUserRoleLabel -GuestUserRoleId ([string]$authMethodsPolicy.GuestUserRoleId))
                }

                if ($authorizationPolicy[0].PSObject.Properties['allowedToUseSSPR']) {
                    Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'SelfServicePasswordResetEnabled' -Value ([bool]$authorizationPolicy[0].allowedToUseSSPR)
                } elseif ($authorizationPolicy[0].PSObject.Properties['AllowedToUseSSPR']) {
                    Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'SelfServicePasswordResetEnabled' -Value ([bool]$authorizationPolicy[0].AllowedToUseSSPR)
                } elseif ($authorizationPolicy[0].PSObject.Properties['allowedToUseSspr']) {
                    Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'SelfServicePasswordResetEnabled' -Value ([bool]$authorizationPolicy[0].allowedToUseSspr)
                } elseif ($authorizationPolicy[0].PSObject.Properties['AllowedToUseSspr']) {
                    Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'SelfServicePasswordResetEnabled' -Value ([bool]$authorizationPolicy[0].AllowedToUseSspr)
                }

                $defaultPermissions = $null
                if ($authorizationPolicy[0].PSObject.Properties['defaultUserRolePermissions']) {
                    $defaultPermissions = $authorizationPolicy[0].defaultUserRolePermissions
                } elseif ($authorizationPolicy[0].PSObject.Properties['DefaultUserRolePermissions']) {
                    $defaultPermissions = $authorizationPolicy[0].DefaultUserRolePermissions
                }

                if ($defaultPermissions) {
                    if ($defaultPermissions.PSObject.Properties['allowedToCreateApps']) {
                        Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'DefaultUserCanCreateApps' -Value ([bool]$defaultPermissions.allowedToCreateApps)
                    } elseif ($defaultPermissions.PSObject.Properties['AllowedToCreateApps']) {
                        Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'DefaultUserCanCreateApps' -Value ([bool]$defaultPermissions.AllowedToCreateApps)
                    }

                    if ($defaultPermissions.PSObject.Properties['allowedToUseSspr']) {
                        Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'SelfServicePasswordResetEnabled' -Value ([bool]$defaultPermissions.allowedToUseSspr)
                    } elseif ($defaultPermissions.PSObject.Properties['AllowedToUseSspr']) {
                        Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'SelfServicePasswordResetEnabled' -Value ([bool]$defaultPermissions.AllowedToUseSspr)
                    }

                    if ($defaultPermissions.PSObject.Properties['allowedToReadOtherUsers']) {
                        Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'DefaultUserCanReadOtherUsers' -Value ([bool]$defaultPermissions.allowedToReadOtherUsers)
                    } elseif ($defaultPermissions.PSObject.Properties['AllowedToReadOtherUsers']) {
                        Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'DefaultUserCanReadOtherUsers' -Value ([bool]$defaultPermissions.AllowedToReadOtherUsers)
                    }

                    $assignedGrantPolicies = @()
                    if ($defaultPermissions.PSObject.Properties['permissionGrantPoliciesAssigned']) {
                        $assignedGrantPolicies = @($defaultPermissions.permissionGrantPoliciesAssigned)
                    } elseif ($defaultPermissions.PSObject.Properties['PermissionGrantPoliciesAssigned']) {
                        $assignedGrantPolicies = @($defaultPermissions.PermissionGrantPoliciesAssigned)
                    }
                    Set-AuthenticationConfigurationProperty -TargetObject $authMethodsPolicy -Name 'PermissionGrantPoliciesAssigned' -Value (@($assignedGrantPolicies | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }))
                }
            }
        } catch {
            Write-Log -Type WARNING -Message "[Get-AuthenticationConfiguration] Unable to retrieve authorization policy details: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }

        # Check admin consent request workflow
        try {
            $adminConsentPolicyResponse = Get-ArrayaGraphResource -Uri "https://graph.microsoft.com/v1.0/policies/adminConsentRequestPolicy" -Activity "Fetching admin consent request policy"
            $adminConsentPolicy = @($adminConsentPolicyResponse | Select-Object -First 1)
            if ($adminConsentPolicy.Count -gt 0 -and $adminConsentPolicy[0]) {
                if ($adminConsentPolicy[0].PSObject.Properties['isEnabled']) {
                    $authMethodsPolicy.AdminConsentWorkflowEnabled = [bool]$adminConsentPolicy[0].isEnabled
                } elseif ($adminConsentPolicy[0].PSObject.Properties['IsEnabled']) {
                    $authMethodsPolicy.AdminConsentWorkflowEnabled = [bool]$adminConsentPolicy[0].IsEnabled
                }

                $reviewers = @()
                if ($adminConsentPolicy[0].PSObject.Properties['reviewers']) {
                    $reviewers = @($adminConsentPolicy[0].reviewers)
                } elseif ($adminConsentPolicy[0].PSObject.Properties['Reviewers']) {
                    $reviewers = @($adminConsentPolicy[0].Reviewers)
                }
                $authMethodsPolicy.AdminConsentWorkflowReviewerCount = $reviewers.Count
            }
        } catch {
            Write-Log -Type WARNING -Message "[Get-AuthenticationConfiguration] Unable to retrieve admin consent workflow policy: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }

        # Check Security Defaults policy state
        try {
            $securityDefaultsResponse = Get-ArrayaGraphResource -Uri "https://graph.microsoft.com/v1.0/policies/identitySecurityDefaultsEnforcementPolicy" -Activity "Fetching security defaults policy"
            $securityDefaultsPolicy = @($securityDefaultsResponse | Select-Object -First 1)
            if ($securityDefaultsPolicy.Count -gt 0 -and $securityDefaultsPolicy[0]) {
                $isEnabled = $null
                if ($securityDefaultsPolicy[0].PSObject.Properties['isEnabled']) {
                    $isEnabled = [bool]$securityDefaultsPolicy[0].isEnabled
                } elseif ($securityDefaultsPolicy[0].PSObject.Properties['IsEnabled']) {
                    $isEnabled = [bool]$securityDefaultsPolicy[0].IsEnabled
                }

                $script:tenantStatsHash["SecurityDefaultsPolicy"]["Configuration"] = [PSCustomObject]@{
                    IsEnabled   = $isEnabled
                    Description = $(if ($isEnabled -eq $true) { 'Security Defaults are enabled.' } elseif ($isEnabled -eq $false) { 'Security Defaults are disabled.' } else { 'Security Defaults state unavailable.' })
                }
            }
        } catch {
            Write-Log -Type WARNING -Message "[Get-AuthenticationConfiguration] Unable to retrieve Security Defaults policy: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }

        if ($collectExtendedIdentityTierB) {
            try {
                Write-Log -Type INFO -Message "[Get-AuthenticationConfiguration] Collecting enterprise application permission posture for governance findings" -ExportFileLocation $ExportDetails
                $resourceServicePrincipalCache = @{}
                $highPrivilegePatterns = @(
                    'Directory.ReadWrite.All', 'Directory.AccessAsUser.All', 'RoleManagement.ReadWrite.Directory',
                    'AppRoleAssignment.ReadWrite.All', 'Application.ReadWrite.All', 'Group.ReadWrite.All',
                    'User.ReadWrite.All', 'Mail.ReadWrite', 'Files.ReadWrite.All', 'Sites.FullControl.All',
                    'Sites.ReadWrite.All', 'Exchange.ManageAsApp', 'Policy.ReadWrite.ConditionalAccess',
                    'DeviceManagementManagedDevices.ReadWrite.All', 'DeviceManagementConfiguration.ReadWrite.All'
                )
                foreach ($servicePrincipal in $servicePrincipals) {
                    if ($null -eq $servicePrincipal -or [string]::IsNullOrWhiteSpace([string]$servicePrincipal.Id)) {
                        continue
                    }
                    $spId = [string]$servicePrincipal.Id
                    $delegatedGrants = @()
                    $applicationPermissionValues = @()
                    try {
                        $delegatedGrants = @(Get-ArrayaGraphResource -Uri ("https://graph.microsoft.com/v1.0/oauth2PermissionGrants?`$filter=clientId eq '{0}'&`$top=50" -f $spId) -Activity "Enterprise app delegated grants [$($servicePrincipal.DisplayName)]" -Headers $global:GraphHeaders)
                    } catch {
                        Write-Log -Type DEBUG -Message "[Get-AuthenticationConfiguration] Delegated grant lookup failed for '$($servicePrincipal.DisplayName)': $($_.Exception.Message)" -ExportFileLocation $ExportDetails
                    }

                    try {
                        $appRoleAssignments = @(Get-ArrayaGraphResource -Uri ("https://graph.microsoft.com/v1.0/servicePrincipals/{0}/appRoleAssignments?`$top=50" -f $spId) -Activity "Enterprise app role assignments [$($servicePrincipal.DisplayName)]" -Headers $global:GraphHeaders)
                        foreach ($assignment in $appRoleAssignments) {
                            $resourceId = if ($assignment.PSObject.Properties['ResourceId']) { [string]$assignment.ResourceId } else { $null }
                            $appRoleId = if ($assignment.PSObject.Properties['AppRoleId']) { [string]$assignment.AppRoleId } else { $null }
                            if (-not $resourceId) { continue }

                            if (-not $resourceServicePrincipalCache.ContainsKey($resourceId)) {
                                try {
                                    $resourceServicePrincipalCache[$resourceId] = Get-ArrayaGraphResource -Uri ("https://graph.microsoft.com/v1.0/servicePrincipals/{0}?`$select=id,displayName,appRoles" -f $resourceId) -Activity "Enterprise app resource lookup [$resourceId]" -Headers $global:GraphHeaders
                                } catch {
                                    $resourceServicePrincipalCache[$resourceId] = $null
                                }
                            }

                            $resourcePrincipal = $resourceServicePrincipalCache[$resourceId]
                            $resourceDisplayName = if ($resourcePrincipal -and $resourcePrincipal.PSObject.Properties['DisplayName']) { [string]$resourcePrincipal.DisplayName } else { $resourceId }
                            $permissionValue = $null
                            if ($resourcePrincipal -and $resourcePrincipal.PSObject.Properties['AppRoles']) {
                                $permissionValue = @($resourcePrincipal.AppRoles | Where-Object { $_.Id -and ([string]$_.Id -eq $appRoleId) } | Select-Object -First 1 | ForEach-Object { $_.Value }) | Select-Object -First 1
                            }
                            if ([string]::IsNullOrWhiteSpace([string]$permissionValue)) {
                                $permissionValue = $appRoleId
                            }
                            $applicationPermissionValues += ("{0}:{1}" -f $resourceDisplayName, $permissionValue)
                        }
                    } catch {
                        Write-Log -Type DEBUG -Message "[Get-AuthenticationConfiguration] App-role assignment lookup failed for '$($servicePrincipal.DisplayName)': $($_.Exception.Message)" -ExportFileLocation $ExportDetails
                    }

                    $delegatedScopes = @(
                        $delegatedGrants |
                            ForEach-Object {
                                if ($_.PSObject.Properties['Scope']) { [string]$_.Scope } elseif ($_.PSObject.Properties['scope']) { [string]$_.scope } else { $null }
                            } |
                            Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
                    )
                    $flattenedDelegatedScopes = @(
                        $delegatedScopes |
                            ForEach-Object { $_ -split ' ' } |
                            ForEach-Object { $_.Trim() } |
                            Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
                    )
                    $combinedPermissionText = (@($applicationPermissionValues) + @($flattenedDelegatedScopes)) -join ';'
                    $highPrivilegeMatches = @(
                        $highPrivilegePatterns | Where-Object { $combinedPermissionText -match [regex]::Escape($_) }
                    )
                    Add-AssessmentEnterpriseApplicationRecord -ServicePrincipal $servicePrincipal -AdditionalProperties @{
                        DelegatedPermissionScopes       = $flattenedDelegatedScopes -join ','
                        DelegatedPermissionGrantCount   = @($delegatedGrants).Count
                        ApplicationPermissions          = $applicationPermissionValues -join ','
                        ApplicationPermissionCount      = @($applicationPermissionValues).Count
                        HighPrivilegePermissionCount    = $highPrivilegeMatches.Count
                        HighPrivilegePermissions        = $highPrivilegeMatches -join ','
                    }
                }
            } catch {
                Write-Log -Type WARNING -Message "[Get-AuthenticationConfiguration] Unable to collect enterprise application permission posture: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
            }
        }

        if ($servicePrincipals.Count -gt 0 -and $detailLevel -ne 'minimum') {
            $tenantOrganizationId = [string](Get-ArrayaObjectValue -Object $script:tenantStatsHash["TenantInfo"] -Names @('TenantId', 'TenantID'))
            $enterpriseApplicationAppRegistrations = @{}
            $servicePrincipalActivityMap = @{}
            $latestServicePrincipalSignIns = @{}
            $latestEnterpriseApplicationSignIns = @{}
            $enterpriseApplicationAppRegistrationMetadataCollected = $false
            $servicePrincipalActivityCollected = $false
            $latestServicePrincipalSignInCollected = $false
            $latestEnterpriseApplicationSignInCollected = $false

            try {
                $enterpriseApplicationAppRegistrations = Get-AssessmentEnterpriseApplicationAppRegistrationMap -ServicePrincipals @($servicePrincipals)
                $enterpriseApplicationAppRegistrationMetadataCollected = $true
            }
            catch {
                Write-Log -Type WARNING -Message "[Get-AuthenticationConfiguration] Unable to retrieve app registration metadata for enterprise applications: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
            }

            try {
                $servicePrincipalActivityMap = Get-AssessmentEnterpriseApplicationServicePrincipalActivityMap -ServicePrincipals @($servicePrincipals)
                $servicePrincipalActivityCollected = $true
            }
            catch {
                Write-Log -Type WARNING -Message "[Get-AuthenticationConfiguration] Unable to retrieve service principal sign-in activity split for enterprise applications from the beta Graph endpoint. Application activity state will remain not validated where this enrichment was required: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
            }

            try {
                $latestServicePrincipalSignIns = Get-AssessmentEnterpriseApplicationLatestServicePrincipalSignInMap -ServicePrincipals @($servicePrincipals)
                $latestServicePrincipalSignInCollected = $true
            }
            catch {
                Write-Log -Type DEBUG -Message "[Get-AuthenticationConfiguration] Unable to retrieve latest service principal sign-in credential types: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
            }

            foreach ($servicePrincipal in @($servicePrincipals)) {
                $identityProfile = Get-AssessmentEnterpriseApplicationIdentityProfile -ServicePrincipal $servicePrincipal
                $servicePrincipalId = [string]$identityProfile.ServicePrincipalId
                if ([string]::IsNullOrWhiteSpace($servicePrincipalId) -or -not $enterpriseApplicationKeyById.ContainsKey($servicePrincipalId)) {
                    continue
                }

                $appId = [string]$identityProfile.AppId
                if ([string]::IsNullOrWhiteSpace($appId)) {
                    continue
                }

                $appRegistration = if ($enterpriseApplicationAppRegistrations.ContainsKey($appId)) { $enterpriseApplicationAppRegistrations[$appId] } else { $null }
                $servicePrincipalActivity = if ($servicePrincipalActivityMap.ContainsKey($appId)) { $servicePrincipalActivityMap[$appId] } else { $null }
                $latestServicePrincipalSignIn = if ($latestServicePrincipalSignIns.ContainsKey($appId)) { $latestServicePrincipalSignIns[$appId] } else { $null }
                $appOwnerOrganizationId = [string](Get-ArrayaObjectValue -Object $servicePrincipal -Names @('appOwnerOrganizationId', 'AppOwnerOrganizationId'))
                $applicationSource = 'Unknown'
                $applicationSourceState = 'Unavailable'
                if ($null -ne $appRegistration) {
                    $applicationSource = 'First Party'
                    $applicationSourceState = 'Collected'
                }
                elseif (
                    -not [string]::IsNullOrWhiteSpace($tenantOrganizationId) -and
                    -not [string]::IsNullOrWhiteSpace($appOwnerOrganizationId)
                ) {
                    $applicationSource = $(if ($appOwnerOrganizationId -eq $tenantOrganizationId) { 'First Party' } else { 'Third Party' })
                    $applicationSourceState = 'Collected'
                }

                $owners = @()
                $ownersText = ''
                $ownerCount = $null
                $ownerSignalState = 'Unavailable'
                if ($applicationSource -eq 'Third Party') {
                    $ownerSignalState = 'NotApplicable'
                }
                elseif ($appRegistration) {
                    $owners = @($appRegistration.Owners)
                    $ownersText = [string]$appRegistration.OwnersText
                    if ([string]$appRegistration.OwnerSignalState -eq 'Collected') {
                        $ownerSignalState = 'Collected'
                        $ownerCount = if ($null -ne $appRegistration.OwnerCount) { [int]$appRegistration.OwnerCount } else { 0 }
                    }
                }

                $redirectUriValues = New-Object System.Collections.Generic.List[string]
                $servicePrincipalReplyUrlsPropertyPresent = ($null -ne $servicePrincipal.PSObject.Properties['replyUrls']) -or ($null -ne $servicePrincipal.PSObject.Properties['ReplyUrls'])
                if ($appRegistration) {
                    foreach ($redirectUri in @($appRegistration.RedirectUris)) {
                        $redirectUriText = [string]$redirectUri
                        if (-not [string]::IsNullOrWhiteSpace($redirectUriText) -and -not $redirectUriValues.Contains($redirectUriText)) {
                            $redirectUriValues.Add($redirectUriText) | Out-Null
                        }
                    }
                }
                foreach ($replyUrl in @((Get-ArrayaObjectValue -Object $servicePrincipal -Names @('replyUrls', 'ReplyUrls')))) {
                    $replyUrlText = [string]$replyUrl
                    if (-not [string]::IsNullOrWhiteSpace($replyUrlText) -and -not $redirectUriValues.Contains($replyUrlText)) {
                        $redirectUriValues.Add($replyUrlText) | Out-Null
                    }
                }

                $redirectUriSignalState = if ($appRegistration) {
                    'Collected'
                }
                elseif ($servicePrincipalReplyUrlsPropertyPresent) {
                    'Partial'
                }
                else {
                    'Unavailable'
                }

                $insecureRedirectUris = @(
                    $redirectUriValues.ToArray() |
                        Where-Object { Test-AssessmentEnterpriseApplicationInsecureRedirectUri -Uri ([string]$_) }
                )
                $insecureRedirectUriCount = $null
                $hasInsecureRedirectUris = $null
                if ($redirectUriSignalState -eq 'Collected') {
                    $insecureRedirectUriCount = @($insecureRedirectUris).Count
                    $hasInsecureRedirectUris = (@($insecureRedirectUris).Count -gt 0)
                }
                elseif ($redirectUriSignalState -eq 'Partial' -and @($insecureRedirectUris).Count -gt 0) {
                    $insecureRedirectUriCount = @($insecureRedirectUris).Count
                    $hasInsecureRedirectUris = $true
                }

                Add-AssessmentEnterpriseApplicationRecord -ServicePrincipal $servicePrincipal -AdditionalProperties @{
                    AppRegistrationId             = $(if ($appRegistration) { $appRegistration.AppRegistrationId } else { $null })
                    AppOwnerOrganizationId        = $appOwnerOrganizationId
                    ApplicationSource             = $applicationSource
                    ApplicationSourceState        = $applicationSourceState
                    Owners                        = $owners
                    OwnersText                    = $ownersText
                    OwnerSignalState              = $ownerSignalState
                    OwnerCount                    = $ownerCount
                    RedirectUris                  = @($redirectUriValues.ToArray())
                    RedirectUrisText              = (@($redirectUriValues.ToArray()) -join ', ')
                    RedirectUriSignalState        = $redirectUriSignalState
                    RedirectUriCount              = $redirectUriValues.Count
                    InsecureRedirectUriCount      = $insecureRedirectUriCount
                    HasInsecureRedirectUris       = $hasInsecureRedirectUris
                    AppCredentials                = $(if ($appRegistration) { [string]$appRegistration.AppCredentials } else { '' })
                    KeyCredentialCount            = $(if ($appRegistration) { [int]$appRegistration.KeyCredentialCount } else { 0 })
                    PasswordCredentialCount       = $(if ($appRegistration) { [int]$appRegistration.PasswordCredentialCount } else { 0 })
                    CredentialReviewState         = $(if ($appRegistration) { [string]$appRegistration.CredentialReviewState } else { 'Unavailable' })
                    CredentialCount               = $(if ($appRegistration) { [int]$appRegistration.CredentialCount } else { 0 })
                    HasExpiredCredentials         = $(if ($appRegistration) { $appRegistration.HasExpiredCredentials } else { $null })
                    ExpiredCredentialCount        = $(if ($appRegistration) { $appRegistration.ExpiredCredentialCount } else { $null })
                    ExpiredKeyCredentialCount     = $(if ($appRegistration) { $appRegistration.ExpiredKeyCredentialCount } else { $null })
                    ExpiredPasswordCredentialCount = $(if ($appRegistration) { $appRegistration.ExpiredPasswordCredentialCount } else { $null })
                    HasCredentialsExpiringSoon    = $(if ($appRegistration) { $appRegistration.HasCredentialsExpiringSoon } else { $null })
                    ExpiringCredentialCount       = $(if ($appRegistration) { $appRegistration.ExpiringCredentialCount } else { $null })
                    ExpiringKeyCredentialCount    = $(if ($appRegistration) { $appRegistration.ExpiringKeyCredentialCount } else { $null })
                    ExpiringPasswordCredentialCount = $(if ($appRegistration) { $appRegistration.ExpiringPasswordCredentialCount } else { $null })
                    NextCredentialExpiryDateTime  = $(if ($appRegistration) { $appRegistration.NextCredentialExpiryDateTime } else { $null })
                    LatestCredentialExpiryDateTime = $(if ($appRegistration) { $appRegistration.LatestCredentialExpiryDateTime } else { $null })
                    CredentialIssueSummary        = $(if ($appRegistration) { [string]$appRegistration.CredentialIssueSummary } else { '' })
                    SignInAudience                = $(if ($appRegistration) { $appRegistration.SignInAudience } else { $null })
                    ApplicationCreatedDateTime    = $(if ($appRegistration) { $appRegistration.ApplicationCreatedDateTime } else { $null })
                    DelegatedLastSignIn           = $(if ($servicePrincipalActivity) { $servicePrincipalActivity.DelegatedLastSignIn } else { $null })
                    ApplicationLastSignIn         = $(if ($servicePrincipalActivity) { $servicePrincipalActivity.ApplicationLastSignIn } else { $null })
                    LastSignInType                = $(if ($latestServicePrincipalSignIn) { $latestServicePrincipalSignIn.LastSignInType } else { $null })
                    LastServicePrincipalSignInDateTime = $(if ($latestServicePrincipalSignIn) { $latestServicePrincipalSignIn.LastServicePrincipalSignInDateTime } else { $null })
                }
            }

            try {
                $latestEnterpriseApplicationSignIns = Get-AssessmentEnterpriseApplicationLatestSignInMap -ServicePrincipals @($servicePrincipals)
                $latestEnterpriseApplicationSignInCollected = $true
            }
            catch {
                Write-Log -Type WARNING -Message "[Get-AuthenticationConfiguration] Unable to retrieve batched enterprise application sign-in details from the beta Graph endpoint. Application inventory will continue without sign-in enrichment and related activity findings will remain validation-aware: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
            }

            foreach ($servicePrincipal in @($servicePrincipals)) {
                $identityProfile = Get-AssessmentEnterpriseApplicationIdentityProfile -ServicePrincipal $servicePrincipal
                $servicePrincipalId = [string]$identityProfile.ServicePrincipalId
                if ([string]::IsNullOrWhiteSpace($servicePrincipalId) -or -not $enterpriseApplicationKeyById.ContainsKey($servicePrincipalId)) {
                    continue
                }

                $appId = [string]$identityProfile.AppId
                if ([string]::IsNullOrWhiteSpace($appId)) {
                    continue
                }

                $servicePrincipalActivity = if ($servicePrincipalActivityMap.ContainsKey($appId)) { $servicePrincipalActivityMap[$appId] } else { $null }
                $latestServicePrincipalSignIn = if ($latestServicePrincipalSignIns.ContainsKey($appId)) { $latestServicePrincipalSignIns[$appId] } else { $null }
                $latestSignInDetails = if ($latestEnterpriseApplicationSignIns.ContainsKey($appId)) { $latestEnterpriseApplicationSignIns[$appId] } else { $null }

                $hasServicePrincipalActivity = (
                    ($servicePrincipalActivity -and (
                        (Test-AssessmentEnterpriseApplicationResolvedSignInValue -Value $servicePrincipalActivity.DelegatedLastSignIn) -or
                        (Test-AssessmentEnterpriseApplicationResolvedSignInValue -Value $servicePrincipalActivity.ApplicationLastSignIn)
                    )) -or
                    ($latestServicePrincipalSignIn -and (Test-AssessmentEnterpriseApplicationResolvedSignInValue -Value $latestServicePrincipalSignIn.LastServicePrincipalSignInDateTime))
                )
                $hasUserActivity = ($latestSignInDetails -and (Test-AssessmentEnterpriseApplicationResolvedSignInValue -Value $latestSignInDetails.LastSignInDateTime))

                $servicePrincipalActivitySourceResolved = (
                    $servicePrincipalActivityCollected -and
                    $latestServicePrincipalSignInCollected -and
                    $null -ne $latestServicePrincipalSignIn -and
                    -not (Test-AssessmentEnterpriseApplicationUnresolvedSignInValue -Value $latestServicePrincipalSignIn.LastServicePrincipalSignInDateTime)
                )
                $userActivitySourceResolved = (
                    $latestEnterpriseApplicationSignInCollected -and
                    $null -ne $latestSignInDetails -and
                    -not (Test-AssessmentEnterpriseApplicationUnresolvedSignInValue -Value $latestSignInDetails.LastSignInDateTime)
                )

                $activitySignalState = if ($servicePrincipalActivitySourceResolved -and $userActivitySourceResolved) {
                    'Collected'
                }
                elseif ($servicePrincipalActivitySourceResolved -or $userActivitySourceResolved) {
                    'Partial'
                }
                else {
                    'Unavailable'
                }

                $hasRecentActivity = if ($hasServicePrincipalActivity -or $hasUserActivity) {
                    $true
                }
                elseif ($activitySignalState -eq 'Collected') {
                    $false
                }
                else {
                    $null
                }

                Add-AssessmentEnterpriseApplicationRecord -ServicePrincipal $servicePrincipal -AdditionalProperties @{
                    LastSignInDateTime          = $(if ($latestSignInDetails) { $latestSignInDetails.LastSignInDateTime } else { $null })
                    LastSignInUserDisplayName   = $(if ($latestSignInDetails) { $latestSignInDetails.LastSignInUserDisplayName } else { $null })
                    LastSignInUserPrincipalName = $(if ($latestSignInDetails) { $latestSignInDetails.LastSignInUserPrincipalName } else { $null })
                    LastConditionalAccessStatus = $(if ($latestSignInDetails) { $latestSignInDetails.LastConditionalAccessStatus } else { $null })
                    LastClientAppUsed           = $(if ($latestSignInDetails) { $latestSignInDetails.LastClientAppUsed } else { $null })
                    ActivitySignalState         = $activitySignalState
                    HasRecentActivity           = $hasRecentActivity
                }
            }
        }

        $enterpriseApplicationRows = @($script:tenantStatsHash["EnterpriseApplications"].Values)
        $resolvedSsoApplicationRows = @($enterpriseApplicationRows | Where-Object { (Convert-ToAssessmentBoolean $_.SsoEnabled) -eq $true })
        if ($resolvedSsoApplicationRows.Count -gt 0) {
            $authMethodsPolicy.SSOEnabled = $true
        }
        $authMethodsPolicy.SSOApplications = @($resolvedSsoApplicationRows)

        $applicationSourceCollectedCount = @($enterpriseApplicationRows | Where-Object { [string]$_.ApplicationSourceState -eq 'Collected' }).Count
        $applicationSourceUnavailableCount = @($enterpriseApplicationRows | Where-Object { [string]$_.ApplicationSourceState -eq 'Unavailable' }).Count
        $ownerSignalCollectedCount = @($enterpriseApplicationRows | Where-Object { [string]$_.OwnerSignalState -eq 'Collected' }).Count
        $ownerSignalUnavailableCount = @($enterpriseApplicationRows | Where-Object { [string]$_.OwnerSignalState -eq 'Unavailable' }).Count
        $ownerSignalNotApplicableCount = @($enterpriseApplicationRows | Where-Object { [string]$_.OwnerSignalState -eq 'NotApplicable' }).Count
        $redirectUriSignalCollectedCount = @($enterpriseApplicationRows | Where-Object { [string]$_.RedirectUriSignalState -eq 'Collected' }).Count
        $redirectUriSignalPartialCount = @($enterpriseApplicationRows | Where-Object { [string]$_.RedirectUriSignalState -eq 'Partial' }).Count
        $redirectUriSignalUnavailableCount = @($enterpriseApplicationRows | Where-Object { [string]$_.RedirectUriSignalState -eq 'Unavailable' }).Count
        $activitySignalCollectedCount = @($enterpriseApplicationRows | Where-Object { [string]$_.ActivitySignalState -eq 'Collected' }).Count
        $activitySignalPartialCount = @($enterpriseApplicationRows | Where-Object { [string]$_.ActivitySignalState -eq 'Partial' }).Count
        $activitySignalUnavailableCount = @($enterpriseApplicationRows | Where-Object { [string]$_.ActivitySignalState -eq 'Unavailable' }).Count

        $applicationSourceCoverageState = if ($enterpriseApplicationRows.Count -eq 0) {
            'Unavailable'
        }
        elseif ($applicationSourceUnavailableCount -eq 0) {
            'Collected'
        }
        elseif ($applicationSourceCollectedCount -gt 0) {
            'Partial'
        }
        else {
            'Unavailable'
        }

        $ownerSignalCoverageState = if ($enterpriseApplicationRows.Count -eq 0) {
            'Unavailable'
        }
        elseif (($ownerSignalCollectedCount + $ownerSignalUnavailableCount) -eq 0 -and $ownerSignalNotApplicableCount -gt 0) {
            'NotApplicable'
        }
        elseif ($ownerSignalUnavailableCount -eq 0) {
            'Collected'
        }
        elseif ($ownerSignalCollectedCount -gt 0) {
            'Partial'
        }
        else {
            'Unavailable'
        }

        $redirectUriSignalCoverageState = if ($enterpriseApplicationRows.Count -eq 0) {
            'Unavailable'
        }
        elseif (($redirectUriSignalPartialCount + $redirectUriSignalUnavailableCount) -eq 0) {
            'Collected'
        }
        elseif (($redirectUriSignalCollectedCount + $redirectUriSignalPartialCount) -gt 0) {
            'Partial'
        }
        else {
            'Unavailable'
        }

        $activitySignalCoverageState = if ($enterpriseApplicationRows.Count -eq 0) {
            'Unavailable'
        }
        elseif (($activitySignalPartialCount + $activitySignalUnavailableCount) -eq 0) {
            'Collected'
        }
        elseif (($activitySignalCollectedCount + $activitySignalPartialCount) -gt 0) {
            'Partial'
        }
        else {
            'Unavailable'
        }

        $script:tenantStatsHash["EnterpriseApplicationSummary"]["Summary"] = [PSCustomObject]@{
            TotalEnterpriseApplications      = $enterpriseApplicationRows.Count
            FirstPartyApplications           = @($enterpriseApplicationRows | Where-Object { [string]$_.ApplicationSource -eq 'First Party' }).Count
            ThirdPartyApplications           = @($enterpriseApplicationRows | Where-Object { [string]$_.ApplicationSource -eq 'Third Party' }).Count
            UnknownSourceApplications        = @($enterpriseApplicationRows | Where-Object { [string]$_.ApplicationSource -eq 'Unknown' }).Count
            ApplicationsWithHighPrivilege    = @($enterpriseApplicationRows | Where-Object { (Convert-ArrayaToNumber $_.HighPrivilegePermissionCount) -gt 0 }).Count
            ApplicationsWithDelegatedGrants  = @($enterpriseApplicationRows | Where-Object { (Convert-ArrayaToNumber $_.DelegatedPermissionGrantCount) -gt 0 }).Count
            ApplicationsWithApplicationPerms = @($enterpriseApplicationRows | Where-Object { (Convert-ArrayaToNumber $_.ApplicationPermissionCount) -gt 0 }).Count
            FirstPartyAppsWithoutOwners      = @($enterpriseApplicationRows | Where-Object { ([string]$_.ApplicationSource -eq 'First Party') -and ([string]$_.OwnerSignalState -eq 'Collected') -and ((Convert-ArrayaToNumber $_.OwnerCount) -le 0) }).Count
            ThirdPartyAppsWithApplicationPerms = @($enterpriseApplicationRows | Where-Object { ([string]$_.ApplicationSource -eq 'Third Party') -and ((Convert-ArrayaToNumber $_.ApplicationPermissionCount) -gt 0) }).Count
            ApplicationsWithNoRecentActivity = @($enterpriseApplicationRows | Where-Object { ([string]$_.ActivitySignalState -eq 'Collected') -and ((Convert-ToAssessmentBoolean $_.HasRecentActivity) -eq $false) }).Count
            ApplicationsWithInsecureRedirectUris = @($enterpriseApplicationRows | Where-Object { (([string]$_.RedirectUriSignalState -eq 'Collected') -or ([string]$_.RedirectUriSignalState -eq 'Partial')) -and ((Convert-ToAssessmentBoolean $_.HasInsecureRedirectUris) -eq $true) }).Count
            SsoEnabledApplications           = $resolvedSsoApplicationRows.Count
            ApplicationsWithExpiredCredentials = @($enterpriseApplicationRows | Where-Object { ([string]$_.CredentialReviewState -eq 'Collected') -and ((Convert-ToAssessmentBoolean $_.HasExpiredCredentials) -eq $true) }).Count
            ApplicationsWithCredentialsExpiringSoon = @($enterpriseApplicationRows | Where-Object { ([string]$_.CredentialReviewState -eq 'Collected') -and ((Convert-ToAssessmentBoolean $_.HasCredentialsExpiringSoon) -eq $true) }).Count
            ApplicationSourceCoverageState   = $applicationSourceCoverageState
            ApplicationSourceCollectedCount  = $applicationSourceCollectedCount
            ApplicationSourceUnavailableCount = $applicationSourceUnavailableCount
            OwnerSignalCoverageState         = $ownerSignalCoverageState
            OwnerSignalCollectedCount        = $ownerSignalCollectedCount
            OwnerSignalUnavailableCount      = $ownerSignalUnavailableCount
            OwnerSignalNotApplicableCount    = $ownerSignalNotApplicableCount
            RedirectUriSignalCoverageState   = $redirectUriSignalCoverageState
            RedirectUriSignalCollectedCount  = $redirectUriSignalCollectedCount
            RedirectUriSignalPartialCount    = $redirectUriSignalPartialCount
            RedirectUriSignalUnavailableCount = $redirectUriSignalUnavailableCount
            ActivitySignalCoverageState      = $activitySignalCoverageState
            ActivitySignalCollectedCount     = $activitySignalCollectedCount
            ActivitySignalPartialCount       = $activitySignalPartialCount
            ActivitySignalUnavailableCount   = $activitySignalUnavailableCount
        }
        
        $normalizedAuthenticationConfig = [pscustomobject]@{
            MFAEnabled                        = [bool]$authMethodsPolicy.MFAEnabled
            MFAMethods                        = @($authMethodsPolicy.MFAMethods)
            SSOEnabled                        = [bool]$authMethodsPolicy.SSOEnabled
            SSOApplications                    = @($authMethodsPolicy.SSOApplications)
            FederatedDomains                  = @($authMethodsPolicy.FederatedDomains)
            PasswordlessMethods               = @($authMethodsPolicy.PasswordlessMethods)
            DefaultUserCanCreateApps          = $authMethodsPolicy.DefaultUserCanCreateApps
            SelfServicePasswordResetEnabled   = $authMethodsPolicy.SelfServicePasswordResetEnabled
            PermissionGrantPoliciesAssigned   = @($authMethodsPolicy.PermissionGrantPoliciesAssigned)
            AdminConsentWorkflowEnabled       = $authMethodsPolicy.AdminConsentWorkflowEnabled
            AdminConsentWorkflowReviewerCount = $authMethodsPolicy.AdminConsentWorkflowReviewerCount
            MFAConditionalAccessPolicies      = $(if ($authMethodsPolicy.PSObject.Properties['MFAConditionalAccessPolicies']) { $authMethodsPolicy.MFAConditionalAccessPolicies } else { 0 })
            AllowInvitesFrom                  = $(if ($authMethodsPolicy.PSObject.Properties['AllowInvitesFrom']) { $authMethodsPolicy.AllowInvitesFrom } else { $null })
            AllowEmailVerifiedUsersToJoinOrganization = $(if ($authMethodsPolicy.PSObject.Properties['AllowEmailVerifiedUsersToJoinOrganization']) { $authMethodsPolicy.AllowEmailVerifiedUsersToJoinOrganization } else { $null })
            GuestUserRoleId                   = $(if ($authMethodsPolicy.PSObject.Properties['GuestUserRoleId']) { $authMethodsPolicy.GuestUserRoleId } else { $null })
            GuestUserRoleLabel                = $(if ($authMethodsPolicy.PSObject.Properties['GuestUserRoleId']) { Get-AssessmentGuestUserRoleLabel -GuestUserRoleId ([string]$authMethodsPolicy.GuestUserRoleId) } else { $null })
            DefaultUserCanReadOtherUsers      = $(if ($authMethodsPolicy.PSObject.Properties['DefaultUserCanReadOtherUsers']) { $authMethodsPolicy.DefaultUserCanReadOtherUsers } else { $null })
        }

        $script:tenantStatsHash["AuthenticationConfig"]["Configuration"] = $normalizedAuthenticationConfig

        $ssoAppNames = @($authMethodsPolicy.SSOApplications | ForEach-Object { $_.DisplayName } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
        $script:tenantStatsHash["AuthenticationConfigSummary"]["Summary"] = [PSCustomObject]@{
            MFAEnabled                   = $authMethodsPolicy.MFAEnabled
            MFAMethods                   = ($authMethodsPolicy.MFAMethods -join ', ')
            SSOEnabled                   = $authMethodsPolicy.SSOEnabled
            SSOApplicationsCount         = @($authMethodsPolicy.SSOApplications).Count
            SSOApplications              = ($ssoAppNames -join ', ')
            FederatedDomains             = ($authMethodsPolicy.FederatedDomains -join ', ')
            PasswordlessMethods          = ($authMethodsPolicy.PasswordlessMethods -join ', ')
            MFAConditionalAccessPolicies = $(if ($authMethodsPolicy.PSObject.Properties['MFAConditionalAccessPolicies']) { $authMethodsPolicy.MFAConditionalAccessPolicies } else { 0 })
            DefaultUserCanCreateApps     = $(if ($null -eq $authMethodsPolicy.DefaultUserCanCreateApps) { 'Not available' } elseif ($authMethodsPolicy.DefaultUserCanCreateApps) { 'Yes' } else { 'No' })
            SelfServicePasswordReset     = $(if ($null -eq $authMethodsPolicy.SelfServicePasswordResetEnabled) { 'Not available' } elseif ($authMethodsPolicy.SelfServicePasswordResetEnabled) { 'Enabled' } else { 'Disabled' })
            PermissionGrantPolicies      = $(if (@($authMethodsPolicy.PermissionGrantPoliciesAssigned).Count -gt 0) { $authMethodsPolicy.PermissionGrantPoliciesAssigned -join ', ' } else { 'Not available' })
            AdminConsentWorkflowEnabled  = $(if ($null -eq $authMethodsPolicy.AdminConsentWorkflowEnabled) { 'Not available' } elseif ($authMethodsPolicy.AdminConsentWorkflowEnabled) { 'Enabled' } else { 'Disabled' })
            AdminConsentWorkflowReviewers = $authMethodsPolicy.AdminConsentWorkflowReviewerCount
            GuestUserRoleLabel           = $(if ($authMethodsPolicy.PSObject.Properties['GuestUserRoleId']) { Get-AssessmentGuestUserRoleLabel -GuestUserRoleId ([string]$authMethodsPolicy.GuestUserRoleId) } else { 'Not available' })
        }

        $existingPasswordLifecycleSummary = $null
        if ($script:tenantStatsHash.ContainsKey("PasswordLifecycleSummary")) {
            $existingPasswordLifecycleSummary = $script:tenantStatsHash["PasswordLifecycleSummary"]
        }
        $passwordLifecycleSummary = [ordered]@{}
        foreach ($field in @(
            'PasswordWriteback',
            'PasswordWritebackEnabled',
            'PasswordSyncEnabled',
            'CloudPasswordPolicyForPasswordSyncedUsersEnabled',
            'UserForcePasswordChangeOnLogonEnabled',
            'PassThroughAuthentication',
            'PassThroughAuthenticationEnabled',
            'DeviceWritebackEnabled',
            'UnifiedGroupWritebackEnabled',
            'UserWritebackEnabled',
            'OnPremisesSyncEnabled',
            'OnPremisesLastSyncDateTime'
        )) {
            $fieldValue = Get-ArrayaObjectValue -Object $existingPasswordLifecycleSummary -Names @($field)
            if ($null -ne $fieldValue) {
                $passwordLifecycleSummary[$field] = $fieldValue
            }
        }

        if ($null -ne $authMethodsPolicy.SelfServicePasswordResetEnabled) {
            $passwordLifecycleSummary['SelfServicePasswordReset'] = $authMethodsPolicy.SelfServicePasswordResetEnabled
            $passwordLifecycleSummary['SelfServicePasswordResetEnabled'] = $authMethodsPolicy.SelfServicePasswordResetEnabled
        }

        if ($passwordLifecycleSummary.Count -gt 0) {
            $script:tenantStatsHash["PasswordLifecycleSummary"] = [pscustomobject]$passwordLifecycleSummary
        }

        $methodIndex = 0
        foreach ($method in @($authMethodsPolicy.MFAMethods)) {
            $methodIndex++
            $script:tenantStatsHash["AuthenticationMethods"][("{0:D3}-MFA" -f $methodIndex)] = [PSCustomObject]@{
                Category = 'MFA Method'
                Value    = $method
            }
        }

        foreach ($method in @($authMethodsPolicy.PasswordlessMethods)) {
            $methodIndex++
            $script:tenantStatsHash["AuthenticationMethods"][("{0:D3}-Passwordless" -f $methodIndex)] = [PSCustomObject]@{
                Category = 'Passwordless Method'
                Value    = $method
            }
        }

        foreach ($domainName in @($authMethodsPolicy.FederatedDomains)) {
            $methodIndex++
            $script:tenantStatsHash["AuthenticationMethods"][("{0:D3}-Federated" -f $methodIndex)] = [PSCustomObject]@{
                Category = 'Federated Domain'
                Value    = $domainName
            }
        }

        $ssoIndex = 0
        foreach ($app in @($authMethodsPolicy.SSOApplications)) {
            $ssoIndex++
            $script:tenantStatsHash["AuthenticationSSOApplications"][("{0:D3}-{1}" -f $ssoIndex, $app.DisplayName)] = $app
        }

        $guestUsers = @(
            $script:tenantStatsHash["Users"].Values |
                Where-Object { ([string]$_.UserType).ToLowerInvariant() -eq 'guest' -or ([string]$_.UserPrincipalName -like '*#EXT#*') }
        )
        $inactiveGuests = @(
            $guestUsers |
                Where-Object {
                    $lastSignIn = $null
                    $lastSignInText = [string]$_.LastSignInDateTime
                    if (-not [string]::IsNullOrWhiteSpace($lastSignInText)) {
                        $parsedLastSignIn = [datetime]::MinValue
                        if ([datetime]::TryParse($lastSignInText, [ref]$parsedLastSignIn)) {
                            $lastSignIn = $parsedLastSignIn
                        }
                    }
                    ($null -eq $lastSignIn) -or ($lastSignIn -lt (Get-Date).AddDays(-90))
                }
        )
        $script:tenantStatsHash["GuestSignInSummary"]["Summary"] = [PSCustomObject]@{
            TotalGuests            = $guestUsers.Count
            InactiveGuests90Days   = $inactiveGuests.Count
            GuestsNeverSignedIn    = @($guestUsers | Where-Object { -not $_.LastSignInDateTime }).Count
            GuestAccountsEnabled   = @($guestUsers | Where-Object { $_.AccountEnabled -eq $true }).Count
        }

        $privilegedAdmins = @($script:tenantStatsHash["Admins"].Values)
        $staleAdmins = @(
            $privilegedAdmins |
                Where-Object {
                    $lastSignIn = $null
                    $lastSignInText = [string]$_.LastSignInDateTime
                    if (-not [string]::IsNullOrWhiteSpace($lastSignInText)) {
                        $parsedLastSignIn = [datetime]::MinValue
                        if ([datetime]::TryParse($lastSignInText, [ref]$parsedLastSignIn)) {
                            $lastSignIn = $parsedLastSignIn
                        }
                    }
                    ($_.AccountEnabled -eq $true) -and $lastSignIn -and ($lastSignIn -lt (Get-Date).AddDays(-90))
                }
        )
        $guestAdmins = @(
            $privilegedAdmins |
                Where-Object {
                    ([string]$_.UserPrincipalName -like '*#EXT#*') -or ([string]$_.UserType).ToLowerInvariant() -eq 'guest'
                }
        )
        $script:tenantStatsHash["PrivilegedAccessSummary"]["Summary"] = [PSCustomObject]@{
            TotalPrivilegedIdentities = $privilegedAdmins.Count
            StalePrivilegedAccounts90Days = $staleAdmins.Count
            GuestPrivilegedAccounts   = $guestAdmins.Count
            GlobalAdministratorCount  = @($privilegedAdmins | Where-Object { ([string]$_.Role) -match 'Global Administrator' }).Count
        }
        
    } catch {
        Write-Log -Type ERROR -Message "An error occurred checking authentication configuration. $($_.Exception.Message)" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
    }
    
    $CompletedTime = (((Get-Date) - $start).ToString('hh\:mm\:ss'))
    Write-AssessmentCollectorCompletionBanner -Message "Completed in $($CompletedTime)"
    Write-Log -Type INFO -Message "[Get-AuthenticationConfiguration] COMPLETED: Checking Authentication Configuration in $($CompletedTime)" -ExportFileLocation $ExportDetails
}

function Get-TenantOverviewInfo {
    [CmdletBinding()]
    param ()

    $start = Get-Date
    if (-not $script:tenantStatsHash) { $script:tenantStatsHash = @{} }
    $script:tenantStatsHash["TenantInfo"] = @{}

    Write-AssessmentCollectorBanner -Message 'Gathering Tenant Overview Info ...' -NoNewline
    Write-Log -Type INFO -Message "[Get-TenantOverviewInfo] START: Gathering tenant overview information" -ExportFileLocation $ExportDetails

    try {
        $org = Get-AssessmentTenantOrganization

        $initialDomain = $null
        $defaultDomain = $null
        $verifiedDomains = @()
        if ($org -and $org.PSObject.Properties['VerifiedDomains']) {
            $verifiedDomains = $org.VerifiedDomains
            $initial = $verifiedDomains | Where-Object { $_.IsInitial -eq $true } | Select-Object -First 1
            $default = $verifiedDomains | Where-Object { $_.IsDefault -eq $true } | Select-Object -First 1
            if ($initial) { $initialDomain = if ($initial.PSObject.Properties['Name']) { $initial.Name } else { $initial.Id } }
            if ($default) { $defaultDomain = if ($default.PSObject.Properties['Name']) { $default.Name } else { $default.Id } }
        }

        $multiGeoEnabled = $null
        $multiGeoAllowed = @()
        $multiGeoCentral = $null
        if ($org.PSObject.Properties['IsMultipleGeolocationEnabled']) {
            $multiGeoEnabled = [bool]$org.IsMultipleGeolocationEnabled
        }
        if ($org.PSObject.Properties['MultiGeoConfiguration'] -and $org.MultiGeoConfiguration) {
            $cfg = $org.MultiGeoConfiguration
            if ($cfg.PSObject.Properties['AllowedDataLocations'] -and $cfg.AllowedDataLocations) {
                $multiGeoAllowed = @($cfg.AllowedDataLocations)
                if ($multiGeoAllowed.Count -gt 1) { $multiGeoEnabled = $true }
            }
            if ($cfg.PSObject.Properties['PreferredDataLocation'] -and $cfg.PreferredDataLocation) {
                $multiGeoCentral = $cfg.PreferredDataLocation
            }
        }

        $selfServiceAnswer = "Not collected"
        $selfServiceNotes = "MSCommerce module not installed"
        $selfServiceDetails = $null
        $effectiveAuthenticationType = if (
            $script:AssessmentAuthWorkloadPlan -and
            $script:AssessmentAuthWorkloadPlan.PSObject.Properties['AuthenticationType'] -and
            -not [string]::IsNullOrWhiteSpace([string]$script:AssessmentAuthWorkloadPlan.AuthenticationType)
        ) {
            [string]$script:AssessmentAuthWorkloadPlan.AuthenticationType
        } else {
            'Unknown'
        }

        if ($effectiveAuthenticationType -ne 'Interactive') {
            $selfServiceAnswer = 'Not validated in current auth mode'
            $selfServiceNotes = "MSCommerce self-service purchase review is skipped for $effectiveAuthenticationType assessment runs."
        }
        else {
            $selfServiceErrorCountBeforeLookup = $global:Error.Count
            try {
                $msCommerceModule = Get-Module -ListAvailable -Name MSCommerce | Sort-Object Version -Descending | Select-Object -First 1
                if (-not $msCommerceModule) {
                    Write-Log -Type INFO -Message "[Get-TenantOverviewInfo] Installing MSCommerce module (CurrentUser)" -ExportFileLocation $ExportDetails
                    Install-Module -Name MSCommerce -Scope CurrentUser -Force -ErrorAction Stop
                    $msCommerceModule = Get-Module -ListAvailable -Name MSCommerce | Sort-Object Version -Descending | Select-Object -First 1
                }

                if (-not $msCommerceModule) {
                    throw 'MSCommerce module could not be resolved after installation.'
                }

                if (-not (Get-Module -Name MSCommerce)) {
                    $msCommerceImportTarget = if (-not [string]::IsNullOrWhiteSpace([string]$msCommerceModule.Path)) {
                        [string]$msCommerceModule.Path
                    } else {
                        'MSCommerce'
                    }

                    if ($PSVersionTable.PSVersion.Major -ge 6) {
                        try {
                            Import-Module -Name $msCommerceImportTarget -ErrorAction Stop
                        } catch {
                            Import-Module MSCommerce -UseWindowsPowerShell -ErrorAction Stop
                        }
                    } else {
                        Import-Module -Name $msCommerceImportTarget -ErrorAction Stop
                    }
                }

                try {
                    Connect-MSCommerce -ErrorAction Stop | Out-Null
                    $sspPolicies = Get-MSCommerceProductPolicies -PolicyId AllowSelfServicePurchase -ErrorAction Stop
                    if ($sspPolicies -and $sspPolicies.Count -gt 0) {
                        $enabled = ($sspPolicies | Where-Object { $_.Value -eq 'Enabled' }).Count
                        $disabled = ($sspPolicies | Where-Object { $_.Value -eq 'Disabled' }).Count
                        $trialOnly = ($sspPolicies | Where-Object { $_.Value -eq 'OnlyTrialsWithoutPaymentMethod' }).Count
                        $total = $sspPolicies.Count
                        if ($enabled -gt 0) {
                            $selfServiceAnswer = "Yes (Enabled for $enabled/$total products)"
                        } else {
                            $selfServiceAnswer = "No (Disabled for all $total products)"
                        }
                        $selfServiceNotes = "Disabled: $disabled; Trial-only: $trialOnly"
                        $selfServiceDetails = [PSCustomObject]@{
                            EnabledCount = $enabled
                            DisabledCount = $disabled
                            TrialOnlyCount = $trialOnly
                            TotalCount = $total
                        }
                    } else {
                        $selfServiceAnswer = "Unknown"
                        $selfServiceNotes = "No policy data returned"
                    }
                } catch {
                    $selfServiceAnswer = "Unknown"
                    $selfServiceNotes = "MSCommerce connection or policy retrieval failed: $($_.Exception.Message)"
                }
            } catch {
                if ($global:Error.Count -gt $selfServiceErrorCountBeforeLookup) {
                    while ($global:Error.Count -gt $selfServiceErrorCountBeforeLookup) {
                        $global:Error.RemoveAt(0)
                    }
                }
                $selfServiceAnswer = "Unknown"
                $selfServiceNotes = "MSCommerce module install/load failed: $($_.Exception.Message)"
            }
        }

        $azureAnswer = "Not collected"
        $azureNotes = "Azure module not used in this report"
        $azureDetails = $null

        $script:tenantStatsHash["TenantInfo"] = [PSCustomObject]@{
            DisplayName           = $org.DisplayName
            TenantId              = $org.Id
            InitialDomain         = $initialDomain
            DefaultDomain         = $defaultDomain
            PreferredDataLocation = $org.PreferredDataLocation
            Country               = $org.Country
            CountryLetterCode     = $org.CountryLetterCode
            MultiGeoEnabled       = $multiGeoEnabled
            MultiGeoAllowed       = $multiGeoAllowed
            MultiGeoCentral       = $multiGeoCentral
            SelfServicePurchase   = [PSCustomObject]@{
                Answer = $selfServiceAnswer
                Notes = $selfServiceNotes
                Details = $selfServiceDetails
            }
            AzureResourceUsage    = [PSCustomObject]@{
                Answer = $azureAnswer
                Notes = $azureNotes
                Details = $azureDetails
            }
        }

        Write-Log -Type INFO -Message "[Get-TenantOverviewInfo] Retrieved tenant info for $($org.DisplayName)" -ExportFileLocation $ExportDetails
    } catch {
        Write-Log -Type WARNING -Message "[Get-TenantOverviewInfo] Unable to retrieve tenant overview info: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
    }

    $elapsed = ((Get-Date) - $start).ToString('hh\:mm\:ss')
    Write-AssessmentCollectorCompletionBanner -Message "Completed in $($elapsed)"
    Write-Log -Type INFO -Message "[Get-TenantOverviewInfo] COMPLETED in $elapsed" -ExportFileLocation $ExportDetails
}

function Get-AdConnectSyncDetails {
    [CmdletBinding()]
    param ()
    
    $start = Get-Date
    if (-not $script:tenantStatsHash) { $script:tenantStatsHash = @{} }
    $script:tenantStatsHash["AdConnectConfiguration"] = @{}
    
    Write-AssessmentCollectorBanner -Message 'Checking AD Connect/Sync status ...' -NoNewline
    Write-Log -Type INFO -Message "[Get-AdConnectSyncDetails] START" -ExportFileLocation $ExportDetails
    
    try {
        $org = $null
        try { $org = Get-AssessmentTenantOrganization } catch {}
        
        $getNamedPropertyValue = {
            param(
                $Object,
                [string[]]$Names
            )

            if ($null -eq $Object) {
                return $null
            }

            foreach ($name in $Names) {
                if ($Object -is [System.Collections.IDictionary] -and $Object.Contains($name)) {
                    return $Object[$name]
                }

                $matchedProperty = @($Object.PSObject.Properties.Match($name) | Select-Object -First 1)
                if ($matchedProperty.Count -gt 0) {
                    return $matchedProperty[0].Value
                }

                if (-not [string]::IsNullOrWhiteSpace($name)) {
                    $camelName = if ($name.Length -gt 1) {
                        '{0}{1}' -f $name.Substring(0, 1).ToLowerInvariant(), $name.Substring(1)
                    }
                    else {
                        $name.ToLowerInvariant()
                    }

                    $camelProperty = @($Object.PSObject.Properties.Match($camelName) | Select-Object -First 1)
                    if ($camelProperty.Count -gt 0) {
                        return $camelProperty[0].Value
                    }
                }
            }

            return $null
        }

        $firstPopulatedValue = {
            param([object[]]$Values)

            foreach ($value in $Values) {
                if ($null -eq $value) {
                    continue
                }
                if ($value -is [string] -and [string]::IsNullOrWhiteSpace($value)) {
                    continue
                }
                return $value
            }

            return $null
        }

        $summary = [pscustomobject]@{
            OnPremisesSyncEnabled                     = if ($org) { $org.OnPremisesSyncEnabled } else { $null }
            OnPremisesLastSyncDateTime               = if ($org) { $org.OnPremisesLastSyncDateTime } else { $null }
            PasswordSyncEnabled                      = $null
            PasswordWritebackEnabled                 = $null
            CloudPasswordPolicyForPasswordSyncedUsersEnabled = $null
            UserForcePasswordChangeOnLogonEnabled    = $null
            DeviceWritebackEnabled                   = $null
            UnifiedGroupWritebackEnabled             = $null
            UserWritebackEnabled                     = $null
            PassThroughAuthenticationEnabled         = $null
        }
        
        $serviceDetails = @()
        $syncErrors = @()

        $syncFeatureCollectionNote = $null
        $syncFeatureErrorCountBeforeFetch = $global:Error.Count
        try {
            $syncServiceResponse = $null
            if (Get-Command Get-MgDirectoryOnPremiseSynchronization -ErrorAction SilentlyContinue) {
                $syncServiceResponse = Get-MgDirectoryOnPremiseSynchronization -ErrorAction Stop
            }
            elseif ($global:GraphHeaders) {
                $syncServiceResponse = Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/directory/onPremisesSynchronization' -Activity 'Fetching directory synchronization service features'
            }

            $syncServiceObject = @($syncServiceResponse) | Select-Object -First 1
            if ($syncServiceObject) {
                $features = $null
                if ($syncServiceObject.PSObject.Properties['Features']) {
                    $features = $syncServiceObject.Features
                } elseif ($syncServiceObject.PSObject.Properties['features']) {
                    $features = $syncServiceObject.features
                }

                if ($features) {
                    foreach ($mapping in @(
                        @{ Summary = 'PasswordSyncEnabled'; PropertyNames = @('PasswordSyncEnabled', 'PasswordHashSyncEnabled') },
                        @{ Summary = 'PasswordWritebackEnabled'; PropertyNames = @('PasswordWritebackEnabled') },
                        @{ Summary = 'CloudPasswordPolicyForPasswordSyncedUsersEnabled'; PropertyNames = @('CloudPasswordPolicyForPasswordSyncedUsersEnabled') },
                        @{ Summary = 'UserForcePasswordChangeOnLogonEnabled'; PropertyNames = @('UserForcePasswordChangeOnLogonEnabled') },
                        @{ Summary = 'DeviceWritebackEnabled'; PropertyNames = @('DeviceWritebackEnabled') },
                        @{ Summary = 'UnifiedGroupWritebackEnabled'; PropertyNames = @('UnifiedGroupWritebackEnabled') },
                        @{ Summary = 'UserWritebackEnabled'; PropertyNames = @('UserWritebackEnabled') },
                        @{ Summary = 'PassThroughAuthenticationEnabled'; PropertyNames = @('PassThroughAuthenticationEnabled', 'PassthroughAuthenticationEnabled', 'PassThroughAuthentication') }
                    )) {
                        $featureValue = & $getNamedPropertyValue $features $mapping.PropertyNames
                        if ($null -ne $featureValue) {
                            try {
                                $summary.$($mapping.Summary) = [bool]$featureValue
                            }
                            catch {
                                $summary.$($mapping.Summary) = $featureValue
                            }
                        }
                    }
                }
            }
        }
        catch {
            $syncFeatureCollectionNote = if ($_.Exception.Message -match 'Authorization_RequestDenied|Insufficient privileges|403 Forbidden') {
                'Not available in current auth mode'
            } else {
                'Not surfaced in current source'
            }
            if ($global:Error.Count -gt $syncFeatureErrorCountBeforeFetch) {
                while ($global:Error.Count -gt $syncFeatureErrorCountBeforeFetch) {
                    $global:Error.RemoveAt(0)
                }
            }
            Write-Log -Type DEBUG -Message "[Get-AdConnectSyncDetails] Unable to retrieve directory synchronization feature flags: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }

        $existingPasswordLifecycleSummary = $null
        if ($script:tenantStatsHash.ContainsKey("PasswordLifecycleSummary")) {
            $existingPasswordLifecycleSummary = $script:tenantStatsHash["PasswordLifecycleSummary"]
        }

        $passwordFeatureFallback = $null
        if ($summary.OnPremisesSyncEnabled -eq $true -and -not [string]::IsNullOrWhiteSpace($syncFeatureCollectionNote)) {
            $passwordFeatureFallback = $syncFeatureCollectionNote
        }

        $script:tenantStatsHash["PasswordLifecycleSummary"] = [pscustomobject]@{
            PasswordWriteback                          = & $firstPopulatedValue @($summary.PasswordWritebackEnabled, (Get-ArrayaObjectValue -Object $existingPasswordLifecycleSummary -Names @('PasswordWriteback', 'PasswordWritebackEnabled')), $passwordFeatureFallback)
            PasswordWritebackEnabled                   = & $firstPopulatedValue @($summary.PasswordWritebackEnabled, (Get-ArrayaObjectValue -Object $existingPasswordLifecycleSummary -Names @('PasswordWritebackEnabled', 'PasswordWriteback')), $passwordFeatureFallback)
            PasswordSyncEnabled                        = & $firstPopulatedValue @($summary.PasswordSyncEnabled, (Get-ArrayaObjectValue -Object $existingPasswordLifecycleSummary -Names @('PasswordSyncEnabled', 'PasswordHashSyncEnabled')), $passwordFeatureFallback)
            CloudPasswordPolicyForPasswordSyncedUsersEnabled = & $firstPopulatedValue @($summary.CloudPasswordPolicyForPasswordSyncedUsersEnabled, (Get-ArrayaObjectValue -Object $existingPasswordLifecycleSummary -Names @('CloudPasswordPolicyForPasswordSyncedUsersEnabled')), $passwordFeatureFallback)
            UserForcePasswordChangeOnLogonEnabled      = & $firstPopulatedValue @($summary.UserForcePasswordChangeOnLogonEnabled, (Get-ArrayaObjectValue -Object $existingPasswordLifecycleSummary -Names @('UserForcePasswordChangeOnLogonEnabled')), $passwordFeatureFallback)
            PassThroughAuthentication                  = & $firstPopulatedValue @($summary.PassThroughAuthenticationEnabled, (Get-ArrayaObjectValue -Object $existingPasswordLifecycleSummary -Names @('PassThroughAuthentication', 'PassThroughAuthenticationEnabled')), $passwordFeatureFallback)
            PassThroughAuthenticationEnabled           = & $firstPopulatedValue @($summary.PassThroughAuthenticationEnabled, (Get-ArrayaObjectValue -Object $existingPasswordLifecycleSummary -Names @('PassThroughAuthenticationEnabled', 'PassThroughAuthentication')), $passwordFeatureFallback)
            SelfServicePasswordReset                   = & $firstPopulatedValue @((Get-ArrayaObjectValue -Object $existingPasswordLifecycleSummary -Names @('SelfServicePasswordReset', 'SelfServicePasswordResetEnabled')))
            SelfServicePasswordResetEnabled            = & $firstPopulatedValue @((Get-ArrayaObjectValue -Object $existingPasswordLifecycleSummary -Names @('SelfServicePasswordResetEnabled', 'SelfServicePasswordReset')))
            DeviceWritebackEnabled                     = & $firstPopulatedValue @($summary.DeviceWritebackEnabled, (Get-ArrayaObjectValue -Object $existingPasswordLifecycleSummary -Names @('DeviceWritebackEnabled')), $passwordFeatureFallback)
            UnifiedGroupWritebackEnabled               = & $firstPopulatedValue @($summary.UnifiedGroupWritebackEnabled, (Get-ArrayaObjectValue -Object $existingPasswordLifecycleSummary -Names @('UnifiedGroupWritebackEnabled')), $passwordFeatureFallback)
            UserWritebackEnabled                       = & $firstPopulatedValue @($summary.UserWritebackEnabled, (Get-ArrayaObjectValue -Object $existingPasswordLifecycleSummary -Names @('UserWritebackEnabled')), $passwordFeatureFallback)
            OnPremisesSyncEnabled                      = & $firstPopulatedValue @($summary.OnPremisesSyncEnabled, (Get-ArrayaObjectValue -Object $existingPasswordLifecycleSummary -Names @('OnPremisesSyncEnabled')))
            OnPremisesLastSyncDateTime                 = & $firstPopulatedValue @($summary.OnPremisesLastSyncDateTime, (Get-ArrayaObjectValue -Object $existingPasswordLifecycleSummary -Names @('OnPremisesLastSyncDateTime')))
            FeatureCollectionNote                      = $syncFeatureCollectionNote
        }
        
        $healthSyncServicesCommand = Get-Command Get-AzureADConnectHealthSyncServices -ErrorAction Ignore
        $healthSyncErrorsCommand = Get-Command Get-AzureADConnectHealthSyncErrors -ErrorAction Ignore
        $healthSyncAlertCommand = Get-Command Get-AzureADConnectHealthSyncAlert -ErrorAction Ignore

        if ($healthSyncServicesCommand) {
            try {
                $services = Get-AzureADConnectHealthSyncServices -ErrorAction SilentlyContinue
                foreach ($svc in $services) {
                    $serviceName = if ($svc.PSObject.Properties['ServiceName']) { $svc.ServiceName } elseif ($svc.PSObject.Properties['Name']) { $svc.Name } else { $null }
                    $serverName = if ($svc.PSObject.Properties['ServerName']) { $svc.ServerName } elseif ($svc.PSObject.Properties['Server']) { $svc.Server } else { $null }
                    $lastSync = if ($svc.PSObject.Properties['LastSyncTime']) { $svc.LastSyncTime } elseif ($svc.PSObject.Properties['LastSyncDateTime']) { $svc.LastSyncDateTime } else { $null }
                    $serviceDetails += [pscustomobject]@{
                        ServiceName = $serviceName
                        ServerName = $serverName
                        LastSyncTime = $lastSync
                    }
                }
            } catch {}
        }
        
        if ($healthSyncErrorsCommand) {
            try {
                $syncErrors = Get-AzureADConnectHealthSyncErrors -ErrorAction SilentlyContinue
            } catch {}
        } elseif ($healthSyncAlertCommand) {
            try {
                $syncErrors = Get-AzureADConnectHealthSyncAlert -ErrorAction SilentlyContinue
            } catch {}
        }
        
        $script:tenantStatsHash["AdConnectConfiguration"]["Summary"] = $summary
        $script:tenantStatsHash["AdConnectConfiguration"]["SyncServices"] = $serviceDetails
        $script:tenantStatsHash["AdConnectConfiguration"]["RecentErrors"] = $syncErrors | Select-Object -First 10
        $script:tenantStatsHash["AdConnectConfiguration"]["ErrorCount"] = ($syncErrors | Measure-Object).Count
        
        Write-Log -Type INFO -Message "[Get-AdConnectSyncDetails] DirSyncEnabled=$($summary.OnPremisesSyncEnabled) LastSync=$($summary.OnPremisesLastSyncDateTime) Services=$($serviceDetails.Count) Errors=$(($syncErrors | Measure-Object).Count)" -ExportFileLocation $ExportDetails
    } catch {
        Write-Log -Type WARNING -Message "[Get-AdConnectSyncDetails] Error: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
    }
    
    $elapsed = ((Get-Date) - $start).ToString('hh\:mm\:ss')
    Write-AssessmentCollectorCompletionBanner -Message " Completed in $elapsed"
    Write-Log -Type INFO -Message "[Get-AdConnectSyncDetails] COMPLETED in $elapsed" -ExportFileLocation $ExportDetails
}

function Get-AssessmentInitialDomainName {
    [CmdletBinding()]
    param()

    if ($connectionResult -and $connectionResult.PSObject.Properties['InitialDomain'] -and -not [string]::IsNullOrWhiteSpace([string]$connectionResult.InitialDomain)) {
        return [string]$connectionResult.InitialDomain
    }

    if (
        $script:tenantStatsHash -and
        $script:tenantStatsHash.ContainsKey('TenantInfo') -and
        $script:tenantStatsHash['TenantInfo']
    ) {
        $tenantInfo = $script:tenantStatsHash['TenantInfo']
        foreach ($candidateName in @('DefaultDomainName', 'InitialDomain', 'DefaultDomain')) {
            $candidateValue = Get-ArrayaObjectValue -Object $tenantInfo -Names @($candidateName)
            if (-not [string]::IsNullOrWhiteSpace([string]$candidateValue)) {
                return [string]$candidateValue
            }
        }
    }

    try {
        $org = Get-AssessmentTenantOrganization
        if ($org -and $org.PSObject.Properties['VerifiedDomains']) {
            $initialDomain = @($org.VerifiedDomains | Where-Object { $_.IsInitial -eq $true } | Select-Object -First 1)
            if ($initialDomain.Count -gt 0) {
                $candidateValue = Get-ArrayaObjectValue -Object $initialDomain[0] -Names @('Name', 'Id')
                if (-not [string]::IsNullOrWhiteSpace([string]$candidateValue)) {
                    return [string]$candidateValue
                }
            }
        }
    }
    catch {}

    return $null
}

function Ensure-PurviewComplianceCommandAvailable {
    [CmdletBinding()]
    param()

    $connectCommand = Get-Command -Name 'Connect-IPPSSession' -ErrorAction SilentlyContinue
    if ($connectCommand) {
        return $connectCommand
    }

    if (-not (Get-Module -ListAvailable -Name 'ExchangeOnlineManagement')) {
        Write-Log -Type WARNING -Message "[Ensure-PurviewComplianceCommandAvailable] ExchangeOnlineManagement is not installed. Purview retention/DLP collection requires Connect-IPPSSession from that module." -ExportFileLocation $ExportDetails
        return $null
    }

    if (-not (Get-Module -Name 'ExchangeOnlineManagement')) {
        try {
            Write-Log -Type INFO -Message "[Ensure-PurviewComplianceCommandAvailable] Importing ExchangeOnlineManagement so Connect-IPPSSession is available for Purview compliance collection." -ExportFileLocation $ExportDetails
            Import-Module 'ExchangeOnlineManagement' -ErrorAction Stop -WarningAction SilentlyContinue
        }
        catch {
            Write-Log -Type WARNING -Message "[Ensure-PurviewComplianceCommandAvailable] Failed to import ExchangeOnlineManagement for Purview compliance collection: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
            return $null
        }
    }

    return (Get-Command -Name 'Connect-IPPSSession' -ErrorAction SilentlyContinue)
}

function Set-PurviewComplianceDiagnosticState {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Status,
        [Parameter(Mandatory = $true)]
        [string]$Message,
        [Parameter(Mandatory = $false)]
        [string]$Guidance,
        [Parameter(Mandatory = $false)]
        [string]$AuthPath,
        [Parameter(Mandatory = $false)]
        [string]$Organization,
        [Parameter(Mandatory = $false)]
        [string[]]$MissingCommands = @()
    )

    $script:PurviewComplianceSessionDiagnostic = [pscustomobject][ordered]@{
        Status          = $Status
        Message         = $Message
        Guidance        = $Guidance
        AuthPath        = $AuthPath
        Organization    = $Organization
        MissingCommands = @($MissingCommands | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    }
}

function Get-PurviewComplianceDiagnosticMessage {
    [CmdletBinding()]
    param()

    $diagnostic = $script:PurviewComplianceSessionDiagnostic
    if (-not $diagnostic) {
        return $null
    }

    $parts = New-Object System.Collections.Generic.List[string]
    if (-not [string]::IsNullOrWhiteSpace([string]$diagnostic.Message)) {
        $parts.Add([string]$diagnostic.Message) | Out-Null
    }
    if (-not [string]::IsNullOrWhiteSpace([string]$diagnostic.AuthPath)) {
        $parts.Add("Auth path: $($diagnostic.AuthPath).") | Out-Null
    }
    if (-not [string]::IsNullOrWhiteSpace([string]$diagnostic.Organization)) {
        $parts.Add("Organization used: $($diagnostic.Organization).") | Out-Null
    }
    if ($diagnostic.MissingCommands -and @($diagnostic.MissingCommands).Count -gt 0) {
        $parts.Add("Missing compliance cmdlets after connect: $((@($diagnostic.MissingCommands) -join ', ')).") | Out-Null
    }
    if (-not [string]::IsNullOrWhiteSpace([string]$diagnostic.Guidance)) {
        $parts.Add("Next step: $($diagnostic.Guidance)") | Out-Null
    }

    return ($parts -join ' ')
}

function Ensure-PurviewComplianceSession {
    [CmdletBinding()]
    param()

    if ($script:PurviewComplianceSessionInitialized) {
        return [bool]$script:PurviewComplianceSessionAvailable
    }

    $script:PurviewComplianceSessionInitialized = $true
    $script:PurviewComplianceSessionAvailable = $false
    $script:PurviewComplianceSessionDiagnostic = $null

    $requiredComplianceCommands = @('Get-RetentionCompliancePolicy', 'Get-DlpCompliancePolicy')
    $existingComplianceCommands = @(
        $requiredComplianceCommands | Where-Object { Get-Command -Name $_ -ErrorAction SilentlyContinue }
    )
    if ($existingComplianceCommands.Count -eq $requiredComplianceCommands.Count) {
        Set-PurviewComplianceDiagnosticState -Status 'AlreadyAvailable' -Message 'Purview compliance cmdlets are already available in the current session.' -AuthPath 'Existing session'
        $script:PurviewComplianceSessionAvailable = $true
        return $true
    }

    $connectCommand = Ensure-PurviewComplianceCommandAvailable
    if (-not $connectCommand) {
        Set-PurviewComplianceDiagnosticState `
            -Status 'MissingConnectCommand' `
            -Message 'Connect-IPPSSession is unavailable in the current session.' `
            -Guidance "Install or import ExchangeOnlineManagement on the execution host, then rerun the assessment." `
            -AuthPath 'Unavailable'
        Write-Log -Type WARNING -Message "[Ensure-PurviewComplianceSession] Connect-IPPSSession is unavailable. Retention/DLP policy collection will be skipped." -ExportFileLocation $ExportDetails
        return $false
    }

    $connectParams = @{
        ErrorAction = 'Stop'
    }
    $purviewAuthPath = 'Interactive'
    $organization = $null
    if (
        $connectCommand.Parameters.ContainsKey('CommandName') -and
        (-not [string]::IsNullOrWhiteSpace($CertificateThumbprint))
    ) {
        $connectParams.CommandName = @('Get-RetentionCompliancePolicy', 'Get-DlpCompliancePolicy')
    }
    if ($connectCommand.Parameters.ContainsKey('ShowBanner')) {
        $connectParams.ShowBanner = $false
    }

    function Invoke-PurviewComplianceDelegatedConnect {
        param(
            [Parameter(Mandatory = $true)]
            [hashtable]$BaseParameters,
            [Parameter(Mandatory = $true)]
            $ConnectCommandMetadata
        )

        $attempts = New-Object System.Collections.Generic.List[hashtable]
        $attempts.Add(@{
            Label = 'interactive authentication'
            AuthPath = 'Interactive'
            Params = @{}
        }) | Out-Null

        if ($ConnectCommandMetadata.Parameters.ContainsKey('DisableWAM')) {
            $attempts.Add(@{
                Label = 'interactive authentication with -DisableWAM'
                AuthPath = 'Interactive (DisableWAM)'
                Params = @{ DisableWAM = $true }
            }) | Out-Null
        }

        if ($ConnectCommandMetadata.Parameters.ContainsKey('Device')) {
            $deviceParams = @{ Device = $true }
            $attempts.Add(@{
                Label = 'device code authentication'
                AuthPath = 'Interactive (DeviceCode)'
                Params = $deviceParams
            }) | Out-Null
        }

        Write-AssessmentInteractiveAuthNotice -ServiceName 'Purview compliance PowerShell' -SupportsDisableWam:$ConnectCommandMetadata.Parameters.ContainsKey('DisableWAM') -SupportsDeviceCode:$ConnectCommandMetadata.Parameters.ContainsKey('Device')
        if (-not $ConnectCommandMetadata.Parameters.ContainsKey('Device')) {
            Write-Log -Type INFO -Message '[Ensure-PurviewComplianceSession] Connect-IPPSSession does not expose device code in this ExchangeOnlineManagement version; interactive and -DisableWAM are available.' -ExportFileLocation $ExportDetails
        }

        $lastFailure = $null
        foreach ($attempt in $attempts) {
            $attemptParams = @{}
            foreach ($key in $BaseParameters.Keys) {
                $attemptParams[$key] = $BaseParameters[$key]
            }
            foreach ($key in $attempt.Params.Keys) {
                $attemptParams[$key] = $attempt.Params[$key]
            }

            try {
                if ($attempt.Label -eq 'interactive authentication') {
                    Write-Log -Type INFO -Message "[Ensure-PurviewComplianceSession] Attempting Purview compliance PowerShell connection with $($attempt.Label)." -ExportFileLocation $ExportDetails
                }
                else {
                    Write-Log -Type WARNING -Message "[Ensure-PurviewComplianceSession] Purview compliance PowerShell connection failed. Retrying with $($attempt.Label)." -ExportFileLocation $ExportDetails
                    $retryContextMessage = if ($lastFailure -and (Test-IsAssessmentInteractiveTokenAcquisitionFailure -Message $lastFailure.Exception.Message)) {
                        switch ($attempt.Label) {
                            'interactive authentication with -DisableWAM' {
                                'Purview auth: interactive sign-in hit a Windows broker / WAM token issue, retrying with -DisableWAM'
                            }
                            'device code authentication' {
                                'Purview auth: interactive sign-in hit a Windows broker / WAM token issue, retrying with device code'
                            }
                            default {
                                "Purview auth: retrying with $($attempt.Label) after a broker / WAM token issue"
                            }
                        }
                    }
                    else {
                        switch ($attempt.Label) {
                            'interactive authentication with -DisableWAM' { 'Purview auth: retrying interactive sign-in with -DisableWAM' }
                            'device code authentication' { 'Purview auth: retrying with device code authentication' }
                            default { "Purview auth: retrying with $($attempt.Label)" }
                        }
                    }
                    Write-AssessmentConsoleSubstep -Message $retryContextMessage -ForegroundColor 'Yellow'
                }

                Connect-IPPSSession @attemptParams | Out-Null
                return [pscustomobject]@{
                    Success = $true
                    AuthPath = $attempt.AuthPath
                    LastError = $null
                }
            }
            catch {
                $lastFailure = $_
            }
        }

        return [pscustomobject]@{
            Success = $false
            AuthPath = $(if ($attempts.Count -gt 0) { $attempts[$attempts.Count - 1].AuthPath } else { 'Interactive' })
            LastError = $lastFailure
        }
    }

    try {
        if (-not [string]::IsNullOrWhiteSpace($CertificateThumbprint)) {
            $purviewAuthPath = 'Certificate'
            $organization = Get-AssessmentInitialDomainName
            if ([string]::IsNullOrWhiteSpace($ClientId) -or [string]::IsNullOrWhiteSpace($organization)) {
                Set-PurviewComplianceDiagnosticState `
                    -Status 'MissingCertificateInputs' `
                    -Message 'Certificate-based Purview collection requires both the application ClientId and the tenant initial domain.' `
                    -Guidance "Confirm the assessment app registration AppId is supplied and that the tenant initial domain can be resolved from the current tenant context." `
                    -AuthPath $purviewAuthPath `
                    -Organization $organization
                throw "Certificate-based Purview collection requires both the application ClientId and the tenant initial domain."
            }

            $connectParams.AppId = $ClientId
            $connectParams.Organization = $organization
            $connectParams.CertificateThumbprint = $CertificateThumbprint
            Connect-IPPSSession @connectParams | Out-Null
            Set-PurviewComplianceDiagnosticState -Status 'Connected' -Message 'Connected to Purview compliance PowerShell using certificate authentication.' -AuthPath $purviewAuthPath -Organization $organization
            Write-Log -Type INFO -Message "[Ensure-PurviewComplianceSession] Connected to Purview compliance PowerShell using certificate authentication." -ExportFileLocation $ExportDetails
        }
        elseif (
            -not [string]::IsNullOrWhiteSpace($ClientSecret) -or
            $null -ne $ClientSecretCredential -or
            $null -ne $ClientSecretSecure
        ) {
            Set-PurviewComplianceDiagnosticState `
                -Status 'UnsupportedClientSecret' `
                -Message 'Client secret authentication is not supported for Purview compliance PowerShell in this workflow.' `
                -Guidance 'Use delegated authentication or certificate-based authentication for retention and DLP policy collection.' `
                -AuthPath 'ClientSecret'
            Write-Log -Type INFO -Message "[Ensure-PurviewComplianceSession] Client secret authentication is not supported for Purview compliance PowerShell in this workflow." -ExportFileLocation $ExportDetails
            return $false
        }
        else {
            $delegatedConnectResult = Invoke-PurviewComplianceDelegatedConnect -BaseParameters $connectParams -ConnectCommandMetadata $connectCommand
            if (-not $delegatedConnectResult.Success) {
                if ($delegatedConnectResult.LastError) {
                    throw $delegatedConnectResult.LastError
                }
                throw 'Purview delegated authentication did not complete successfully.'
            }

            $purviewAuthPath = [string]$delegatedConnectResult.AuthPath
            Set-PurviewComplianceDiagnosticState -Status 'Connected' -Message ("Connected to Purview compliance PowerShell using {0} authentication." -f $purviewAuthPath) -AuthPath $purviewAuthPath -Organization $organization
            Write-Log -Type INFO -Message ("[Ensure-PurviewComplianceSession] Connected to Purview compliance PowerShell using {0} authentication." -f $purviewAuthPath) -ExportFileLocation $ExportDetails
        }
    }
    catch {
        $underlyingError = [string]$_.Exception.Message
        $interactiveTokenIssue = ($purviewAuthPath -ne 'Certificate' -and (Test-IsAssessmentInteractiveTokenAcquisitionFailure -Message $underlyingError))
        $guidance = if ($purviewAuthPath -eq 'Certificate') {
            if ($underlyingError -match 'No cmdlet assigned to the user have this feature enabled') {
                'The certificate and app registration were accepted, but this tenant did not expose the Purview retention/DLP cmdlets to that app session. Update the service principal to include the Exchange Administrator role in this tenant, or establish Connect-IPPSSession successfully in the current PowerShell session and rerun the assessment with session reuse. Also confirm the target tenant is licensed and enabled for those compliance features.'
            }
            else {
                'Confirm the app registration has the required Purview / compliance PowerShell access, the certificate thumbprint is valid on this host, and the tenant initial domain used for -Organization is correct. If the app path remains blocked, update the service principal to include the Exchange Administrator role in this tenant or run Connect-IPPSSession successfully in the current session and rerun the assessment with session reuse.'
            }
        }
        elseif ($interactiveTokenIssue) {
            'Interactive Purview sign-in hit a Windows broker / WAM token acquisition failure. The assessment already tried the available delegated retries, including -DisableWAM and device code when supported. Next, try Connect-IPPSSession manually in a fresh PowerShell window. If that works, rerun the assessment with session reuse. If browser-based sign-in keeps failing on this host, complete the device code prompt in this console or switch to certificate-based authentication.'
        }
        else {
            'Confirm the signed-in operator can establish a compliance PowerShell session and that Connect-IPPSSession is allowed in this environment. If app-based Purview access is expected, update the service principal to include the Exchange Administrator role in the tenant.'
        }
        $diagnosticMessage = if ($interactiveTokenIssue) {
            "Purview compliance PowerShell interactive sign-in hit a Windows broker / WAM token acquisition failure. Underlying error: $underlyingError"
        }
        else {
            "Purview compliance PowerShell session could not be established. Underlying error: $underlyingError"
        }

        Set-PurviewComplianceDiagnosticState `
            -Status 'ConnectFailed' `
            -Message $diagnosticMessage `
            -Guidance $guidance `
            -AuthPath $purviewAuthPath `
            -Organization $organization
        Write-Log -Type WARNING -Message "[Ensure-PurviewComplianceSession] Unable to establish Purview compliance PowerShell session: $underlyingError" -ExportFileLocation $ExportDetails
        return $false
    }

    $existingComplianceCommands = @(
        $requiredComplianceCommands | Where-Object { Get-Command -Name $_ -ErrorAction SilentlyContinue }
    )
    $missingComplianceCommands = @(
        $requiredComplianceCommands | Where-Object { -not (Get-Command -Name $_ -ErrorAction SilentlyContinue) }
    )
    $script:PurviewComplianceSessionAvailable = ($existingComplianceCommands.Count -eq $requiredComplianceCommands.Count)
    if (-not $script:PurviewComplianceSessionAvailable) {
        Set-PurviewComplianceDiagnosticState `
            -Status 'MissingComplianceCmdletsAfterConnect' `
            -Message 'Purview compliance PowerShell connected, but the required retention/DLP cmdlets were not available afterward.' `
            -Guidance 'Confirm Connect-IPPSSession completed successfully for the target tenant and that the compliance cmdlets are exposed in the current session. If this is an app-based run, update the service principal to include the Exchange Administrator role in the tenant, or run Connect-IPPSSession successfully in the current PowerShell session and rerun the assessment with session reuse.' `
            -AuthPath $purviewAuthPath `
            -Organization $organization `
            -MissingCommands $missingComplianceCommands
    }
    return [bool]$script:PurviewComplianceSessionAvailable
}

function Get-PurviewCompliancePolicies {
    [CmdletBinding()]
    param()

    $start = Get-Date
    if (-not $script:tenantStatsHash) { $script:tenantStatsHash = @{} }
    $script:tenantStatsHash["RetentionPolicies"] = [ordered]@{}
    $script:tenantStatsHash["DlpPolicies"] = [ordered]@{}

    Write-Log -Type INFO -Message "[Get-PurviewCompliancePolicies] START" -ExportFileLocation $ExportDetails

    $formatComplianceValue = {
        param($Value)

        if ($null -eq $Value) {
            return 'Not surfaced in current source'
        }

        if ($Value -is [string]) {
            if ([string]::IsNullOrWhiteSpace($Value)) {
                return 'Not surfaced in current source'
            }

            return $Value
        }

        if ($Value -is [System.Collections.IEnumerable] -and -not ($Value -is [string])) {
            $rows = @($Value)
            if ($rows.Count -eq 0) {
                return 'None'
            }

            $displayValues = @(
                $rows |
                    Select-Object -First 3 |
                    ForEach-Object {
                        $candidate = Get-ArrayaObjectValue -Object $_ -Names @('DisplayName', 'Name', 'Id', 'Identity')
                        if ([string]::IsNullOrWhiteSpace([string]$candidate)) {
                            $candidate = [string]$_
                        }
                        $candidate
                    } |
                    Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }
            )

            if ($displayValues.Count -eq 0) {
                return ('{0} item(s)' -f $rows.Count)
            }

            if ($rows.Count -le 3) {
                return ($displayValues -join '; ')
            }

            return ('{0} item(s): {1}' -f $rows.Count, ($displayValues -join '; '))
        }

        return [string]$Value
    }

    try {
        if (-not (Ensure-PurviewComplianceSession)) {
            $message = if (-not (Get-Command -Name 'Connect-IPPSSession' -ErrorAction SilentlyContinue)) {
                'Connect-IPPSSession is unavailable in the current session.'
            }
            elseif (
                -not [string]::IsNullOrWhiteSpace($ClientSecret) -or
                $null -ne $ClientSecretCredential -or
                $null -ne $ClientSecretSecure
            ) {
                'Client secret authentication is not supported for Purview compliance PowerShell in this workflow.'
            }
            else {
                'Purview compliance PowerShell session could not be established.'
            }
            $purviewDiagnosticMessage = Get-PurviewComplianceDiagnosticMessage
            if (-not [string]::IsNullOrWhiteSpace($purviewDiagnosticMessage)) {
                $message = $purviewDiagnosticMessage
            }

            return (New-AssessmentStepResult -Status Skipped -Message $message)
        }

        $issues = New-Object System.Collections.Generic.List[string]
        $retentionCollected = $false
        $dlpCollected = $false

        try {
            if (Get-Command -Name 'Get-RetentionCompliancePolicy' -ErrorAction SilentlyContinue) {
                $retentionPolicies = @(Get-RetentionCompliancePolicy -ErrorAction Stop | Sort-Object -Property Name)
                $retentionCollected = $true
                $retentionIndex = 0
                foreach ($policy in $retentionPolicies) {
                    $policyName = Convert-ToAssessmentPathComponent -Value ([string](Get-ArrayaObjectValue -Object $policy -Names @('Name', 'Identity'))) -Fallback 'RetentionPolicy'
                    $retentionIndex++
                    $script:tenantStatsHash["RetentionPolicies"][("{0:D3}-{1}" -f $retentionIndex, $policyName)] = [pscustomobject]@{
                        PolicyName                 = Get-ArrayaObjectValue -Object $policy -Names @('Name', 'Identity')
                        Enabled                    = Get-ArrayaObjectValue -Object $policy -Names @('Enabled', 'IsEnabled')
                        Mode                       = Get-ArrayaObjectValue -Object $policy -Names @('Mode')
                        Workload                   = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('Workload', 'Workloads'))
                        Priority                   = Get-ArrayaObjectValue -Object $policy -Names @('Priority')
                        ExchangeLocation           = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('ExchangeLocation'))
                        SharePointLocation         = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('SharePointLocation'))
                        OneDriveLocation           = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('OneDriveLocation'))
                        TeamsChatLocation          = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('TeamsChatLocation'))
                        TeamsChannelLocation       = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('TeamsChannelLocation'))
                        ModernGroupLocation        = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('ModernGroupLocation'))
                        ExchangeLocationException  = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('ExchangeLocationException'))
                        SharePointLocationException = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('SharePointLocationException'))
                        OneDriveLocationException  = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('OneDriveLocationException'))
                        Comment                    = Get-ArrayaObjectValue -Object $policy -Names @('Comment', 'Description')
                    }
                }
            }
            else {
                $issues.Add('Retention policy cmdlet was not available after establishing the compliance session.') | Out-Null
            }
        }
        catch {
            $issues.Add("Retention policy collection failed: $($_.Exception.Message)") | Out-Null
        }

        try {
            if (Get-Command -Name 'Get-DlpCompliancePolicy' -ErrorAction SilentlyContinue) {
                $dlpPolicies = @(Get-DlpCompliancePolicy -ErrorAction Stop | Sort-Object -Property Name)
                $dlpCollected = $true
                $dlpIndex = 0
                foreach ($policy in $dlpPolicies) {
                    $policyName = Convert-ToAssessmentPathComponent -Value ([string](Get-ArrayaObjectValue -Object $policy -Names @('Name', 'Identity'))) -Fallback 'DlpPolicy'
                    $dlpIndex++
                    $script:tenantStatsHash["DlpPolicies"][("{0:D3}-{1}" -f $dlpIndex, $policyName)] = [pscustomobject]@{
                        PolicyName                  = Get-ArrayaObjectValue -Object $policy -Names @('Name', 'Identity')
                        Enabled                     = Get-ArrayaObjectValue -Object $policy -Names @('Enabled', 'IsEnabled')
                        Mode                        = Get-ArrayaObjectValue -Object $policy -Names @('Mode')
                        Workload                    = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('Workload', 'Workloads'))
                        ExchangeLocation            = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('ExchangeLocation'))
                        SharePointLocation          = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('SharePointLocation'))
                        OneDriveLocation            = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('OneDriveLocation'))
                        TeamsLocation               = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('TeamsLocation', 'TeamsChatLocation', 'TeamsChannelLocation'))
                        EndpointDlpLocation         = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('EndpointDlpLocation'))
                        ExchangeLocationException   = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('ExchangeLocationException'))
                        SharePointLocationException = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('SharePointLocationException'))
                        OneDriveLocationException   = & $formatComplianceValue (Get-ArrayaObjectValue -Object $policy -Names @('OneDriveLocationException'))
                        Comment                     = Get-ArrayaObjectValue -Object $policy -Names @('Comment', 'Description')
                    }
                }
            }
            else {
                $issues.Add('DLP policy cmdlet was not available after establishing the compliance session.') | Out-Null
            }
        }
        catch {
            $issues.Add("DLP policy collection failed: $($_.Exception.Message)") | Out-Null
        }

        $status = if ($issues.Count -eq 0) {
            'Completed'
        }
        elseif ($retentionCollected -or $dlpCollected) {
            'Partial'
        }
        else {
            'Skipped'
        }

        $message = if ($status -eq 'Completed') {
            'Retention policies={0}; DLP policies={1}' -f $script:tenantStatsHash["RetentionPolicies"].Count, $script:tenantStatsHash["DlpPolicies"].Count
        }
        else {
            ($issues -join '; ')
        }

        return (New-AssessmentStepResult -Status $status -Message $message)
    }
    catch {
        Write-Log -Type WARNING -Message "[Get-PurviewCompliancePolicies] Error: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        return (New-AssessmentStepResult -Status Partial -Message $_.Exception.Message)
    }
    finally {
        $elapsed = ((Get-Date) - $start).ToString('hh\:mm\:ss')
        Write-Log -Type INFO -Message "[Get-PurviewCompliancePolicies] COMPLETED in $elapsed" -ExportFileLocation $ExportDetails
    }
}

function Get-MfaRegistrationDetails {
    [CmdletBinding()]
    param ()
    
    $start = Get-Date
    if (-not $script:tenantStatsHash) { $script:tenantStatsHash = @{} }
    $script:tenantStatsHash["MfaRegistrationDetails"] = @{}
    $script:tenantStatsHash["MfaRegistrationSummary"] = $null
    $script:tenantStatsHash["MfaEnrollmentSummary"] = $null
    $script:tenantStatsHash["MfaEnforcementSummary"] = $null
    $script:tenantStatsHash["MfaEnforcementGapUsers"] = @{}
    $script:tenantStatsHash["MfaEnforcementScopeReview"] = @{}
    $script:tenantStatsHash["AdminMfaSummary"] = $null
    $script:tenantStatsHash["AdminMfaRegistrationGaps"] = @{}
    $script:tenantStatsHash["AdminMfaEnforcementGaps"] = @{}
    
    Write-AssessmentCollectorBanner -Message 'Gathering MFA registration details ...' -NoNewline
    Write-Log -Type INFO -Message "[Get-MfaRegistrationDetails] START: Gathering MFA registration details" -ExportFileLocation $ExportDetails
    
    try {
        $regData = @()
        try {
            if (Get-Command Get-MgReportAuthenticationMethodUserRegistrationDetail -ErrorAction SilentlyContinue) {
                $regData = Get-MgReportAuthenticationMethodUserRegistrationDetail -All -ProgressAction SilentlyContinue -ErrorAction Stop
            }
        } catch {}
        
        if (-not $regData -or $regData.Count -eq 0) {
            try {
                $uri = "https://graph.microsoft.com/v1.0/reports/authenticationMethods/userRegistrationDetails"
                $regData = Get-ArrayaGraphResource -Uri $uri -Activity "Fetching MFA Registration Details"
            } catch {
                Write-Log -Type WARNING -Message "[Get-MfaRegistrationDetails] Unable to retrieve registration report: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
            }
        }
        
        $methodCounts = @{}
        $weakMethodCounts = @{}
        $strongMethodCounts = @{}
        $phishingResistantMethodCounts = @{}
        $defaultMethodCounts = @{}
        $registeredUsers = 0
        $totalUsers = 0
        $usersWithWeakMethodsOnly = 0
        $usersWithWeakDefaultMethod = 0
        $usersWithStrongMethods = 0
        $usersWithPhishingResistantMethods = 0
        
        foreach ($user in $regData) {
            $totalUsers++
            $upn = $user.UserPrincipalName
            $methods = @()
            if ($user.MethodsRegistered) {
                $methods = @($user.MethodsRegistered)
            }

            $userHasWeakMethod = $false
            $userHasStrongMethod = $false
            $userHasPhishingResistantMethod = $false

            foreach ($m in $methods) {
                $methodProfile = Get-AssessmentMfaMethodProfile -MethodName ([string]$m)
                $friendlyName = $methodProfile.FriendlyName
                if ([string]::IsNullOrWhiteSpace($friendlyName)) { continue }

                if (-not $methodCounts.ContainsKey($friendlyName)) { $methodCounts[$friendlyName] = 0 }
                $methodCounts[$friendlyName]++

                switch ($methodProfile.Category) {
                    'Weak' {
                        if (-not $weakMethodCounts.ContainsKey($friendlyName)) { $weakMethodCounts[$friendlyName] = 0 }
                        $weakMethodCounts[$friendlyName]++
                        $userHasWeakMethod = $true
                    }
                    'Strong' {
                        if (-not $strongMethodCounts.ContainsKey($friendlyName)) { $strongMethodCounts[$friendlyName] = 0 }
                        $strongMethodCounts[$friendlyName]++
                        $userHasStrongMethod = $true
                    }
                    'PhishingResistant' {
                        if (-not $phishingResistantMethodCounts.ContainsKey($friendlyName)) { $phishingResistantMethodCounts[$friendlyName] = 0 }
                        $phishingResistantMethodCounts[$friendlyName]++
                        $userHasStrongMethod = $true
                        $userHasPhishingResistantMethod = $true
                    }
                    default {
                        $userHasStrongMethod = $true
                    }
                }
            }

            $defaultMfaMethod = [string]$user.DefaultMfaMethod
            $defaultMethodProfile = Get-AssessmentMfaMethodProfile -MethodName $defaultMfaMethod
            $defaultMethodName = $defaultMethodProfile.FriendlyName
            if (-not [string]::IsNullOrWhiteSpace($defaultMethodName)) {
                if (-not $defaultMethodCounts.ContainsKey($defaultMethodName)) { $defaultMethodCounts[$defaultMethodName] = 0 }
                $defaultMethodCounts[$defaultMethodName]++
            }

            if ($user.IsMfaRegistered -eq $true) {
                $registeredUsers++
                if ($userHasWeakMethod -and -not $userHasStrongMethod) { $usersWithWeakMethodsOnly++ }
                if ($userHasStrongMethod) { $usersWithStrongMethods++ }
                if ($userHasPhishingResistantMethod) { $usersWithPhishingResistantMethods++ }
                if ($defaultMethodProfile.IsWeak -eq $true) { $usersWithWeakDefaultMethod++ }
            }
            
            if ($upn) {
                $script:tenantStatsHash["MfaRegistrationDetails"][$upn] = [pscustomobject]@{
                    UserPrincipalName = $upn
                    IsMfaRegistered = $user.IsMfaRegistered
                    IsMfaCapable = $user.IsMfaCapable
                    MethodsRegistered = if ($methods) { $methods -join ', ' } else { $null }
                    DefaultMfaMethod = $defaultMethodName
                    HasWeakMethod = $userHasWeakMethod
                    HasStrongMethod = $userHasStrongMethod
                    HasPhishingResistantMethod = $userHasPhishingResistantMethod
                }
            }
        }
        
        if ($totalUsers -gt 0) {
            $summary = [pscustomobject]@{
                TotalUsers = $totalUsers
                RegisteredUsers = $registeredUsers
                NotRegisteredUsers = ($totalUsers - $registeredUsers)
                RegistrationPercent = [math]::Round(($registeredUsers / $totalUsers) * 100, 1)
                MethodCounts = $methodCounts
                WeakMethodCounts = $weakMethodCounts
                StrongMethodCounts = $strongMethodCounts
                PhishingResistantMethodCounts = $phishingResistantMethodCounts
                DefaultMethodCounts = $defaultMethodCounts
                UsersWithWeakMethodsOnly = $usersWithWeakMethodsOnly
                UsersWithWeakDefaultMethod = $usersWithWeakDefaultMethod
                UsersWithStrongMethods = $usersWithStrongMethods
                UsersWithPhishingResistantMethods = $usersWithPhishingResistantMethods
            }
            $script:tenantStatsHash["MfaRegistrationSummary"] = $summary

            $script:tenantStatsHash["MfaEnrollmentSummary"] = [pscustomobject]@{
                TotalUsers                      = $totalUsers
                RegisteredUsers                 = $registeredUsers
                NotRegisteredUsers              = ($totalUsers - $registeredUsers)
                RegistrationPercent             = [math]::Round(($registeredUsers / $totalUsers) * 100, 1)
                RegisteredMethodBreakdown       = Convert-AssessmentMfaCountMapToText -CountMap $methodCounts
                WeakMethodBreakdown             = Convert-AssessmentMfaCountMapToText -CountMap $weakMethodCounts
                StrongMethodBreakdown           = Convert-AssessmentMfaCountMapToText -CountMap $strongMethodCounts
                PhishingResistantMethodBreakdown = Convert-AssessmentMfaCountMapToText -CountMap $phishingResistantMethodCounts
                DefaultMethodBreakdown          = Convert-AssessmentMfaCountMapToText -CountMap $defaultMethodCounts
                UsersWithWeakMethodsOnly        = $usersWithWeakMethodsOnly
                UsersWithWeakDefaultMethod      = $usersWithWeakDefaultMethod
                UsersWithStrongMethods          = $usersWithStrongMethods
                UsersWithPhishingResistantMethods = $usersWithPhishingResistantMethods
                CollectionState                 = 'Collected'
            }
        }

        $conditionalAccessSummaryRecord = if ($script:tenantStatsHash.ContainsKey("ConditionalAccessPolicySummary")) { Get-ArrayaObjectValue -Object $script:tenantStatsHash["ConditionalAccessPolicySummary"] -Names @('Summary') } else { $null }
        $securityDefaultsRecord = if ($script:tenantStatsHash.ContainsKey("SecurityDefaultsPolicy")) { Get-ArrayaObjectValue -Object $script:tenantStatsHash["SecurityDefaultsPolicy"] -Names @('Configuration') } else { $null }
        $conditionalAccessPolicies = @()
        if ($script:tenantStatsHash.ContainsKey("ConditionalAccessPolicies")) {
            $conditionalAccessPolicies = @($script:tenantStatsHash["ConditionalAccessPolicies"].Values)
        }

        $mfaPolicies = @(
            $conditionalAccessPolicies |
                Where-Object { Test-AssessmentConditionalAccessRequiresMfa -Policy $_ }
        )
        $enabledMfaPolicies = @($mfaPolicies | Where-Object { ([string](Get-ArrayaObjectValue -Object $_ -Names @('State'))).ToLowerInvariant() -eq 'enabled' })
        $reportOnlyMfaPolicies = @($mfaPolicies | Where-Object { ([string](Get-ArrayaObjectValue -Object $_ -Names @('State'))) -match '(?i)report' })
        $mfaCoverageAnalysis = Get-AssessmentMfaEnforcementCoverageSummary -EnabledMfaPolicies $enabledMfaPolicies -Users $script:tenantStatsHash["Users"] -Groups $script:tenantStatsHash["EntraIDGroups"] -OperationName 'Get-MfaRegistrationDetails' -IncludeDetails
        $mfaCoverageSummary = if ($mfaCoverageAnalysis -and $mfaCoverageAnalysis.PSObject.Properties['Summary']) { $mfaCoverageAnalysis.Summary } else { $mfaCoverageAnalysis }
        $securityDefaultsEnabled = $null
        if ($securityDefaultsRecord) {
            if ($securityDefaultsRecord.PSObject.Properties['IsEnabled']) {
                $securityDefaultsEnabled = [bool]$securityDefaultsRecord.IsEnabled
            } elseif ($securityDefaultsRecord.PSObject.Properties['Enabled']) {
                $securityDefaultsEnabled = [bool]$securityDefaultsRecord.Enabled
            }
        }

        $enforcementState = if ($enabledMfaPolicies.Count -gt 0 -and $securityDefaultsEnabled -eq $true) {
            'Conditional Access and Security Defaults both enforce MFA; confirm that the overlapping baseline is intentional.'
        }
        elseif ($enabledMfaPolicies.Count -gt 0) {
            'MFA enforcement is active through enabled Conditional Access policies.'
        }
        elseif ($securityDefaultsEnabled -eq $true) {
            'MFA enforcement is active through Security Defaults.'
        }
        elseif ($reportOnlyMfaPolicies.Count -gt 0) {
            'MFA appears staged in report-only Conditional Access, but active enforcement was not clearly detected.'
        }
        else {
            'Active MFA enforcement was not clearly detected in the reviewed policy baseline.'
        }

        $guestUserEnforcementState = if ($securityDefaultsEnabled -eq $true) {
            'Guest users are generally enforced through Security Defaults.'
        }
        elseif ((Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('EnabledGuestUsersReviewed'))) -eq 0) {
            'No enabled guest users were present in the reviewed data.'
        }
        elseif ((Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('GuestUsersCoveredByEnabledMfaPolicies'))) -ge (Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('EnabledGuestUsersReviewed')))) {
            'Reviewed enabled guest users appear covered by the active MFA enforcement baseline.'
        }
        elseif ((Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('GuestUsersCoveredByEnabledMfaPolicies'))) -gt 0) {
            'Guest users are partially covered by the active MFA enforcement baseline.'
        }
        elseif ($enabledMfaPolicies.Count -gt 0) {
            'Guest users are not clearly covered by the active MFA enforcement baseline.'
        }
        elseif ($reportOnlyMfaPolicies.Count -gt 0) {
            'Guest MFA appears staged in report-only Conditional Access, but active guest enforcement was not clearly detected.'
        }
        else {
            'Guest MFA enforcement was not clearly detected in the reviewed policy baseline.'
        }

        $conditionalAccessPoliciesReviewed = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $conditionalAccessSummaryRecord -Names @('TotalPolicies'))
        if ($null -eq $conditionalAccessPoliciesReviewed) {
            $conditionalAccessPoliciesReviewed = @($conditionalAccessPolicies).Count
        }

        $guestCoveredPolicyNames = @(
            Convert-ToAssessmentStringArray -Value (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('GuestCoveredPolicyNames'))
        )
        $guestExplicitScopePolicyNames = @(
            Convert-ToAssessmentStringArray -Value (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('GuestExplicitScopePolicyNames'))
        )
        $guestMfaConditionalAccessPoliciesText = if ($guestCoveredPolicyNames.Count -gt 0) {
            $guestCoveredPolicyNames -join '; '
        }
        elseif ($enabledMfaPolicies.Count -gt 0) {
            'No specific guest-covered MFA policy names were resolved from the reviewed guest population.'
        }
        else {
            'None detected'
        }
        $guestMfaExplicitGuestScopePoliciesText = if ($guestExplicitScopePolicyNames.Count -gt 0) {
            $guestExplicitScopePolicyNames -join '; '
        }
        else {
            'No explicit guest/external-user MFA scope detected.'
        }
        $guestMfaEnforcementSources = New-Object System.Collections.Generic.List[string]
        if ($securityDefaultsEnabled -eq $true) {
            $guestMfaEnforcementSources.Add('Security Defaults') | Out-Null
        }
        if ($guestCoveredPolicyNames.Count -gt 0) {
            $guestMfaEnforcementSources.Add(("Conditional Access: {0}" -f ($guestCoveredPolicyNames -join '; '))) | Out-Null
        }
        elseif ($enabledMfaPolicies.Count -gt 0) {
            $guestMfaEnforcementSources.Add('Conditional Access: enabled MFA policies were detected, but no guest-covered policy names were resolved from the reviewed guest population') | Out-Null
        }
        if ($guestMfaEnforcementSources.Count -eq 0 -and $reportOnlyMfaPolicies.Count -gt 0) {
            $guestMfaEnforcementSources.Add('Report-only Conditional Access policies require MFA, but active guest enforcement was not clearly detected') | Out-Null
        }
        $guestMfaEnforcementSourcesText = if ($guestMfaEnforcementSources.Count -gt 0) {
            @($guestMfaEnforcementSources) -join ' | '
        }
        else {
            'No active guest MFA enforcement source was clearly detected.'
        }

        $script:tenantStatsHash["MfaEnforcementSummary"] = [pscustomobject]@{
            ConditionalAccessPoliciesReviewed     = $conditionalAccessPoliciesReviewed
            EnabledConditionalAccessPolicies      = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $conditionalAccessSummaryRecord -Names @('EnabledPolicies'))
            ReportOnlyConditionalAccessPolicies   = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $conditionalAccessSummaryRecord -Names @('ReportOnlyPolicies'))
            PoliciesWithExclusions                = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $conditionalAccessSummaryRecord -Names @('PoliciesWithExclusions'))
            PoliciesRequiringMfa                  = $mfaPolicies.Count
            EnabledPoliciesRequiringMfa          = $enabledMfaPolicies.Count
            ReportOnlyPoliciesRequiringMfa       = $reportOnlyMfaPolicies.Count
            EnabledUsersReviewed                 = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('EnabledUsersReviewed'))
            EnabledMemberUsersReviewed           = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('EnabledMemberUsersReviewed'))
            EnabledGuestUsersReviewed            = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('EnabledGuestUsersReviewed'))
            UsersCoveredByEnabledMfaPolicies     = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('UsersCoveredByEnabledMfaPolicies'))
            UserCoveragePercent                  = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('UserCoveragePercent'))
            MemberUsersCoveredByEnabledMfaPolicies = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('MemberUsersCoveredByEnabledMfaPolicies'))
            MemberUserCoveragePercent            = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('MemberUserCoveragePercent'))
            GuestUsersCoveredByEnabledMfaPolicies = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('GuestUsersCoveredByEnabledMfaPolicies'))
            GuestUserCoveragePercent             = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('GuestUserCoveragePercent'))
            GuestCoveredPolicyCount              = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('GuestCoveredPolicyCount'))
            GuestCoveredPolicyNames              = $guestMfaConditionalAccessPoliciesText
            GuestExplicitScopePolicyCount        = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('GuestExplicitScopePolicyCount'))
            GuestExplicitScopePolicyNames        = $guestMfaExplicitGuestScopePoliciesText
            GuestMfaEnforcementSources           = $guestMfaEnforcementSourcesText
            GroupTargetedPolicyCount             = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('GroupTargetedPolicyCount'))
            RoleTargetedPolicyCount              = Convert-ArrayaToNumber (Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('RoleTargetedPolicyCount'))
            CoverageCalculationNote              = Get-ArrayaObjectValue -Object $mfaCoverageSummary -Names @('CoverageCalculationNote')
            SecurityDefaultsEnabled              = $securityDefaultsEnabled
            GuestOrExternalCoverage              = Get-ArrayaObjectValue -Object $conditionalAccessSummaryRecord -Names @('HasGuestCoverage')
            GuestUserEnforcementState            = $guestUserEnforcementState
            PrivilegedRoleCoverage               = Get-ArrayaObjectValue -Object $conditionalAccessSummaryRecord -Names @('HasPrivilegedRoleCoverage')
            RiskBasedCoverage                    = Get-ArrayaObjectValue -Object $conditionalAccessSummaryRecord -Names @('HasRiskBasedCoverage')
            CompliantDeviceRequirement           = Get-ArrayaObjectValue -Object $conditionalAccessSummaryRecord -Names @('HasCompliantDeviceRequirement')
            EnforcementState                     = $enforcementState
            CollectionState                      = 'Collected'
        }

        $gapUserIndex = 0
        foreach ($gapUser in @($mfaCoverageAnalysis.GapUsers)) {
            $gapUserIndex++
            $gapUserKey = Convert-ToAssessmentPathComponent -Value (Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $gapUser -Names @('UserPrincipalName', 'DisplayName', 'DirectoryObjectId')) -Default ('GapUser{0:D3}' -f $gapUserIndex)) -Fallback ('GapUser{0:D3}' -f $gapUserIndex)
            $script:tenantStatsHash["MfaEnforcementGapUsers"][("{0:D3}-{1}" -f $gapUserIndex, $gapUserKey)] = $gapUser
        }

        $scopeReviewIndex = 0
        foreach ($scopeReviewRow in @($mfaCoverageAnalysis.ScopeReview)) {
            $scopeReviewIndex++
            $scopeRowKey = Convert-ToAssessmentPathComponent -Value (Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $scopeReviewRow -Names @('DisplayName', 'Identifier', 'PolicyName')) -Default ('ScopeReview{0:D3}' -f $scopeReviewIndex)) -Fallback ('ScopeReview{0:D3}' -f $scopeReviewIndex)
            $script:tenantStatsHash["MfaEnforcementScopeReview"][("{0:D3}-{1}" -f $scopeReviewIndex, $scopeRowKey)] = $scopeReviewRow
        }

        try {
            $adminMfaReview = Get-AssessmentAdminMfaReview `
                -Admins $script:tenantStatsHash["Admins"] `
                -Users $script:tenantStatsHash["Users"] `
                -MfaRegistrationDetails $script:tenantStatsHash["MfaRegistrationDetails"] `
                -MfaCoverageAnalysis $mfaCoverageAnalysis `
                -SecurityDefaultsEnabled $securityDefaultsEnabled `
                -EnabledMfaPolicyCount $enabledMfaPolicies.Count `
                -ReportOnlyMfaPolicyCount $reportOnlyMfaPolicies.Count
            if ($adminMfaReview) {
                $script:tenantStatsHash["AdminMfaSummary"] = if ($adminMfaReview.PSObject.Properties['Summary']) { $adminMfaReview.Summary } else { $adminMfaReview }
                $adminRegistrationGapIndex = 0
                foreach ($adminRegistrationGap in @($adminMfaReview.RegistrationGaps)) {
                    $adminRegistrationGapIndex++
                    $adminRegistrationGapKey = Convert-ToAssessmentPathComponent -Value (Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $adminRegistrationGap -Names @('UserPrincipalName', 'DisplayName')) -Default ('AdminMfaRegistrationGap{0:D3}' -f $adminRegistrationGapIndex)) -Fallback ('AdminMfaRegistrationGap{0:D3}' -f $adminRegistrationGapIndex)
                    $script:tenantStatsHash["AdminMfaRegistrationGaps"][("{0:D3}-{1}" -f $adminRegistrationGapIndex, $adminRegistrationGapKey)] = $adminRegistrationGap
                }
                $adminEnforcementGapIndex = 0
                foreach ($adminEnforcementGap in @($adminMfaReview.EnforcementGaps)) {
                    $adminEnforcementGapIndex++
                    $adminEnforcementGapKey = Convert-ToAssessmentPathComponent -Value (Convert-ToAssessmentDisplayText -Value (Get-ArrayaObjectValue -Object $adminEnforcementGap -Names @('UserPrincipalName', 'DisplayName')) -Default ('AdminMfaEnforcementGap{0:D3}' -f $adminEnforcementGapIndex)) -Fallback ('AdminMfaEnforcementGap{0:D3}' -f $adminEnforcementGapIndex)
                    $script:tenantStatsHash["AdminMfaEnforcementGaps"][("{0:D3}-{1}" -f $adminEnforcementGapIndex, $adminEnforcementGapKey)] = $adminEnforcementGap
                }
            }
        }
        catch {
            Write-Log -Type WARNING -Message "[Get-MfaRegistrationDetails] Admin MFA review enrichment did not complete, but MFA enforcement summary data was retained. $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }
    } catch {
        $failureLine = $null
        if ($_.InvocationInfo -and $_.InvocationInfo.ScriptLineNumber) {
            $failureLine = "Line $($_.InvocationInfo.ScriptLineNumber)"
        }
        $failureCommand = $null
        if ($_.InvocationInfo -and $_.InvocationInfo.Line) {
            $failureCommand = $_.InvocationInfo.Line.Trim()
        }
        $failureContext = @($failureLine, $failureCommand | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join ' | '
        $stackSuffix = if (-not [string]::IsNullOrWhiteSpace($_.ScriptStackTrace)) {
            " Stack: $($_.ScriptStackTrace)"
        }
        else {
            ''
        }
        $message = "[Get-MfaRegistrationDetails] Error: $($_.Exception.Message)"
        if (-not [string]::IsNullOrWhiteSpace($failureContext)) {
            $message = "$message ($failureContext)"
        }
        Write-Log -Type WARNING -Message ($message + $stackSuffix) -ExportFileLocation $ExportDetails
    }
    
    $elapsed = ((Get-Date) - $start).ToString('hh\:mm\:ss')
    Write-AssessmentCollectorCompletionBanner -Message " Completed in $elapsed"
    Write-Log -Type INFO -Message "[Get-MfaRegistrationDetails] COMPLETED in $elapsed" -ExportFileLocation $ExportDetails
}

# Federation and Cross-Tenant Configuration (External Identities)
function Get-FederationAndCrossTenantConfiguration {
    [CmdletBinding()]
    param()

    $start = Get-Date
    if (-not $script:tenantStatsHash) { $script:tenantStatsHash = @{} }
    $script:tenantStatsHash["FederationConfiguration"] = @{}

    Write-AssessmentCollectorBanner -Message 'Checking Federation and Cross-Tenant Configuration ...' -NoNewline
    Write-Log -Type INFO -Message "[Get-FederationAndCrossTenantConfiguration] START" -ExportFileLocation $ExportDetails

    try {
        # Exchange federation signals
        $orgR = Get-OrganizationRelationship -ErrorAction SilentlyContinue |
                Where-Object {
                    $_.TargetApplicationUri -or $_.TargetAutodiscoverEpr -or $_.DomainNames
                }
        $ioc  = Get-IntraOrganizationConnector -ErrorAction SilentlyContinue | Where-Object { $_.Enabled }

        $exchangeFed = [pscustomobject]@{
            OrganizationRelationshipCount = $orgR.Count
            IntraOrgConnectorCount         = $ioc.Count
            OrganizationRelationships      = ($orgR | Select-Object -ExpandProperty Name) -join ', '
            IntraOrgConnectors             = ($ioc  | Select-Object -ExpandProperty Name) -join ', '
        }

        # External identities / cross-tenant access (Graph)
        $crossTenantPolicy = $null
        $crossTenantPartners = @()
        $b2bPolicy = $null

        try {
            $crossTenantPolicy = Get-MgPolicyCrossTenantAccessPolicy -ProgressAction SilentlyContinue -ErrorAction Stop
        } catch {
            Write-Log -Type WARNING -Message "[Get-FederationAndCrossTenantConfiguration] Unable to retrieve CrossTenantAccessPolicy: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }

        try {
            $crossTenantPartners = Get-MgPolicyCrossTenantAccessPolicyPartner -All -ProgressAction SilentlyContinue -ErrorAction Stop
        } catch {
            Write-Log -Type WARNING -Message "[Get-FederationAndCrossTenantConfiguration] Unable to retrieve CrossTenantAccessPolicy partners: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }

        $b2bPolicyErrorCountBeforeLookup = $global:Error.Count
        try {
            $b2bPolicyCommand = Get-Command -Name 'Get-MgPolicyB2BManagementPolicy' -ErrorAction Ignore
            if ($b2bPolicyCommand) {
                $b2bPolicy = Get-MgPolicyB2BManagementPolicy -ProgressAction SilentlyContinue -ErrorAction Stop
            }
            else {
                throw 'Get-MgPolicyB2BManagementPolicy is not available in the installed Microsoft Graph module set.'
            }
        } catch {
            if ($global:Error.Count -gt $b2bPolicyErrorCountBeforeLookup) {
                while ($global:Error.Count -gt $b2bPolicyErrorCountBeforeLookup) {
                    $global:Error.RemoveAt(0)
                }
            }
            if (Get-Command Invoke-MgGraphRequest -ErrorAction SilentlyContinue) {
                try {
                    $b2bPolicy = Invoke-MgGraphRequest -Method GET -Uri 'https://graph.microsoft.com/v1.0/policies/b2bManagementPolicy' -ProgressAction SilentlyContinue -ErrorAction Stop
                } catch {
                    while ($global:Error.Count -gt $b2bPolicyErrorCountBeforeLookup) {
                        $global:Error.RemoveAt(0)
                    }
                    $b2bMessage = $_.Exception.Message
                    $b2bLogType = if ($b2bMessage -match 'BadRequest') { 'INFO' } else { 'WARNING' }
                    Write-Log -Type $b2bLogType -Message "[Get-FederationAndCrossTenantConfiguration] Unable to retrieve B2B management policy: $b2bMessage" -ExportFileLocation $ExportDetails
                }
            } else {
                $b2bMessage = $_.Exception.Message
                $b2bLogType = if ($b2bMessage -match 'BadRequest') { 'INFO' } else { 'WARNING' }
                Write-Log -Type $b2bLogType -Message "[Get-FederationAndCrossTenantConfiguration] Unable to retrieve B2B management policy: $b2bMessage" -ExportFileLocation $ExportDetails
            }
        }

        function Get-CrossTenantNestedValue {
            param(
                [AllowNull()][object]$SourceObject,
                [Parameter(Mandatory = $true)][string[]]$PropertyPaths
            )

            if (-not $SourceObject) {
                return $null
            }

            foreach ($propertyPath in $PropertyPaths) {
                if ([string]::IsNullOrWhiteSpace([string]$propertyPath)) {
                    continue
                }

                $currentObject = $SourceObject
                $pathFound = $true
                foreach ($segment in @($propertyPath -split '\.')) {
                    if ($null -eq $currentObject) {
                        $pathFound = $false
                        break
                    }

                    if ($currentObject -is [System.Collections.IDictionary] -and $currentObject.Contains($segment)) {
                        $currentObject = $currentObject[$segment]
                        continue
                    }

                    if ($currentObject.PSObject -and $currentObject.PSObject.Properties[$segment]) {
                        $currentObject = $currentObject.$segment
                        continue
                    }

                    $pathFound = $false
                    break
                }

                if ($pathFound) {
                    return $currentObject
                }
            }

            return $null
        }

        function Resolve-CrossTenantTrustValue {
            param(
                [AllowNull()][object]$TrustObject,
                [Parameter(Mandatory = $true)][string[]]$PropertyNames,
                [string]$Unavailable = 'Not available in current source'
            )

            if (-not $TrustObject) {
                return $Unavailable
            }

            $value = Get-CrossTenantNestedValue -SourceObject $TrustObject -PropertyPaths $PropertyNames
            if ($null -ne $value) {
                try {
                    return [bool]$value
                }
                catch {
                    return $value
                }
            }

            foreach ($propertyName in $PropertyNames) {
                $leafName = [string](@($propertyName -split '\.') | Select-Object -Last 1)
                if (($TrustObject -is [System.Collections.IDictionary] -and $TrustObject.Contains($leafName)) -or ($TrustObject.PSObject -and $TrustObject.PSObject.Properties[$leafName])) {
                    return 'Not configured'
                }
            }

            if (@($TrustObject.PSObject.Properties).Count -gt 0) {
                return 'Not configured'
            }
            return $Unavailable
        }

        $defaultInboundMfa = if ($crossTenantPolicy -and $crossTenantPolicy.Default) {
            Resolve-CrossTenantTrustValue -TrustObject $crossTenantPolicy.Default.InboundTrust -PropertyNames @('IsMfaAccepted', 'isMfaAccepted', 'AutomaticTrustSettings.IsMfaAccepted', 'automaticTrustSettings.isMfaAccepted', 'MfaTrustEnabled', 'mfaTrustEnabled')
        } else { 'Not available in current source' }
        $defaultOutboundMfa = if ($crossTenantPolicy -and $crossTenantPolicy.Default) {
            Resolve-CrossTenantTrustValue -TrustObject $crossTenantPolicy.Default.OutboundTrust -PropertyNames @('IsMfaAccepted', 'isMfaAccepted', 'AutomaticTrustSettings.IsMfaAccepted', 'automaticTrustSettings.isMfaAccepted', 'MfaTrustEnabled', 'mfaTrustEnabled')
        } else { 'Not available in current source' }

        function Get-B2BDirectConnectSummary {
            param([object]$Setting)
            if (-not $Setting) { return "Not configured" }
            $usersAndGroups = Get-CrossTenantNestedValue -SourceObject $Setting -PropertyPaths @('UsersAndGroups', 'usersAndGroups')
            $applications = Get-CrossTenantNestedValue -SourceObject $Setting -PropertyPaths @('Applications', 'applications')

            $uAccess = Get-CrossTenantNestedValue -SourceObject $usersAndGroups -PropertyPaths @('AccessType', 'accessType')
            $uTargets = Get-CrossTenantNestedValue -SourceObject $usersAndGroups -PropertyPaths @('Targets', 'targets')
            $uTargetText = if ($uTargets) {
                if ($uTargets -is [string]) { $uTargets } else { "$(($uTargets | Measure-Object).Count) targets" }
            } else { $null }

            $aAccess = Get-CrossTenantNestedValue -SourceObject $applications -PropertyPaths @('AccessType', 'accessType')
            $aTargets = Get-CrossTenantNestedValue -SourceObject $applications -PropertyPaths @('Targets', 'targets')
            $aTargetText = if ($aTargets) {
                if ($aTargets -is [string]) { $aTargets } else { "$(($aTargets | Measure-Object).Count) targets" }
            } else { $null }

            $parts = @()
            if ($uAccess -or $uTargetText) { $parts += "Users: $uAccess $uTargetText".Trim() }
            if ($aAccess -or $aTargetText) { $parts += "Apps: $aAccess $aTargetText".Trim() }
            if ($parts.Count -gt 0) { return ($parts -join '; ') }
            return "Not configured"
        }

        function Resolve-TenantDisplayName {
            param(
                [Parameter(Mandatory = $true)][string]$TenantId,
                [Parameter(Mandatory = $false)][object]$PartnerObject
            )
            
            # 1) Partner object might already include a display name
            if ($PartnerObject -and $PartnerObject.PSObject.Properties['DisplayName']) {
                $name = $PartnerObject.DisplayName
                if (-not [string]::IsNullOrWhiteSpace($name)) { return $name }
            }
            
            # 2) Try Graph v1.0 findTenantInformationByTenantId (preferred)
            $tenantLookupUri = "https://graph.microsoft.com/v1.0/tenantRelationships/findTenantInformationByTenantId(tenantId='$TenantId')"
            try {
                if (Get-Command Find-MgTenantRelationshipTenantInformationByTenantId -ErrorAction SilentlyContinue) {
                    $lookup = Find-MgTenantRelationshipTenantInformationByTenantId -TenantId $TenantId -ProgressAction SilentlyContinue -ErrorAction Stop
                    if ($lookup.DisplayName) { return $lookup.DisplayName }
                }
                if (Get-Command Invoke-MgGraphRequest -ErrorAction SilentlyContinue) {
                    $lookup = Office365Custom\Get-GraphData -Uri $tenantLookupUri -Activity "Tenant lookup (v1.0)"
                    $lookupItem = $lookup | Select-Object -First 1
                    if ($lookupItem.displayName) { return $lookupItem.displayName }
                } elseif ($global:GraphHeaders) {
                    $lookup = Invoke-QuietRestMethod -Parameters @{
                        Uri         = $tenantLookupUri
                        Headers     = $global:GraphHeaders
                        Method      = 'GET'
                        ContentType = 'application/json'
                        ErrorAction = 'Stop'
                    }
                    if ($lookup.displayName) { return $lookup.displayName }
                }
            } catch {
                Write-Log -Type WARNING -Message "[Get-FederationAndCrossTenantConfiguration] Tenant name lookup (v1.0) failed for $($TenantId): $($_.Exception.Message)" -ExportFileLocation $ExportDetails
            }

            # 3) Last resort - this often fails cross-tenant
            try {
                $orgInfo = Get-AssessmentTenantOrganization -OrganizationId $TenantId
                if ($orgInfo) { return $orgInfo.DisplayName }
            } catch {
                Write-Log -Type WARNING -Message "[Get-FederationAndCrossTenantConfiguration] Unable to resolve tenant name for $($TenantId): $($_.Exception.Message)" -ExportFileLocation $ExportDetails
            }
            
            return $null
        }

        $partnerDetails = @()
        foreach ($partner in $crossTenantPartners) {
            $tenantId = $partner.TenantId
            $displayName = Resolve-TenantDisplayName -TenantId $tenantId -PartnerObject $partner
            $b2bInboundSummary = Get-B2BDirectConnectSummary -Setting $partner.B2bDirectConnectInbound
            $b2bOutboundSummary = Get-B2BDirectConnectSummary -Setting $partner.B2bDirectConnectOutbound
            $inboundTrust = $partner.InboundTrust
            $partnerDetails += [pscustomobject]@{
                TenantId = $tenantId
                DisplayName = $displayName
                B2BDirectConnectInbound = $b2bInboundSummary
                B2BDirectConnectOutbound = $b2bOutboundSummary
                TrustMfa = Resolve-CrossTenantTrustValue -TrustObject $inboundTrust -PropertyNames @('IsMfaAccepted', 'isMfaAccepted', 'AutomaticTrustSettings.IsMfaAccepted', 'automaticTrustSettings.isMfaAccepted')
                TrustCompliantDevices = Resolve-CrossTenantTrustValue -TrustObject $inboundTrust -PropertyNames @('IsCompliantDeviceAccepted', 'isCompliantDeviceAccepted', 'AutomaticTrustSettings.IsCompliantDeviceAccepted', 'automaticTrustSettings.isCompliantDeviceAccepted')
                TrustHybridJoinedDevices = Resolve-CrossTenantTrustValue -TrustObject $inboundTrust -PropertyNames @('IsHybridAzureAdJoinedDeviceAccepted', 'isHybridAzureAdJoinedDeviceAccepted', 'AutomaticTrustSettings.IsHybridAzureAdJoinedDeviceAccepted', 'automaticTrustSettings.isHybridAzureAdJoinedDeviceAccepted')
            }
        }

        $defaultB2BInbound = $null
        $defaultB2BOutbound = $null
        if ($crossTenantPolicy -and $crossTenantPolicy.Default) {
            $defaultB2BInbound = Get-B2BDirectConnectSummary -Setting $crossTenantPolicy.Default.B2bDirectConnectInbound
            $defaultB2BOutbound = Get-B2BDirectConnectSummary -Setting $crossTenantPolicy.Default.B2bDirectConnectOutbound
        }

        $crossTenantSummary = [pscustomobject]@{
            HasCrossTenantAccessPolicy = [bool]($crossTenantPolicy)
            PartnerCount               = ($crossTenantPartners | Measure-Object).Count
            PartnerTenants             = ($crossTenantPartners | ForEach-Object { $_.TenantId }) -join ', '
            PartnerTenantNames         = ($partnerDetails | Where-Object { $_.DisplayName } | ForEach-Object { $_.DisplayName }) -join ', '
            PartnerTenantDetails       = $partnerDetails
            DefaultInboundAccess       = $defaultInboundMfa
            DefaultOutboundAccess      = $defaultOutboundMfa
            DefaultB2BDirectConnectInbound  = $defaultB2BInbound
            DefaultB2BDirectConnectOutbound = $defaultB2BOutbound
        }

        $externalIdentities = [pscustomobject]@{
            B2BManagementPolicyPresent = [bool]($b2bPolicy)
            GuestUserRole              = if ($b2bPolicy) { $b2bPolicy.GuestUserRoleId } else { $null }
            InvitationsAllowed         = if ($b2bPolicy -and $b2bPolicy.InvitationPolicy) { $b2bPolicy.InvitationPolicy.AllowedToInvite } else { $null }
        }

        $script:tenantStatsHash["FederationConfiguration"]["ExchangeFederation"] = $exchangeFed
        $script:tenantStatsHash["FederationConfiguration"]["CrossTenantAccess"] = $crossTenantSummary
        $script:tenantStatsHash["FederationConfiguration"]["ExternalIdentities"] = $externalIdentities

        Write-Log -Type INFO -Message "[Get-FederationAndCrossTenantConfiguration] OrgRel=$($exchangeFed.OrganizationRelationshipCount) IOC=$($exchangeFed.IntraOrgConnectorCount) Partners=$($crossTenantSummary.PartnerCount)" -ExportFileLocation $ExportDetails
    }
    catch {
        Write-Log -Type WARNING -Message "[Get-FederationAndCrossTenantConfiguration] Error: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
    }

    $elapsed = ((Get-Date) - $start).ToString('hh\:mm\:ss')
    Write-AssessmentCollectorCompletionBanner -Message " Completed in $elapsed"
    Write-Log -Type INFO -Message "[Get-FederationAndCrossTenantConfiguration] COMPLETED in $elapsed" -ExportFileLocation $ExportDetails
}

function Export-TenantStatsJson {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [hashtable]$TenantStatsHash,
        [Parameter(Mandatory)]
        [string]$Path
    )

    function Get-TenantStatsExportCount {
        param(
            [Parameter(Mandatory = $true)]
            [string]$Key
        )

        if (-not ($TenantStatsHash -is [System.Collections.IDictionary]) -or -not $TenantStatsHash.ContainsKey($Key)) {
            return 0
        }

        $value = $TenantStatsHash[$Key]
        if ($value -is [System.Collections.IDictionary]) {
            return $value.Count
        }
        if ($null -ne $value -and $value -is [System.Collections.IEnumerable] -and -not ($value -is [string])) {
            return @($value).Count
        }

        return 0
    }

    $metadata = [ordered]@{
        GeneratedAt        = (Get-Date).ToString('o')
        AssessmentVersion  = $script:AssessmentScriptVersion.Label
        AssessmentVersionMajor = $script:AssessmentScriptVersion.MajorVersion
        AssessmentVersionMinor = $script:AssessmentScriptVersion.MinorVersion
        AssessmentVersionSource = $script:AssessmentScriptVersion.Source
        OutputProfile      = $OutputProfile
        OutputProfileLabel = $script:EffectiveOutputProfileLabel
        ReportingMode      = $reportingMode
        AuthMode           = $script:CurrentGraphMode
        CollectionOnly     = [bool]$runCollectionOnly
        ExportOnly         = [bool]$runExportOnly
    }

    if ($script:AssessmentAuthWorkloadPlan -or $connectionResult) {
        $metadata['Authentication'] = [ordered]@{
            BootstrapMode       = if ($connectionResult -and $connectionResult.PSObject.Properties['AuthenticationType']) { [string]$connectionResult.AuthenticationType } else { $null }
            RequiredWorkloads   = if ($connectionResult -and $connectionResult.PSObject.Properties['RequiredWorkloads']) { @($connectionResult.RequiredWorkloads) } else { @() }
            ConnectedWorkloads  = if ($connectionResult -and $connectionResult.PSObject.Properties['ConnectedWorkloads']) { @($connectionResult.ConnectedWorkloads) } else { @() }
            SkippedWorkloads    = if ($connectionResult -and $connectionResult.PSObject.Properties['SkippedWorkloads']) { @($connectionResult.SkippedWorkloads) } else { @() }
            FallbackWorkloads   = if ($connectionResult -and $connectionResult.PSObject.Properties['FallbackWorkloads']) { @($connectionResult.FallbackWorkloads) } else { @() }
            GraphContext        = if ($connectionResult -and $connectionResult.PSObject.Properties['GraphContextAvailable']) { [bool]$connectionResult.GraphContextAvailable } else { $false }
            ExchangeCmdlets     = if ($connectionResult -and $connectionResult.PSObject.Properties['ExchangeCmdletsAvailable']) { [bool]$connectionResult.ExchangeCmdletsAvailable } else { $false }
            PurviewCmdlets      = if ($connectionResult -and $connectionResult.PSObject.Properties['PurviewCmdletsAvailable']) { [bool]$connectionResult.PurviewCmdletsAvailable } else { $false }
        }
    }

    if ($TenantStatsHash.ContainsKey('TenantInfo') -and $TenantStatsHash['TenantInfo']) {
        $tenantInfo = $TenantStatsHash['TenantInfo']
        $metadata['Tenant'] = [ordered]@{
            TenantId          = $tenantInfo.TenantID
            DisplayName       = $tenantInfo.DisplayName
            DefaultDomainName = $tenantInfo.DefaultDomainName
        }
    }

    $collectionPlan = [ordered]@{}
    if ($script:SnapshotCollectionPlan -is [System.Collections.IDictionary]) {
        foreach ($entry in $script:SnapshotCollectionPlan.GetEnumerator()) {
            $collectionPlan[[string]$entry.Key] = $entry.Value
        }
    }
    elseif ($script:ProfileCollectionPlan -is [System.Collections.IDictionary]) {
        foreach ($entry in $script:ProfileCollectionPlan.GetEnumerator()) {
            $collectionPlan[[string]$entry.Key] = [ordered]@{
                Status             = if ([bool]$entry.Value) { 'Collected' } else { 'Skipped' }
                NotCollectedReason = if ([bool]$entry.Value) { $null } else { 'Disabled by output profile policy.' }
            }
        }
    }

    $warningSummary = @()
    $errorSummary = @()
    if ($global:AllDiscoveryErrors) {
        foreach ($errorRow in $global:AllDiscoveryErrors) {
            $msg = [string]$errorRow.ErrorMessage
            if ([string]::IsNullOrWhiteSpace($msg)) {
                continue
            }
            $errorSummary += $msg
        }
    }

    $sourceCoverage = [ordered]@{}
    if ($TenantStatsHash.ContainsKey('PrimaryMailboxStatsCollectionSummary') -and $TenantStatsHash['PrimaryMailboxStatsCollectionSummary']) {
        $sourceCoverage['PrimaryMailboxStats'] = $TenantStatsHash['PrimaryMailboxStatsCollectionSummary']
    }
    if ($TenantStatsHash.ContainsKey('UnifiedGroupMailboxStatsCollectionSummary') -and $TenantStatsHash['UnifiedGroupMailboxStatsCollectionSummary']) {
        $sourceCoverage['UnifiedGroupMailboxStats'] = $TenantStatsHash['UnifiedGroupMailboxStatsCollectionSummary']
    }

    $diagnostics = [ordered]@{
        WarningCount   = $warningSummary.Count
        ErrorCount     = $errorSummary.Count
        WarningSummary = $warningSummary
        ErrorSummary   = $errorSummary
        SourceCoverage = $sourceCoverage
        CollectorStats = [ordered]@{
            StepMetrics = $script:AssessmentStepMetrics
        }
    }

    Write-Log -Type INFO -Message ("[Export-TenantStatsJson] Snapshot table counts before export: AllRecipients={0}; AllMailboxes={1}; MailboxFullDetails={2}; PrimaryMailboxStats={3}; ArchiveMailboxStats={4}; InactiveMailboxDetails={5}" -f (Get-TenantStatsExportCount -Key 'AllRecipients'), (Get-TenantStatsExportCount -Key 'AllMailboxes'), (Get-TenantStatsExportCount -Key 'MailboxFullDetails'), (Get-TenantStatsExportCount -Key 'PrimaryMailboxStats'), (Get-TenantStatsExportCount -Key 'ArchiveMailboxStats'), (Get-TenantStatsExportCount -Key 'InactiveMailboxDetails')) -ExportFileLocation $ExportDetails

    $snapshot = Convert-ArrayaLegacyTenantStatsToSnapshot `
        -TenantStatsHash $TenantStatsHash `
        -Metadata $metadata `
        -CollectionPlan $collectionPlan `
        -Diagnostics $diagnostics

    Export-ArrayaTenantSnapshot -Snapshot $snapshot -Path $Path
}

function Import-TenantStatsJson {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Path
    )

    if (-not (Test-Path -Path $Path)) {
        return $null
    }

    $snapshotContext = Import-ArrayaTenantSnapshotContext -Path $Path -Purpose Export
    $script:LoadedTenantSnapshot = $snapshotContext.Snapshot

    return $snapshotContext.LegacyData
}

