function Ensure-AssessmentServiceContext {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [string]$TenantId,
        [Parameter(Mandatory = $false)]
        [string]$ClientId,
        [Parameter(Mandatory = $false)]
        [string]$CertificateThumbprint,
        [Parameter(Mandatory = $false)]
        [string]$ClientSecret,
        [Parameter(Mandatory = $false)]
        [pscredential]$ClientSecretCredential,
        [Parameter(Mandatory = $false)]
        [securestring]$ClientSecretSecure,
        [Parameter(Mandatory = $false)]
        [string]$InitialDomain,
        [Parameter(Mandatory = $false)]
        [switch]$ExistingConnectionsOnly
    )

    $mgContext = Get-MgContext -ErrorAction SilentlyContinue
    if ($mgContext -and -not [string]::IsNullOrWhiteSpace($TenantId)) {
        try {
            Assert-AssessmentGraphContextMatchesTenant -TenantId $TenantId -ServiceName 'Assessment service context bootstrap' | Out-Null
        }
        catch {
            Write-Log -Type WARNING -Message "[Ensure-AssessmentServiceContext] Existing Microsoft Graph context did not match requested tenant $TenantId. Reconnecting in caller scope. Details: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
            try {
                Disconnect-MgGraph -ErrorAction SilentlyContinue
            }
            catch {}
            $mgContext = $null
        }
    }

    if (-not $mgContext -and -not $ExistingConnectionsOnly) {
        try {
            if (
                -not [string]::IsNullOrWhiteSpace($TenantId) -and
                -not [string]::IsNullOrWhiteSpace($ClientId) -and
                -not [string]::IsNullOrWhiteSpace($CertificateThumbprint)
            ) {
                Connect-MgGraph -TenantId $TenantId -ClientId $ClientId -CertificateThumbprint $CertificateThumbprint -NoWelcome -ErrorAction Stop | Out-Null
                Write-Log -Type INFO -Message "[Ensure-AssessmentServiceContext] Reconnected Microsoft Graph context using certificate auth in caller scope." -ExportFileLocation $ExportDetails
            }
            elseif (
                -not [string]::IsNullOrWhiteSpace($TenantId) -and
                (
                    -not [string]::IsNullOrWhiteSpace($ClientSecret) -or
                    $null -ne $ClientSecretCredential -or
                    $null -ne $ClientSecretSecure
                )
            ) {
                $clientSecretAuthContext = Resolve-AssessmentClientSecretAuthContext -ClientId $ClientId -ClientSecret $ClientSecret -ClientSecretCredential $ClientSecretCredential -ClientSecretSecure $ClientSecretSecure
                Connect-MgGraph -TenantId $TenantId -ClientSecretCredential $clientSecretAuthContext.ClientSecretCredential -NoWelcome -ErrorAction Stop | Out-Null
                Write-Log -Type INFO -Message ("[Ensure-AssessmentServiceContext] Reconnected Microsoft Graph context using client secret auth in caller scope via {0} input." -f $clientSecretAuthContext.InputSource) -ExportFileLocation $ExportDetails
            }
        }
        catch {
            Write-Log -Type WARNING -Message "[Ensure-AssessmentServiceContext] Unable to reconnect Microsoft Graph context in caller scope: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }
    }

    $mgContext = Get-MgContext -ErrorAction SilentlyContinue
    if ($mgContext) {
        try {
            $graphAccessToken = Get-MgAccessToken -ErrorAction Stop
            if (-not [string]::IsNullOrWhiteSpace([string]$graphAccessToken)) {
                $global:GraphToken = [string]$graphAccessToken
                $global:GraphHeaders = @{
                    'Content-Type'     = 'application/json'
                    'Authorization'    = "Bearer $graphAccessToken"
                    'ConsistencyLevel' = 'eventual'
                }
            }
        }
        catch {
            Write-Log -Type WARNING -Message "[Ensure-AssessmentServiceContext] Unable to cache Graph access token for REST fallback headers: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }
    }
    else {
        $graphMessage = if ($ExistingConnectionsOnly) {
            "[Ensure-AssessmentServiceContext] Microsoft Graph context is unavailable. Run Invoke-M365TenantConnectionPreflight first or omit -UseExistingConnections."
        }
        else {
            "[Ensure-AssessmentServiceContext] Microsoft Graph context is unavailable after connection bootstrap."
        }
        Write-Log -Type ERROR -Message $graphMessage -ExportFileLocation $ExportDetails
        throw $graphMessage
    }

    $hasExoMailboxCommand = [bool](Get-Command -Name 'Get-EXOMailbox' -ErrorAction SilentlyContinue)
    $hasUnifiedGroupCommand = [bool](Get-Command -Name 'Get-UnifiedGroup' -ErrorAction SilentlyContinue)
    if (-not ($hasExoMailboxCommand -and $hasUnifiedGroupCommand) -and -not $ExistingConnectionsOnly) {
        try {
            $existingExchangeConnection = @()
            if (Get-Command -Name 'Get-ConnectionInformation' -ErrorAction SilentlyContinue) {
                try {
                    $existingExchangeConnection = @(Get-ConnectionInformation -ErrorAction Stop)
                }
                catch {}
            }

            if ($existingExchangeConnection.Count -gt 0) {
                Write-Log -Type INFO -Message '[Ensure-AssessmentServiceContext] Exchange Online session exists, but EXO cmdlets are not visible in the collector scope. Reconnecting cmdlets for collector visibility.' -ExportFileLocation $ExportDetails
            }

            if (
                -not [string]::IsNullOrWhiteSpace($ClientId) -and
                -not [string]::IsNullOrWhiteSpace($CertificateThumbprint)
            ) {
                $organization = $InitialDomain
                if ([string]::IsNullOrWhiteSpace($organization) -and $mgContext) {
                    try {
                        $organizationResponse = Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/organization' -Activity 'Resolving tenant initial domain'
                        $organizationObject = @($organizationResponse) | Select-Object -First 1
                        if ($organizationObject -and $organizationObject.PSObject.Properties['verifiedDomains']) {
                            $initialDomain = @($organizationObject.verifiedDomains | Where-Object { $_.isInitial -eq $true } | Select-Object -First 1)
                            if ($initialDomain -and $initialDomain[0].name) {
                                $organization = [string]$initialDomain[0].name
                            }
                        }
                    }
                    catch {}
                }

                if (-not [string]::IsNullOrWhiteSpace($organization)) {
                    Connect-ExchangeOnline -AppId $ClientId -Organization $organization -CertificateThumbprint $CertificateThumbprint -ShowBanner:$false -ErrorAction Stop | Out-Null
                    Write-Log -Type INFO -Message "[Ensure-AssessmentServiceContext] Reconnected Exchange Online cmdlets in caller scope for collector visibility." -ExportFileLocation $ExportDetails
                }
            }
        }
        catch {
            Write-Log -Type WARNING -Message "[Ensure-AssessmentServiceContext] Unable to reconnect Exchange Online cmdlets in caller scope: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }
    }

    $hasExoMailboxCommand = [bool](Get-Command -Name 'Get-EXOMailbox' -ErrorAction SilentlyContinue)
    $hasUnifiedGroupCommand = [bool](Get-Command -Name 'Get-UnifiedGroup' -ErrorAction SilentlyContinue)
    if (-not ($hasExoMailboxCommand -and $hasUnifiedGroupCommand)) {
        $exchangeMessage = if ($ExistingConnectionsOnly) {
            "[Ensure-AssessmentServiceContext] Exchange Online cmdlets are unavailable. Run Invoke-M365TenantConnectionPreflight first or omit -UseExistingConnections."
        }
        else {
            "[Ensure-AssessmentServiceContext] Exchange Online cmdlets are unavailable after connection bootstrap."
        }
        Write-Log -Type ERROR -Message $exchangeMessage -ExportFileLocation $ExportDetails
        throw $exchangeMessage
    }
}

$connectionResult = $null
$defaultTenantDisplayName = 'Tenant'

if ($runExportOnly) {
    $resolvedTenantStatsJsonPath = [System.IO.Path]::GetFullPath($TenantStatsJsonPath)
    $loadedTenantStats = Import-TenantStatsJson -Path $resolvedTenantStatsJsonPath
    if (-not $loadedTenantStats) {
        throw "Export only mode could not load tenant data snapshot: $resolvedTenantStatsJsonPath"
    }
    if (-not ($loadedTenantStats -is [hashtable])) {
        throw "Export only mode requires a hashtable-compatible tenant data snapshot. Snapshot format was not compatible: $resolvedTenantStatsJsonPath"
    }

    $script:tenantStatsHash = $loadedTenantStats
    if (
        $script:LoadedTenantSnapshot -and
        $script:LoadedTenantSnapshot.Contains('CollectionPlan') -and
        $script:LoadedTenantSnapshot['CollectionPlan'] -is [System.Collections.IDictionary]
    ) {
        $script:SnapshotCollectionPlan = [ordered]@{}
        foreach ($entry in $script:LoadedTenantSnapshot['CollectionPlan'].GetEnumerator()) {
            $script:SnapshotCollectionPlan[[string]$entry.Key] = $entry.Value
        }
    }

    if (
        $script:tenantStatsHash.ContainsKey('TenantInfo') -and
        $script:tenantStatsHash['TenantInfo'] -and
        $script:tenantStatsHash['TenantInfo'].PSObject.Properties['DisplayName'] -and
        -not [string]::IsNullOrWhiteSpace([string]$script:tenantStatsHash['TenantInfo'].DisplayName)
    ) {
        $defaultTenantDisplayName = [string]$script:tenantStatsHash['TenantInfo'].DisplayName
    }
}
else {
    $resolvedAuthMode = Resolve-AssessmentRequestedAuthMode -AuthMode $AuthMode -CertificateThumbprint $CertificateThumbprint -ClientSecret $ClientSecret -ClientSecretCredential $ClientSecretCredential -ClientSecretSecure $ClientSecretSecure
    $assessmentGraphScopePlan = Resolve-AssessmentGraphScopePlan -ProfileCollectionPlan $script:ProfileCollectionPlan
    $assessmentAuthWorkloadPlan = Resolve-AssessmentAuthWorkloadPlan `
        -AuthMode $resolvedAuthMode `
        -GraphScopePlan $assessmentGraphScopePlan `
        -NeedsGovernanceCompliancePolicies ([bool]$script:ProfileCollectionPlan.CollectGovernanceCompliancePolicies) `
        -NeedsTeamsInventory ([bool]$script:ProfileCollectionPlan.CollectTeamsDetails) `
        -NeedsTeamsVoice ([bool]$script:ProfileCollectionPlan.CollectTeamsVoiceDetails) `
        -NeedsSharePointData ([bool]$script:ProfileCollectionPlan.CollectSharePointAndOneDriveSites)
    $script:AssessmentAuthWorkloadPlan = $assessmentAuthWorkloadPlan

    # Interactive runs reuse any cached Connect-MgGraph context. Without an explicit
    # TenantId there is nothing to validate that context against, which is how a Graph
    # session belonging to a different customer can end up feeding the assessment.
    if ($resolvedAuthMode -eq 'Interactive' -and [string]::IsNullOrWhiteSpace($TenantId)) {
        throw (
            'Interactive runs require -TenantId so the Microsoft Graph context can be validated against the intended tenant. ' +
            'Without it a cached Connect-MgGraph session from another tenant is reused silently and the assessment mixes tenants. ' +
            'Rerun with -TenantId <guid> for the tenant being assessed.'
        )
    }

    if ($runUseExistingConnections) {
        Write-ConsoleSection -Step 'Connection' -Title 'Existing Connection Check'
        Write-Host 'Using existing Microsoft 365 connections for data collection. Authentication and permission preflight are skipped.' -ForegroundColor Cyan
        $connectionResult = Test-AssessmentExistingSessions -WorkloadPlan $assessmentAuthWorkloadPlan -TenantId $TenantId -ModeLabel 'UseExistingConnections' -ConfirmTenantSelection
    }
    else {
        Write-ConsoleSection -Step 'Connection' -Title 'Connection / Preflight'
        $connectionResult = Initialize-AssessmentAuthentication `
            -WorkloadPlan $assessmentAuthWorkloadPlan `
            -SkipAuth:$SkipAuth `
            -SkipPermissionPreflight:$SkipPermissionPreflight `
            -TenantId $TenantId `
            -ClientId $ClientId `
            -CertificateThumbprint $CertificateThumbprint `
            -ClientSecret $ClientSecret `
            -ClientSecretCredential $ClientSecretCredential `
            -ClientSecretSecure $ClientSecretSecure
    }
    if (
        -not $connectionResult -or
        -not $connectionResult.Graph -or
        -not $connectionResult.ExchangeOnline
    ) {
        throw "Authentication bootstrap did not complete successfully. Graph=$($connectionResult.Graph); ExchangeOnline=$($connectionResult.ExchangeOnline)"
    }

    # Both the fresh-connect and existing-session paths populate these, so validating here
    # covers both. A mixed-tenant run is never valid output, so fail before collecting.
    Assert-AssessmentWorkloadTenantsMatch `
        -GraphTenantDetails $connectionResult.GraphTenantDetails `
        -ExchangeTenantDetails $connectionResult.ExchangeTenantDetails

    # Get default tenant display name from live connection
    $defaultOrganization = $null
    try {
        $defaultOrganization = Get-AssessmentTenantOrganization
    } catch {}
    $defaultTenantDisplayName = if ($defaultOrganization -and $defaultOrganization.DisplayName) { $defaultOrganization.DisplayName } else { 'Tenant' }

    $initialDomainForContext = $null
    if ($connectionResult -and $connectionResult.PSObject.Properties['InitialDomain'] -and $connectionResult.InitialDomain) {
        $initialDomainForContext = [string]$connectionResult.InitialDomain
    }
    Ensure-AssessmentServiceContext -TenantId $TenantId -ClientId $ClientId -CertificateThumbprint $CertificateThumbprint -ClientSecret $ClientSecret -ClientSecretCredential $ClientSecretCredential -ClientSecretSecure $ClientSecretSecure -InitialDomain $initialDomainForContext -ExistingConnectionsOnly:$runUseExistingConnections
    if ($runUseExistingConnections) {
        Write-Host 'Existing connections ready for data collection.' -ForegroundColor Green
    }
    else {
        Write-ConnectionPreflightSummary -ConnectionResult ([pscustomobject]$connectionResult) -PermissionPreflightSkipped:$SkipPermissionPreflight
    }

    if ($runPreflightOnly) {
        return
    }
}

#Get Export Path
$profileFileTagSource = if ([string]::IsNullOrWhiteSpace($effectiveOutputProfileLabel)) { $OutputProfile } else { $effectiveOutputProfileLabel }
$profileFileTag = Convert-ToAssessmentPathComponent -Value (Convert-ToShortAssessmentProfileLabel -Value $profileFileTagSource -Fallback 'Profile') -Fallback 'Profile'
$tenantFileTag = Convert-ToAssessmentPathComponent -Value $defaultTenantDisplayName -Fallback 'Tenant'
$defaultReportFileName = "{0} - Tenant Details" -f $tenantFileTag
$outputFolderProfileLabel = if ($isMergedOutputProfileSelection) { $effectiveOutputProfileLabel } else { $OutputProfile }
$defaultOutputRoot = Get-ArrayaAssessmentOutputRoot -FallbackPath $PSScriptRoot
$resolvedExportTargetPath = Resolve-AssessmentExportTargetPath `
    -RequestedExportPath $ExportPath `
    -DefaultOutputRoot $defaultOutputRoot `
    -TenantDisplayName $defaultTenantDisplayName `
    -OutputProfileFolderLabel $outputFolderProfileLabel
$humanDeliverableTargetPath = Resolve-AssessmentHumanDeliverableTargetPath -ResolvedExportTargetPath $resolvedExportTargetPath
$ExportDetails = Get-ExportPath -FileName $defaultReportFileName -UserInputPath $humanDeliverableTargetPath

# Initialize list to store all discovery errors
$global:AllDiscoveryErrors = New-Object System.Collections.Generic.List[pscustomobject]

# Resolve collection depth and output behavior from the selected profile.
Write-Host -NoNewline '  Output profile:  ' -ForegroundColor DarkGray
Write-Host ("{0}  (scope: {1})" -f $effectiveOutputProfileLabel, $reportingMode) -ForegroundColor Cyan

$script:CollectionDepthPolicy = Get-ArrayaCollectionDepthPolicy -ReportingMode ((Get-Culture).TextInfo.ToTitleCase($reportingMode)) -CollectionScopePolicy $effectiveCollectionScopePolicy

$collectSecureScoreMappings = ($effectiveGenerateBestPracticesHtml -or $effectiveGenerateWorkbook -or $effectiveGenerateJson)
if ($script:CollectionDepthPolicy.PSObject.Properties['CollectSecureScoreMappings']) {
    $script:CollectionDepthPolicy | Add-Member -MemberType NoteProperty -Name CollectSecureScoreMappings -Value ([bool]$collectSecureScoreMappings) -Force
}

$script:ProfileCollectionPlan = Resolve-AssessmentProfileCollectionPlan `
    -OutputProfile $OutputProfile `
    -EffectiveOutputProfileLabel $effectiveOutputProfileLabel `
    -GenerateTechnicalHtml ([bool]$effectiveGenerateTechnicalHtml) `
    -GenerateWorkbook ([bool]$effectiveGenerateWorkbook) `
    -GenerateBestPracticesHtml ([bool]$effectiveGenerateBestPracticesHtml) `
    -GenerateJson ([bool]$effectiveGenerateJson) `
    -GenerateQuestionnaire ([bool]$effectiveGenerateQuestionnaire) `
    -IsMergedOutputProfileSelection ([bool]$isMergedOutputProfileSelection) `
    -ReportingMode $reportingMode `
    -CollectionScopePolicy $effectiveCollectionScopePolicy

$script:SnapshotCollectionPlan = [ordered]@{
    Exchange = [ordered]@{
        Status = if (
            $script:ProfileCollectionPlan.CollectExchangeRecipients -or
            $script:ProfileCollectionPlan.CollectExchangeGroups -or
            $script:ProfileCollectionPlan.CollectMailFlowRulesConnectors -or
            $script:ProfileCollectionPlan.CollectPublicFolders -or
            $script:ProfileCollectionPlan.CollectEmailActivityDetails
        ) { 'Collected' } else { 'Skipped' }
        Collectors = [ordered]@{
            ExchangeRecipients      = [bool]$script:ProfileCollectionPlan.CollectExchangeRecipients
            ExchangeGroups          = [bool]$script:ProfileCollectionPlan.CollectExchangeGroups
            MailFlowRulesConnectors = [bool]$script:ProfileCollectionPlan.CollectMailFlowRulesConnectors
            PublicFolders           = [bool]$script:ProfileCollectionPlan.CollectPublicFolders
            EmailActivity           = [bool]$script:ProfileCollectionPlan.CollectEmailActivityDetails
        }
        NotCollectedReason = if (
            $script:ProfileCollectionPlan.CollectExchangeRecipients -or
            $script:ProfileCollectionPlan.CollectExchangeGroups -or
            $script:ProfileCollectionPlan.CollectMailFlowRulesConnectors -or
            $script:ProfileCollectionPlan.CollectPublicFolders -or
            $script:ProfileCollectionPlan.CollectEmailActivityDetails
        ) { $null } else { 'All Exchange collectors were disabled by output profile policy.' }
    }
    Identity = [ordered]@{
        Status = if (
            $script:ProfileCollectionPlan.CollectUsers -or
            $script:ProfileCollectionPlan.CollectAdmins -or
            $script:ProfileCollectionPlan.CollectEntraGroups -or
            $script:ProfileCollectionPlan.CollectDomains -or
            $script:ProfileCollectionPlan.CollectAuthenticationConfiguration -or
            $script:ProfileCollectionPlan.CollectConditionalAccessPolicies -or
            $script:ProfileCollectionPlan.CollectMfaRegistrationDetails -or
            $script:ProfileCollectionPlan.CollectDevices -or
            $script:ProfileCollectionPlan.CollectSecuritySecureScore
        ) { 'Collected' } else { 'Skipped' }
        Collectors = [ordered]@{
            Users               = [bool]$script:ProfileCollectionPlan.CollectUsers
            Admins              = [bool]$script:ProfileCollectionPlan.CollectAdmins
            EntraGroups         = [bool]$script:ProfileCollectionPlan.CollectEntraGroups
            Devices             = [bool]$script:ProfileCollectionPlan.CollectDevices
            ConditionalAccess   = [bool]$script:ProfileCollectionPlan.CollectConditionalAccessPolicies
            Authentication      = [bool]$script:ProfileCollectionPlan.CollectAuthenticationConfiguration
            SecureScore         = [bool]$script:ProfileCollectionPlan.CollectSecuritySecureScore
            LicenseSkus         = $true
            Domains             = [bool]$script:ProfileCollectionPlan.CollectDomains
        }
        NotCollectedReason = if (
            $script:ProfileCollectionPlan.CollectUsers -or
            $script:ProfileCollectionPlan.CollectAdmins -or
            $script:ProfileCollectionPlan.CollectEntraGroups -or
            $script:ProfileCollectionPlan.CollectDomains -or
            $script:ProfileCollectionPlan.CollectAuthenticationConfiguration -or
            $script:ProfileCollectionPlan.CollectConditionalAccessPolicies -or
            $script:ProfileCollectionPlan.CollectMfaRegistrationDetails -or
            $script:ProfileCollectionPlan.CollectDevices -or
            $script:ProfileCollectionPlan.CollectSecuritySecureScore
        ) { $null } else { 'Identity collectors were disabled by output profile policy.' }
    }
    Collaboration = [ordered]@{
        Status = if (
            $script:ProfileCollectionPlan.CollectUnifiedGroups -or
            $script:ProfileCollectionPlan.CollectTeamsDetails -or
            $script:ProfileCollectionPlan.CollectTeamsVoiceDetails -or
            $script:ProfileCollectionPlan.CollectSharePointAndOneDriveSites
        ) { 'Collected' } else { 'Skipped' }
        Collectors = [ordered]@{
            UnifiedGroups  = [bool]$script:ProfileCollectionPlan.CollectUnifiedGroups
            TeamsInventory = [bool]$script:ProfileCollectionPlan.CollectTeamsDetails
            TeamsVoice     = [bool]$script:ProfileCollectionPlan.CollectTeamsVoiceDetails
            SharePointSite = [bool]$script:ProfileCollectionPlan.CollectSharePointAndOneDriveSites
            Teams          = [bool]$script:ProfileCollectionPlan.CollectTeamsDetails
        }
        NotCollectedReason = if (
            $script:ProfileCollectionPlan.CollectUnifiedGroups -or
            $script:ProfileCollectionPlan.CollectTeamsDetails -or
            $script:ProfileCollectionPlan.CollectTeamsVoiceDetails -or
            $script:ProfileCollectionPlan.CollectSharePointAndOneDriveSites
        ) { $null } else { 'Collaboration enrichment collectors were disabled by output profile policy.' }
    }
    Security = [ordered]@{
        Status = if (
            $script:ProfileCollectionPlan.CollectThirdPartySpamFiltering -or
            $script:ProfileCollectionPlan.CollectSmtpRelayConfiguration -or
            $script:ProfileCollectionPlan.CollectSecuritySecureScore -or
            $script:ProfileCollectionPlan.CollectConditionalAccessPolicies -or
            $script:ProfileCollectionPlan.CollectAuthenticationConfiguration
        ) { 'Collected' } else { 'Partial' }
        Collectors = [ordered]@{
            ThirdPartySpamFiltering = [bool]$script:ProfileCollectionPlan.CollectThirdPartySpamFiltering
            SMTPRelayConfiguration  = [bool]$script:ProfileCollectionPlan.CollectSmtpRelayConfiguration
            SecureScore             = [bool]$script:ProfileCollectionPlan.CollectSecuritySecureScore
            ConditionalAccess       = [bool]$script:ProfileCollectionPlan.CollectConditionalAccessPolicies
            Authentication          = [bool]$script:ProfileCollectionPlan.CollectAuthenticationConfiguration
        }
        NotCollectedReason = $null
    }
    Governance = [ordered]@{
        Status = if ($script:ProfileCollectionPlan.CollectGovernanceCompliancePolicies) { 'Collected' } else { 'Partial' }
        Collectors = [ordered]@{
            RetentionPolicies = [bool]$script:ProfileCollectionPlan.CollectGovernanceCompliancePolicies
            DlpPolicies       = [bool]$script:ProfileCollectionPlan.CollectGovernanceCompliancePolicies
            PasswordLifecycle = $true
        }
        NotCollectedReason = if ($script:ProfileCollectionPlan.CollectGovernanceCompliancePolicies) { $null } else { 'Governance compliance policy collection was disabled by output profile policy.' }
    }
    Tenant = [ordered]@{
        Status = 'Collected'
        Collectors = [ordered]@{
            TenantInfo          = $true
            Federation          = [bool]$script:ProfileCollectionPlan.CollectFederationConfiguration
            AdConnect           = $true
            OwnershipGovernance = [bool]$script:ProfileCollectionPlan.BuildOwnershipGovernanceTables
            ConfigurationTables = [bool]$script:ProfileCollectionPlan.BuildConfigurationSummaryTables
            AssessmentTables    = [bool]$script:ProfileCollectionPlan.BuildAssessmentReportTables
            MigrationReadinessTables = [bool]$script:ProfileCollectionPlan.BuildMigrationReadinessTables
        }
        NotCollectedReason = $null
    }
}

if (
    $runExportOnly -and
    -not (
        $script:LoadedTenantSnapshot -and
        $script:LoadedTenantSnapshot.Contains('CollectionPlan') -and
        $script:LoadedTenantSnapshot['CollectionPlan'] -is [System.Collections.IDictionary]
    )
) {
    foreach ($domainKey in $script:SnapshotCollectionPlan.Keys) {
        $script:SnapshotCollectionPlan[$domainKey].Status = 'NotCollected'
        $script:SnapshotCollectionPlan[$domainKey].NotCollectedReason = 'Export-only mode consumed a previously collected snapshot.'
    }
}

Write-Log -Type INFO -Message ("Collection depth policy: Mode={0}; EntraDeep={1}; GroupCounts={2}; GroupLicenses={3}; SSOAppDetails={4}; ExtendedGraphEnrichment={5}; SecureScoreMappings={6}; MailboxDelegatePermissions={7}; MailboxCalendarDelegatePermissions={8}" -f $script:CollectionDepthPolicy.ReportingMode, $script:CollectionDepthPolicy.CollectEntraGroupDeepDetails, $script:CollectionDepthPolicy.CollectEntraGroupMemberCounts, $script:CollectionDepthPolicy.CollectEntraGroupLicenseChecks, $script:CollectionDepthPolicy.CollectSsoApplicationDetails, $script:CollectionDepthPolicy.CollectExtendedGraphEnrichment, $script:CollectionDepthPolicy.CollectSecureScoreMappings, $script:CollectionDepthPolicy.CollectMailboxDelegatePermissions, $script:CollectionDepthPolicy.CollectMailboxCalendarDelegatePermissions) -ExportFileLocation $ExportDetails
Write-Log -Type INFO -Message ("Profile collection plan ({0}): CollectionScopePolicy={1}; Users={2}; Admins={3}; EntraGroups={4}; Domains={5}; AuthConfig={6}; Federation={7}; ConditionalAccess={8}; MFA={9}; ExchangeRecipients={10}; ExchangeMailboxes={11}; EmailActivity={12}; ExchangeGroups={13}; Hybrid={14}; MailFlow={15}; PublicFolders={16}; SpamFiltering={17}; SMTPRelay={18}; GovernancePolicies={19}; SharePointAndOneDrive={20}; TeamsDetails={21}; TeamsVoice={22}; UnifiedGroups={23}; Devices={24}; SecureScore={25}; OwnershipTables={26}; AssessmentTables={27}; MigrationReadinessTables={28}; ConfigSummaryTables={29}; LicenseMetadata={30}; CombinedUserMailboxProjection={31}" -f $effectiveOutputProfileLabel, $effectiveCollectionScopePolicy, $script:ProfileCollectionPlan.CollectUsers, $script:ProfileCollectionPlan.CollectAdmins, $script:ProfileCollectionPlan.CollectEntraGroups, $script:ProfileCollectionPlan.CollectDomains, $script:ProfileCollectionPlan.CollectAuthenticationConfiguration, $script:ProfileCollectionPlan.CollectFederationConfiguration, $script:ProfileCollectionPlan.CollectConditionalAccessPolicies, $script:ProfileCollectionPlan.CollectMfaRegistrationDetails, $script:ProfileCollectionPlan.CollectExchangeRecipients, $script:ProfileCollectionPlan.CollectExchangeMailboxes, $script:ProfileCollectionPlan.CollectEmailActivityDetails, $script:ProfileCollectionPlan.CollectExchangeGroups, $script:ProfileCollectionPlan.CollectHybridConfiguration, $script:ProfileCollectionPlan.CollectMailFlowRulesConnectors, $script:ProfileCollectionPlan.CollectPublicFolders, $script:ProfileCollectionPlan.CollectThirdPartySpamFiltering, $script:ProfileCollectionPlan.CollectSmtpRelayConfiguration, $script:ProfileCollectionPlan.CollectGovernanceCompliancePolicies, $script:ProfileCollectionPlan.CollectSharePointAndOneDriveSites, $script:ProfileCollectionPlan.CollectTeamsDetails, $script:ProfileCollectionPlan.CollectTeamsVoiceDetails, $script:ProfileCollectionPlan.CollectUnifiedGroups, $script:ProfileCollectionPlan.CollectDevices, $script:ProfileCollectionPlan.CollectSecuritySecureScore, $script:ProfileCollectionPlan.BuildOwnershipGovernanceTables, $script:ProfileCollectionPlan.BuildAssessmentReportTables, $script:ProfileCollectionPlan.BuildMigrationReadinessTables, $script:ProfileCollectionPlan.BuildConfigurationSummaryTables, $script:ProfileCollectionPlan.BuildLicenseClassificationMetadata, $script:ProfileCollectionPlan.BuildCombinedUserMailboxProjection) -ExportFileLocation $ExportDetails

#Global Start Time for Script
$global:InitialStart = Get-Date
Sync-CollectorModuleRuntimeContext

function Update-ExchangeGovernanceTables {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$TenantStatsHash,
        [Parameter(Mandatory = $true)]
        [string]$DetailLevel
    )

    if (-not $TenantStatsHash.ContainsKey('InboxRulesExternalForwarding')) { $TenantStatsHash['InboxRulesExternalForwarding'] = @{} }
    if (-not $TenantStatsHash.ContainsKey('InboxRuleForwardingSummary')) { $TenantStatsHash['InboxRuleForwardingSummary'] = @{} }
    if (-not $TenantStatsHash.ContainsKey('SharedMailboxGovernanceSummary')) { $TenantStatsHash['SharedMailboxGovernanceSummary'] = @{} }
    if (-not $TenantStatsHash.ContainsKey('ForwardingPolicySummary')) { $TenantStatsHash['ForwardingPolicySummary'] = @{} }

    $governanceProgressId = 81
    $inboxRuleProgressId = 82
    $governancePhaseTotal = 3

    try {
        Write-ProgressHelper -Total $governancePhaseTotal -Id $governanceProgressId -Index 1 -Activity 'Exchange governance summaries' -Operation 'Shared mailbox review'
        Write-AssessmentConsoleSubstep -Message 'Exchange governance: shared mailbox review'
        $allMailboxRows = if ($TenantStatsHash.ContainsKey('AllMailboxes') -and $TenantStatsHash['AllMailboxes'] -is [System.Collections.IDictionary]) { @($TenantStatsHash['AllMailboxes'].Values) } else { @() }
        $mailboxFullRows = if ($TenantStatsHash.ContainsKey('MailboxFullDetails') -and $TenantStatsHash['MailboxFullDetails'] -is [System.Collections.IDictionary]) { @($TenantStatsHash['MailboxFullDetails'].Values) } else { @() }
        $sharedMailboxRows = @(
            $allMailboxRows | Where-Object {
                $_ -and $_.PSObject.Properties['RecipientTypeDetails'] -and ([string]$_.RecipientTypeDetails -match 'SharedMailbox')
            }
        )
        $oversizedSharedMailboxes = @(
            $mailboxFullRows | Where-Object {
                $_ -and $_.PSObject.Properties['RecipientTypeDetails'] -and ([string]$_.RecipientTypeDetails -match 'SharedMailbox') -and
                $_.PSObject.Properties['TotalItemSizeGB'] -and $null -ne $_.TotalItemSizeGB -and ([double]$_.TotalItemSizeGB -gt 50)
            }
        )
        $ownerSignalMissing = @(
            $sharedMailboxRows | Where-Object {
                $grantSendOnBehalf = if ($_.PSObject.Properties['GrantSendOnBehalfTo']) { [string]$_.GrantSendOnBehalfTo } else { '' }
                [string]::IsNullOrWhiteSpace($grantSendOnBehalf)
            }
        )
        $TenantStatsHash['SharedMailboxGovernanceSummary']['Summary'] = [pscustomobject]@{
            SharedMailboxCount          = $sharedMailboxRows.Count
            OversizedSharedMailboxes    = $oversizedSharedMailboxes.Count
            SharedMailboxesWithoutOwnerSignal = $ownerSignalMissing.Count
        }
        Write-AssessmentConsoleSubstep -Message ("Exchange governance: shared mailbox review completed ({0} shared; {1} oversized; {2} without owner signal)" -f $sharedMailboxRows.Count, $oversizedSharedMailboxes.Count, $ownerSignalMissing.Count)

        Write-ProgressHelper -Total $governancePhaseTotal -Id $governanceProgressId -Index 2 -Activity 'Exchange governance summaries' -Operation 'Forwarding policy review'
        Write-AssessmentConsoleSubstep -Message 'Exchange governance: forwarding policy review'
        $remoteDomainRows = if ($TenantStatsHash.ContainsKey('RemoteDomains') -and $TenantStatsHash['RemoteDomains'] -is [System.Collections.IDictionary]) { @($TenantStatsHash['RemoteDomains'].Values) } else { @() }
        $remoteDomainsWithForwardingEnabled = @(
            $remoteDomainRows |
                Where-Object {
                    $_ -and
                    $_.PSObject.Properties['AutoForwardEnabled'] -and
                    $_.AutoForwardEnabled -eq $true
                }
        )
        $defaultRemoteDomain = @(
            $remoteDomainRows |
                Where-Object {
                    $identity = if ($_.PSObject.Properties['Identity']) { [string]$_.Identity } else { '' }
                    $domainName = if ($_.PSObject.Properties['DomainName']) { [string]$_.DomainName } else { '' }
                    $identity -match '^default$' -or $domainName -eq '*'
                }
        ) | Select-Object -First 1
        $defaultRemoteDomainForwarding = if ($defaultRemoteDomain) {
            if ($defaultRemoteDomain.PSObject.Properties['AutoForwardEnabled']) { [bool]$defaultRemoteDomain.AutoForwardEnabled } else { $null }
        } else {
            $null
        }

        $hostedOutboundPolicies = @()
        $hostedOutboundRules = @()
        $forwardingPolicyCollectionState = 'Unavailable'
        try {
            if (Get-Command -Name 'Get-HostedOutboundSpamFilterPolicy' -ErrorAction SilentlyContinue) {
                $hostedOutboundPolicies = @(
                    Get-HostedOutboundSpamFilterPolicy -ErrorAction Stop |
                        Select-Object Name, Identity, IsDefault, AutoForwardingMode
                )
                $forwardingPolicyCollectionState = 'Collected'
            }
        }
        catch {
            $forwardingPolicyCollectionState = 'PolicyLookupFailed'
            Write-Log -Type DEBUG -Message "[Update-ExchangeGovernanceTables] Hosted outbound spam filter policy lookup failed: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }

        try {
            if (Get-Command -Name 'Get-HostedOutboundSpamFilterRule' -ErrorAction SilentlyContinue) {
                $hostedOutboundRules = @(
                    Get-HostedOutboundSpamFilterRule -ErrorAction Stop |
                        Select-Object Name, HostedOutboundSpamFilterPolicy, State, Priority
                )
                if ($forwardingPolicyCollectionState -eq 'Unavailable') {
                    $forwardingPolicyCollectionState = 'RulesOnly'
                }
            }
        }
        catch {
            if ($forwardingPolicyCollectionState -eq 'Unavailable') {
                $forwardingPolicyCollectionState = 'RuleLookupFailed'
            }
            Write-Log -Type DEBUG -Message "[Update-ExchangeGovernanceTables] Hosted outbound spam filter rule lookup failed: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }

        $policiesExplicitlyAllowingAutoForwarding = @(
            $hostedOutboundPolicies |
                Where-Object {
                    $mode = if ($_.PSObject.Properties['AutoForwardingMode']) { [string]$_.AutoForwardingMode } else { '' }
                    $mode -match '^(On|Automatic)$'
                }
        )
        $policiesRestrictingAutoForwarding = @(
            $hostedOutboundPolicies |
                Where-Object {
                    $mode = if ($_.PSObject.Properties['AutoForwardingMode']) { [string]$_.AutoForwardingMode } else { '' }
                    $mode -match '^(Off|InternalOnly)$'
                }
        )
        $autoForwardModeSummary = @(
            $hostedOutboundPolicies |
                ForEach-Object {
                    $policyName = if ($_.PSObject.Properties['Name']) { [string]$_.Name } elseif ($_.PSObject.Properties['Identity']) { [string]$_.Identity } else { 'UnnamedPolicy' }
                    $mode = if ($_.PSObject.Properties['AutoForwardingMode']) { [string]$_.AutoForwardingMode } else { 'Unknown' }
                    "{0}={1}" -f $policyName, $mode
                }
        )
        $rulePolicyAssignments = @(
            $hostedOutboundRules |
                ForEach-Object {
                    $policyName = if ($_.PSObject.Properties['HostedOutboundSpamFilterPolicy']) { [string]$_.HostedOutboundSpamFilterPolicy } else { '' }
                    if (-not [string]::IsNullOrWhiteSpace($policyName)) { $policyName }
                } |
                Sort-Object -Unique
        )

        $TenantStatsHash['ForwardingPolicySummary']['Summary'] = [pscustomobject]@{
            PolicyCollectionState                    = $forwardingPolicyCollectionState
            HostedOutboundPolicyCount                = $hostedOutboundPolicies.Count
            HostedOutboundRuleCount                  = $hostedOutboundRules.Count
            PoliciesExplicitlyAllowingAutoForwarding = $policiesExplicitlyAllowingAutoForwarding.Count
            PoliciesRestrictingAutoForwarding        = $policiesRestrictingAutoForwarding.Count
            PolicyAutoForwardingModes                = if ($autoForwardModeSummary.Count -gt 0) { $autoForwardModeSummary -join '; ' } else { $null }
            PoliciesReferencedByRules                = if ($rulePolicyAssignments.Count -gt 0) { $rulePolicyAssignments -join '; ' } else { $null }
            RemoteDomainCount                        = $remoteDomainRows.Count
            RemoteDomainsAllowingAutoForwarding      = $remoteDomainsWithForwardingEnabled.Count
            RemoteDomainsAllowingAutoForwardingList  = if ($remoteDomainsWithForwardingEnabled.Count -gt 0) {
                @(
                    $remoteDomainsWithForwardingEnabled |
                        ForEach-Object {
                            if ($_.PSObject.Properties['Identity']) { [string]$_.Identity } elseif ($_.PSObject.Properties['DomainName']) { [string]$_.DomainName } else { '' }
                        } |
                        Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
                        Sort-Object -Unique
                ) -join '; '
            } else { $null }
            DefaultRemoteDomainAllowsAutoForwarding  = $defaultRemoteDomainForwarding
        }
        Write-AssessmentConsoleSubstep -Message ("Exchange governance: forwarding policy review completed ({0} policy rows; {1} rule rows; {2} remote domains allowing auto-forwarding)" -f $hostedOutboundPolicies.Count, $hostedOutboundRules.Count, $remoteDomainsWithForwardingEnabled.Count)

        if ($DetailLevel -eq 'minimum') {
            Write-ProgressHelper -Total $governancePhaseTotal -Id $governanceProgressId -Index 3 -Activity 'Exchange governance summaries' -Operation 'Inbox rule forwarding review skipped in minimum mode'
            Write-AssessmentConsoleSubstep -Message 'Exchange governance: inbox rule forwarding review skipped in minimum mode'
            $TenantStatsHash['InboxRuleForwardingSummary']['Summary'] = [pscustomobject]@{
                InspectedMailboxCount = 0
                ExternalForwardingRuleCount = 0
                LookupFailureCount = 0
                SlowMailboxCount = 0
                CollectionState = 'Skipped in minimum mode'
            }
            return
        }

        Write-AssessmentConsoleSubstep -Message 'Exchange governance: inbox rule forwarding review'
        $acceptedDomains = @()
        if ($TenantStatsHash.ContainsKey('Domains') -and $TenantStatsHash['Domains'] -is [System.Collections.IDictionary]) {
            $acceptedDomains = @(
                $TenantStatsHash['Domains'].Values |
                    ForEach-Object { if ($_.PSObject.Properties['Domain']) { [string]$_.Domain } elseif ($_.PSObject.Properties['Id']) { [string]$_.Id } } |
                    Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
                    ForEach-Object { $_.Trim().ToLowerInvariant() } |
                    Select-Object -Unique
            )
        }

        $mailboxesToInspect = @(
            $allMailboxRows | Where-Object {
                $_ -and $_.PSObject.Properties['PrimarySmtpAddress'] -and $_.PrimarySmtpAddress -and
                ([string]$_.RecipientTypeDetails -in @('UserMailbox', 'SharedMailbox'))
            }
        )

        Write-ProgressHelper -Total $governancePhaseTotal -Id $governanceProgressId -Index 3 -Activity 'Exchange governance summaries' -Operation ("Inbox rule forwarding review across {0} mailbox(es)" -f $mailboxesToInspect.Count)
        $inboxRuleProgressTotal = [Math]::Max($mailboxesToInspect.Count, 1)
        Write-ProgressHelper -Total $inboxRuleProgressTotal -Id $inboxRuleProgressId -Index 0 -Activity 'Reviewing mailbox inbox rules for external forwarding' -Operation 'Preparing mailbox review'

        $ruleIndex = 0
        $processedMailboxCount = 0
        $inboxRuleLookupFailureCount = 0
        $slowInboxRuleMailboxCount = 0
        $slowInboxRuleMailboxThresholdSeconds = 20

        foreach ($mailbox in $mailboxesToInspect) {
            $processedMailboxCount++
            $mailboxAddress = [string]$mailbox.PrimarySmtpAddress
            $mailboxProgressLabel = @(
                $mailboxAddress
                [string]$mailbox.UserPrincipalName
                [string]$mailbox.DisplayName
            ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1
            if ([string]::IsNullOrWhiteSpace($mailboxProgressLabel)) {
                $mailboxProgressLabel = "Mailbox $processedMailboxCount"
            }

            Write-ProgressHelper -Total $inboxRuleProgressTotal -Id $inboxRuleProgressId -Index $processedMailboxCount -Activity 'Reviewing mailbox inbox rules for external forwarding' -Operation ("Mailbox {0}/{1}: {2} | External rules {3} | Lookup failures {4}" -f $processedMailboxCount, $mailboxesToInspect.Count, $mailboxProgressLabel, $TenantStatsHash['InboxRulesExternalForwarding'].Count, $inboxRuleLookupFailureCount)

            $mailboxRuleStopwatch = [System.Diagnostics.Stopwatch]::StartNew()
            $previousWarningPreference = $WarningPreference
            $errorCountBeforeInboxRuleLookup = $global:Error.Count
            try {
                $WarningPreference = 'SilentlyContinue'
                $inboxRules = @(Get-InboxRule -Mailbox $mailboxAddress -WarningAction SilentlyContinue -ErrorAction Stop)
                foreach ($rule in $inboxRules) {
                    $forwardTargets = @()
                    foreach ($propertyName in @('ForwardTo', 'ForwardAsAttachmentTo', 'RedirectTo')) {
                        if ($rule.PSObject.Properties[$propertyName] -and $rule.$propertyName) {
                            $forwardTargets += @($rule.$propertyName | ForEach-Object { [string]$_ })
                        }
                    }
                    if ($forwardTargets.Count -eq 0) { continue }

                    $externalTargets = @(
                        $forwardTargets |
                            ForEach-Object {
                                $addressText = $_
                                $domainPart = $null
                                if ($addressText -match '@') {
                                    $domainPart = ($addressText -split '@')[-1].Trim().Trim('>',';').ToLowerInvariant()
                                }
                                if (-not [string]::IsNullOrWhiteSpace($domainPart) -and ($acceptedDomains -notcontains $domainPart)) {
                                    $addressText
                                }
                            } |
                            Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
                    )
                    if ($externalTargets.Count -eq 0) { continue }

                    $ruleIndex++
                    $TenantStatsHash['InboxRulesExternalForwarding'][("{0:D4}-{1}" -f $ruleIndex, ($mailboxAddress -replace '[^a-zA-Z0-9@._-]', '_'))] = [pscustomobject]@{
                        Mailbox            = $mailboxAddress
                        RuleName           = $rule.Name
                        Enabled            = $rule.Enabled
                        Description        = $rule.Description
                        ExternalTargets    = ($externalTargets -join ',')
                        ForwardTargetCount = $externalTargets.Count
                    }
                }
            }
            catch {
                $inboxRuleLookupFailureCount++
                while ($global:Error.Count -gt $errorCountBeforeInboxRuleLookup) {
                    $global:Error.RemoveAt(0)
                }
                Write-Log -Type DEBUG -Message "[Update-ExchangeGovernanceTables] Inbox rule lookup failed for ${mailboxAddress}: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
            }
            finally {
                $WarningPreference = $previousWarningPreference
                $mailboxRuleStopwatch.Stop()
            }

            if ($mailboxRuleStopwatch.Elapsed.TotalSeconds -ge $slowInboxRuleMailboxThresholdSeconds) {
                $slowInboxRuleMailboxCount++
                Write-Log -Type INFO -Message ("[Update-ExchangeGovernanceTables] Slow inbox rule lookup detected for mailbox '{0}'. Duration={1}; FindingsSoFar={2}" -f $mailboxProgressLabel, $mailboxRuleStopwatch.Elapsed.ToString('hh\:mm\:ss'), $TenantStatsHash['InboxRulesExternalForwarding'].Count) -ExportFileLocation $ExportDetails
            }
        }

        $TenantStatsHash['InboxRuleForwardingSummary']['Summary'] = [pscustomobject]@{
            InspectedMailboxCount        = $mailboxesToInspect.Count
            ExternalForwardingRuleCount  = $TenantStatsHash['InboxRulesExternalForwarding'].Count
            LookupFailureCount           = $inboxRuleLookupFailureCount
            SlowMailboxCount             = $slowInboxRuleMailboxCount
            CollectionState              = 'Collected'
        }
        Write-AssessmentConsoleSubstep -Message ("Exchange governance: inbox rule forwarding review completed ({0} mailbox(es); {1} external forwarding rule(s); {2} lookup issue(s))" -f $mailboxesToInspect.Count, $TenantStatsHash['InboxRulesExternalForwarding'].Count, $inboxRuleLookupFailureCount)
    }
    finally {
        Write-ProgressHelper -Total ([Math]::Max($governancePhaseTotal, 1)) -Id $governanceProgressId -Activity 'Exchange governance summaries' -Completed
        Write-ProgressHelper -Total 1 -Id $inboxRuleProgressId -Activity 'Reviewing mailbox inbox rules for external forwarding' -Completed
    }
}

function Update-DeviceManagementSummary {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$TenantStatsHash
    )

    Write-AssessmentConsoleSubstep -Message 'Device management summaries: building compliance and supportability rollup'
    if (-not $TenantStatsHash.ContainsKey('DeviceManagementSummary')) { $TenantStatsHash['DeviceManagementSummary'] = @{} }

    $deviceRows = if ($TenantStatsHash.ContainsKey('DeviceDetails') -and $TenantStatsHash['DeviceDetails'] -is [System.Collections.IDictionary]) { @($TenantStatsHash['DeviceDetails'].Values) } else { @() }
    $managedDeviceCount = @($deviceRows | Where-Object { $_.PSObject.Properties['IsManaged'] -and $_.IsManaged -eq $true }).Count
    $compliantDeviceCount = @($deviceRows | Where-Object { $_.PSObject.Properties['IsCompliant'] -and $_.IsCompliant -eq $true }).Count
    $unsupportedOsCount = @(
        $deviceRows | Where-Object {
            $os = [string]$_.OperatingSystem
            $version = [string]$_.OperatingSystemVersion
            ($os -match 'Windows' -and $version -match '^10\.0\.(1[0-8]\d{3}|9\d{3})') -or
            ($os -match 'Windows' -and $version -match '^6\.') -or
            ($os -match 'Android' -and $version -match '^[0-9]+(\.[0-9]+)?' -and ([double]($version.Split('.')[0]) -lt 10)) -or
            ($os -match 'iOS' -and $version -match '^[0-9]+(\.[0-9]+)?' -and ([double]($version.Split('.')[0]) -lt 16))
        }
    ).Count

    $TenantStatsHash['DeviceManagementSummary']['Summary'] = [pscustomobject]@{
        TotalDevices         = $deviceRows.Count
        ManagedDevices       = $managedDeviceCount
        UnmanagedDevices     = $deviceRows.Count - $managedDeviceCount
        CompliantDevices     = $compliantDeviceCount
        NonCompliantDevices  = $deviceRows.Count - $compliantDeviceCount
        UnsupportedOsDevices = $unsupportedOsCount
    }
    Write-AssessmentConsoleSubstep -Message ("Device management summaries: completed ({0} device(s); {1} managed; {2} unsupported OS)" -f $deviceRows.Count, $managedDeviceCount, $unsupportedOsCount)
}

function Update-TierBOperationalSummaries {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$TenantStatsHash
    )

    $tierBProgressId = 91
    $tierBProgressTotal = 4
    Write-ProgressHelper -Total $tierBProgressTotal -Id $tierBProgressId -Index 1 -Activity 'Governance summaries' -Operation 'Normalizing device management summary'
    Write-AssessmentConsoleSubstep -Message 'Governance summaries: device and SharePoint/OneDrive rollups'
    if (-not $TenantStatsHash.ContainsKey('SharePointSharingSummary')) { $TenantStatsHash['SharePointSharingSummary'] = @{} }
    $deviceRows = if ($TenantStatsHash.ContainsKey('DeviceDetails') -and $TenantStatsHash['DeviceDetails'] -is [System.Collections.IDictionary]) { @($TenantStatsHash['DeviceDetails'].Values) } else { @() }
    if ($deviceRows.Count -gt 0) {
        Update-DeviceManagementSummary -TenantStatsHash $TenantStatsHash
    }

    $sharePointRows = if ($TenantStatsHash.ContainsKey('SharePoint') -and $TenantStatsHash['SharePoint'] -is [System.Collections.IDictionary]) { @($TenantStatsHash['SharePoint'].Values) } else { @() }
    $oneDriveRows = if ($TenantStatsHash.ContainsKey('OneDrive') -and $TenantStatsHash['OneDrive'] -is [System.Collections.IDictionary]) { @($TenantStatsHash['OneDrive'].Values) } else { @() }

    $sharePointSummary = [ordered]@{
        CollectionState                         = 'Not collected'
        CollectionSource                        = 'Not collected'
        SettingsApiVersion                      = 'Not collected'
        TenantSharingCapability                 = 'Not collected'
        OneDriveSharingCapability               = 'Not collected'
        DefaultSharingLinkType                  = 'Not collected'
        DefaultLinkPermission                   = 'Not collected'
        FileAnonymousLinkType                   = 'Not collected'
        AnonymousLinkExpirationInDays           = 'Not collected'
        RequireAnonymousLinksExpire             = 'Not collected'
        SharingDomainRestrictionMode            = 'Not collected'
        SharingAllowedDomainList                = 'Not collected'
        SharingBlockedDomainList                = 'Not collected'
        RequireInvitedUserMatch                 = 'Not collected'
        ExternalResharingEnabled                = 'Not collected'
        PreventExternalUsersFromResharing       = 'Not collected'
        GuestAccessExpirationInDays             = 'Not collected'
        OneDriveStorageQuotaMB                  = 'Not collected'
        SiteCreationDefaultStorageQuotaMB       = 'Not collected'
        IsSitesStorageLimitAutomatic            = 'Not collected'
        DeletedUserPersonalSiteRetentionPeriodInDays = 'Not collected'
        IsLegacyAuthProtocolsEnabled            = 'Not collected'
        DisableCustomAppAuthentication          = 'Not collected'
        IsUnmanagedSyncAppForTenantRestricted   = 'Not collected'
        IsSyncButtonHiddenOnPersonalSite        = 'Not collected'
        IsSiteCreationEnabled                   = 'Not collected'
        IsSiteCreationUIEnabled                 = 'Not collected'
        IsLoopEnabled                           = 'Not collected'
        AvailableManagedPathsForSiteCreation    = 'Not collected'
        SiteCreationDefaultManagedPath          = 'Not collected'
        AllowedDomainGuidsForSyncApp            = 'Not collected'
        ExcludedFileExtensionsForSyncApp        = 'Not collected'
    }
    $sharePointSettingsPropertyMap = [ordered]@{
        TenantSharingCapability                 = @('sharingCapability', 'SharingCapability')
        OneDriveSharingCapability               = @('oneDriveSharingCapability', 'OneDriveSharingCapability', 'ODBSharingCapability')
        DefaultSharingLinkType                  = @('defaultSharingLinkType', 'DefaultSharingLinkType', 'defaultShareLinkScope', 'DefaultShareLinkScope', 'defaultSharingScope', 'DefaultSharingScope')
        DefaultLinkPermission                   = @('defaultLinkPermission', 'DefaultLinkPermission', 'defaultShareLinkRole', 'DefaultShareLinkRole')
        FileAnonymousLinkType                   = @('fileAnonymousLinkType', 'FileAnonymousLinkType')
        AnonymousLinkExpirationInDays           = @('anonymousLinkExpirationInDays', 'AnonymousLinkExpirationInDays', 'RequireAnonymousLinksExpireInDays')
        SharingDomainRestrictionMode            = @('sharingDomainRestrictionMode', 'SharingDomainRestrictionMode')
        SharingAllowedDomainList                = @('sharingAllowedDomainList', 'SharingAllowedDomainList')
        SharingBlockedDomainList                = @('sharingBlockedDomainList', 'SharingBlockedDomainList')
        RequireInvitedUserMatch                 = @('isRequireAcceptingUserToMatchInvitedUserEnabled', 'IsRequireAcceptingUserToMatchInvitedUserEnabled', 'RequireAcceptingUserToMatchInvitedUserEnabled')
        ExternalResharingEnabled                = @('isResharingByExternalUsersEnabled', 'IsResharingByExternalUsersEnabled')
        GuestAccessExpirationInDays             = @('guestExpirationInDays', 'GuestExpirationInDays', 'ExternalUserExpirationInDays', 'ExternalUserExpireInDays')
        OneDriveStorageQuotaMB                  = @('personalSiteDefaultStorageLimitInMB', 'PersonalSiteDefaultStorageLimitInMB', 'OneDriveStorageQuota')
        SiteCreationDefaultStorageQuotaMB       = @('siteCreationDefaultStorageLimitInMB', 'SiteCreationDefaultStorageLimitInMB', 'SiteCreationDefaultStorageQuota')
        IsSitesStorageLimitAutomatic            = @('isSitesStorageLimitAutomatic', 'IsSitesStorageLimitAutomatic', 'AutoQuotaEnabled')
        DeletedUserPersonalSiteRetentionPeriodInDays = @('deletedUserPersonalSiteRetentionPeriodInDays', 'DeletedUserPersonalSiteRetentionPeriodInDays', 'OrphanedPersonalSitesRetentionPeriod')
        IsLegacyAuthProtocolsEnabled            = @('isLegacyAuthProtocolsEnabled', 'IsLegacyAuthProtocolsEnabled', 'LegacyAuthProtocolsEnabled')
        DisableCustomAppAuthentication          = @('disableCustomAppAuthentication', 'DisableCustomAppAuthentication')
        ExternalServicesEnabled                 = @('externalServicesEnabled', 'ExternalServicesEnabled')
        ShowEveryoneClaim                       = @('showEveryoneClaim', 'ShowEveryoneClaim')
        ShowAllUsersClaim                       = @('showAllUsersClaim', 'ShowAllUsersClaim')
        ShowEveryoneExceptExternalUsersClaim    = @('showEveryoneExceptExternalUsersClaim', 'ShowEveryoneExceptExternalUsersClaim')
        AllowEveryoneExceptExternalUsersClaimInPrivateSite = @('allowEveryoneExceptExternalUsersClaimInPrivateSite', 'AllowEveryoneExceptExternalUsersClaimInPrivateSite')
        AnyoneLinkTrackUsers                    = @('anyoneLinkTrackUsers', 'AnyoneLinkTrackUsers')
        OwnerAnonymousNotification              = @('ownerAnonymousNotification', 'OwnerAnonymousNotification')
        NotifyOwnersWhenItemsReshared           = @('notifyOwnersWhenItemsReshared', 'NotifyOwnersWhenItemsReshared')
        NotifyOwnersWhenInvitationsAccepted     = @('notifyOwnersWhenInvitationsAccepted', 'NotifyOwnersWhenInvitationsAccepted')
        EnableAzureADB2BIntegration             = @('enableAzureADB2BIntegration', 'EnableAzureADB2BIntegration')
        SharePointAddInsDisabled                = @('sharePointAddInsDisabled', 'SharePointAddInsDisabled')
        SharePointAddInsBlocked                 = @('sharePointAddInsBlocked', 'SharePointAddInsBlocked')
        EnableSensitivityLabelForPDF            = @('enableSensitivityLabelForPDF', 'EnableSensitivityLabelForPDF')
        EnableSensitivityLabelForOneNote        = @('enableSensitivityLabelForOneNote', 'EnableSensitivityLabelForOneNote')
        EnableSensitivityLabelForVideoFiles     = @('enableSensitivityLabelForVideoFiles', 'EnableSensitivityLabelForVideoFiles')
        AllowFileArchive                        = @('allowFileArchive', 'AllowFileArchive')
        AllowFileArchiveOnNewSitesByDefault     = @('allowFileArchiveOnNewSitesByDefault', 'AllowFileArchiveOnNewSitesByDefault')
        RecycleBinRetentionPeriod               = @('recycleBinRetentionPeriod', 'RecycleBinRetentionPeriod')
        AllowDownloadingNonWebViewableFiles     = @('allowDownloadingNonWebViewableFiles', 'AllowDownloadingNonWebViewableFiles')
        AllowEditing                            = @('allowEditing', 'AllowEditing')
        MarkNewFilesSensitiveByDefault          = @('markNewFilesSensitiveByDefault', 'MarkNewFilesSensitiveByDefault')
        RestrictedOneDriveLicense               = @('restrictedOneDriveLicense', 'RestrictedOneDriveLicense')
        RestrictedSharePointLicense             = @('restrictedSharePointLicense', 'RestrictedSharePointLicense')
        IsUnmanagedSyncAppForTenantRestricted   = @('isUnmanagedSyncAppForTenantRestricted', 'IsUnmanagedSyncAppForTenantRestricted')
        IsSyncButtonHiddenOnPersonalSite        = @('isSyncButtonHiddenOnPersonalSite', 'IsSyncButtonHiddenOnPersonalSite')
        IsSiteCreationEnabled                   = @('isSiteCreationEnabled', 'IsSiteCreationEnabled')
        IsSiteCreationUIEnabled                 = @('isSiteCreationUIEnabled', 'IsSiteCreationUIEnabled')
        IsLoopEnabled                           = @('isLoopEnabled', 'IsLoopEnabled')
        AvailableManagedPathsForSiteCreation    = @('availableManagedPathsForSiteCreation', 'AvailableManagedPathsForSiteCreation')
        SiteCreationDefaultManagedPath          = @('siteCreationDefaultManagedPath', 'SiteCreationDefaultManagedPath')
        AllowedDomainGuidsForSyncApp            = @('allowedDomainGuidsForSyncApp', 'AllowedDomainGuidsForSyncApp')
        ExcludedFileExtensionsForSyncApp        = @('excludedFileExtensionsForSyncApp', 'ExcludedFileExtensionsForSyncApp')
    }
    $sharePointSettingsSources = New-Object System.Collections.Generic.List[string]
    $sharePointSettingsApiVersions = New-Object System.Collections.Generic.List[string]
    $spoTenantSettingsRetrieved = $false
    $graphSharePointSettingsRetrieved = $false

    function Update-SharePointSummaryFromSettingsObject {
        param(
            [AllowNull()][object]$SettingsObject,
            [string]$SourceLabel,
            [string]$ApiVersion
        )

        if ($null -eq $SettingsObject) {
            return $false
        }

        $updated = $false
        foreach ($summaryKey in $sharePointSettingsPropertyMap.Keys) {
            if ([string]$sharePointSummary[$summaryKey] -ne 'Not collected') {
                continue
            }

            $rawValue = $null
            foreach ($propertyName in @($sharePointSettingsPropertyMap[$summaryKey])) {
                if ($SettingsObject.PSObject -and $SettingsObject.PSObject.Properties[$propertyName]) {
                    $rawValue = $SettingsObject.$propertyName
                    break
                }
            }

            if ($null -eq $rawValue) {
                continue
            }

            if ($rawValue -is [System.Collections.IEnumerable] -and -not ($rawValue -is [string])) {
                $normalizedValues = @($rawValue | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
                if ($normalizedValues.Count -eq 0) {
                    continue
                }
                $sharePointSummary[$summaryKey] = ($normalizedValues -join ', ')
                $updated = $true
                continue
            }

            if (-not [string]::IsNullOrWhiteSpace([string]$rawValue)) {
                $sharePointSummary[$summaryKey] = $rawValue
                $updated = $true
            }
        }

        if ([string]$sharePointSummary['DefaultSharingLinkType'] -eq 'Not collected') {
            foreach ($propertyName in @('DefaultLinkToExistingAccess', 'DefaultShareLinkToExistingAccess', 'defaultLinkToExistingAccess', 'defaultShareLinkToExistingAccess')) {
                if ($SettingsObject.PSObject -and $SettingsObject.PSObject.Properties[$propertyName] -and $null -ne $SettingsObject.$propertyName) {
                    try {
                        if ([bool]$SettingsObject.$propertyName) {
                            $sharePointSummary['DefaultSharingLinkType'] = 'ExistingAccess'
                            $updated = $true
                            break
                        }
                    }
                    catch {}
                }
            }
        }

        if ($updated) {
            if (-not [string]::IsNullOrWhiteSpace($SourceLabel) -and -not $sharePointSettingsSources.Contains($SourceLabel)) {
                $sharePointSettingsSources.Add($SourceLabel) | Out-Null
            }
            if (-not [string]::IsNullOrWhiteSpace($ApiVersion) -and -not $sharePointSettingsApiVersions.Contains($ApiVersion)) {
                $sharePointSettingsApiVersions.Add($ApiVersion) | Out-Null
            }
        }

        return $updated
    }

    $sharePointConnected = $false
    $scriptConnectionResult = Get-Variable -Name connectionResult -Scope Script -ErrorAction SilentlyContinue
    if ($scriptConnectionResult -and $scriptConnectionResult.Value -and $scriptConnectionResult.Value.PSObject.Properties['SharePointOnline']) {
        $sharePointConnectionValue = $scriptConnectionResult.Value.SharePointOnline
        if ($sharePointConnectionValue -is [bool]) {
            $sharePointConnected = $sharePointConnectionValue
        }
        elseif (-not [string]::IsNullOrWhiteSpace([string]$sharePointConnectionValue)) {
            $sharePointConnected = ([string]$sharePointConnectionValue -match '^(?i:true|1|yes|connected)$')
        }
    }

    if ($sharePointConnected) {
        Write-ProgressHelper -Total $tierBProgressTotal -Id $tierBProgressId -Index 2 -Activity 'Governance summaries' -Operation 'Reviewing SharePoint tenant settings from the admin session'
        Write-AssessmentConsoleSubstep -Message 'Governance summaries: reviewing SharePoint tenant settings from SharePoint Online'
        $spoTenantCommand = Get-Command -Name 'Get-SPOTenant' -ErrorAction SilentlyContinue
        if ($spoTenantCommand) {
            try {
                $spoTenant = Get-SPOTenant -ErrorAction Stop
                $spoTenantSettingsRetrieved = $true
                $null = Update-SharePointSummaryFromSettingsObject -SettingsObject $spoTenant -SourceLabel 'SharePoint Online Management Shell' -ApiVersion 'SPO'
            }
            catch {
                Write-Log -Type DEBUG -Message "[Update-TierBOperationalSummaries] SharePoint tenant sharing summary lookup failed: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
            }
        }
    }

    $requiresGraphSharePointSettings = @(
        $sharePointSettingsPropertyMap.Keys | Where-Object { [string]$sharePointSummary[$_] -eq 'Not collected' }
    )

    if ($requiresGraphSharePointSettings.Count -gt 0) {
        Write-ProgressHelper -Total $tierBProgressTotal -Id $tierBProgressId -Index 3 -Activity 'Governance summaries' -Operation 'Reviewing SharePoint tenant settings from Microsoft Graph'
        Write-AssessmentConsoleSubstep -Message 'Governance summaries: reviewing SharePoint tenant settings from Microsoft Graph'
        try {
            $sharePointSettingsResponse = Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/v1.0/admin/sharepoint/settings' -Activity 'Fetching SharePoint tenant settings'
            $sharePointSettings = @($sharePointSettingsResponse | Select-Object -First 1)
            if ($sharePointSettings.Count -gt 0 -and $sharePointSettings[0]) {
                $graphSharePointSettingsRetrieved = $true
                $null = Update-SharePointSummaryFromSettingsObject -SettingsObject $sharePointSettings[0] -SourceLabel 'Microsoft Graph SharePoint tenant settings' -ApiVersion 'v1.0'
            }
        }
        catch {
            Write-Log -Type DEBUG -Message "[Update-TierBOperationalSummaries] Graph SharePoint settings lookup failed: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }
    }

    $requiresGraphBetaSharePointSettings = @(
        'OneDriveSharingCapability',
        'DefaultSharingLinkType',
        'DefaultLinkPermission',
        'AnonymousLinkExpirationInDays',
        'GuestAccessExpirationInDays'
    ) | Where-Object { [string]$sharePointSummary[$_] -eq 'Not collected' }

    if ($requiresGraphBetaSharePointSettings.Count -gt 0) {
        Write-AssessmentConsoleSubstep -Message 'Governance summaries: attempting beta SharePoint settings fallback for remaining fields' -ForegroundColor Yellow
        try {
            Write-Log -Type WARNING -Message "[Update-TierBOperationalSummaries] Some SharePoint tenant settings are not available from Graph v1.0 in this run. Attempting a best-effort beta fallback for the remaining fields." -ExportFileLocation $ExportDetails
            $sharePointBetaSettingsResponse = Get-ArrayaGraphResource -Uri 'https://graph.microsoft.com/beta/admin/sharepoint/settings' -Activity 'Fetching SharePoint tenant settings (beta best-effort fallback)'
            $sharePointBetaSettings = @($sharePointBetaSettingsResponse | Select-Object -First 1)
            if ($sharePointBetaSettings.Count -gt 0 -and $sharePointBetaSettings[0]) {
                $graphSharePointSettingsRetrieved = $true
                $null = Update-SharePointSummaryFromSettingsObject -SettingsObject $sharePointBetaSettings[0] -SourceLabel 'Microsoft Graph SharePoint tenant settings beta best-effort fallback' -ApiVersion 'beta'
            }
        }
        catch {
            Write-Log -Type DEBUG -Message "[Update-TierBOperationalSummaries] Graph SharePoint settings beta best-effort fallback failed: $($_.Exception.Message)" -ExportFileLocation $ExportDetails
        }
    }

    $sharePointInventoryRows = @($sharePointRows) + @($oneDriveRows)
    if ($sharePointInventoryRows.Count -gt 0) {
        Write-ProgressHelper -Total $tierBProgressTotal -Id $tierBProgressId -Index 4 -Activity 'Governance summaries' -Operation ("Deriving sharing rollups from {0} site inventory row(s)" -f $sharePointInventoryRows.Count)
        Write-AssessmentConsoleSubstep -Message ("Governance summaries: deriving sharing rollups from {0} SharePoint/OneDrive inventory row(s)" -f $sharePointInventoryRows.Count)
        $oneDriveSharingCapabilities = @(
            $oneDriveRows |
                ForEach-Object {
                    if ($_.PSObject.Properties['SharingCapability']) { [string]$_.SharingCapability } else { $null }
                } |
                Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
                Select-Object -Unique
        )
        $sharingCapabilities = @(
            $sharePointInventoryRows |
                ForEach-Object {
                    if ($_.PSObject.Properties['SharingCapability']) { [string]$_.SharingCapability } else { $null }
                } |
                Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
                Select-Object -Unique
        )
        $defaultSharingLinkTypes = @(
            $sharePointInventoryRows |
                ForEach-Object {
                    if ($_.PSObject.Properties['DefaultSharingLinkType']) { [string]$_.DefaultSharingLinkType } else { $null }
                } |
                Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
                Select-Object -Unique
        )
        $defaultLinkPermissions = @(
            $sharePointInventoryRows |
                ForEach-Object {
                    if ($_.PSObject.Properties['DefaultLinkPermission']) { [string]$_.DefaultLinkPermission } else { $null }
                } |
                Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
                Select-Object -Unique
        )

        if ($sharingCapabilities.Count -gt 0 -and [string]$sharePointSummary['TenantSharingCapability'] -eq 'Not collected') {
            $sharePointSummary['TenantSharingCapability'] = ($sharingCapabilities -join ', ')
        }
        if ($oneDriveSharingCapabilities.Count -gt 0 -and [string]$sharePointSummary['OneDriveSharingCapability'] -eq 'Not collected') {
            $sharePointSummary['OneDriveSharingCapability'] = ($oneDriveSharingCapabilities -join ', ')
        }
        if ($defaultSharingLinkTypes.Count -gt 0 -and [string]$sharePointSummary['DefaultSharingLinkType'] -eq 'Not collected') {
            $sharePointSummary['DefaultSharingLinkType'] = ($defaultSharingLinkTypes -join ', ')
        }
        if ($defaultLinkPermissions.Count -gt 0 -and [string]$sharePointSummary['DefaultLinkPermission'] -eq 'Not collected') {
            $sharePointSummary['DefaultLinkPermission'] = ($defaultLinkPermissions -join ', ')
        }
        if ($sharingCapabilities.Count -gt 0 -or $defaultSharingLinkTypes.Count -gt 0 -or $defaultLinkPermissions.Count -gt 0) {
            $sharePointSummary['DerivedFromSiteInventory'] = $true
            $sharePointSummary['DerivedSiteCount'] = $sharePointInventoryRows.Count
        }
    }

    $sharePointLinkSettingUnavailableText = if ([string]$AuthMode -in @('Certificate', 'ClientSecret')) {
        'Not available in current app-only source'
    }
    else {
        'Not surfaced in current source'
    }

    foreach ($summaryKey in @('DefaultSharingLinkType', 'DefaultLinkPermission', 'AnonymousLinkExpirationInDays', 'GuestAccessExpirationInDays', 'OneDriveSharingCapability')) {
        if ([string]$sharePointSummary[$summaryKey] -ne 'Not collected') {
            continue
        }

        if ($spoTenantSettingsRetrieved) {
            $sharePointSummary[$summaryKey] = 'Not surfaced in current source'
            continue
        }

        if ($graphSharePointSettingsRetrieved -or [string]$sharePointSummary['TenantSharingCapability'] -ne 'Not collected') {
            $sharePointSummary[$summaryKey] = $sharePointLinkSettingUnavailableText
        }
    }

    foreach ($summaryKey in @(
        'SharingDomainRestrictionMode',
        'SharingAllowedDomainList',
        'SharingBlockedDomainList',
        'RequireInvitedUserMatch',
        'ExternalResharingEnabled',
        'OneDriveStorageQuotaMB',
        'SiteCreationDefaultStorageQuotaMB',
        'IsSitesStorageLimitAutomatic',
        'DeletedUserPersonalSiteRetentionPeriodInDays',
        'IsLegacyAuthProtocolsEnabled',
        'DisableCustomAppAuthentication',
        'ExternalServicesEnabled',
        'ShowEveryoneClaim',
        'ShowAllUsersClaim',
        'ShowEveryoneExceptExternalUsersClaim',
        'AllowEveryoneExceptExternalUsersClaimInPrivateSite',
        'AnyoneLinkTrackUsers',
        'OwnerAnonymousNotification',
        'NotifyOwnersWhenItemsReshared',
        'NotifyOwnersWhenInvitationsAccepted',
        'EnableAzureADB2BIntegration',
        'SharePointAddInsDisabled',
        'SharePointAddInsBlocked',
        'EnableSensitivityLabelForPDF',
        'EnableSensitivityLabelForOneNote',
        'EnableSensitivityLabelForVideoFiles',
        'AllowFileArchive',
        'AllowFileArchiveOnNewSitesByDefault',
        'RecycleBinRetentionPeriod',
        'AllowDownloadingNonWebViewableFiles',
        'AllowEditing',
        'MarkNewFilesSensitiveByDefault',
        'RestrictedOneDriveLicense',
        'RestrictedSharePointLicense',
        'IsUnmanagedSyncAppForTenantRestricted',
        'IsSyncButtonHiddenOnPersonalSite',
        'IsSiteCreationEnabled',
        'IsSiteCreationUIEnabled',
        'IsLoopEnabled',
        'AvailableManagedPathsForSiteCreation',
        'SiteCreationDefaultManagedPath',
        'AllowedDomainGuidsForSyncApp',
        'ExcludedFileExtensionsForSyncApp'
    )) {
        if ([string]$sharePointSummary[$summaryKey] -ne 'Not collected') {
            continue
        }

        if ($spoTenantSettingsRetrieved -or $graphSharePointSettingsRetrieved) {
            $sharePointSummary[$summaryKey] = 'Not surfaced in current source'
        }
    }

    $anonymousLinkExpirationDays = $null
    $anonymousLinkExpirationText = [string]$sharePointSummary['AnonymousLinkExpirationInDays']
    $parsedAnonymousLinkExpirationDays = 0
    if (
        -not [string]::IsNullOrWhiteSpace($anonymousLinkExpirationText) -and
        [int]::TryParse($anonymousLinkExpirationText, [ref]$parsedAnonymousLinkExpirationDays)
    ) {
        $anonymousLinkExpirationDays = $parsedAnonymousLinkExpirationDays
    }
    if ($null -ne $anonymousLinkExpirationDays) {
        $sharePointSummary['RequireAnonymousLinksExpire'] = [bool]($anonymousLinkExpirationDays -gt 0)
    }
    elseif ($anonymousLinkExpirationText -in @('Not collected', 'Not surfaced in current source', 'Not available in current app-only source')) {
        $sharePointSummary['RequireAnonymousLinksExpire'] = $anonymousLinkExpirationText
    }

    $externalResharingEnabledValue = $sharePointSummary['ExternalResharingEnabled']
    if ($externalResharingEnabledValue -is [bool]) {
        $sharePointSummary['PreventExternalUsersFromResharing'] = (-not $externalResharingEnabledValue)
    }
    else {
        $externalResharingEnabledText = [string]$externalResharingEnabledValue
        switch -Regex ($externalResharingEnabledText) {
            '^(true|yes|enabled|on|1)$' { $sharePointSummary['PreventExternalUsersFromResharing'] = $false; break }
            '^(false|no|disabled|off|0)$' { $sharePointSummary['PreventExternalUsersFromResharing'] = $true; break }
            default {
                if ([string]::IsNullOrWhiteSpace($externalResharingEnabledText) -or $externalResharingEnabledText -eq 'Not collected') {
                    $sharePointSummary['PreventExternalUsersFromResharing'] = 'Not collected'
                }
                else {
                    $sharePointSummary['PreventExternalUsersFromResharing'] = 'Not surfaced in current source'
                }
            }
        }
    }

    $sharePointSettingsEvaluatedKeys = @(
        $sharePointSummary.Keys | Where-Object { $_ -notin @('CollectionState', 'CollectionSource', 'SettingsApiVersion') }
    )
    $presentSharePointSettingsCount = @(
        $sharePointSettingsEvaluatedKeys |
            Where-Object {
                [string]$sharePointSummary[$_] -notin @('Not collected', 'Not surfaced in current source', 'Not available in current app-only source')
            }
    ).Count
    if ($presentSharePointSettingsCount -eq 0) {
        $sharePointSummary['CollectionState'] = 'Not collected'
    }
    elseif ($presentSharePointSettingsCount -lt $sharePointSettingsEvaluatedKeys.Count) {
        $sharePointSummary['CollectionState'] = 'Partial'
    }
    else {
        $sharePointSummary['CollectionState'] = 'Collected'
    }

    if ($sharePointSettingsSources.Count -gt 0) {
        $sharePointSummary['CollectionSource'] = ($sharePointSettingsSources -join '; ')
    }
    elseif ($sharePointInventoryRows.Count -gt 0) {
        $sharePointSummary['CollectionSource'] = 'Derived site inventory fallback'
    }

    if ($sharePointSettingsApiVersions.Count -gt 0) {
        $sharePointSummary['SettingsApiVersion'] = ($sharePointSettingsApiVersions -join '; ')
    }

    $TenantStatsHash['SharePointSharingSummary']['Summary'] = [pscustomobject]$sharePointSummary
    Write-AssessmentConsoleSubstep -Message ("Governance summaries: completed (SharePoint collection state {0}; {1} SharePoint site(s); {2} OneDrive site(s))" -f $sharePointSummary['CollectionState'], $sharePointRows.Count, $oneDriveRows.Count)
    Write-ProgressHelper -Total ([Math]::Max($tierBProgressTotal, 1)) -Id $tierBProgressId -Activity 'Governance summaries' -Completed
}

function Update-ExternalExposureSummaries {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$TenantStatsHash
    )

    $externalExposureProgressId = 92
    $externalExposureProgressTotal = 3
    Write-ProgressHelper -Total $externalExposureProgressTotal -Id $externalExposureProgressId -Index 1 -Activity 'External exposure summaries' -Operation 'Reviewing sharing baseline and site overrides'
    Write-AssessmentConsoleSubstep -Message 'External exposure summaries: reviewing sharing baseline and site override signals'
    function Get-ExternalExposureValue {
        param(
            [AllowNull()][object]$Object,
            [Parameter(Mandatory = $true)][string[]]$Names
        )

        if ($null -eq $Object) { return $null }
        foreach ($name in $Names) {
            if ($Object -is [System.Collections.IDictionary] -and $Object.Contains($name)) {
                return $Object[$name]
            }
            if ($Object.PSObject -and $Object.PSObject.Properties[$name]) {
                return $Object.$name
            }
        }

        return $null
    }

    function Convert-ToExternalExposureArray {
        param([AllowNull()][object]$Value)

        if ($null -eq $Value) { return @() }
        if ($Value -is [System.Collections.IDictionary]) { return @($Value.Values) }
        if ($Value -is [System.Collections.IEnumerable] -and -not ($Value -is [string])) { return @($Value) }
        return @($Value)
    }

    function Convert-ToExternalExposureText {
        param(
            [AllowNull()][object]$Value,
            [string]$Default = 'Not surfaced in current source'
        )

        if ($null -eq $Value) { return $Default }
        if ($Value -is [System.Collections.IEnumerable] -and -not ($Value -is [string])) {
            $items = @($Value | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
            if ($items.Count -eq 0) { return $Default }
            return ($items -join ', ')
        }

        $text = [string]$Value
        if ([string]::IsNullOrWhiteSpace($text)) { return $Default }
        return $text
    }

    function Test-ExternalExposureValuePresent {
        param([AllowNull()][object]$Value)

        if ($null -eq $Value) { return $false }
        if ($Value -is [string]) {
            return -not [string]::IsNullOrWhiteSpace($Value) -and $Value -notin @('Not collected', 'Not surfaced in current source', 'Not available in current auth mode')
        }
        if ($Value -is [System.Collections.IEnumerable] -and -not ($Value -is [string])) {
            return @($Value).Count -gt 0
        }

        return $true
    }

    function Get-ExternalExposureSharingCapabilityRank {
        param([string]$Value)

        if ([string]::IsNullOrWhiteSpace($Value)) { return $null }
        $text = $Value.Trim()
        if ($text -match 'Not collected|Not surfaced|Not available') { return $null }
        if ($text -match 'Disabled|Internal|OnlyPeopleInYourOrganization') { return 1 }
        if ($text -match 'ExistingExternalUserSharingOnly|ExternalUserSharingOnly') { return 2 }
        if ($text -match 'ExternalUserAndGuestSharing|Anyone|Anonymous') { return 3 }
        return $null
    }

    function Get-ExternalExposureLinkTypeRank {
        param([string]$Value)

        if ([string]::IsNullOrWhiteSpace($Value)) { return $null }
        $text = $Value.Trim()
        if ($text -match 'Not collected|Not surfaced|Not available') { return $null }
        if ($text -match 'ExistingAccess') { return 1 }
        if ($text -match 'SpecificPeople') { return 2 }
        if ($text -match 'Organization|PeopleInYourOrganization|Internal') { return 3 }
        if ($text -match 'Anonymous|Anyone') { return 4 }
        return $null
    }

    function Get-ExternalExposureLinkPermissionRank {
        param([string]$Value)

        if ([string]::IsNullOrWhiteSpace($Value)) { return $null }
        $text = $Value.Trim()
        if ($text -match 'Not collected|Not surfaced|Not available') { return $null }
        if ($text -match 'View|Read') { return 1 }
        if ($text -match 'Edit') { return 2 }
        return $null
    }

    function New-ExternalExposureFindingRow {
        param(
            [Parameter(Mandatory = $true)][string]$Workload,
            [Parameter(Mandatory = $true)][string]$AssetType,
            [Parameter(Mandatory = $true)][string]$Title,
            [Parameter(Mandatory = $true)][string]$UrlOrIdentifier,
            [Parameter(Mandatory = $true)][string]$ExposureCategory,
            [Parameter(Mandatory = $true)][string]$TenantBaseline,
            [Parameter(Mandatory = $true)][string]$ObservedSetting,
            [Parameter(Mandatory = $true)][string]$OwnerSignal,
            [Parameter(Mandatory = $true)][string]$GuestSignal,
            [Parameter(Mandatory = $true)][string]$ActivitySignal,
            [Parameter(Mandatory = $true)][string]$StaleSignal,
            [Parameter(Mandatory = $true)][string]$GapReason,
            [Parameter(Mandatory = $true)][string]$ReviewPriority
        )

        [pscustomobject]@{
            Workload         = $Workload
            AssetType        = $AssetType
            Title            = $Title
            UrlOrIdentifier  = $UrlOrIdentifier
            ExposureCategory = $ExposureCategory
            TenantBaseline   = $TenantBaseline
            ObservedSetting  = $ObservedSetting
            OwnerSignal      = $OwnerSignal
            GuestSignal      = $GuestSignal
            ActivitySignal   = $ActivitySignal
            StaleSignal      = $StaleSignal
            GapReason        = $GapReason
            ReviewPriority   = $ReviewPriority
        }
    }

    if (-not $TenantStatsHash.ContainsKey('ExternalSharingSummary')) { $TenantStatsHash['ExternalSharingSummary'] = @{} }
    if (-not $TenantStatsHash.ContainsKey('ExternalSharingSiteOverrides')) { $TenantStatsHash['ExternalSharingSiteOverrides'] = @() }
    if (-not $TenantStatsHash.ContainsKey('ExternalIdentityRestrictions')) { $TenantStatsHash['ExternalIdentityRestrictions'] = @{} }
    if (-not $TenantStatsHash.ContainsKey('GuestAccessConfiguration')) { $TenantStatsHash['GuestAccessConfiguration'] = @{} }
    if (-not $TenantStatsHash.ContainsKey('ExternalExposureFindings')) { $TenantStatsHash['ExternalExposureFindings'] = @() }

    $sharePointSummaryRecord = if ($TenantStatsHash.ContainsKey('SharePointSharingSummary')) {
        Get-ExternalExposureValue -Object $TenantStatsHash['SharePointSharingSummary'] -Names @('Summary')
    } else { $null }
    $sharePointRows = Convert-ToExternalExposureArray -Value $(if ($TenantStatsHash.ContainsKey('SharePoint')) { $TenantStatsHash['SharePoint'] } else { $null })
    $oneDriveRows = Convert-ToExternalExposureArray -Value $(if ($TenantStatsHash.ContainsKey('OneDrive')) { $TenantStatsHash['OneDrive'] } else { $null })
    $unifiedGroupRows = Convert-ToExternalExposureArray -Value $(if ($TenantStatsHash.ContainsKey('UnifiedGroups')) { $TenantStatsHash['UnifiedGroups'] } else { $null })
    $teamRows = Convert-ToExternalExposureArray -Value $(if ($TenantStatsHash.ContainsKey('AllTeams')) { $TenantStatsHash['AllTeams'] } else { $null })
    $guestSummaryRecord = if ($TenantStatsHash.ContainsKey('GuestSignInSummary')) {
        Get-ExternalExposureValue -Object $TenantStatsHash['GuestSignInSummary'] -Names @('Summary')
    } else { $null }
    $conditionalAccessSummaryRecord = if ($TenantStatsHash.ContainsKey('ConditionalAccessPolicySummary')) {
        Get-ExternalExposureValue -Object $TenantStatsHash['ConditionalAccessPolicySummary'] -Names @('Summary')
    } else { $null }
    $authConfig = if ($TenantStatsHash.ContainsKey('AuthenticationConfig')) { $TenantStatsHash['AuthenticationConfig'] } else { $null }
    $federationConfiguration = if ($TenantStatsHash.ContainsKey('FederationConfiguration')) { $TenantStatsHash['FederationConfiguration'] } else { $null }
    $crossTenantSummary = Get-ExternalExposureValue -Object $federationConfiguration -Names @('CrossTenantAccess')
    $externalIdentities = Get-ExternalExposureValue -Object $federationConfiguration -Names @('ExternalIdentities')

    $tenantSharingCapability = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $sharePointSummaryRecord -Names @('TenantSharingCapability')) -Default 'Not collected'
    $defaultSharingLinkType = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $sharePointSummaryRecord -Names @('DefaultSharingLinkType')) -Default 'Not collected'
    $defaultLinkPermission = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $sharePointSummaryRecord -Names @('DefaultLinkPermission')) -Default 'Not collected'
    $sharingDomainRestrictionMode = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $sharePointSummaryRecord -Names @('SharingDomainRestrictionMode')) -Default 'Not collected'
    $sharingAllowedDomainList = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $sharePointSummaryRecord -Names @('SharingAllowedDomainList')) -Default 'Not surfaced in current source'
    $sharingBlockedDomainList = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $sharePointSummaryRecord -Names @('SharingBlockedDomainList')) -Default 'Not surfaced in current source'
    $anonymousLinkExpirationInDays = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $sharePointSummaryRecord -Names @('AnonymousLinkExpirationInDays')) -Default 'Not collected'
    $requireInvitedUserMatch = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $sharePointSummaryRecord -Names @('RequireInvitedUserMatch')) -Default 'Not surfaced in current source'
    $externalResharingEnabled = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $sharePointSummaryRecord -Names @('ExternalResharingEnabled')) -Default 'Not surfaced in current source'

    $siteRows = @($sharePointRows) + @($oneDriveRows)
    $siteOverrides = @(
        foreach ($site in $siteRows) {
            $siteSharingCapability = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $site -Names @('SharingCapability')) -Default ''
            $siteDefaultSharingLinkType = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $site -Names @('DefaultSharingLinkType')) -Default ''
            $siteDefaultLinkPermission = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $site -Names @('DefaultLinkPermission')) -Default ''

            $overrideReasons = New-Object System.Collections.Generic.List[string]
            if (-not [string]::IsNullOrWhiteSpace($siteSharingCapability) -and $tenantSharingCapability -ne 'Not collected' -and $siteSharingCapability -ne $tenantSharingCapability) {
                $overrideReasons.Add('Sharing capability differs from tenant setting') | Out-Null
            }
            if (-not [string]::IsNullOrWhiteSpace($siteDefaultSharingLinkType) -and $defaultSharingLinkType -ne 'Not collected' -and $siteDefaultSharingLinkType -ne $defaultSharingLinkType) {
                $overrideReasons.Add('Default sharing link type differs from tenant setting') | Out-Null
            }
            if (-not [string]::IsNullOrWhiteSpace($siteDefaultLinkPermission) -and $defaultLinkPermission -ne 'Not collected' -and $siteDefaultLinkPermission -ne $defaultLinkPermission) {
                $overrideReasons.Add('Default link permission differs from tenant setting') | Out-Null
            }
            if ($overrideReasons.Count -eq 0 -and -not [string]::IsNullOrWhiteSpace($siteSharingCapability) -and $siteSharingCapability -notmatch 'Disabled|Internal|OnlyPeopleInYourOrganization') {
                $overrideReasons.Add('Site supports external sharing') | Out-Null
            }

            if ($overrideReasons.Count -eq 0) {
                continue
            }

            [pscustomobject]@{
                Workload               = $(if ([string](Get-ExternalExposureValue -Object $site -Names @('Url')) -match '-my\.sharepoint\.com') { 'OneDrive' } else { 'SharePoint' })
                Title                  = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $site -Names @('Title', 'DisplayName')) -Default 'Untitled site'
                Url                    = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $site -Names @('Url')) -Default 'Not surfaced in current source'
                SharingCapability      = $(if ([string]::IsNullOrWhiteSpace($siteSharingCapability)) { 'Not surfaced in current source' } else { $siteSharingCapability })
                DefaultSharingLinkType = $(if ([string]::IsNullOrWhiteSpace($siteDefaultSharingLinkType)) { 'Not surfaced in current source' } else { $siteDefaultSharingLinkType })
                DefaultLinkPermission  = $(if ([string]::IsNullOrWhiteSpace($siteDefaultLinkPermission)) { 'Not surfaced in current source' } else { $siteDefaultLinkPermission })
                OverrideReason         = ($overrideReasons -join '; ')
            }
        }
    ) | Sort-Object Url, Title

    $sitesWithExternalSharingEnabled = @(
        $siteRows | Where-Object {
            $sharingCapability = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $_ -Names @('SharingCapability')) -Default ''
            -not [string]::IsNullOrWhiteSpace($sharingCapability) -and $sharingCapability -notmatch 'Disabled|Internal|OnlyPeopleInYourOrganization'
        }
    ).Count
    $sitesWithAnonymousDefaultLinks = @(
        $siteRows | Where-Object {
            (Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $_ -Names @('DefaultSharingLinkType')) -Default '') -match 'Anonymous|Anyone'
        }
    ).Count
    $sitesWithSpecificPeopleDefaults = @(
        $siteRows | Where-Object {
            (Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $_ -Names @('DefaultSharingLinkType')) -Default '') -match 'SpecificPeople'
        }
    ).Count

    $sharingSignalsPresent = @(
        Test-ExternalExposureValuePresent -Value $tenantSharingCapability
        Test-ExternalExposureValuePresent -Value $defaultSharingLinkType
        Test-ExternalExposureValuePresent -Value $defaultLinkPermission
        Test-ExternalExposureValuePresent -Value $sharingDomainRestrictionMode
    ) | Where-Object { $_ -eq $true }
    $sharingCollectionState = if ($sharingSignalsPresent.Count -eq 0 -and $siteRows.Count -eq 0) {
        'Not collected'
    }
    elseif (
        $tenantSharingCapability -in @('Not collected', 'Not surfaced in current source', 'Not available in current auth mode', 'Not available in current app-only source') -or
        $defaultSharingLinkType -in @('Not collected', 'Not surfaced in current source', 'Not available in current auth mode', 'Not available in current app-only source') -or
        $defaultLinkPermission -in @('Not collected', 'Not surfaced in current source', 'Not available in current auth mode', 'Not available in current app-only source')
    ) {
        'Partial'
    }
    else {
        'Collected'
    }

    $TenantStatsHash['ExternalSharingSummary']['Summary'] = [pscustomobject]@{
        CollectionState                = $sharingCollectionState
        TenantSharingCapability        = $tenantSharingCapability
        DefaultSharingLinkType         = $defaultSharingLinkType
        DefaultLinkPermission          = $defaultLinkPermission
        SharingDomainRestrictionMode   = $sharingDomainRestrictionMode
        SharingAllowedDomainList       = $sharingAllowedDomainList
        SharingBlockedDomainList       = $sharingBlockedDomainList
        AnonymousLinkExpirationInDays  = $anonymousLinkExpirationInDays
        GuestExpirationInDays          = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $sharePointSummaryRecord -Names @('GuestAccessExpirationInDays')) -Default 'Not surfaced in current source'
        RequireInvitedUserMatch        = $requireInvitedUserMatch
        ExternalResharingEnabled       = $externalResharingEnabled
        PreventExternalUsersFromResharing = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $sharePointSummaryRecord -Names @('PreventExternalUsersFromResharing')) -Default 'Not surfaced in current source'
        SharePointSitesReviewed        = $sharePointRows.Count
        OneDriveSitesReviewed          = $oneDriveRows.Count
        SitesWithExternalSharingEnabled = $sitesWithExternalSharingEnabled
        SitesWithAnonymousDefaultLinks = $sitesWithAnonymousDefaultLinks
        SitesWithSpecificPeopleLinks   = $sitesWithSpecificPeopleDefaults
        SiteOverrideCount              = @($siteOverrides).Count
    }
    $TenantStatsHash['ExternalSharingSiteOverrides'] = @($siteOverrides)

    Write-ProgressHelper -Total $externalExposureProgressTotal -Id $externalExposureProgressId -Index 2 -Activity 'External exposure summaries' -Operation 'Reviewing guest and cross-tenant identity restrictions'
    Write-AssessmentConsoleSubstep -Message 'External exposure summaries: reviewing guest access and cross-tenant restriction signals'
    $authConfigDetails = Get-ExternalExposureValue -Object $authConfig -Names @('Configuration')
    if ($null -eq $authConfigDetails) {
        $authConfigDetails = $authConfig
    }

    $allowInvitesFrom = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $authConfigDetails -Names @('AllowInvitesFrom')) -Default 'Not surfaced in current source'
    $allowEmailVerifiedUsersToJoin = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $authConfigDetails -Names @('AllowEmailVerifiedUsersToJoinOrganization')) -Default 'Not surfaced in current source'
    $defaultUserCanReadOtherUsers = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $authConfigDetails -Names @('DefaultUserCanReadOtherUsers')) -Default 'Not surfaced in current source'
    $guestUserRoleId = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $authConfigDetails -Names @('GuestUserRoleId')) -Default $(Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $externalIdentities -Names @('GuestUserRole')) -Default 'Not surfaced in current source')
    $guestUserRoleLabelRaw = Get-ExternalExposureValue -Object $authConfigDetails -Names @('GuestUserRoleLabel')
    if ($null -eq $guestUserRoleLabelRaw) {
        $guestUserRoleLabelRaw = Get-AssessmentGuestUserRoleLabel -GuestUserRoleId ([string](Get-ExternalExposureValue -Object $authConfigDetails -Names @('GuestUserRoleId')))
    }
    if ($null -eq $guestUserRoleLabelRaw) {
        $guestUserRoleLabelRaw = Get-AssessmentGuestUserRoleLabel -GuestUserRoleId ([string](Get-ExternalExposureValue -Object $externalIdentities -Names @('GuestUserRole')))
    }
    $guestUserRoleLabel = Convert-ToExternalExposureText -Value $guestUserRoleLabelRaw -Default 'Not surfaced in current source'
    $b2bInvitationSetting = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $externalIdentities -Names @('InvitationsAllowed')) -Default 'Not surfaced in current source'
    $crossTenantPartnerCount = Get-ExternalExposureValue -Object $crossTenantSummary -Names @('PartnerCount')
    $partnerTenantNames = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $crossTenantSummary -Names @('PartnerTenantNames')) -Default 'Not surfaced in current source'
    $defaultInboundMfaTrust = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $crossTenantSummary -Names @('DefaultInboundAccess')) -Default 'Not surfaced in current source'
    $defaultOutboundMfaTrust = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $crossTenantSummary -Names @('DefaultOutboundAccess')) -Default 'Not surfaced in current source'
    $defaultB2BInbound = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $crossTenantSummary -Names @('DefaultB2BDirectConnectInbound')) -Default 'Not surfaced in current source'
    $defaultB2BOutbound = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $crossTenantSummary -Names @('DefaultB2BDirectConnectOutbound')) -Default 'Not surfaced in current source'
    $hasCrossTenantAccessPolicy = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $crossTenantSummary -Names @('HasCrossTenantAccessPolicy')) -Default 'Not surfaced in current source'

    $externalIdentitySignalsPresent = @(
        Test-ExternalExposureValuePresent -Value $allowInvitesFrom
        Test-ExternalExposureValuePresent -Value $crossTenantPartnerCount
        Test-ExternalExposureValuePresent -Value $hasCrossTenantAccessPolicy
        Test-ExternalExposureValuePresent -Value $guestUserRoleId
    ) | Where-Object { $_ -eq $true }
    $externalIdentityCollectionState = if ($externalIdentitySignalsPresent.Count -eq 0) { 'Not collected' } elseif ($allowInvitesFrom -eq 'Not surfaced in current source') { 'Partial' } else { 'Collected' }

    $TenantStatsHash['ExternalIdentityRestrictions']['Summary'] = [pscustomobject]@{
        CollectionState                        = $externalIdentityCollectionState
        AllowInvitesFrom                       = $allowInvitesFrom
        AllowEmailVerifiedUsersToJoinOrganization = $allowEmailVerifiedUsersToJoin
        DefaultUserCanReadOtherUsers           = $defaultUserCanReadOtherUsers
        GuestUserRoleId                        = $guestUserRoleId
        GuestUserRoleLabel                     = $guestUserRoleLabel
        B2BInvitationPolicyAllowedToInvite     = $b2bInvitationSetting
        HasCrossTenantAccessPolicy             = $hasCrossTenantAccessPolicy
        CrossTenantPartnerCount                = $(if ($null -eq $crossTenantPartnerCount) { 'Not surfaced in current source' } else { $crossTenantPartnerCount })
        DefaultInboundMfaTrust                 = $defaultInboundMfaTrust
        DefaultOutboundMfaTrust                = $defaultOutboundMfaTrust
        DefaultB2BDirectConnectInbound         = $defaultB2BInbound
        DefaultB2BDirectConnectOutbound        = $defaultB2BOutbound
        PartnerTenantNames                     = $partnerTenantNames
    }

    $inactiveGuests90Days = Get-ExternalExposureValue -Object $guestSummaryRecord -Names @('InactiveGuests90Days')
    $guestCoverage = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $conditionalAccessSummaryRecord -Names @('HasGuestCoverage')) -Default 'Not surfaced in current source'
    $mfaEnforcementSummaryRecord = if ($TenantStatsHash.ContainsKey('MfaEnforcementSummary')) {
        $TenantStatsHash['MfaEnforcementSummary']
    }
    else {
        $null
    }
    $guestMfaEnforcementState = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $mfaEnforcementSummaryRecord -Names @('GuestUserEnforcementState')) -Default 'Not surfaced in current source'
    $guestMfaEnforcementSources = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $mfaEnforcementSummaryRecord -Names @('GuestMfaEnforcementSources')) -Default 'Not surfaced in current source'
    $guestMfaConditionalAccessPolicies = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $mfaEnforcementSummaryRecord -Names @('GuestCoveredPolicyNames')) -Default 'Not surfaced in current source'
    $guestMfaExplicitScopePolicies = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $mfaEnforcementSummaryRecord -Names @('GuestExplicitScopePolicyNames')) -Default 'Not surfaced in current source'
    $groupsAllowingGuests = @(
        $unifiedGroupRows | Where-Object {
            $allowGuests = Get-ExternalExposureValue -Object $_ -Names @('AllowAddGuests')
            $null -ne $allowGuests -and [bool]$allowGuests -eq $true
        }
    ).Count
    $groupsBlockingGuests = @(
        $unifiedGroupRows | Where-Object {
            $allowGuests = Get-ExternalExposureValue -Object $_ -Names @('AllowAddGuests')
            $null -ne $allowGuests -and [bool]$allowGuests -eq $false
        }
    ).Count
    $guestHeavyTeams = @(
        $teamRows | Where-Object {
            $guestCount = Get-ExternalExposureValue -Object $_ -Names @('GuestCount')
            $memberCount = Get-ExternalExposureValue -Object $_ -Names @('MemberCount')
            $null -ne $guestCount -and $null -ne $memberCount -and [int]$memberCount -gt 0 -and (([double]$guestCount / [double]$memberCount) -ge 0.4)
        }
    ).Count

    $guestSignalsPresent = @(
        Test-ExternalExposureValuePresent -Value $inactiveGuests90Days
        Test-ExternalExposureValuePresent -Value $tenantSharingCapability
        Test-ExternalExposureValuePresent -Value $allowInvitesFrom
        Test-ExternalExposureValuePresent -Value $guestCoverage
    ) | Where-Object { $_ -eq $true }
    $guestAccessCollectionState = if ($guestSignalsPresent.Count -eq 0) { 'Not collected' } elseif ($allowInvitesFrom -eq 'Not surfaced in current source') { 'Partial' } else { 'Collected' }

    $TenantStatsHash['GuestAccessConfiguration']['Summary'] = [pscustomobject]@{
        CollectionState                 = $guestAccessCollectionState
        InactiveGuests90Days            = $(if ($null -eq $inactiveGuests90Days) { 'Not surfaced in current source' } else { $inactiveGuests90Days })
        ConditionalAccessGuestCoverage  = $guestCoverage
        GuestMfaEnforcementState        = $guestMfaEnforcementState
        GuestMfaEnforcementSources      = $guestMfaEnforcementSources
        GuestMfaConditionalAccessPolicies = $guestMfaConditionalAccessPolicies
        GuestMfaExplicitScopePolicies   = $guestMfaExplicitScopePolicies
        GuestInvitationControl          = $allowInvitesFrom
        GuestUserRoleId                 = $guestUserRoleId
        GuestUserRoleLabel              = $guestUserRoleLabel
        TenantSharingCapability         = $tenantSharingCapability
        DefaultSharingLinkType          = $defaultSharingLinkType
        DefaultLinkPermission           = $defaultLinkPermission
        UnifiedGroupsReviewed           = $unifiedGroupRows.Count
        GroupsAllowingGuests            = $groupsAllowingGuests
        GroupsBlockingGuests            = $groupsBlockingGuests
        TeamsReviewed                   = $teamRows.Count
        GuestHeavyTeams                 = $guestHeavyTeams
        CrossTenantPartnerCount         = $(if ($null -eq $crossTenantPartnerCount) { 'Not surfaced in current source' } else { $crossTenantPartnerCount })
        SiteOverrideCount               = @($siteOverrides).Count
    }

    $externalExposureRows = New-Object System.Collections.Generic.List[object]
    $tenantSharingRank = Get-ExternalExposureSharingCapabilityRank -Value $tenantSharingCapability
    $tenantLinkTypeRank = Get-ExternalExposureLinkTypeRank -Value $defaultSharingLinkType
    $tenantLinkPermissionRank = Get-ExternalExposureLinkPermissionRank -Value $defaultLinkPermission
    $staleSiteCutoff = (Get-Date).AddDays(-180)
    $staleTeamCutoff = (Get-Date).AddDays(-90)

    $oneDriveMismatchLookup = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($mismatch in (Convert-ToExternalExposureArray -Value $(if ($TenantStatsHash.ContainsKey('OneDriveOwnerMismatches')) { $TenantStatsHash['OneDriveOwnerMismatches'] } else { $null }))) {
        foreach ($candidate in @(
            (Get-ExternalExposureValue -Object $mismatch -Names @('SiteUrl', 'Url')),
            (Get-ExternalExposureValue -Object $mismatch -Names @('OwnerPrincipalName', 'UserPrincipalName'))
        )) {
            $candidateText = Convert-ToExternalExposureText -Value $candidate -Default ''
            if (-not [string]::IsNullOrWhiteSpace($candidateText)) {
                $null = $oneDriveMismatchLookup.Add($candidateText)
            }
        }
    }

    foreach ($site in $siteRows) {
        $siteUrl = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $site -Names @('Url')) -Default 'Not surfaced in current source'
        $siteTitle = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $site -Names @('Title', 'DisplayName')) -Default 'Untitled site'
        $siteSharingCapability = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $site -Names @('SharingCapability')) -Default ''
        $siteDefaultSharingLinkType = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $site -Names @('DefaultSharingLinkType')) -Default ''
        $siteDefaultLinkPermission = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $site -Names @('DefaultLinkPermission')) -Default ''
        $siteOwner = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $site -Names @('Owner')) -Default 'Not surfaced in current source'
        $lastModified = Get-ExternalExposureValue -Object $site -Names @('LastContentModifiedDate')
        $lastModifiedDate = $null
        try { if ($lastModified) { $lastModifiedDate = [datetime]$lastModified } } catch {}
        $staleSite = ($lastModifiedDate -and $lastModifiedDate -lt $staleSiteCutoff)
        $siteSharingRank = Get-ExternalExposureSharingCapabilityRank -Value $siteSharingCapability
        $siteLinkTypeRank = Get-ExternalExposureLinkTypeRank -Value $siteDefaultSharingLinkType
        $siteLinkPermissionRank = Get-ExternalExposureLinkPermissionRank -Value $siteDefaultLinkPermission
        $externallySharable = ($null -ne $siteSharingRank -and $siteSharingRank -gt 1)
        $sharingMorePermissive = ($externallySharable -and $null -ne $tenantSharingRank -and $siteSharingRank -gt $tenantSharingRank)
        $linkTypeDiffers = (-not [string]::IsNullOrWhiteSpace($siteDefaultSharingLinkType) -and $defaultSharingLinkType -notin @('Not collected', 'Not surfaced in current source', 'Not available in current auth mode') -and $siteDefaultSharingLinkType -ne $defaultSharingLinkType)
        $linkPermissionDiffers = (-not [string]::IsNullOrWhiteSpace($siteDefaultLinkPermission) -and $defaultLinkPermission -notin @('Not collected', 'Not surfaced in current source', 'Not available in current auth mode') -and $siteDefaultLinkPermission -ne $defaultLinkPermission)
        $oneDriveOwnershipMismatch = (($siteUrl -match '-my\.sharepoint\.com' -or $siteTitle -match 'OneDrive') -and ($oneDriveMismatchLookup.Contains($siteUrl) -or $oneDriveMismatchLookup.Contains($siteOwner)))

        $gapReasons = New-Object System.Collections.Generic.List[string]
        $exposureCategory = $null
        $reviewPriority = 'Medium'

        if ($externallySharable -and $staleSite) {
            $gapReasons.Add('Site supports external sharing and last content activity is older than the 180-day stale threshold.') | Out-Null
            $exposureCategory = 'Stale externally shared content'
            $reviewPriority = 'High'
        }
        if ($externallySharable -and $oneDriveOwnershipMismatch) {
            $gapReasons.Add('Externally sharable OneDrive also appears in the ownership-mismatch review.') | Out-Null
            if (-not $exposureCategory) { $exposureCategory = 'Externally sharable OneDrive with ownership mismatch' }
            $reviewPriority = 'High'
        }
        if ($sharingMorePermissive) {
            $gapReasons.Add('Site sharing capability is more permissive than the tenant baseline.') | Out-Null
            if (-not $exposureCategory) { $exposureCategory = 'More permissive site sharing than tenant baseline' }
        }
        if ($linkTypeDiffers) {
            $gapReasons.Add('Site default sharing link type differs from the tenant baseline.') | Out-Null
            if (-not $exposureCategory) { $exposureCategory = 'Site default sharing link type differs from tenant baseline' }
        }
        if ($linkPermissionDiffers) {
            $gapReasons.Add('Site default link permission differs from the tenant baseline.') | Out-Null
            if (-not $exposureCategory) { $exposureCategory = 'Site default link permission differs from tenant baseline' }
        }

        if ($gapReasons.Count -eq 0) {
            continue
        }

        $observedSettingParts = New-Object System.Collections.Generic.List[string]
        if (-not [string]::IsNullOrWhiteSpace($siteSharingCapability)) { $observedSettingParts.Add("SharingCapability=$siteSharingCapability") | Out-Null }
        if (-not [string]::IsNullOrWhiteSpace($siteDefaultSharingLinkType)) { $observedSettingParts.Add("DefaultSharingLinkType=$siteDefaultSharingLinkType") | Out-Null }
        if (-not [string]::IsNullOrWhiteSpace($siteDefaultLinkPermission)) { $observedSettingParts.Add("DefaultLinkPermission=$siteDefaultLinkPermission") | Out-Null }

        $tenantBaselineParts = New-Object System.Collections.Generic.List[string]
        if ($tenantSharingCapability -notin @('Not collected', 'Not surfaced in current source', 'Not available in current auth mode')) { $tenantBaselineParts.Add("SharingCapability=$tenantSharingCapability") | Out-Null }
        if ($defaultSharingLinkType -notin @('Not collected', 'Not surfaced in current source', 'Not available in current auth mode')) { $tenantBaselineParts.Add("DefaultSharingLinkType=$defaultSharingLinkType") | Out-Null }
        if ($defaultLinkPermission -notin @('Not collected', 'Not surfaced in current source', 'Not available in current auth mode')) { $tenantBaselineParts.Add("DefaultLinkPermission=$defaultLinkPermission") | Out-Null }

        $externalExposureRows.Add((New-ExternalExposureFindingRow `
            -Workload $(if ($siteUrl -match '-my\.sharepoint\.com') { 'OneDrive' } else { 'SharePoint' }) `
            -AssetType $(if ($siteUrl -match '-my\.sharepoint\.com') { 'Personal Site' } else { 'Site' }) `
            -Title $siteTitle `
            -UrlOrIdentifier $siteUrl `
            -ExposureCategory $exposureCategory `
            -TenantBaseline $(if ($tenantBaselineParts.Count -gt 0) { $tenantBaselineParts -join '; ' } else { 'Not surfaced in current source' }) `
            -ObservedSetting $(if ($observedSettingParts.Count -gt 0) { $observedSettingParts -join '; ' } else { 'Not surfaced in current source' }) `
            -OwnerSignal $(if ($oneDriveOwnershipMismatch) { "Owner=$siteOwner; ownership mismatch surfaced" } else { "Owner=$siteOwner" }) `
            -GuestSignal 'Not applicable' `
            -ActivitySignal $(if ($lastModifiedDate) { "LastContentModifiedDate=$($lastModifiedDate.ToString('yyyy-MM-dd'))" } else { 'Last content activity not surfaced' }) `
            -StaleSignal $(if ($staleSite) { 'Yes' } else { 'No' }) `
            -GapReason ($gapReasons.ToArray() -join ' ') `
            -ReviewPriority $reviewPriority
        )) | Out-Null
    }

    foreach ($team in $teamRows) {
        $teamTitle = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $team -Names @('DisplayName', 'Title')) -Default 'Untitled Team'
        $teamIdentifier = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $team -Names @('SharePointSiteUrl', 'TeamId', 'GroupId')) -Default 'Not surfaced in current source'
        $guestCount = Get-ExternalExposureValue -Object $team -Names @('GuestCount', 'Guests')
        $memberCount = Get-ExternalExposureValue -Object $team -Names @('MemberCount', 'Members')
        $ownerCount = Get-ExternalExposureValue -Object $team -Names @('OwnerCount')
        $lastActivityValue = Get-ExternalExposureValue -Object $team -Names @('LastActivityDate')
        $lastActivityDate = $null
        try { if ($lastActivityValue) { $lastActivityDate = [datetime]$lastActivityValue } } catch {}
        $guestCountNumber = $null
        $memberCountNumber = $null
        $ownerCountNumber = $null
        try { if ($null -ne $guestCount) { $guestCountNumber = [double]$guestCount } } catch {}
        try { if ($null -ne $memberCount) { $memberCountNumber = [double]$memberCount } } catch {}
        try { if ($null -ne $ownerCount -and -not [string]::IsNullOrWhiteSpace([string]$ownerCount)) { $ownerCountNumber = [int]$ownerCount } } catch {}
        $guestHeavy = ($null -ne $guestCountNumber -and $null -ne $memberCountNumber -and $memberCountNumber -gt 0 -and (($guestCountNumber / $memberCountNumber) -ge 0.4))
        $guestEnabledDormant = ($null -ne $guestCountNumber -and $guestCountNumber -gt 0 -and $lastActivityDate -and $lastActivityDate -lt $staleTeamCutoff)
        $guestEnabledOwnerless = ($null -ne $guestCountNumber -and $guestCountNumber -gt 0 -and $null -ne $ownerCountNumber -and $ownerCountNumber -eq 0)

        if (-not ($guestHeavy -or $guestEnabledDormant -or $guestEnabledOwnerless)) {
            continue
        }

        $gapReasons = New-Object System.Collections.Generic.List[string]
        $exposureCategory = $null
        $reviewPriority = 'Medium'

        if ($guestHeavy -and $guestEnabledDormant) {
            $gapReasons.Add('Team is guest-heavy and its recorded activity is older than the 90-day dormant threshold.') | Out-Null
            $exposureCategory = 'Guest-heavy dormant Team'
            $reviewPriority = 'High'
        }
        elseif ($guestHeavy) {
            $gapReasons.Add('Team guest membership is at or above the 40% guest-heavy threshold.') | Out-Null
            $exposureCategory = 'Guest-heavy Team'
        }
        elseif ($guestEnabledDormant) {
            $gapReasons.Add('Team still has guests but recorded activity is older than the 90-day dormant threshold.') | Out-Null
            $exposureCategory = 'Dormant guest-enabled Team'
        }

        if ($guestEnabledOwnerless) {
            $gapReasons.Add('Guest-enabled Team does not currently show an owner signal.') | Out-Null
            if (-not $exposureCategory) { $exposureCategory = 'Guest-enabled ownerless Team' }
            if ($reviewPriority -ne 'High') { $reviewPriority = 'High' }
        }

        $guestRatioText = if ($null -ne $guestCountNumber -and $null -ne $memberCountNumber -and $memberCountNumber -gt 0) {
            '{0:P0}' -f ($guestCountNumber / $memberCountNumber)
        } else {
            'Not surfaced in current source'
        }

        $externalExposureRows.Add((New-ExternalExposureFindingRow `
            -Workload 'Teams' `
            -AssetType 'Team' `
            -Title $teamTitle `
            -UrlOrIdentifier $teamIdentifier `
            -ExposureCategory $exposureCategory `
            -TenantBaseline "GuestInvitationControl=$allowInvitesFrom; ConditionalAccessGuestCoverage=$guestCoverage" `
            -ObservedSetting "Guests=$($guestCountNumber); Members=$($memberCountNumber); GuestRatio=$guestRatioText" `
            -OwnerSignal $(if ($null -ne $ownerCountNumber) { "$ownerCountNumber owner(s)" } else { 'Owner signal not surfaced' }) `
            -GuestSignal $(if ($null -ne $guestCountNumber) { "$guestCountNumber guest(s)" } else { 'Guest count not surfaced' }) `
            -ActivitySignal $(if ($lastActivityDate) { "LastActivityDate=$($lastActivityDate.ToString('yyyy-MM-dd'))" } else { 'Last activity not surfaced' }) `
            -StaleSignal $(if ($guestEnabledDormant) { 'Yes' } else { 'No' }) `
            -GapReason ($gapReasons.ToArray() -join ' ') `
            -ReviewPriority $reviewPriority
        )) | Out-Null
    }

    foreach ($group in $unifiedGroupRows) {
        $allowGuests = Get-ExternalExposureValue -Object $group -Names @('AllowAddGuests')
        if ($null -eq $allowGuests) { continue }

        $allowsGuests = $false
        try { $allowsGuests = [bool]$allowGuests } catch {}
        if (-not $allowsGuests) { continue }

        $ownerCount = Get-ExternalExposureValue -Object $group -Names @('OwnerCount')
        $groupOwnerless = $false
        if ($null -ne $ownerCount) {
            try { $groupOwnerless = ([int]$ownerCount -eq 0) } catch {}
        }
        else {
            $managedByDetails = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $group -Names @('ManagedByDetails')) -Default ''
            $groupOwnerless = [string]::IsNullOrWhiteSpace($managedByDetails)
        }

        if (-not $groupOwnerless) { continue }

        $groupTitle = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $group -Names @('DisplayName', 'Title')) -Default 'Untitled Microsoft 365 Group'
        $groupIdentifier = Convert-ToExternalExposureText -Value (Get-ExternalExposureValue -Object $group -Names @('ExternalDirectoryObjectId', 'Id', 'GroupId')) -Default 'Not surfaced in current source'

        $externalExposureRows.Add((New-ExternalExposureFindingRow `
            -Workload 'Microsoft 365 Groups' `
            -AssetType 'Group' `
            -Title $groupTitle `
            -UrlOrIdentifier $groupIdentifier `
            -ExposureCategory 'Guest-enabled ownerless Microsoft 365 Group' `
            -TenantBaseline "GuestInvitationControl=$allowInvitesFrom" `
            -ObservedSetting 'AllowAddGuests=True' `
            -OwnerSignal '0 owners surfaced' `
            -GuestSignal 'Guest-enabled group' `
            -ActivitySignal 'Group activity not surfaced in current source' `
            -StaleSignal 'Not evaluated at object level' `
            -GapReason 'Group allows guests but does not currently show an owner signal.' `
            -ReviewPriority 'High'
        )) | Out-Null
    }

    $tenantAllowsBroadExternalSharing = ($tenantSharingCapability -match 'ExternalUserAndGuestSharing|ExternalUserSharingOnly')
    $guestCoverageEnabled = $false
    try { if ($guestCoverage -notin @('Not surfaced in current source', 'Not collected', 'Not available in current auth mode')) { $guestCoverageEnabled = [bool]$guestCoverage } } catch {}
    if ($tenantAllowsBroadExternalSharing -and -not $guestCoverageEnabled) {
        $externalExposureRows.Add((New-ExternalExposureFindingRow `
            -Workload 'Tenant Policy' `
            -AssetType 'External Access Baseline' `
            -Title 'Tenant external sharing without guest Conditional Access coverage' `
            -UrlOrIdentifier 'Tenant-level summary' `
            -ExposureCategory 'Guest access protection gap' `
            -TenantBaseline "SharingCapability=$tenantSharingCapability; GuestCoverageExpected=True" `
            -ObservedSetting "ConditionalAccessGuestCoverage=$guestCoverage; GuestInvitationControl=$allowInvitesFrom" `
            -OwnerSignal 'Tenant-level policy' `
            -GuestSignal $(if ($null -eq $inactiveGuests90Days) { 'Inactive guest count not surfaced' } else { "$inactiveGuests90Days inactive guest(s) over 90 days" }) `
            -ActivitySignal 'Not applicable' `
            -StaleSignal 'Not applicable' `
            -GapReason 'Tenant-wide external sharing is enabled, but Conditional Access summary does not show guest or external-user coverage.' `
            -ReviewPriority 'High'
        )) | Out-Null
    }

    $crossTenantPolicyEnabled = $false
    try { if ($hasCrossTenantAccessPolicy -notin @('Not surfaced in current source', 'Not collected', 'Not available in current auth mode')) { $crossTenantPolicyEnabled = [bool]$hasCrossTenantAccessPolicy } } catch {}
    $crossTenantTrustNeedsReview = $false
    $crossTenantTrustReasons = New-Object System.Collections.Generic.List[string]
    if ($crossTenantPolicyEnabled) {
        if ($defaultInboundMfaTrust -in @('Not configured', 'True')) {
            $crossTenantTrustNeedsReview = $true
            $crossTenantTrustReasons.Add("Default inbound MFA trust is $defaultInboundMfaTrust") | Out-Null
        }
        if ($defaultOutboundMfaTrust -in @('Not configured', 'True')) {
            $crossTenantTrustNeedsReview = $true
            $crossTenantTrustReasons.Add("Default outbound MFA trust is $defaultOutboundMfaTrust") | Out-Null
        }
    }
    if ($crossTenantTrustNeedsReview) {
        $externalExposureRows.Add((New-ExternalExposureFindingRow `
            -Workload 'Cross-Tenant Access' `
            -AssetType 'Tenant Policy' `
            -Title 'Cross-tenant default trust posture' `
            -UrlOrIdentifier 'Tenant-level summary' `
            -ExposureCategory 'Cross-tenant trust posture review' `
            -TenantBaseline 'Cross-tenant trust documented and intentionally configured' `
            -ObservedSetting "PartnerCount=$(if ($null -eq $crossTenantPartnerCount) { 'Not surfaced in current source' } else { $crossTenantPartnerCount }); DefaultInboundMfaTrust=$defaultInboundMfaTrust; DefaultOutboundMfaTrust=$defaultOutboundMfaTrust" `
            -OwnerSignal 'Tenant-level policy' `
            -GuestSignal "PartnerTenants=$partnerTenantNames" `
            -ActivitySignal 'Not applicable' `
            -StaleSignal 'Not applicable' `
            -GapReason (($crossTenantTrustReasons.ToArray()) -join '; ') `
            -ReviewPriority 'Medium'
        )) | Out-Null
    }

    if ($allowInvitesFrom -notin @('Not surfaced in current source', 'Not collected', 'Not available in current auth mode', 'adminsAndGuestInviters', 'none')) {
        $externalExposureRows.Add((New-ExternalExposureFindingRow `
            -Workload 'External Identity' `
            -AssetType 'Tenant Policy' `
            -Title 'Guest invitation posture allows broad invitation paths' `
            -UrlOrIdentifier 'Tenant-level summary' `
            -ExposureCategory 'Guest invitation posture review' `
            -TenantBaseline 'Guest invitations restricted to documented sponsor paths' `
            -ObservedSetting "AllowInvitesFrom=$allowInvitesFrom; AllowEmailVerifiedUsersToJoinOrganization=$allowEmailVerifiedUsersToJoin" `
            -OwnerSignal 'Tenant-level policy' `
            -GuestSignal $(if ($null -eq $crossTenantPartnerCount) { 'Partner count not surfaced' } else { "$crossTenantPartnerCount cross-tenant partner(s)" }) `
            -ActivitySignal 'Not applicable' `
            -StaleSignal 'Not applicable' `
            -GapReason 'Guest invitation control is broader than the tighter admin/sponsor-only baseline usually expected for external collaboration review.' `
            -ReviewPriority 'Medium'
        )) | Out-Null
    }

    $priorityRank = @{
        High   = 1
        Medium = 2
        Low    = 3
    }
    $categoryRank = @{
        'Stale externally shared content'                   = 1
        'Externally sharable OneDrive with ownership mismatch' = 2
        'Guest-heavy dormant Team'                          = 3
        'Guest-enabled ownerless Team'                      = 4
        'Guest-heavy Team'                                  = 5
        'Dormant guest-enabled Team'                        = 6
        'Guest-enabled ownerless Microsoft 365 Group'       = 7
        'More permissive site sharing than tenant baseline' = 8
        'Site default sharing link type differs from tenant baseline' = 9
        'Site default link permission differs from tenant baseline' = 10
        'Guest access protection gap'                       = 11
        'Cross-tenant trust posture review'                 = 12
        'Guest invitation posture review'                   = 13
    }
    $TenantStatsHash['ExternalExposureFindings'] = @(
        $externalExposureRows.ToArray() |
            Sort-Object `
                @{ Expression = { if ($priorityRank.ContainsKey([string]$_.ReviewPriority)) { $priorityRank[[string]$_.ReviewPriority] } else { 99 } } }, `
                @{ Expression = { if ($categoryRank.ContainsKey([string]$_.ExposureCategory)) { $categoryRank[[string]$_.ExposureCategory] } else { 99 } } }, `
                Workload, Title, UrlOrIdentifier
    )
    Write-ProgressHelper -Total $externalExposureProgressTotal -Id $externalExposureProgressId -Index 3 -Activity 'External exposure summaries' -Operation 'Finalizing external exposure findings'
    Write-AssessmentConsoleSubstep -Message ("External exposure summaries: completed ({0} site override(s); {1} external exposure finding(s))" -f @($siteOverrides).Count, @($TenantStatsHash['ExternalExposureFindings']).Count)
    Write-ProgressHelper -Total ([Math]::Max($externalExposureProgressTotal, 1)) -Id $externalExposureProgressId -Activity 'External exposure summaries' -Completed
}

########################################################
# Main Execution (Main Block)
########################################################
try {
Write-Host "Microsoft 365 Tenant Assessment" -ForegroundColor Cyan

$GraphTest = if ($runExportOnly) {
    'CACHE'
}
elseif (Get-MgContext -ErrorAction SilentlyContinue) {
    'SDK'
}
elseif ($global:GraphHeaders) {
    'REST'
}
else {
    'SDK'
}
$script:CurrentGraphMode = $GraphTest

if ($runExportOnly) {
    Write-Host ("Loaded tenant data snapshot for export: {0}" -f ([System.IO.Path]::GetFullPath($TenantStatsJsonPath))) -ForegroundColor DarkCyan
    if ($script:ProfileCollectionPlan.BuildOwnershipGovernanceTables) {
        Update-OwnershipGovernanceTables -TenantStatsHash $script:tenantStatsHash
    }
    if ($script:ProfileCollectionPlan.BuildLicenseClassificationMetadata) {
        Update-LicenseClassificationMetadata -TenantStatsHash $script:tenantStatsHash
    }
    if ($script:ProfileCollectionPlan.BuildAssessmentReportTables -or $script:ProfileCollectionPlan.BuildMigrationReadinessTables) {
        Update-AssessmentReportTables -TenantStatsHash $script:tenantStatsHash -IncludeBestPracticeTables ([bool]$script:ProfileCollectionPlan.BuildAssessmentReportTables) -IncludeMigrationReadiness ([bool]$script:ProfileCollectionPlan.BuildMigrationReadinessTables)
    }
    if ($script:ProfileCollectionPlan.BuildConfigurationSummaryTables) {
        Update-ConfigurationSummaryTables -TenantStatsHash $script:tenantStatsHash
    }
}
else {
    $sharePointDiscoveryLabel = if ($GraphTest -in @('REST', 'SDK') -and $connectionResult -and $connectionResult.SharePointOnline) {
        'Graph/SPO'
    }
    elseif ($GraphTest -in @('REST', 'SDK')) {
        'API'
    }
    elseif ($connectionResult -and $connectionResult.SharePointOnline) {
        'SPO'
    }
    else {
        'API'
    }
    $sharePointDiscoveryService = if ($GraphTest -in @('REST', 'SDK')) {
        'API'
    }
    elseif ($connectionResult -and $connectionResult.SharePointOnline) {
        'SPO'
    }
    else {
        'API'
    }
    $teamsDiscoveryService = if ($GraphTest -in @('SDK', 'REST')) { 'MGGraph' } else { 'Teams' }
    if ($GraphTest -eq 'REST') {
        Write-Verbose 'Attempting to use Microsoft Graph REST API for tenant identity details'
    }
    else {
        Write-Verbose 'Attempting to use Microsoft Graph SDK for tenant identity details'
    }

    $collectorSections = New-AssessmentCollectorSections
    $collectorPlan = New-AssessmentLiveCollectorPlan -GraphMode $GraphTest -SharePointDiscoveryService $sharePointDiscoveryService -SharePointDiscoveryLabel $sharePointDiscoveryLabel -TeamsDiscoveryService $teamsDiscoveryService
    $collectorSelection = Select-AssessmentCollectorPlan -Sections $collectorSections -Steps $collectorPlan -CollectorSection $CollectorSection -CollectorStep $CollectorStep
    $collectorSections = @($collectorSelection.Sections)
    $collectorPlan = @($collectorSelection.Steps)
    if ($collectorSelection.Filtered) {
        Write-Host ("Targeted collector filter active: {0}" -f $collectorSelection.Summary) -ForegroundColor Yellow
        Write-Log -Type INFO -Message ("Targeted collector filter active: {0}" -f $collectorSelection.Summary) -ExportFileLocation $ExportDetails
    }
    Initialize-AssessmentProgress -TotalSteps ([Math]::Max(@($collectorPlan).Count, 1))
    $script:AssessmentCollectorPlan = $collectorPlan
    Sync-CollectorModuleRuntimeContext
    Invoke-ArrayaCollectorPlan `
        -Sections $collectorSections `
        -Steps $collectorPlan `
        -Context $script:AssessmentContext `
        -OnSection {
            param($Section)
            Write-ConsoleSection -Step ([string]$Section.Step) -Title ([string]$Section.Name)
        } `
        -OnStep {
            param($Step, $Enabled, $SkipReason)
            Invoke-ProfileAwareAssessmentStep -Name ([string]$Step.Name) -Enabled ([bool]$Enabled) -SkipReason ([string]$SkipReason) -ScriptBlock $Step.ScriptBlock
        } | Out-Null

    Complete-AssessmentProgress
    Write-CollectorInventoryMatrix -TenantStatsHash $script:tenantStatsHash -ExportFileLocation $ExportDetails
    Write-AssessmentStepMetricsSummary -ExportFileLocation $ExportDetails
}


########################################################
### Export Reports ###
########################################################

#Exclude specific reports from Export
Write-ConsoleSection -Step 'Export' -Title 'Exporting results'
$requiresFilteredExportSnapshot = (-not $effectiveSkipWorkbook)
$ExportTenantStatsHash = $null
Prepare-AssessmentExportData `
    -BuildCombinedUserMailboxProjection ([bool]$script:ProfileCollectionPlan.BuildCombinedUserMailboxProjection) `
    -RequiresFilteredExportSnapshot ([bool]$requiresFilteredExportSnapshot)
if ($requiresFilteredExportSnapshot) {
    $ExportTenantStatsHash = Filter-TenantStatsHash -TenantStatsStore $script:tenantStatsHash -reportingMode $reportingMode -GraphTest $GraphTest
} else {
    Write-Log -Type INFO -Message "Skipping filtered export snapshot build because workbook output is disabled for this profile." -ExportFileLocation $ExportDetails
}
$generatedArtifacts = [ordered]@{}
$requiresAssessmentSnapshotArtifact = (-not $effectiveSkipJsonReport)
try {
    if (Test-Path -Path $tenantExportPipelinePath) {
        . $tenantExportPipelinePath
    }
    else {
        throw "Export pipeline script was not found: $tenantExportPipelinePath"
    }

    if (-not (Get-Command -Name Invoke-M365TenantAssessmentExportPipeline -ErrorAction SilentlyContinue)) {
        throw "Export pipeline function is unavailable. Expected loader path: $tenantExportPipelinePath"
    }

    $generatedArtifacts = Invoke-M365TenantAssessmentExportPipeline `
        -TenantStatsHash $script:tenantStatsHash `
        -ExportTenantStatsHash $ExportTenantStatsHash `
        -ExportDetails $ExportDetails `
        -SkipWorkbook $effectiveSkipWorkbook `
        -SkipBestPracticesHtml $effectiveSkipBestPracticesHtml `
        -SkipQuestionnaire $effectiveSkipQuestionnaire `
        -SkipHtmlReport $effectiveSkipHtmlReport `
        -SkipPdfReport $effectiveSkipPdfReport `
        -SkipJsonReport $effectiveSkipJsonReport `
        -OutputProfileLabel $effectiveOutputProfileLabel `
        -ReportingMode $reportingMode `
        -CollectionOnly ([bool]$runCollectionOnly) `
        -ExportOnly ([bool]$runExportOnly) `
        -WorkbookExportPolicy $effectiveWorkbookExportPolicy `
        -TechnicalHtmlPolicy $effectiveTechnicalHtmlPolicy `
        -GenerateMigrationPack ([bool]$effectiveGenerateMigrationPack) `
        -LegacyScriptRoot $PSScriptRoot

    if ($requiresAssessmentSnapshotArtifact) {
        $snapshotArtifactPath = $null
        foreach ($artifactKey in @('Assessment Snapshot JSON', 'JSON')) {
            if (
                $generatedArtifacts -is [System.Collections.IDictionary] -and
                $generatedArtifacts.Contains($artifactKey) -and
                -not [string]::IsNullOrWhiteSpace([string]$generatedArtifacts[$artifactKey])
            ) {
                $snapshotArtifactPath = [string]$generatedArtifacts[$artifactKey]
                break
            }
        }

        if ([string]::IsNullOrWhiteSpace($snapshotArtifactPath) -or -not (Test-Path -Path $snapshotArtifactPath)) {
            throw ('The assessment workbook export completed, but the required assessment snapshot JSON was not produced. Improve, export replay, and manifest-based follow-up cannot continue without that snapshot. Review the earlier JSON export error in the run log and rerun after it is corrected.')
        }

        $manifestArtifactPath = $null
        if (
            $generatedArtifacts -is [System.Collections.IDictionary] -and
            $generatedArtifacts.Contains('Manifest') -and
            -not [string]::IsNullOrWhiteSpace([string]$generatedArtifacts['Manifest'])
        ) {
            $manifestArtifactPath = [string]$generatedArtifacts['Manifest']
        }

        if ([string]::IsNullOrWhiteSpace($manifestArtifactPath) -or -not (Test-Path -Path $manifestArtifactPath)) {
            throw ('The assessment snapshot JSON was produced, but the required run manifest was not produced. Improve and manifest-based follow-up cannot continue without the manifest. Review the earlier manifest write warning in the run log and rerun after it is corrected.')
        }
    }
}
catch {
    Write-Log -Type ERROR -Message "Export pipeline execution failed: $($_.Exception.Message)" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
    $generatedArtifacts = [ordered]@{}
    if ($requiresAssessmentSnapshotArtifact) {
        throw
    }
}

$runLogBaseDirectory = [System.IO.Path]::GetDirectoryName($ExportDetails)
if ([string]::IsNullOrWhiteSpace($runLogBaseDirectory)) {
    $runLogBaseDirectory = (Get-Location).Path
}
if ([string]::Equals((Split-Path -Path $runLogBaseDirectory -Leaf), 'Deliverables', [System.StringComparison]::OrdinalIgnoreCase)) {
    $runRootDirectory = Split-Path -Path $runLogBaseDirectory -Parent
    if (-not [string]::IsNullOrWhiteSpace($runRootDirectory)) {
        $runLogBaseDirectory = Join-Path -Path $runRootDirectory -ChildPath 'Support'
    }
}
if ([string]::Equals((Split-Path -Path $runLogBaseDirectory -Leaf), 'Debugging', [System.StringComparison]::OrdinalIgnoreCase)) {
    $runLogDirectory = $runLogBaseDirectory
}
else {
    $runLogDirectory = Join-Path -Path $runLogBaseDirectory -ChildPath 'Debugging'
}
$runLogBaseName = [System.IO.Path]::GetFileNameWithoutExtension($ExportDetails)
if (-not [string]::IsNullOrWhiteSpace($runLogBaseName)) {
    $runLogPath = Join-Path -Path $runLogDirectory -ChildPath ($runLogBaseName + '-FullReportLog.txt')
    if (Test-Path -Path $runLogPath) {
        $generatedArtifacts['Run Log'] = $runLogPath
    }
}

Write-Host ""
if ($global:AllDiscoveryErrors.Count -gt 0) {
    try {
        $errorReportSummary = Export-ArrayaErrorReports -ExportFileLocation $ExportDetails -ErrorData $global:AllDiscoveryErrors -LogReportDirectory $ExportDetails
        if ($errorReportSummary -and -not [string]::IsNullOrWhiteSpace([string]$errorReportSummary.JsonPath)) {
            $generatedArtifacts['Error Report'] = $errorReportSummary.JsonPath
        }
    }
    catch {
        Write-Log -Type ERROR -Message "An error occurred in Exporting the Error Reports. $($_.Exception.Message)" -ExportFileLocation $ExportDetails -CaptureError -ErrorRecordVar $_
    }
}

$scriptEndTime = Get-Date
$totalTime = $scriptEndTime - $global:InitialStart
$totalHours = [math]::Floor($totalTime.TotalHours)
$totalMinutes = $totalTime.Minutes
$totalSeconds = $totalTime.Seconds
$timeString = if ($totalHours -gt 0) {
    "$totalHours hour(s), $totalMinutes minute(s), $totalSeconds second(s)"
} elseif ($totalMinutes -gt 0) {
    "$totalMinutes minute(s), $totalSeconds second(s)"
} else {
    "$totalSeconds second(s)"
}

Write-ConsoleArtifactSummary -Artifacts $generatedArtifacts -DurationText $timeString -CapturedErrorCount $global:AllDiscoveryErrors.Count

$finalMemory = Get-CurrentProcessMemorySnapshot
Write-Log -Type INFO -Message ("Final process memory snapshot: WorkingSetMB={0}; PrivateMB={1}; PagedMB={2}; ManagedHeapMB={3}" -f $finalMemory.WorkingSetMB, $finalMemory.PrivateMB, $finalMemory.PagedMB, $finalMemory.HeapMB) -ExportFileLocation $ExportDetails

if ($StoreTenantStatsGlobal) {
    $resolvedTenantStatsVariableName = if ([string]::IsNullOrWhiteSpace($TenantStatsVariableName)) { 'ArrayaTenantStats' } else { $TenantStatsVariableName }
    Set-Variable -Scope Global -Name $resolvedTenantStatsVariableName -Value $script:tenantStatsHash -Force
    Write-Host ("Published tenant stats to global variable `${0}" -f $resolvedTenantStatsVariableName) -ForegroundColor DarkCyan
    Write-Log -Type INFO -Message ("Published tenant stats to global variable '{0}' for interactive inspection." -f $resolvedTenantStatsVariableName) -ExportFileLocation $ExportDetails
}

########################################################
### End of HTML Report Integration ###
########################################################

Write-Log -Type INFO -Message "COMPLETED: Gathered Tenant Details. Completed Time: $($timeString)" -ExportFileLocation $ExportDetails

# Encourage GC after large export/report generation to reduce retained working set in long-lived shells.
$ExportTenantStatsHash = $null
$script:AssessmentStepMetrics = $null
[GC]::Collect()
[GC]::WaitForPendingFinalizers()
}
finally {
    Restore-AssessmentGraphRuntimeState
}
